window.NOTAS=[{"id":"2026-11-06-comision-de-diputados-aprueba-en-lo-general-el-presupuesto-2027-por-10","t":"Comisión de Diputados aprueba en lo general el Presupuesto 2027 por 10.6 billones; hoy se discuten las reservas","c":"economia","f":"2026-11-06T07:19","r":"La Comisión de Presupuesto y Cuenta Pública avaló el dictamen del gasto federal 2027 con 33 votos a favor y 12 en contra. Contempla un gasto neto de 10 billones 636 mil millones de pesos, 1.3% más en términos reales que en 2026, con supuestos de petróleo a 61.8 dólares y tipo de cambio de 18 pesos. PAN y PRI criticaron el endeudamiento y el gasto en salud; la discusión en lo particular sigue este viernes a las 10:00 horas.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/06/diputados-aprueban-en-lo-general-el-presupuesto-2027-por-106-billones-de-pesos/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-06-trabajadores-del-poder-judicial-federal-inician-un-paro-nacional-contr","t":"Trabajadores del Poder Judicial federal inician un paro nacional contra la nueva evaluación de desempeño","c":"nacional","f":"2026-11-06T07:18","r":"Personal de juzgados y tribunales federales suspendió labores este viernes en al menos 22 sedes de más de 16 estados, incluida la CDMX, en rechazo al esquema de evaluación que el Órgano de Administración Judicial publicó el jueves en el DOF. El examen de conocimientos valdrá 40% de la calificación y quienes obtengan 59 o menos podrían ser separados del cargo si no aprueban un extraordinario. Los sindicatos piden a sus agremiados no inscribirse y advierten posibles represalias de los titulares.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://infobae.com/mexico/2026/11/06/paro-nacional-del-pjf-hoy-6-de-noviembre-que-estados-se-suman-y-por-que-los-trabajadores-rechazan-examen-de-evaluacion"]],"dest":true,"a":"Redacción"},{"id":"2026-11-06-el-ine-aprueba-un-plan-para-revisar-contratos-crear-un-buzon-anonimo-d","t":"El INE aprueba un plan para revisar contratos, crear un buzón anónimo de denuncias y evaluar proveedores extranjeros para 2027","c":"politica","f":"2026-11-06T07:17","r":"Las diez consejerías del Consejo General del INE respaldaron medidas para reforzar sus controles internos tras el escándalo que llevó a la renuncia de Guadalupe Taddei. El acuerdo prevé una plataforma confidencial para que el personal denuncie irregularidades, un plan para revisar o rescindir contratos y valorar proveedores internacionales para el proceso electoral 2027, y pide a la ASF una auditoría urgente de las compras de los últimos diez años.","b":"","img":"ine","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/06/ine-plataforma-denuncias-caso-taddei-proveedores-extranjeros"]],"dest":true,"a":"Redacción"},{"id":"2026-11-06-difunden-video-en-el-que-un-contratista-del-ine-advierte-a-guadalupe-t","t":"Difunden video en el que un contratista del INE advierte a Guadalupe Taddei que tiene grabaciones comprometedoras","c":"politica","f":"2026-11-06T07:16","r":"Latinus presentó una grabación atribuida a José Alfredo Hernández Casillas, empresario ligado a una compañía con contratos electorales, en la que supuestamente dice a la expresidenta del INE que guarda material sobre ella como «seguro de vida». Según Infobae, en el video también se habla de 62 plazas manejadas por un exfuncionario cercano a Taddei. Los señalamientos no han sido verificados por autoridades.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/06/sale-a-la-luz-nuevo-video-que-revela-amenazas-de-contratista-a-guadalupe-taddei-me-pasa-algo-y-te-lleva-a-ti-y-tu-ine/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-06-fiscalia-de-tamaulipas-confirma-que-la-bala-que-mato-a-aranza-de-7-ano","t":"Fiscalía de Tamaulipas confirma que la bala que mató a Aranza, de 7 años, salió de un helicóptero de la Guardia Estatal","c":"estados","f":"2026-11-06T07:15","r":"El fiscal Eduardo Govea Orozco informó que los peritajes vinculan el disparo calibre 7.62 que mató a la niña, de nacionalidad estadounidense, con un arma usada desde una aeronave de la Guardia Estatal durante un operativo en Matamoros el 29 de octubre. Los cuatro agentes a bordo están identificados, pero siguen en activo y no se ha fijado fecha para pedir órdenes de aprehensión. El fiscal rechazó calificar el caso como «daño colateral».","b":"","img":"carretera","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/estados/2026/11/5/arma-de-la-guardia-estatal-mato-a-aranza-fiscalia-de-tamaulipas-536160.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-enfrentamiento-entre-militares-y-civiles-armados-en-navolato-sinaloa-d","t":"Enfrentamiento entre militares y civiles armados en Navolato, Sinaloa, deja al menos tres muertos","c":"seguridad","f":"2026-11-06T07:14","r":"Elementos del Ejército que patrullaban la zona de Las Trancas, en Navolato, fueron atacados el jueves por la tarde por hombres que viajaban en una camioneta, lo que derivó en un intercambio de disparos. Un conteo extraoficial reporta al menos tres fallecidos, aún sin identificar; agentes de la FGR y el Servicio Médico Forense acudieron al lugar.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín Sinaloa","https://sinaloa.quadratin.com.mx/deja-enfrentamiento-en-navolato-al-menos-3-muertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-la-confianza-del-consumidor-baja-a-45-puntos-en-octubre-cae-la-expecta","t":"La confianza del consumidor baja a 45 puntos en octubre; cae la expectativa de empleo","c":"economia","f":"2026-11-06T07:13","r":"El indicador que elaboran el INEGI y Banxico retrocedió 0.1 puntos frente a septiembre y 0.6 puntos respecto a octubre de 2025, con cifras desestacionalizadas. Entre los componentes, la expectativa sobre el empleo dentro de un año cayó 2.6% y la percepción sobre la capacidad de comprar ropa, calzado y alimentos bajó 1.1%, mientras que la posibilidad de ahorrar subió 1.2%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/negocios/mexicanos-perciben-menos-posibilidades-de-comprar-alimentos-ropa-y-zapatos-revela-el-inegi/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-el-brent-se-mantiene-cerca-de-98-dolares-y-va-rumbo-a-su-mayor-caida-s","t":"El Brent se mantiene cerca de 98 dólares y va rumbo a su mayor caída semanal desde 2020","c":"economia","f":"2026-11-06T07:12","r":"El crudo Brent para enero cotizaba alrededor de 98.40 dólares por barril la mañana del viernes en Londres, con un alza de 0.2%, y el WTI en 90.92 dólares. En la semana, el contrato más cercano del Brent acumula una baja cercana a 17%, ante señales de diálogo con Irán, la reanudación de envíos desde el Golfo y la expectativa de que Washington busque una salida más rápida al conflicto tras las elecciones.","b":"","img":"pemex","foto":"","cred":"","src":[["Bloomberg Línea","https://www.bloomberglinea.com/mercados/brent-ronda-los-us98-y-se-encamina-a-su-mayor-caida-semanal-desde-2020-por-senales-de-dialogo-con-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-las-bolsas-de-asia-se-hunden-tras-el-desplome-tecnologico-de-wall-stre","t":"Las bolsas de Asia se hunden tras el desplome tecnológico de Wall Street; el Kospi cae 7.4%","c":"economia","f":"2026-11-06T07:11","r":"El índice surcoreano Kospi perdía 7.4% y quedaba por debajo de los 5 mil puntos a media sesión del viernes, mientras el Nikkei japonés retrocedía 5.7%; Shanghái bajaba 1.3% y Hong Kong 0.7%. Samsung Electronics llegó a caer 7.9%. La venta se atribuye al temor de que se frene la construcción de centros de datos para inteligencia artificial, después de que el Nasdaq perdiera 5.5% el jueves.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/06/bolsas-de-asia-caen-hasta-74-tras-desplome-de-acciones-tecnologicas-en-wall-street/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/06/las-bolsas-de-asia-sufren-el-peor-desplome-desde-2020-lastradas-por-el-sector-de-la-ia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-el-embajador-ronald-johnson-afirma-que-las-detenciones-en-la-frontera","t":"El embajador Ronald Johnson afirma que las detenciones en la frontera sur de EU bajaron 95% en un año","c":"nacional","f":"2026-11-06T07:10","r":"En un mensaje en X, el embajador de Estados Unidos en México aseguró que las aprehensiones en la frontera suroeste están en mínimos históricos y que septiembre sumó 17 meses sin liberar migrantes dentro del país. La embajada advirtió con la etiqueta #NiLoIntentes que las leyes migratorias no cambiaron tras las elecciones del 3 de noviembre y que quien cruce de forma irregular enfrentará consecuencias.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/06/ronald-johnson-presume-caida-de-95-en-detenciones-migratorias-en-la-frontera-de-eeuu-embajada-advierte-sobre-cruces-ilegales/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-investigan-como-feminicidio-la-muerte-de-una-estudiante-en-huatulco-es","t":"Investigan como feminicidio la muerte de una estudiante en Huatulco; estudiantes bloquean la carretera 200","c":"estados","f":"2026-11-06T07:09","r":"La Fiscalía de Oaxaca indaga bajo protocolo de feminicidio la muerte de Zaira Marbeli Hernández Gaspar, de 20 años y alumna de la Universidad del Mar, hallada el 3 de noviembre en un cuarto rentado en Santa Cruz Huatulco. En el mismo predio fue encontrada sin vida en junio otra mujer, Norma Adela Hernández. No hay detenidos en ninguno de los casos; compañeros de la joven bloquearon la carretera federal 200 para exigir justicia.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/06/mismo-predio-cinco-meses-de-diferencia-feminicidios-de-zaira-marbeli-y-norma-encienden-alertas-en-huatulco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-vinculan-a-proceso-a-un-hombre-detenido-con-casi-23-kilos-de-metanfeta","t":"Vinculan a proceso a un hombre detenido con casi 23 kilos de metanfetamina y cocaína en el AICM","c":"seguridad","f":"2026-11-06T07:08","r":"La FGR obtuvo la vinculación a proceso de Jesús Alejandro Delgado Valencia por delitos contra la salud, luego de que Semar, SSPC y SSC le aseguraran cerca de la Terminal 2 una maleta y una mochila con unos 17.9 kilos de metanfetamina y 5 kilos de cocaína. El juez le impuso prisión preventiva oficiosa en el Reclusorio Sur y fijó tres meses para la investigación complementaria.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/05/fgr-procesa-a-hombre-detenido-con-metanfetamina-y-cocaina-en-el-aicm/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-trabajadores-del-imss-convocan-a-una-megamarcha-nacional-el-9-de-novie","t":"Trabajadores del IMSS convocan a una megamarcha nacional el 9 de noviembre en la CDMX","c":"cdmx","f":"2026-11-06T07:07","r":"La Asamblea de la Resistencia IMSS saldrá del Centro Médico Nacional Siglo XXI hacia el Zócalo el lunes 9 a las 15:00 horas, con una asamblea previa el domingo 8. Rechazan el aumento de 2.9% salarial y 3% en prestaciones pactado por el sindicato, y piden 10% de alza, más personal e insumos, un presupuesto de salud de al menos 7% del PIB y la salida del líder sindical Rafael Olivos.","b":"","img":"imss","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/megamarcha-nacional-trabajadores-del-imss-en-cdmx-fecha-hora-y-ruta-9-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-diputados-de-paraguay-rechazan-la-renuncia-de-santiago-pena-y-siguen-c","t":"Diputados de Paraguay rechazan la renuncia de Santiago Peña y siguen con su juicio político; el vicepresidente se salva","c":"internacional","f":"2026-11-06T07:06","r":"Peña anunció su dimisión el jueves por el colapso de Ueno Bank, que dejó congelados los fondos de unos 2.9 millones de clientes, incluidos cerca de 850 millones de dólares de dinero público. La Cámara no aceptó la renuncia y mantuvo el proceso en su contra, pero rechazó 48 votos a 30 el juicio al vicepresidente Pedro Alliana, a quien el Partido Colorado eligió para concluir el mandato. Peña debe comparecer ante el Senado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/america-latina/2026/11/06/quien-gobierna-paraguay-tras-la-fallida-renuncia-de-santiago-pena/"],["Infobae","https://www.infobae.com/america/america-latina/2026/11/05/santiago-pena-renuncio-a-la-presidencia-de-paraguay-por-el-escandalo-del-ueno-bank/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-el-papa-leon-xiv-inicia-una-gira-de-12-dias-por-uruguay-argentina-y-pe","t":"El papa León XIV inicia una gira de 12 días por Uruguay, Argentina y Perú","c":"internacional","f":"2026-11-06T07:05","r":"El pontífice salió de Roma este viernes y tiene previsto aterrizar en Montevideo a las 16:30 hora local, en su primer viaje a Sudamérica como papa y semanas después de una cirugía por un tumor pulmonar. En Uruguay se reunirá con el presidente Yamandú Orsi y el sábado oficiará misa en Paysandú; será el segundo papa en visitar ese país, 38 años después de Juan Pablo II.","b":"","img":"vaticano","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/america-latina/2026/11/06/papa-leon-xiv-en-uruguay-en-vivo-las-ultimas-noticias-de-su-gira-por-sudamerica-hoy-6-de-noviembre/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/06/temas-del-dia-de-internacional-del-viernes-6-de-noviembre-de-2026-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-trump-hablara-esta-noche-en-el-centro-espacial-kennedy-su-primer-acto","t":"Trump hablará esta noche en el Centro Espacial Kennedy, su primer acto fuera de Washington tras la derrota electoral","c":"internacional","f":"2026-11-06T07:04","r":"Según la agenda de la Casa Blanca, el presidente dará un mensaje a las 18:00 horas del Este en el evento Max Power de la NASA en Florida, cuyo programa principal será el 7 y 8 de noviembre. Es su primera salida de la capital después de que los demócratas recuperaron el control del Congreso; Trump ha defendido su agenda pese al resultado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["SpacePolicyOnline","https://spacepolicyonline.com/events/president-trump-delivers-remarks-at-max-power-nov-6-2026-ksc-600-pm-et/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/06/temas-del-dia-de-internacional-del-viernes-6-de-noviembre-de-2026-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-muere-humberto-musacchio-periodista-cultural-y-autor-del-diccionario-e","t":"Muere Humberto Musacchio, periodista cultural y autor del Diccionario enciclopédico de México, a los 83 años","c":"entretenimiento","f":"2026-11-06T07:03","r":"El cronista y editor nacido en Ciudad Obregón falleció la noche del miércoles, informó la editora Consuelo Sáizar. Dirigió las secciones culturales de El Universal y Unomásuno, fue subdirector fundador de La Jornada y encabezó el suplemento Comala de El Financiero; entre sus libros están el Diccionario enciclopédico de México (1989) y Ciudad quebrada.","b":"","img":"bellas","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4899078/humberto-musacchio-periodista-cultural-y-ensayista-mexicano-muere-a-los-83-anos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-rafa-marquez-convoca-a-28-jugadores-para-la-serie-ante-jamaica-regresa","t":"Rafa Márquez convoca a 28 jugadores para la serie ante Jamaica; regresan Quiñones y Alexis Vega","c":"deportes","f":"2026-11-06T07:02","r":"El técnico de la Selección Mexicana dio a conocer su primera lista para un torneo oficial: los cuartos de final de la Liga de Naciones de Concacaf, el sábado 14 y el martes 17 de noviembre. Hay siete caras nuevas, entre ellas Armando León, Jesús Corona y Andrés Montaño, y quedaron fuera Hirving Lozano, Orbelín Pineda, Germán Berterame y Luis Chávez.","b":"","img":"estadio","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/deportes/2026/11/05/las-sorpresas-de-rafa-marquez-en-la-lista-de-convocados-de-mexico-para-enfrentar-a-jamaica/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-liga-mx-san-luis-recibe-a-juarez-y-atlante-a-santos-para-abrir-la-jorn","t":"Liga MX: San Luis recibe a Juárez y Atlante a Santos para abrir la jornada 16","c":"deportes","f":"2026-11-06T07:01","r":"La penúltima fecha del Apertura 2026 arranca este viernes con el Atlético de San Luis contra FC Juárez a las 19:00 horas y el Atlante frente a Santos a las 21:00 horas en el Estadio Banorte. El torneo regular está por terminar y los equipos pelean sus últimos lugares rumbo a la fase final.","b":"","img":"estadio","foto":"","cred":"","src":[["TUDN","https://www.tudn.com/mx/futbol/liga-mx/partidos-del-viernes-6-de-noviembre-liga-mx-j16-y-liga-femenil-j14"]],"dest":false,"a":"Redacción"},{"id":"2026-11-06-google-meta-y-tiktok-demandan-a-california-para-frenar-la-ley-que-proh","t":"Google, Meta y TikTok demandan a California para frenar la ley que prohíbe el scroll infinito a menores de 16","c":"tecnologia","f":"2026-11-06T07:00","r":"Las tres empresas presentaron demandas por separado en cortes federales de San José, San Francisco y Los Ángeles contra el fiscal Rob Bonta por la ley AB 1709, que desde el 1 de enero de 2027 impediría ofrecer recomendaciones personalizadas, reproducción automática y desplazamiento infinito a usuarios menores de 16 años. Alegan que viola la libertad de expresión; la fiscalía dijo que defenderá la norma.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/06/google-meta-y-tiktok-demandaron-para-frenar-la-ley-de-california-que-limita-el-scroll-infinito-a-menores-de-16/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-banxico-sorprende-y-recorta-su-tasa-a-6-25-el-nivel-mas-bajo-desde-mar","t":"Banxico sorprende y recorta su tasa a 6.25%, el nivel más bajo desde marzo de 2022","c":"economia","f":"2026-11-05T18:42","r":"La Junta de Gobierno del Banco de México bajó la tasa de interés objetivo 25 puntos base, a 6.25%, con efecto a partir del 6 de noviembre; la mayoría de los analistas esperaba que se mantuviera en 6.50%. Votaron por el recorte la gobernadora Victoria Rodríguez Ceja y los subgobernadores Gabriel Cuadra y Omar Mejía, mientras que Galia Borja y Jonathan Heath votaron por no moverla. Banxico elevó a 3.70% su pronóstico de inflación general para el cierre de 2026 y anticipó que mantendrá la tasa «por un tiempo prolongado» en este nivel.","b":"","img":"bolsa","foto":"","cred":"","src":[["Bloomberg Línea","https://www.bloomberglinea.com/latinoamerica/mexico/banxico-sorprende-con-recorte-de-la-tasa-de-interes-y-la-deja-en-un-nivel-de-625/"],["Infobae","https://www.infobae.com/mexico/2026/11/05/banxico-reduce-la-tasa-de-interes-a-625-el-nivel-mas-bajo-desde-marzo-de-2022/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-anticorrupcion-expone-que-empresas-de-los-hermanos-hernandez-casillas","t":"Anticorrupción expone que empresas de los hermanos Hernández Casillas obtuvieron más de 2 mil millones en contratos electorales","c":"politica","f":"2026-11-05T18:40","r":"En la mañanera, la secretaria Anticorrupción y Buen Gobierno, Raquel Buenrostro, detalló que las empresas de José Alfredo y Raymundo Hernández Casillas —entre ellas Cajas Graf, Formas Finas y Materiales, Seriplast de México, Comercializadora JVLY y Corporativo Zeg— recibieron contratos del INE y de 23 institutos electorales locales, en un esquema que simulaba competencia en las licitaciones. Buenrostro señaló omisiones en la supervisión y falta de lineamientos claros para comprar material electoral; ninguna de las empresas está inhabilitada para contratar con el gobierno federal.","b":"","img":"ine","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/05/del-cisen-a-corromper-el-ine-asi-los-hermanos-hernandez-casilla-enlace-de-taddei-recibieron-millones/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-5-de-noviembre-de-2026"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-abaten-en-naucalpan-a-el-general-fundador-del-cartel-nuevo-imperio-y-p","t":"Abaten en Naucalpan a «El General», fundador del Cártel Nuevo Imperio y protector de la red de Ryan Wedding","c":"seguridad","f":"2026-11-05T18:38","r":"El secretario de Seguridad, Omar García Harfuch, informó que Edgar Aarón «N», alias «El General» o «El Lic», murió junto con otra persona en Lomas Verdes, Naucalpan, cuando agentes federales que cumplían una orden de aprehensión por delincuencia organizada repelieron una agresión. Según las autoridades, era el autor intelectual del asesinato del mando policial capitalino Milton Morales, ocurrido en Coacalco en julio de 2024, y operaba redes de protección para la célula del prófugo Ryan Wedding; el Tesoro de EU lo había sancionado en noviembre de 2025.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/abaten-general-fundador-cartel-nuevo-imperio-ligado-capo-ryan-wedding-garcia-harfuch"],["Infobae","https://www.infobae.com/mexico/2026/11/05/quien-era-edgar-aaron-vazquez-alias-el-general-el-protector-de-ryan-wedding-sancionado-por-la-ofac-y-abatido-en-mexico/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-el-superavit-comercial-de-mexico-con-eu-llega-a-un-record-de-184-019-m","t":"El superávit comercial de México con EU llega a un récord de 184,019 millones de dólares entre enero y septiembre","c":"economia","f":"2026-11-05T18:36","r":"Con datos del Departamento de Comercio de Estados Unidos, el saldo a favor de México en su comercio con ese país creció 26.1% anual en los primeros nueve meses del año. Solo en septiembre, las exportaciones mexicanas a EU sumaron 62,242 millones de dólares, un máximo para ese mes y un alza anual de 39.6%, la mayor en 64 meses.","b":"","img":"carretera","foto":"","cred":"","src":[["Luces del Siglo","https://lucesdelsiglo.com/2026/11/05/tienen-exportaciones-mayor-alza-en-4-anos-negocios"],["Uno TV","https://www.unotv.com/nacional/las-de-hoy-5-de-noviembre-de-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-el-peso-pierde-1-tras-el-recorte-de-banxico-y-cierra-en-18-75-por-dola","t":"El peso pierde 1% tras el recorte de Banxico y cierra en 18.75 por dólar","c":"economia","f":"2026-11-05T18:34","r":"La moneda mexicana retrocedió de 18.57 a 18.75 unidades por dólar, según el tipo de cambio de cierre del Banco de México, luego de la inesperada baja de la tasa de interés. En la jornada, el dólar osciló entre 18.54 y 18.96 pesos; JPMorgan advirtió que la reducción del diferencial de tasas con EU podría presionar más al peso.","b":"","img":"bolsa","foto":"","cred":"","src":[["EFE vía ABC Color","https://www.abc.com.py/internacionales/2026/11/05/la-bolsa-mexicana-repunta-038-y-apunta-su-mejor-nivel-desde-finales-de-febrero/"],["Investing.com","https://mx.investing.com/news/forex-news/precio-del-dolar-hoy-cierra-al-alza-banxico-se-pone-dificil-con-el-peso-mexicano-3836202"],["Infobae","https://www.infobae.com/mexico/2026/11/05/banxico-reduce-la-tasa-de-interes-a-625-el-nivel-mas-bajo-desde-marzo-de-2022/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-wall-street-se-desploma-el-nasdaq-cae-mas-de-5-por-la-venta-de-accione","t":"Wall Street se desploma: el Nasdaq cae más de 5% por la venta de acciones de chips e inteligencia artificial","c":"economia","f":"2026-11-05T18:32","r":"El índice Nasdaq perdió alrededor de 5.3% y entró en corrección, el S&P 500 bajó 4% y el Dow Jones 3.1%, con lo que se borraron las ganancias del miércoles tras las elecciones en EU. Las mayores caídas fueron de Nebius (-17%), AMD (-15.4%), Marvell (-14.4%) y Nvidia (-8.5%), ante dudas sobre la expansión de centros de datos con un Congreso de mayoría demócrata y un pronóstico débil de Qualcomm.","b":"","img":"bolsa","foto":"","cred":"","src":[["KCH Comunicación","https://kchcomunicacion.com/2026/11/05/desplome-en-wall-street-nasdaq-cae-5-por-acciones-de-ia-y-chips/"],["TV Azteca","https://www.tvazteca.com/aztecanoticias/como-cerro-la-bols-mexicana-de-valores-hoy-5-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-sheinbaum-dice-que-taddei-no-es-responsable-de-la-mafia-electoral-y-qu","t":"Sheinbaum dice que Taddei no es responsable de la «mafia electoral» y que el gobierno desconoce su paradero","c":"politica","f":"2026-11-05T18:30","r":"La presidenta afirmó que Guadalupe Taddei no originó el esquema de contratos en el INE y que no es militante de Morena; si cometió un acto ilegal, dijo, corresponderá a la ASF y a la Fiscalía revisarlo. Añadió que el gobierno no sabe dónde están Taddei ni los hermanos Hernández Casillas, aunque considera posible que sigan en el país. El titular de la ASF no reveló nombres ni montos de las cuentas inmovilizadas.","b":"","img":"ine","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-5-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-sheinbaum-presentara-la-proxima-semana-un-decreto-para-que-talleres-gr","t":"Sheinbaum presentará la próxima semana un decreto para que Talleres Gráficos fabrique material electoral","c":"politica","f":"2026-11-05T18:28","r":"La presidenta anunció un decreto para fortalecer a Talleres Gráficos de México, con el objetivo de que el material electoral lo produzcan empresas del Estado y de abrir la participación a más empresas e instituciones educativas. También dijo que el gobierno no estuvo de acuerdo con la propuesta de presupuesto del INE para 2027, de unos 47 mil millones de pesos, aunque la decisión corresponde al Congreso.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-5-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-trump-coloca-una-gorra-con-la-palabra-veto-en-el-despacho-oval-tras-pe","t":"Trump coloca una gorra con la palabra «veto» en el Despacho Oval tras perder el Congreso","c":"internacional","f":"2026-11-05T18:26","r":"El presidente de EU exhibió en su escritorio la gorra que ya había mostrado la noche electoral y advirtió que usará su poder de veto contra las leyes del nuevo Congreso. Según las proyecciones, los demócratas tendrán unos 250 escaños en la Cámara de Representantes y 54 de los 100 del Senado a partir de enero, y preparan investigaciones contra su administración.","b":"","img":"ultimahora","foto":"","cred":"","src":[["EFE vía Diario Libre","https://www.diariolibre.com/usa/actualidad/2026/11/05/despacho-oval-de-trump-muestra-veto-tras-resultados-electorales/3712347"],["Infobae","https://www.infobae.com/estados-unidos/2026/11/05/los-democratas-en-el-congreso-preparan-investigaciones-contra-la-administracion-de-donald-trump/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-la-bolsa-mexicana-sube-0-38-y-cierra-en-71-087-puntos-su-mejor-nivel-d","t":"La Bolsa Mexicana sube 0.38% y cierra en 71,087 puntos, su mejor nivel desde febrero","c":"economia","f":"2026-11-05T18:24","r":"El S&P/BMV IPC ligó su tercera alza consecutiva, pese a la caída de Wall Street. Chedraui (+7.39%), Grupo TMM (+3.54%) y Bimbo (+3.42%) encabezaron las ganancias, mientras que Alpek (-9.02%) y Vista Oil & Gas (-6.88%) tuvieron los peores resultados.","b":"","img":"bolsa","foto":"","cred":"","src":[["EFE vía ABC Color","https://www.abc.com.py/internacionales/2026/11/05/la-bolsa-mexicana-repunta-038-y-apunta-su-mejor-nivel-desde-finales-de-febrero/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-el-petroleo-rebota-casi-4-el-brent-sube-a-98-29-dolares-por-nuevos-ata","t":"El petróleo rebota casi 4%: el Brent sube a 98.29 dólares por nuevos ataques a buques en el Golfo","c":"economia","f":"2026-11-05T18:22","r":"Tras el desplome del miércoles, el Brent ganó 3.67 dólares (3.88%) y el WTI subió 2.72%, a 90.52 dólares por barril. El repunte se dio luego de que Irán reportara cinco petroleros y un remolcador incendiados por minas en el estrecho de Ormuz y de que la agencia marítima británica UKMTO informara de un buque cisterna alcanzado por dos proyectiles frente a Qatar.","b":"","img":"pemex","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/como-cerro-la-bols-mexicana-de-valores-hoy-5-de-noviembre-de-2026/"],["Infobae","https://www.infobae.com/america/mundo/2026/11/05/el-regimen-de-iran-aseguro-que-cinco-petroleros-y-un-remolcador-se-incendiaron-en-el-estrecho-de-ormuz/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-operativo-federal-en-el-edomex-deja-32-detenidos-ligados-a-los-gigan-y","t":"Operativo federal en el Edomex deja 32 detenidos ligados a «Los Gigan» y el aseguramiento de 178 mil litros de gas LP","c":"seguridad","f":"2026-11-05T18:20","r":"García Harfuch informó de 38 operativos simultáneos en el Estado de México contra una red vinculada al CJNG dedicada a la extorsión, la venta de drogas y la comercialización ilegal de gas LP, tras siete meses de investigación. Entre los detenidos están «Miky Juárez», «El Gigan» y «El Pollo», señalados como líderes, y dos policías municipales de Nezahualcóyotl.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/mexico/2026/11/5/harfuch-anuncia-detenidos-operativos-edomex-aseguran-mil-litros-gas-lp.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-el-edomex-pone-en-marcha-un-centro-de-mando-para-la-busqueda-inmediata","t":"El Edomex pone en marcha un centro de mando para la búsqueda inmediata de personas desaparecidas","c":"estados","f":"2026-11-05T18:18","r":"La gobernadora Delfina Gómez inauguró el Centro de Mando de la Alerta Nacional de Búsqueda Inmediata, encabezado por la Comisión de Búsqueda estatal y con participación de la Fiscalía mexiquense, la Guardia Nacional y la Defensa, que usará las cámaras de videovigilancia del estado. Entre enero de 2025 y el 26 de agosto de 2026 hubo 5,808 reportes de desaparición en la entidad; 1,730 personas seguían sin ser localizadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/ponen-en-marcha-centro-de-mando-de-busqueda-inmediata-en-edomex-para-localizar-a-desaparecidos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-una-narcomanta-en-culiacan-exige-cancelar-el-palenque-la-gobernadora-i","t":"Una narcomanta en Culiacán exige cancelar el Palenque; la gobernadora interina dice que la Feria Ganadera sigue","c":"estados","f":"2026-11-05T18:16","r":"La manta apareció el miércoles en un puente del bulevar Emiliano Zapata y advierte a los artistas que cancelen sus presentaciones, previstas a partir del 12 de noviembre, y a la población que no asista. Las autoridades no han identificado a los responsables; la gobernadora interina Graciela Domínguez confirmó la feria, cuyas instalaciones fueron baleadas el 2 de noviembre.","b":"","img":"ganado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-5-de-noviembre-amenazan-con-represalias-a-artistas-y-asistentes-al-palenque-de-culiacan-2026-exigen-cancelar-presentaciones/"],["Uno TV","https://www.unotv.com/estados/sinaloa/rafaguean-feria-ganadera-de-culiacan-a-dias-del-regreso-del-palenque/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-el-frente-frio-4-trae-lluvias-fuertes-a-cinco-estados-y-temperaturas-d","t":"El frente frío 4 trae lluvias fuertes a cinco estados y temperaturas de hasta -5 grados en el norte","c":"nacional","f":"2026-11-05T18:14","r":"El Servicio Meteorológico Nacional pronosticó lluvias de 25 a 50 milímetros en Tamaulipas, Guerrero, Oaxaca, Veracruz y Chiapas, y temperaturas de -5 a 0 grados en las sierras de Baja California, Chihuahua y Durango. También prevé rachas de viento de 30 a 50 km/h en el norte y calor de 35 a 40 grados en Michoacán, Oaxaca, Chiapas y Tamaulipas.","b":"","img":"lluvia","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/mexico/2026/11/05/smn-alerta-por-lluvias-fuertes-en-5-estados-y-temperaturas-bajo-cero-por-frente-frio-4-este-es-el-pronostico-para-mexico-hoy-5-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-sheinbaum-recibe-a-xochitl-joven-inventora-de-chiapas-y-pide-a-la-sep","t":"Sheinbaum recibe a Xóchitl, joven inventora de Chiapas, y pide a la SEP y la Sener difundir su calentador solar","c":"nacional","f":"2026-11-05T18:12","r":"La presidenta recibió en Palacio Nacional a la estudiante chiapaneca, creadora de un calentador de agua hecho con materiales reciclados. Propuso que Energía y Educación documenten cómo se construye y elaboren un manual para difundirlo, y mencionó la posibilidad de crear un fondo para jóvenes inventores; también dijo que buscará apoyarla para que estudie medicina.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/05/sheinbaum-recibe-en-palacio-nacional-a-xochitl-inventora-de-chiapas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-los-creditos-de-fondeso-en-la-cdmx-seran-sin-intereses-brugada-anuncia","t":"Los créditos de Fondeso en la CDMX serán sin intereses; Brugada anuncia un Instituto del Emprendimiento","c":"cdmx","f":"2026-11-05T18:10","r":"La jefa de Gobierno, Clara Brugada, informó que todos los créditos del Fondo para el Desarrollo Social pasarán a tasa de 0%, por lo que los beneficiarios solo devolverán el capital. En el Estadio Fray Nano entregó cerca de 5 mil créditos y apoyos por 140 millones de pesos, y anunció que en los próximos días se creará el Instituto del Emprendimiento de la Ciudad de México.","b":"","img":"zocalo","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/05/brugada-elimina-intereses-a-creditos-de-fondeso-y-anuncia-instituto-del-emprendimiento/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-eisenkot-suma-67-recomendaciones-para-formar-gobierno-en-israel-netany","t":"Eisenkot suma 67 recomendaciones para formar gobierno en Israel; Netanyahu se queda con 46","c":"internacional","f":"2026-11-05T18:08","r":"Al cierre de las consultas con el presidente Isaac Herzog, Gadi Eisenkot obtuvo el respaldo de Yashar!, Yisrael Beytenu, Ra'am, Los Demócratas, Together y la Lista Conjunta. Netanyahu recibió el apoyo del Likud, Shas, Sionismo Religioso, Otzma Yehudit y Zehut, mientras que el bloque ultraortodoxo Judaísmo Unido de la Torá no recomendó a nadie. La nueva Knéset rendirá protesta el 10 de noviembre.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Diario Judío","https://diariojudio.com/2026/11/05/elecciones-en-israel-eisenkot-obtiene-67-recomendaciones-y-se-acerca-al-mandato-para-formar-el-proximo-gobierno-de-israel/542230/"],["Infobae","https://www.infobae.com/america/mundo/2026/11/05/los-ultraortodoxos-se-niegan-a-respaldar-a-netanyahu-y-dejan-a-eisenkot-con-ventaja-en-las-consultas-con-el-presidente-de-israel/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-cristiano-ronaldo-anuncia-su-retiro-de-la-seleccion-de-portugal-tras-2","t":"Cristiano Ronaldo anuncia su retiro de la selección de Portugal tras 234 partidos y 146 goles","c":"deportes","f":"2026-11-05T18:06","r":"A los 41 años, el delantero comunicó en un video en sus redes sociales que deja la selección, con la que debutó el 20 de agosto de 2003 ante Kazajistán. La decisión llega después de desacuerdos con el seleccionador Jorge Jesus en la última concentración de eliminatorias, según la prensa.","b":"","img":"estadio","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/deportes/futbol/cristiano-ronaldo-anuncio-que-se-retira-de-la-seleccion-de-portugal-nid05112026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-openai-presenta-gpt-6-cyber-un-modelo-que-hallo-81-fallas-graves-en-fi","t":"OpenAI presenta GPT-6 Cyber, un modelo que halló 81 fallas graves en Firefox y que solo podrán usar clientes verificados","c":"tecnologia","f":"2026-11-05T18:04","r":"La empresa clasificó el modelo en el nivel «crítico» de riesgo en ciberseguridad y limitó su acceso, por API y Codex, a clientes seleccionados de su programa Daybreak Red, como Cisco y Palo Alto Networks. Además de las vulnerabilidades de Firefox, que Mozilla ya empezó a corregir, reprodujo 1,724 fallas del kernel de Linux y entregó 304 hallazgos críticos a sus responsables.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/05/openai-lanzo-un-modelo-de-ia-que-hallo-81-fallas-graves-en-firefox-y-lo-limito-a-clientes-verificados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-la-uif-bloquea-las-cuentas-de-40-personas-y-empresas-ligadas-a-proveed","t":"La UIF bloquea las cuentas de 40 personas y empresas ligadas a proveedores del INE; entre ellas estaría Guadalupe Taddei","c":"politica","f":"2026-11-05T06:59","r":"Hacienda, a través de la Unidad de Inteligencia Financiera, incluyó a 25 personas físicas y 15 morales en la Lista de Personas Bloqueadas y presentó una denuncia ante la FGR. De acuerdo con El Universal, en la lista figuran la expresidenta del INE Guadalupe Taddei y los hermanos José Alfredo y Raymundo Francisco Hernández Casillas, proveedores del instituto. La UIF aclaró que es una medida preventiva que no determina responsabilidad; la ASF abrió de oficio una revisión de compras del INE de 2000 a 2025.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/polemica-de-taddei-escala-uif-bloquea-a-40-personas-vinculadas-con-proveedores-del-ine/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-entra-en-vigor-la-ley-de-pagos-digitales-hacienda-tiene-15-dias-habile","t":"Entra en vigor la ley de pagos digitales; Hacienda tiene 15 días hábiles para definir dónde se dejará de aceptar efectivo","c":"economia","f":"2026-11-05T06:57","r":"La Ley de Economía Digital para Pagos Digitales y Electrónicos se publicó el 4 de noviembre en el Diario Oficial y rige desde este 5 de noviembre. Hacienda deberá determinar en 15 días hábiles los sectores en los que el pago digital podrá ser la única opción, como casetas y gasolineras, y luego las autoridades tendrán otros 15 días hábiles para fijar las reglas. El cambio será gradual y, si falla el sistema digital, se podrá pagar en efectivo o con cheque.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/sheinbaum-hace-oficial-la-ley-que-elimina-el-dinero-en-efectivo-en-casetas-y-gasolineras/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-se-reanudan-este-jueves-las-exportaciones-de-aguacate-tras-tres-semana","t":"Se reanudan este jueves las exportaciones de aguacate tras tres semanas de paro en Michoacán","c":"nacional","f":"2026-11-05T06:55","r":"La secretaria de Agricultura, Columba López, informó en la mañanera que los envíos se reanudan el 5 de noviembre tras un acuerdo entre empacadoras y trabajadores; la suspensión de cortes duró tres semanas por la caída de precios internacionales. Alicia Bárcena, de Medio Ambiente, dijo que unas 5 mil huertas están en terrenos ligados a deforestación y que se exigirá un certificado de Semarnat que acredite que no hubo afectación forestal desde 2019.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-4-de-noviembre-de-2026"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-el-peso-gana-1-44-tras-las-elecciones-en-eu-y-cierra-en-18-57-por-dola","t":"El peso gana 1.44% tras las elecciones en EU y cierra en 18.57 por dólar, según Banxico","c":"economia","f":"2026-11-05T06:53","r":"El tipo de cambio cerró el miércoles en 18.5669 pesos por dólar, 27 centavos menos que el martes (18.8385), de acuerdo con Banco de México. El FIX se ubicó en 18.6285. La moneda mexicana se recuperó después del triunfo demócrata en las elecciones intermedias de Estados Unidos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Heraldo Binario","https://www.heraldobinario.com.mx/tendencias/2026/11/4/noticia-43284.html"],["El Informador","https://www.informador.mx/economia/bolsa-mexicana-repunta-0.91--y-se-ubica-en-70-mil-819.8-puntos-tras-elecciones-en-eu-20261104-0187.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-05-el-petroleo-se-desploma-casi-8-el-brent-cae-a-95-36-dolares-tras-el-tr","t":"El petróleo se desploma casi 8%: el Brent cae a 95.36 dólares tras el triunfo demócrata en EU","c":"economia","f":"2026-11-05T06:51","r":"El Brent para enero bajó 7.95% a 95.36 dólares por barril y el WTI para diciembre perdió 7.58% a 88.80 dólares. Los inversionistas apostaron a que el control demócrata del Congreso favorece un acuerdo de paz en Medio Oriente y limita la acción militar contra Irán; además, Trump dijo al Financial Times que no tenía planes inmediatos de atacar a ese país.","b":"","img":"pemex","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/precios-del-petroleo-hoy-4-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-la-bolsa-mexicana-sube-0-91-y-cierra-en-70-819-8-puntos-volaris-y-peno","t":"La Bolsa Mexicana sube 0.91% y cierra en 70,819.8 puntos; Volaris y Peñoles encabezan las alzas","c":"economia","f":"2026-11-05T06:49","r":"El S&P/BMV IPC sumó su segunda alza consecutiva y acumula 10.09% en 2026. Se negociaron 264.7 millones de títulos por 22,665 millones de pesos; las mayores ganancias fueron de Volaris (5.79%), Peñoles (5.53%) y Walmex (4.32%). Los tres principales índices de Wall Street también cerraron al alza.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/economia/bolsa-mexicana-repunta-0.91--y-se-ubica-en-70-mil-819.8-puntos-tras-elecciones-en-eu-20261104-0187.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-banxico-anuncia-hoy-su-decision-de-tasa-la-mayoria-de-los-analistas-pr","t":"Banxico anuncia hoy su decisión de tasa; la mayoría de los analistas prevé que se mantenga en 6.50%","c":"economia","f":"2026-11-05T06:47","r":"El Banco de México dará a conocer su decisión de política monetaria este jueves a las 13:00 horas. En la encuesta Citi, 20 de 36 participantes no esperan cambios y 6 anticipan un recorte; la mediana para el cierre de 2026 se mantiene en 6.50%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Bloomberg Línea","https://www.bloomberglinea.com/latinoamerica/mexico/banxico-decide-su-tasa-este-jueves-con-el-peso-al-alza-tras-la-derrota-republicana-que-esperan-los-analistas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-sheinbaum-planea-viajar-a-china-para-la-cumbre-apec-en-shenzhen-donde","t":"Sheinbaum planea viajar a China para la cumbre APEC en Shenzhen, donde México recibiría la sede de 2028","c":"politica","f":"2026-11-05T06:45","r":"La presidenta dijo que prevé asistir al Foro de Cooperación Económica Asia-Pacífico los días 18 y 19 de noviembre, con una agenda breve. Defendió los aranceles a productos asiáticos como parte del Plan México y afirmó que el país mantiene buena relación con China y Estados Unidos. Sobre Ecuador, reiteró que no habrá restablecimiento de relaciones mientras no reconozca la irrupción en la embajada mexicana en Quito.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-4-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-sheinbaum-dice-que-no-puede-reunirse-con-grecia-quiroz-por-el-proceso","t":"Sheinbaum dice que no puede reunirse con Grecia Quiroz por el proceso electoral y que la FGR decidirá si atrae el caso Manzo","c":"politica","f":"2026-11-05T06:43","r":"La alcaldesa de Uruapan pidió una reunión con la presidenta; Sheinbaum respondió que se comunican por mensajes y que Omar García Harfuch coordina con ella los temas de seguridad. Reconoció que la percepción de inseguridad en Uruapan sigue alta según el INEGI y dijo que corresponde a la propia FGR decidir si atrae la investigación del asesinato de Carlos Manzo.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-4-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-plan-michoacan-concluyen-una-clinica-toxicologica-en-apatzingan-y-un-c","t":"Plan Michoacán: concluyen una clínica toxicológica en Apatzingán y un centro de salud mental en Huetamo","c":"nacional","f":"2026-11-05T06:41","r":"En la mañanera se informó que IMSS-Bienestar terminó la clínica de especialidades toxicológicas de Apatzingán (41.9 millones de pesos) y el centro de salud mental y adicciones de Huetamo (34.2 millones). El hospital de Villas del Pedregal, en Morelia, de 260 camas, lleva 3% de avance, y el de Zitácuaro, de 90 camas, 35%. Gobernación reportó 673 armas recolectadas con el programa de desarme.","b":"","img":"imss","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-4-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-asesinan-a-balazos-a-gabriel-rivas-rios-regidor-de-morena-en-cuernavac","t":"Asesinan a balazos a Gabriel Rivas Ríos, regidor de Morena en Cuernavaca; había denunciado amenazas","c":"estados","f":"2026-11-05T06:39","r":"Hombres en motocicleta dispararon contra el regidor la tarde del miércoles en la zona de Acapantzingo, en Cuernavaca, Morelos. La Fiscalía estatal dijo que investigará todas las líneas; no se reportan detenidos. La gobernadora Margarita González Saravia y la dirigencia nacional de Morena exigieron esclarecer el crimen. Rivas Ríos, de unos 72 años, fue fundador del PRD y de Morena en el estado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/morena-exige-esclarecer-el-asesinato-de-gabriel-rivas-rios-regidor-de-cuernavaca-y-precursor-del-movimiento/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-la-noche-de-muertos-en-michoacan-atrae-a-mas-de-un-millon-de-visitante","t":"La Noche de Muertos en Michoacán atrae a más de un millón de visitantes y deja una derrama de 1,960 millones","c":"estados","f":"2026-11-05T06:37","r":"Del 28 de octubre al 2 de noviembre, la celebración registró 104% más visitantes que en 2025 y una derrama 220% mayor, según se informó en la conferencia presidencial. Hubo más de 700 actividades en siete regiones turísticas, con 105 municipios y comunidades participantes y visitantes de más de 40 países.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-4-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-la-linea-b-del-metro-reabre-sus-11-estaciones-tras-casi-15-horas-sin-s","t":"La Línea B del Metro reabre sus 11 estaciones tras casi 15 horas sin servicio por un incendio","c":"cdmx","f":"2026-11-05T06:35","r":"Una quema de basura junto al tramo Deportivo Oceanía-Oceanía dañó el cableado y obligó a suspender el servicio entre Ciudad Azteca y Oceanía desde las 05:19 del miércoles. El director del Metro, Adrián Rubalcava, informó que todas las estaciones reabrieron a las 20:00 horas. RTP y Mexibús apoyaron con traslados gratuitos.","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/despues-mas-de-14-horas-sin-servicio-linea-b-del-metro-abrio-todas-sus-estaciones-afectadas-por-incendio/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-fiscalia-de-eu-pide-30-anos-de-prision-para-tony-montana-hermano-de-el","t":"Fiscalía de EU pide 30 años de prisión para «Tony Montana», hermano de «El Mencho»; la sentencia será el 13 de noviembre","c":"seguridad","f":"2026-11-05T06:33","r":"El Departamento de Justicia solicitó 30 años de cárcel y cinco de libertad supervisada para Antonio Oseguera Cervantes, quien en julio se declaró culpable en una corte federal de Washington de conspirar para traficar cocaína y metanfetamina y de portar un arma. Su defensa pidió 20 años. La jueza Beryl A. Howell dictará sentencia.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/eeuu-pide-30-anos-de-prision-y-multa-de-200-dolares-para-tony-montana-hermano-de-el-mencho/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-capturan-en-coatzacoalcos-a-el-panda-senalado-como-jefe-regional-del-c","t":"Capturan en Coatzacoalcos a «El Panda», señalado como jefe regional del CJNG en el sur de Veracruz","c":"seguridad","f":"2026-11-05T06:31","r":"Samuel de la Cruz Anaya fue detenido por Semar, SSPC y autoridades locales en la colonia Estero del Pantano con una orden de aprehensión por privación ilegal de la libertad; la investigación partió del rapto de dos empresarios en Cosoleacaque en enero. Fue trasladado a un juzgado de Xalapa. La captura forma parte de la Estrategia Refuerzo Coatzacoalcos, que suma 163 detenciones.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/capturan-en-coatzacoalcos-a-samuel-de-la-cruz-alias-el-panda-presunto-lider-regional-del-cjng/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-los-democratas-ganan-al-menos-28-gubernaturas-en-eu-trump-dice-que-hab","t":"Los demócratas ganan al menos 28 gubernaturas en EU; Trump dice que habría arrasado si hubiera estado en la boleta","c":"internacional","f":"2026-11-05T06:29","r":"Con conteos aún abiertos, los demócratas suman 54 escaños en el Senado y 28 gubernaturas, tras ganar Texas, Georgia, Ohio, Iowa y Nevada; Misisipi y Alaska siguen por definirse en el Senado. Trump atribuyó la derrota a no aparecer en la boleta y advirtió que podría vetar leyes demócratas. El nuevo Congreso asumirá el 3 de enero de 2027.","b":"","img":"texas","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/us/inmigracion-us/asi-amanecio-el-mapa-electoral-de-eu-y-que-cambia-para-trump/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-la-guardia-revolucionaria-de-iran-afirma-que-cuatro-petroleros-estadou","t":"La Guardia Revolucionaria de Irán afirma que cuatro petroleros estadounidenses arden en Ormuz tras chocar con minas","c":"internacional","f":"2026-11-05T06:27","r":"En un comunicado difundido por la agencia Tasnim, el cuerpo militar iraní dijo que los buques fueron destruidos en la zona sur del estrecho, que otros dos fueron detenidos y que derribó un dron MQ-9. Las cifras no han sido verificadas de forma independiente ni confirmadas por Washington.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Nacional","https://www.elnacional.com/2026/11/iran-dice-que-cuatro-petroleros-estadounidenses-arden-en-ormuz-tras-chocar-con-minas-antibuque/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-champions-el-real-madrid-remonta-3-2-en-atenas-el-liverpool-cae-3-2-en","t":"Champions: el Real Madrid remonta 3-2 en Atenas, el Liverpool cae 3-2 en Estambul y el Como golea 9-1 al Lens","c":"deportes","f":"2026-11-05T06:25","r":"En la jornada 4 de la fase de liga, el Madrid remontó tres veces ante el AEK, con un gol de Jude Bellingham, y el Fenerbahce le dio la vuelta dos veces al Liverpool. El Manchester City ganó 3-2 en Leipzig, el Arsenal 2-1 en Praga ante el Slavia y el Porto goleó 4-1 al Napoli.","b":"","img":"estadio","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/todos-los-resultados-de-la-jornada-4-de-la-champions-league-2026110423363329970"],["La Razón","https://www.razon.com.mx/deportes/2026/11/04/champions-league-resumen-y-goles-de-los-partidos-de-hoy-miercoles-4-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-muere-a-los-77-anos-maria-alicia-delgado-actriz-de-odisea-burbujas-y-d","t":"Muere a los 77 años María Alicia Delgado, actriz de «Odisea Burbujas» y «Derbez en cuando»","c":"entretenimiento","f":"2026-11-05T06:23","r":"La actriz, comediante y locutora regiomontana falleció el 4 de noviembre; la causa no ha sido confirmada oficialmente. Debutó en televisión en 1984 y participó en programas como «Cero en conducta», «La casa de la risa» y «XHDRBZ», además de telenovelas y el doblaje de las películas de «Huevitos».","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/05/de-que-murio-maria-alicia-delgado-actriz-y-comediante-de-odisea-burbujas-derbez-en-cuando-y-otras-queridas-producciones/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-05-greg-brockman-dice-que-openai-ya-obtiene-la-mayor-parte-de-sus-ingreso","t":"Greg Brockman dice que OpenAI ya obtiene la mayor parte de sus ingresos de empresas y ve posible salir a bolsa en 2027","c":"tecnologia","f":"2026-11-05T06:21","r":"En una conferencia de The Wall Street Journal en Napa, California, el presidente de OpenAI respondió «creo que sí» al preguntarle si la compañía estará lista para cotizar en 2027, aunque no fijó fecha. Afirmó que las ventas a empresas ya superan a las de usuarios individuales.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/05/openai-ya-vende-mas-a-empresas-que-a-usuarios-y-su-presidente-ve-posible-salir-a-bolsa-en-2027/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-los-democratas-recuperan-el-senado-de-eu-al-ganar-escanos-en-texas-ohi","t":"Los demócratas recuperan el Senado de EU al ganar escaños en Texas, Ohio, Kansas, Iowa y las Carolinas","c":"internacional","f":"2026-11-04T06:50","r":"El Partido Demócrata obtuvo el control del Senado estadounidense en las elecciones intermedias del martes, al arrebatar a los republicanos escaños en seis estados que Trump ganó en sus tres elecciones presidenciales: Iowa, Kansas, Ohio, Carolina del Norte, Carolina del Sur y Texas, según la AP citada por The New York Times. En Texas, James Talarico venció a Ken Paxton; en Kansas, Adam Hamilton derrotó al senador Roger Marshall, y en Ohio regresa Sherrod Brown. En Florida, la republicana Ashley Moody retuvo el asiento que dejó Marco Rubio.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / The New York Times","https://www.infobae.com/america/the-new-york-times/2026/11/04/los-democratas-obtienen-el-control-del-senado-en-las-elecciones-intermedias/"],["El Tiempo","https://www.eltiempo.com/mundo/eeuu-y-canada/resultados-elecciones-intermedias-en-estados-unidos-democratas-derrotan-a-republicanos-y-toman-el-control-total-del-congreso-segun-proyecciones-3598282"]],"dest":true,"a":"Redacción"},{"id":"2026-11-04-el-senado-aprueba-la-reforma-a-la-ley-del-derecho-de-autor-que-fija-mu","t":"El Senado aprueba la reforma a la Ley del Derecho de Autor que fija multas de hasta 4.3 millones a plataformas digitales","c":"politica","f":"2026-11-04T06:49","r":"Morena y sus aliados aprobaron el martes en el pleno del Senado la reforma a la Ley Federal del Derecho de Autor enviada por la presidenta Claudia Sheinbaum, a la que la oposición llama «ley antimemes». Las comisiones la avalaron 19 votos contra 7 en una sesión de menos de 40 minutos. El texto obliga a las plataformas a retirar con rapidez contenido que infrinja derechos de autor, prevé multas del IMPI de hasta 40 mil UMA (más de 4.3 millones de pesos) y la suspensión de cuentas de infractores reincidentes; PRI y PAN advirtieron riesgo de censura, lo que Morena negó.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/ley-antimemes-se-concreta-en-el-senado-morena-y-aliados-la-aprueban-en-menos-de-40-minutos/"],["Político MX","https://politico.mx/2026/11/04/morena-y-aliados-aprueban-ley-antimemes-20-en-el-senado-oposicion-alerta-por-censura/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-04-mexico-recibe-5-362-millones-de-dolares-en-remesas-en-septiembre-el-mo","t":"México recibe 5,362 millones de dólares en remesas en septiembre, el monto más bajo en cinco meses","c":"economia","f":"2026-11-04T06:48","r":"Los envíos de dinero de mexicanos en el exterior sumaron 5,362 millones de dólares en septiembre, la cifra mensual más baja en cinco meses, informó el Banco de México. Se registraron 12.6 millones de operaciones con un promedio de 426 dólares cada una. En enero-septiembre las remesas acumularon 47,164 millones de dólares, 2.1% más que en el mismo periodo de 2025.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/03/politica-migratoria-de-trump-ataca-remesas-mexico-recibe-5-mil-mdd-en-septiembre-el-mas-bajo-en-5-meses/"],["La Razón","https://www.razon.com.mx/negocios/2026/11/03/ingresos-por-remesas-caen-16-en-septiembre-y-se-ubican-en-5-mil-362-mdd/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-04-suman-30-renuncias-en-el-ine-tras-la-salida-de-guadalupe-taddei-tres-s","t":"Suman 30 renuncias en el INE tras la salida de Guadalupe Taddei; tres son de la Junta General Ejecutiva","c":"politica","f":"2026-11-04T06:47","r":"Ya son 30 los funcionarios que dejaron el Instituto Nacional Electoral tras la salida de Guadalupe Taddei de la presidencia, entre ellos tres integrantes de la Junta General Ejecutiva: los titulares de la Unidad de Género, de Servicios de Informática y de Comunicación Social. Las bajas en la oficina de la presidencia pasaron de 12 a 17 y los consejeros prevén pedir la renuncia de otros cuatro directores. Ricardo Monreal dijo que aún no hay acuerdo en San Lázaro sobre la convocatoria para elegir a la nueva presidencia del INE, que podría aplazarse al 13 o 14 de noviembre.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/03/ya-son-30-los-funcionarios-que-han-renunciado-al-ine-tras-los-escandalos-protagonizados-por-guadalupe-taddei/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-04-nbc-y-cbs-proyectan-que-los-democratas-ganan-la-camara-de-representant","t":"NBC y CBS proyectan que los demócratas ganan la Cámara de Representantes; Trump dice que acepta el resultado","c":"internacional","f":"2026-11-04T06:46","r":"Las cadenas NBC News y CBS News proyectaron la noche del martes que el Partido Demócrata obtendrá la mayoría en la Cámara de Representantes, con triunfos en distritos de Pensilvania, Kentucky, Colorado y Carolina del Norte. El líder demócrata Hakeem Jeffries, que buscaría presidir la Cámara a partir de enero, prometió centrarse en el costo de vida y en revertir los recortes a Medicaid. Trump dijo a The New York Times que acepta los resultados y que probablemente llegará a acuerdos con los demócratas, aunque advirtió que vetará leyes que considere dañinas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["MundoNOW","https://www.mundonow.com/nbc-cbs-proyectan-democratas-ganan-control-camara-representantes/"],["El Diario de Madrid","https://www.eldiariodemadrid.es/articulo/internacional/elecciones-eeuu-2026-democratas-ganan-congreso-senado-trump/20261104110741146006.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-gina-hinojosa-nacida-en-mcallen-derrota-a-greg-abbott-y-sera-la-primer","t":"Gina Hinojosa, nacida en McAllen, derrota a Greg Abbott y será la primera gobernadora latina de Texas","c":"internacional","f":"2026-11-04T06:45","r":"La legisladora demócrata Gina Hinojosa, de 52 años, venció al gobernador republicano Greg Abbott, quien buscaba un cuarto periodo, y asumirá el cargo en enero de 2027. Es la primera latina en gobernar Texas y la primera demócrata desde Ann Richards, electa en 1990. Hinojosa nació en McAllen y creció en Brownsville, en la frontera con México; Abbott la llamó para felicitarla y ofreció apoyo en la transición.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/04/gina-hinojosa-derrota-a-greg-abbott-y-se-convierte-en-la-primera-gobernadora-latina-de-texas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-el-peso-cae-1-4-y-cierra-en-18-83-por-dolar-segun-banxico-presionado-p","t":"El peso cae 1.4% y cierra en 18.83 por dólar según Banxico, presionado por las elecciones en EU","c":"economia","f":"2026-11-04T06:44","r":"El peso perdió alrededor de 26 centavos el martes y el tipo de cambio interbancario cerró en 18.83 unidades por dólar, de acuerdo con datos del Banco de México; en la sesión osciló entre 18.60 y 18.86. Fue la segunda moneda más depreciada del día, en medio de la cautela por los comicios intermedios en Estados Unidos. El FIX publicado para este miércoles quedó en 18.7592, mientras el mercado espera la decisión de política monetaria de Banxico del jueves.","b":"","img":"bolsa","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/04/elecciones-ee-uu-golpean-peso-dolar-roza-19-pesos/"],["N+","https://www.nmas.com.mx/economia/dolar/como-esta-tipo-de-cambio-peso-dolar-estadounidense-mexico-miercoles-4-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-semar-liquida-un-bono-de-566-millones-de-dolares-ligado-a-la-cancelaci","t":"Semar liquida un bono de 566 millones de dólares ligado a la cancelación del aeropuerto de Texcoco; restan 3,152 millones","c":"economia","f":"2026-11-04T06:43","r":"El Fideicomiso MEXCAT pagó el 2 de noviembre 565.9 millones de dólares para saldar el bono con vencimiento en 2026 emitido para el cancelado aeropuerto de Texcoco, informó la Secretaría de Marina. Con ello, el saldo pendiente baja a 3,152 millones de dólares en tres bonos. Los títulos están respaldados por la Tarifa de Uso de Aeropuerto que pagan los pasajeros del AICM.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/mexico-ha-pagado-566-millones-de-dolares-por-la-cancelacion-del-naim-en-texcoco-pero-todavia-faltan-3-mil-152-mdd/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-laura-itzel-castillo-atribuye-a-herencias-ahorros-y-ventas-su-patrimon","t":"Laura Itzel Castillo atribuye a herencias, ahorros y ventas su patrimonio de 15.7 millones de pesos","c":"politica","f":"2026-11-04T06:42","r":"La secretaria de las Mujeres, Laura Itzel Castillo, respondió en un comunicado a una investigación que señala que su patrimonio declarado creció 437.3% desde 2019, hasta 15.7 millones de pesos en octubre de 2026. Explicó que sus bienes provienen de su trayectoria laboral, ahorros, dos inmuebles heredados y la venta de propiedades, y que los valores declarados siguen los formatos oficiales y no el precio de mercado. Dijo estar dispuesta a dar aclaraciones a las autoridades.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/03/laura-itzel-castillo-defiende-su-patrimonio-de-157-millones-de-pesos-tras-senalamientos-sobre-un-aumento-de-4373/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-oposicion-en-sonora-denuncia-una-red-de-funcionarios-electorales-encab","t":"Oposición en Sonora denuncia una red de funcionarios electorales encabezada por el hijo de Guadalupe Taddei","c":"estados","f":"2026-11-04T06:41","r":"Representantes del PRI, PAN, PRD y Somos en Sonora presentaron denuncias ante el Instituto Estatal Electoral y el INE por una presunta red de funcionarios con vínculos familiares y políticos que, según ellos, encabeza Luis Rogelio Piñeda Taddei, secretario particular del gobernador Alfonso Durazo. Señalan además contratos por unos 187 millones de pesos entre 2017 y 2025 a empresas que, afirman, pertenecen a un mismo grupo. El PAN pidió auditorías a la ASF y al órgano de fiscalización estatal.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/oposicion-destapa-al-cartel-electoral-en-sonora-acusan-que-hijo-de-guadalupe-taddei-lo-encabeza/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-fernandez-norona-reclama-a-higinio-martinez-en-el-pleno-el-presidente","t":"Fernández Noroña reclama a Higinio Martínez en el pleno; el presidente del Senado niega haberle negado la palabra","c":"politica","f":"2026-11-04T06:40","r":"El senador Gerardo Fernández Noroña acusó en la sesión del martes a la Mesa Directiva de no permitirle responder alusiones y de no pronunciarse sobre presuntas amenazas del dirigente del PRI, Alejandro Moreno. Higinio Martínez, presidente del Senado, respondió que cada legislador es responsable de sus dichos y que el reglamento no reconoce alusiones implícitas, por lo que no hubo motivo para darle la palabra de inmediato.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/higinio-martinez-encara-a-fernandez-norona-por-sus-reclamos-al-senado-trato-de-entender-su-forma-de-ser/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-la-suprema-corte-valida-el-plazo-de-60-dias-en-chiapas-para-impugnar-l","t":"La Suprema Corte valida el plazo de 60 días en Chiapas para impugnar la paternidad de un hijo","c":"nacional","f":"2026-11-04T06:39","r":"El pleno de la Suprema Corte declaró constitucional el artículo 326 del Código Civil de Chiapas, que da 60 días para promover el desconocimiento de paternidad, en el amparo directo en revisión 5065/2025. El caso surgió de un hombre que, tras una prueba genética, pidió anular la filiación de un menor registrado como su hijo. La Corte resolvió que una prueba posterior no reabre el plazo, para dar certeza a los derechos de niñas y niños.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/suprema-corte-avala-plazo-de-60-dias-en-chiapas-para-impugnar-paternidad-y-proteger-identidad-de-menores/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-detienen-en-cocula-a-el-pikachu-presunto-integrante-de-los-tlacos-por","t":"Detienen en Cocula a «El Pikachu», presunto integrante de Los Tlacos, por el asesinato del abogado Anselmo Campuzano","c":"seguridad","f":"2026-11-04T06:38","r":"La Fiscalía de Guerrero detuvo en Tlanipatlán, municipio de Cocula, a Jesús «N», alias «El Pikachu», señalado como integrante de Los Tlacos y presunto partícipe del ataque armado contra el abogado Anselmo Campuzano Martínez en Iguala. En el operativo participaron el Ejército, la Guardia Nacional y la policía estatal; le aseguraron una pistola, cartuchos y un polvo similar a la cocaína. Fue puesto a disposición de un juez de control.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/golpe-a-los-tlacos-detienen-a-el-pikachu-por-el-homicidio-del-abogado-anselmo-campuzano-en-guerrero/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-vinculan-a-proceso-a-negro-pimentel-presunto-operador-del-cartel-de-si","t":"Vinculan a proceso a «Negro Pimentel», presunto operador del Cártel de Sinaloa detenido en Ensenada con 38 kilos de droga","c":"seguridad","f":"2026-11-04T06:37","r":"Un juez vinculó a proceso a Raúl «N», alias «Negro Pimentel», por delitos contra la salud y en materia de armas de fuego, y le impuso prisión preventiva oficiosa en el Cereso de Ensenada, informó la FGR. Fue detenido en Maneadero, Baja California, con cinco armas, 367 cartuchos y más de 38 kilos de marihuana, metanfetamina y heroína. La FGR lo vincula con la célula de Los Panteras.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/autoridades-llevan-a-juicio-al-negro-pimentel-integrante-del-cartel-de-sinaloa-arrestado-en-ensenada/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-detienen-en-tuxtla-gutierrez-a-seis-presuntos-integrantes-del-cartel-d","t":"Detienen en Tuxtla Gutiérrez a seis presuntos integrantes del Cártel de Sinaloa con 10 armas y chalecos tácticos","c":"estados","f":"2026-11-04T06:36","r":"La Fiscalía de Chiapas informó la detención en Tuxtla Gutiérrez de seis presuntos miembros de una célula ligada al Cártel de Sinaloa, a quienes aseguró 10 armas de fuego, 36 cargadores, 895 cartuchos, chalecos y cascos balísticos e insignias de corporaciones. También recuperó dos camionetas con reporte de robo. Serán llevados al penal de El Amate y el caso se turnará a la FGR por posibles delitos federales.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/capturan-a-seis-miembros-del-cartel-de-sinaloa-en-tuxtla-les-decomisaron-armas-de-fuego-y-equipo-tactico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-tras-una-persecucion-en-iztapalapa-la-ssc-detiene-a-el-chopercito-liga","t":"Tras una persecución en Iztapalapa, la SSC detiene a «El Chopercito», ligado a al menos 10 homicidios","c":"cdmx","f":"2026-11-04T06:35","r":"La Secretaría de Seguridad Ciudadana detuvo el 3 de noviembre a Alan Rafael Ávila Ramírez, de 20 años, alias «El Chopercito», considerado objetivo prioritario y relacionado con al menos 10 homicidios en Iztapalapa. Fue capturado en la colonia Santa Cruz Meyehualco tras una persecución en la que, según la SSC, disparó contra los policías; tres personas resultaron lesionadas. Se le aseguró una pistola y fue presentado ante el Ministerio Público.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/04/detienen-en-iztapalapa-a-alan-rafael-alias-el-chopercito-objetivo-prioritario-ligado-con-al-menos-10-homicidios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-muere-a-los-83-anos-carlos-albert-exdefensa-del-necaxa-y-periodista-de","t":"Muere a los 83 años Carlos Albert, exdefensa del Necaxa y periodista deportivo durante más de cuatro décadas","c":"deportes","f":"2026-11-04T06:34","r":"Carlos Albert Llorente murió el martes 3 de noviembre a los 83 años; la familia no informó la causa. Fue defensa central del Necaxa, su único club, y se retiró como jugador en 1971. Después trabajó 43 años en televisión, radio y prensa, fue parte del equipo original de Los Protagonistas con José Ramón Fernández e investigó el caso de «Los Cachirules».","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/04/muere-carlos-albert-exfutbolista-del-necaxa-y-destacado-periodista-deportivo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-google-limitara-sus-herramientas-de-ia-en-escuelas-y-advierte-que-bloq","t":"Google limitará sus herramientas de IA en escuelas y advierte que bloquearlas podría dejar sin buscador a los alumnos","c":"tecnologia","f":"2026-11-04T06:33","r":"Google anunció que sus herramientas de inteligencia artificial, como Gemini y Gemini en Classroom, ya no estarán disponibles para estudiantes de primaria y secundaria salvo que las escuelas lo autoricen, y dará a los administradores controles para gestionarlas. Advirtió que, por la integración de sus productos, los planteles que bloqueen estas funciones podrían dejar a sus alumnos sin acceso al buscador. La medida llega tras cuestionamientos de senadores estadounidenses sobre la promoción de la IA entre menores.","b":"","img":"tech","foto":"","cred":"","src":[["El Nacional / EFE","https://elnacional.com/2026/11/google-limitara-las-busquedas-de-las-escuelas-que-bloqueen-su-ia"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-ramon-juarez-defensa-del-america-califica-de-toxico-el-ambiente-en-tor","t":"Ramón Juárez, defensa del América, califica de «tóxico» el ambiente en torno a la Selección Mexicana","c":"deportes","f":"2026-11-04T06:32","r":"El defensa del América Ramón Juárez dijo en un pódcast que el entorno de la Selección es tóxico porque la afición sigue juzgando a los jugadores por la camiseta de su club, y pidió apoyar al equipo nacional sin importar si se es del América o de Chivas. El zaguero ha jugado ocho partidos en el Apertura 2026 y su contrato vence en junio de 2027.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/04/ramon-juarez-senala-toxicidad-dentro-del-ambiente-de-la-seleccion-mexicana-todos-siguen-con-la-playera-de-su-equipo-abajo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-aitana-morat-karol-g-y-el-corona-capital-entre-los-conciertos-de-novie","t":"Aitana, Morat, Karol G y el Corona Capital, entre los conciertos de noviembre en la Ciudad de México","c":"entretenimiento","f":"2026-11-04T06:31","r":"La cartelera de noviembre en la capital incluye a Aitana en el Auditorio Nacional del 5 al 7, a Morat con siete fechas en el Palacio de los Deportes y a Karol G en el Estadio GNP Seguros del 13 al 15. El Corona Capital se realizará del 20 al 22 en el Autódromo Hermanos Rodríguez, con Gorillaz, Twenty One Pilots y The Strokes como cabezas de cartel, y el Flow Fest el 28 y 29 en la misma sede.","b":"","img":"autodromo","foto":"","cred":"","src":[["SDPnoticias","https://www.sdpnoticias.com/espectaculos/musica/conciertos-en-cdmx-noviembre-2026-fechas-artistas-y-sedes/"],["Chilango","https://www.chilango.com/que-hacer/musica/corona-capital-2026-cartel-fechas-sede-y-boletos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-04-48e549bb62b9","t":"Luis Manuel Kadour Ponce, el chef que cocina con la memoria","c":"entretenimiento","f":"2026-11-03T22:04","r":"Formado en la Escuela Nacional de Gastronomía, el chef y escritor Luis Manuel Kadour Ponce ha construido una cocina que parte de lo conocido para sorprender: platillos de siempre, técnica de hoy y una idea central, que comer también es recordar.","b":"Luis Manuel Kadour Ponce pertenece a una generación de cocineros mexicanos que no ve contradicción entre la tradición y la técnica contemporánea. Su trabajo consiste en tomar recetas que el comensal reconoce y llevarlas a un lugar nuevo sin que pierdan el sabor de casa que les dio origen.\n\nFormación y oficio\n\nKadour Ponce se formó en la Escuela Nacional de Gastronomía en 2017. Desde entonces ha desarrollado una práctica itinerante entre la Ciudad de México y Tamaulipas, combinando el trabajo en cocina con talleres, clases y contenidos en plataformas digitales, donde comparte técnica con cocineros aficionados.\n\nEntre las preparaciones con las que suele asociarse su nombre está su versión del pollo a la naranja, un clásico que reelabora buscando el equilibrio entre lo cítrico, lo dulce y una textura crujiente.\n\nDel fogón a la página\n\nEl chef ha llevado su cocina también al papel. En 2024 publicó La mesa de Luis Manuel Kadour Ponce. Un viaje de sabores y pasión culinaria, y en 2026 el recetario Los sabores de México, dedicado a la cocina tradicional del país. Ambos títulos están disponibles en edición digital y pueden consultarse en la página de sus libros.\n\nUna cena para los sentidos\n\nSu proyecto más reciente es La Mesa Invisible, una experiencia de siete tiempos presentada en 2026 en la que aromas, sonidos, luz y elementos táctiles anteceden a cada platillo. La propuesta, que fue reseñada por Excélsior, parte de una convicción que atraviesa toda su obra: que buena parte de lo que se disfruta en la mesa está ligado a la memoria.\n\nLa cocina como vínculo\n\nPara Luis Manuel Kadour Ponce, cocinar no se reduce a preparar alimentos. Lo entiende como un lenguaje de creatividad y conexión entre personas, capaz de convertir un ingrediente cotidiano en una experiencia memorable. Su trayectoria, sus libros y sus proyectos pueden consultarse en su sitio oficial.","img":"","foto":"/img/subidas/b768b4e8-e0ed-4b95-8c1b-7a8db818d711.jpg","cred":"","src":[],"dest":false,"a":"Redacción"},{"id":"2026-11-03-morena-entrego-a-sus-254-diputados-monederos-electronicos-por-63-5-mil","t":"Morena entregó a sus 254 diputados monederos electrónicos por 63.5 millones de pesos, revela El Universal","c":"politica","f":"2026-11-03T18:34","r":"Cada uno de los 254 diputados federales de Morena recibió el 28 de octubre cinco tarjetas prepagadas de Broxel con 10 mil pesos cada una, 50 mil pesos por legislador y 63.5 millones en total, según El Universal. El reparto lo hizo la coordinación administrativa de la bancada tras una reunión a puerta cerrada en el Salón Verde; el gasto no forma parte de las prerrogativas de los legisladores. La excomisionada Norma Julieta del Río comparó el caso con Monex de 2012 y pidió a la Auditoría Superior de la Federación investigar.","b":"","img":"ine","foto":"","cred":"","src":[["Vanguardia / El Universal","https://vanguardia.com.mx/noticias/mexico/entregan-a-diputados-de-morena-monederos-por-63-mdp-evocan-caso-monex-CG24555043"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-imss-reporta-561-cirugias-en-un-fin-de-semana-y-compras-urgentes-por-8","t":"IMSS reporta 561 cirugías en un fin de semana y compras urgentes por 88.4 millones en su plan de mejora","c":"nacional","f":"2026-11-03T18:33","r":"En la mañanera, Zoé Robledo informó el avance de siete días del plan para el IMSS: compra emergente de insumos y medicinas por 88.4 millones de pesos, 561 cirugías en 20 hospitales durante un fin de semana y la adquisición de 28 tomógrafos, 3 aceleradores lineales y 67 mastógrafos. También anunció la convocatoria para 2,500 plazas de médicos especialistas, publicada este 3 de noviembre, y el primer pago del aumento salarial de 8% a 565,339 trabajadores y 370,537 jubilados.","b":"","img":"imss","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-3-de-noviembre-de-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-diputados-aprueban-con-349-votos-los-cambios-del-senado-a-la-ley-del-i","t":"Diputados aprueban con 349 votos los cambios del Senado a la Ley del ISR","c":"politica","f":"2026-11-03T18:32","r":"El pleno de la Cámara de Diputados avaló en lo general y en lo particular, con 349 votos a favor, las modificaciones del Senado a la Ley del Impuesto sobre la Renta, que agregan excepciones para la industria automotriz terminal y para quienes distribuyen o venden gasolina y diésel. Carol Antonio Altamirano, de Morena, dijo que son ajustes normativos que no cambian tasas ni otorgan privilegios fiscales; el PAN reclamó que se dejó fuera a autopartistas, gaseros y distribuidoras de autos.","b":"","img":"senado","foto":"","cred":"","src":[["Central Municipal","https://centralmunicipal.mx/politica/2026/11/03/aprueban-diputados-modificaciones-a-la-ley-del-impuesto-sobre-la-renta/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-issste-presenta-un-plan-de-12-acciones-en-120-dias-1-070-especialistas","t":"ISSSTE presenta un plan de 12 acciones en 120 días: 1,070 especialistas, 100 consultorios y 64 urgencias remodeladas","c":"nacional","f":"2026-11-03T18:31","r":"Martí Batres expuso en Palacio Nacional un plan de 12 acciones para el ISSSTE en 120 días, que incluye contratar 1,070 especialistas, 502 enfermeras y 250 médicos generales, construir 100 consultorios, terminar 55 quirófanos, remodelar 64 áreas de urgencias y mantener el abasto de medicinas arriba de 97%. Como avance, reportó 4,078 especialistas contratados, 7,605 trabajadores basificados, cinco hospitales nuevos y 710 ambulancias.","b":"","img":"imss","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-3-de-noviembre-de-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-andres-lopez-beltran-niega-vinculos-con-el-huachicol-fiscal-y-denuncia","t":"Andrés López Beltrán niega vínculos con el huachicol fiscal y denuncia una campaña en su contra","c":"politica","f":"2026-11-03T18:30","r":"En un video de unos diez minutos difundido en Facebook y YouTube, Andrés Manuel López Beltrán rechazó estar ligado al llamado huachicol fiscal y negó acusaciones de corrupción y tráfico de influencias. Atribuyó los señalamientos a sectores empresariales y mediáticos, anunció un canal en redes para responder y expresó su respaldo a la presidenta Sheinbaum. No anunció ninguna candidatura ni licencia.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/no-nos-vamos-a-doblar-el-mensaje-de-andres-lopez-beltran-contra-sus-criticos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-sheinbaum-el-pri-y-el-pan-crearon-el-modelo-del-ine-y-solo-la-asf-pued","t":"Sheinbaum: el PRI y el PAN crearon el modelo del INE y solo la ASF puede auditarlo","c":"politica","f":"2026-11-03T18:29","r":"Ante las críticas por el apoyo de Morena a Guadalupe Taddei, la presidenta recordó que la reforma que dio origen al INE y a los organismos locales fue aprobada por PRI y PAN, y que en 2023 todos los partidos votaron la quinteta en la que iba Taddei. Dijo que el instituto debe salir fortalecido y que la Auditoría Superior de la Federación es la única facultada para auditarlo; el auditor Aureliano Hernández anunció una revisión de periodos anteriores.","b":"","img":"ine","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-3-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-sheinbaum-la-comision-internacional-de-limites-no-texas-define-a-quien","t":"Sheinbaum: la Comisión Internacional de Límites, no Texas, define a quién pertenecen los islotes del río Bravo","c":"nacional","f":"2026-11-03T18:28","r":"La presidenta afirmó que el gobierno de Texas no decide la propiedad de los nueve islotes del río Bravo que declaró suyos, pues esa determinación corresponde a la Comisión Internacional de Límites y Aguas. Explicó que las islas se forman por el movimiento natural del agua y relacionó la declaración texana con el periodo electoral en Estados Unidos.","b":"","img":"texas","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-3-de-noviembre-de-2026/"],["Zeta Tijuana","https://zetatijuana.com/2026/10/texas-declara-suyas-nueve-islas-del-rio-bravo-y-sre-rechaza-la-medida/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-sheinbaum-celebra-a-xavier-becerra-quien-podria-ser-el-primer-gobernad","t":"Sheinbaum celebra a Xavier Becerra, quien podría ser el primer gobernador latino de California","c":"internacional","f":"2026-11-03T18:27","r":"En el día de las elecciones intermedias en Estados Unidos, la presidenta aplaudió que Xavier Becerra pueda convertirse en el primer gobernador latino de California. Añadió que unos 40 millones de mexicanos que viven en ese país son parte de la vida de México y que los discursos racistas y clasistas deben terminar en cualquier lugar del mundo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-3-de-noviembre-de-2026/"],["Excélsior","https://www.excelsior.com.mx/nacional/sheinbaum-celebra-avance-xavier-becerra-estados-unidos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-el-peso-pierde-16-centavos-y-cotiza-en-18-72-por-dolar-en-la-jornada-e","t":"El peso pierde 16 centavos y cotiza en 18.72 por dólar en la jornada electoral de EU","c":"economia","f":"2026-11-03T18:26","r":"El peso retrocedió este martes y el dólar se ubicó en 18.72 unidades, un alza de 16 centavos, según datos de Bloomberg citados por El Financiero, mientras los mercados seguían las elecciones intermedias en Estados Unidos. En ventanilla de Banamex el dólar se vendió en 19.20 pesos; el bono a 10 años de EU rindió 4.99% y el mexicano 9.36%.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/03/peso-dolar-tipo-de-cambio-hoy-3-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-el-brent-baja-por-segunda-sesion-y-cierra-en-103-60-dolares-su-menor-n","t":"El Brent baja por segunda sesión y cierra en 103.60 dólares, su menor nivel desde el 7 de octubre","c":"economia","f":"2026-11-03T18:25","r":"El crudo Brent perdió 1.17 dólares y terminó en 103.60 dólares por barril, su nivel más bajo desde el 7 de octubre; el WTI cedió 37 centavos a 96.09 dólares, mínimo desde el 14 de octubre. Los mercados siguieron las negociaciones sobre los conflictos en Medio Oriente y Ucrania y la elección en Estados Unidos.","b":"","img":"pemex","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/cierre-bolsa-mexicana-valores-bmv-hoy-3-noviembre-2026-por-elecciones-eu"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/03/el-brent-cae-por-segundo-dia-y-cierra-en-10360-dolares-el-barril/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-la-bolsa-mexicana-sube-0-52-y-cierra-en-70-143-puntos-en-wall-street-e","t":"La Bolsa Mexicana sube 0.52% y cierra en 70,143 puntos; en Wall Street el Dow baja y el Nasdaq avanza","c":"economia","f":"2026-11-03T18:24","r":"El S&P/BMV IPC ganó 0.52% en su primera sesión de noviembre y cerró en 70,143.09 puntos. En Nueva York, el Dow Jones bajó 0.43%, mientras el S&P 500 subió 0.28% y el Nasdaq 0.66%, en una jornada atenta a las elecciones intermedias de Estados Unidos.","b":"","img":"bolsa","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/cierre-bolsa-mexicana-valores-bmv-hoy-3-noviembre-2026-por-elecciones-eu"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-detienen-en-ixtapaluca-a-el-patron-senalado-como-generador-de-violenci","t":"Detienen en Ixtapaluca a «el Patrón», señalado como generador de violencia en Morelos","c":"seguridad","f":"2026-11-03T18:23","r":"El Gabinete de Seguridad informó la detención en Ixtapaluca, Estado de México, de Lino Sotelo Adame, alias el Patrón, señalado como líder de un grupo dedicado a la extorsión, el homicidio, el robo de vehículos y el trasiego de cocaína en Emiliano Zapata, Tlaltizapán, Yautepec, Jiutepec y Cuernavaca. Le aseguraron droga, cartuchos, un vehículo y un arma; con él suman nueve detenidos de la organización.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/03/detienen-en-mexico-a-lider-criminal-vinculado-con-narcotrafico-extorsiones-y-homicidios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-gabinete-de-seguridad-confirma-el-aseguramiento-de-66-armas-en-la-coma","t":"Gabinete de Seguridad confirma el aseguramiento de 66 armas en la comandancia de Huitzuco, Guerrero","c":"seguridad","f":"2026-11-03T18:22","r":"El Gabinete de Seguridad detalló que en el operativo del 30 de octubre en la comandancia de la policía de Huitzuco se aseguraron 66 armas de fuego, cinco cargadores, 14 cartuchos, equipo de videograbación, dos bitácoras y una patrulla. En la acción participaron el Ejército, la Guardia Nacional, la Policía Estatal y la Fiscalía de Guerrero; el alcalde Eder Nájera dijo que los policías fueron llevados a declarar.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín Guerrero","https://guerrero.quadratin.com.mx/confirma-gobierno-decomiso-de-66-armas-a-la-policia-de-huitzuco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-detienen-a-dos-implicados-en-el-asesinato-del-defensor-tsotsil-reynald","t":"Detienen a dos implicados en el asesinato del defensor tsotsil Reynaldo Pérez en Chenalhó, Chiapas","c":"estados","f":"2026-11-03T18:21","r":"La Fiscalía de Chiapas detuvo a Manasés N y a Alberto N, alias el Semáforo, por el homicidio de Reynaldo Pérez Pérez, defensor de derechos humanos asesinado a tiros el 28 de octubre en un taller de Yateklum, Chenalhó. El fiscal Jorge Luis Llaven Abarca calificó el crimen como premeditado y dijo que se busca a otros participantes; la víctima estaba en el Mecanismo de Protección federal desde 2023.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/03/caen-dos-implicados-en-el-asesinato-de-reynaldo-perez-defensor-de-derechos-humanos-en-chiapas-asi-cometieron-el-crimen/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-lluvias-dejan-22-afectaciones-en-siete-municipios-de-sonora-rescatan-a","t":"Lluvias dejan 22 afectaciones en siete municipios de Sonora; rescatan a tres automovilistas en Nogales","c":"estados","f":"2026-11-03T18:20","r":"Protección Civil de Sonora reportó 22 incidentes en siete municipios por las lluvias, entre ellos desbordamientos de arroyos, inundaciones, deslaves y cierres carreteros temporales; las precipitaciones fuertes se concentraron en Magdalena, Ímuris, Cananea, Benjamín Hill y Altar. En Nogales hubo dos deslaves, dos casas inundadas y tres conductores rescatados, sin lesionados.","b":"","img":"lluvia","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/son/sonora/2026/11/03/desbordamientos-de-arroyos-inundaciones-y-cierres-carreteros-temporales-dejan-las-lluvias-en-sonora-con-22-afectaciones-reportadas-en-siete-municipios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-la-cdmx-estima-una-derrama-de-56-mil-millones-de-pesos-por-el-fin-de-s","t":"La CDMX estima una derrama de 56 mil millones de pesos por el fin de semana de Fórmula 1 y Día de Muertos","c":"cdmx","f":"2026-11-03T18:19","r":"La jefa de Gobierno, Clara Brugada, informó que entre el 30 de octubre y el 1 de noviembre la capital tuvo una derrama estimada de 56 mil millones de pesos: unos 25 mil millones por el Gran Premio de Fórmula 1 y más de 30 mil millones por actividad turística, cultural y comercial. La ocupación hotelera promedió 92% y llegó a 100% en la Roma, la Condesa y la zona del aeropuerto.","b":"","img":"autodromo","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/cdmx/2026/11/03/cdmx-registra-derrama-economica-estimada-de-56-mil-millones-de-pesos-en-fin-de-semana-de-formula-1-y-dia-de-muertos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-brugada-ve-como-buena-noticia-una-posible-visita-de-leon-xiv-a-guadalu","t":"Brugada ve como «buena noticia» una posible visita de León XIV a Guadalupe; aún no hay fecha","c":"cdmx","f":"2026-11-03T18:18","r":"La jefa de Gobierno dijo que una eventual visita del papa León XIV sería una buena noticia para la capital y que podría darse en 2027. La posibilidad surgió luego de que la nueva prefecta del Dicasterio para la Comunicación, María Montserrat Alvarado, mencionó que el pontífice visitaría a la Virgen de Guadalupe, sin precisar dónde; la visita no está confirmada ni tiene fechas.","b":"","img":"vaticano","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/03/es-buena-noticia-dice-clara-brugada-sobre-eventual-visita-del-papa-leon-xiv-a-la-cdmx"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-champions-el-bayern-gana-2-0-en-madrid-al-atletico-el-psg-golea-6-0-al","t":"Champions: el Bayern gana 2-0 en Madrid al Atlético; el PSG golea 6-0 al Villarreal y el Barcelona vence 3-0 al Aston Villa","c":"deportes","f":"2026-11-03T18:17","r":"En la jornada 4 de la fase de liga, el Bayern Múnich se impuso 2-0 al Atlético de Madrid, el Paris Saint-Germain goleó 6-0 al Villarreal y el Barcelona superó 3-0 al Aston Villa. También ganaron el Inter (3-0 al Feyenoord), el Manchester United (3-2 a la Roma), el Galatasaray (2-0 al Stuttgart), el Sporting (1-0 al Shakhtar) y el LASK (4-0 al Slovan Bratislava); Bodø/Glimt y Lille empataron sin goles.","b":"","img":"estadio","foto":"","cred":"","src":[["Once Noticias","https://oncenoticias.hn/on/resultados-champions-league-3-noviembre-2026-barcelona-aston-villa-psg-villarreal-bayern-atletico/"],["VAVEL","https://www.vavel.com/en-us/soccer/2026/11/03/1277856-atletico-de-madrid-vs-bayern-munich-live-score-uefa-champions-league.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-reino-unido-advierte-que-es-muy-probable-un-ataque-con-ia-contra-su-in","t":"Reino Unido advierte que es muy probable un ataque con IA contra su infraestructura crítica antes de 2028","c":"tecnologia","f":"2026-11-03T18:16","r":"El Centro Nacional de Ciberseguridad británico, parte del GCHQ, señaló en su informe anual que es muy probable que se use IA maliciosa en un ataque de ransomware contra infraestructura crítica del país en los próximos dos años, con sectores como energía, transporte, salud y finanzas en riesgo. Ubica a China como el actor más capaz y menciona a Rusia e Irán; el gobierno destinará 130 millones de libras a un escudo cibernético y a un centro de detección de vulnerabilidades.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://infobae.com/tecno/2026/11/03/el-reino-unido-preve-un-ataque-con-ia-contra-sus-servicios-esenciales-antes-de-2028"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-kanye-west-anuncia-un-concierto-en-la-ciudad-de-mexico-para-el-19-de-ma","t":"Kanye West anuncia un concierto en la Ciudad de México para el 19 de marzo de 2027","c":"entretenimiento","f":"2026-11-03T18:15","r":"El rapero estadounidense Kanye West anunció oficialmente un concierto en la Ciudad de México el 19 de marzo de 2027 en el Estadio Banorte, antes Estadio Azteca. Aún no se han dado a conocer fechas de venta, precios ni detalles de acceso.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/espectaculos/kanye-west-anuncia-concierto-mexico-dara-show-estadio-banorte-dia"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-sheinbaum-mantiene-69-de-aprobacion-en-octubre-la-calificacion-en-segu","t":"Sheinbaum mantiene 69% de aprobación en octubre; la calificación en seguridad cae de 27% a 17%","c":"politica","f":"2026-11-03T06:59","r":"La encuesta mensual de El Financiero ubica la aprobación de la presidenta Claudia Sheinbaum en 69% en octubre, sin cambio respecto a la medición previa, con 31% de desaprobación. La opinión positiva sobre su manejo de la seguridad bajó de 27% a 17%, la de la economía de 49% a 46% y la de los programas sociales de 68% a 66%. El sondeo telefónico se levantó del 15 al 20 de octubre entre 800 adultos, con margen de error de ±3.5 puntos.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/03/aprobacion-de-69-a-sheinbaum-en-octubre-encuesta-ef/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-estados-unidos-vota-hoy-en-las-elecciones-intermedias-los-pronosticos","t":"Estados Unidos vota hoy en las elecciones intermedias; los pronósticos favorecen a los demócratas","c":"internacional","f":"2026-11-03T06:58","r":"Este martes se renuevan las 435 bancas de la Cámara de Representantes, 35 del Senado y más de 30 gubernaturas. Decision Desk HQ estima en 84% la probabilidad de que los demócratas ganen la Cámara baja y en 64% el Senado; una encuesta NYT/Siena los coloca al frente en seis de siete contiendas clave al Senado. El voto anticipado sumó 54.8 millones de personas, frente a 45.9 millones en 2022, según el Election Lab de la Universidad de Florida.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/03/va-eu-a-elecciones-hoy-con-pronostico-adverso-para-trump-y-los-republicanos/"],["Infobae","https://www.infobae.com/america/agencias/2026/11/03/temas-del-dia-de-internacional-del-martes-3-de-noviembre-de-2026-1200-gmt/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-proveedores-ligados-al-escandalo-del-ine-tienen-contratos-por-1-803-mi","t":"Proveedores ligados al escándalo del INE tienen contratos por 1,803 millones con institutos de 17 estados","c":"politica","f":"2026-11-03T06:57","r":"Las empresas señaladas en las investigaciones que llevaron a la renuncia de Guadalupe Taddei a la presidencia del INE firmaron contratos por cerca de 1,803 millones de pesos con organismos electorales locales de al menos 17 estados, según Excélsior con datos de la ASF, la UIF, el Órgano Interno de Control del INE y la Plataforma Nacional de Transparencia. Cajas Graf suma 586.3 millones en 13 institutos y Formas Finas y Materiales más de 540 millones en 11. Se trata de presuntas irregularidades aún en investigación.","b":"","img":"ine","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/politica/red-taddei-con-tentaculos-17-estados-suma-1-803-millones-pesos"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-eu-lanza-ataques-limitados-contra-la-isla-irani-de-qeshm-en-ormuz-iran","t":"EU lanza ataques limitados contra la isla iraní de Qeshm, en Ormuz; Irán dice haber derribado drones","c":"internacional","f":"2026-11-03T06:56","r":"Fuerzas de Estados Unidos realizaron ataques que funcionarios de ese país calificaron de limitados y defensivos contra la isla de Qeshm, en el estrecho de Ormuz, en la víspera de las elecciones intermedias. La agencia iraní IRNA reportó cinco explosiones y no hubo reportes de víctimas. La Guardia Revolucionaria afirmó haber derribado drones estadounidenses, lo que EU no confirmó. Trump escribió que Irán quiere un acuerdo; el Brent subía alrededor de 1.84 dólares, a unos 106.61 dólares.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/03/estados-unidos-lanzo-ataques-limitados-y-defensivos-contra-la-isla-irani-de-qeshm-en-el-estrecho-de-ormuz/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/03/iran-asegura-que-ha-derribado-otros-dos-drones-de-estados-unidos-cerca-de-ormuz/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-mexico-concentra-17-de-los-37-asesinatos-de-periodistas-en-america-lat","t":"México concentra 17 de los 37 asesinatos de periodistas en América Latina en 2024-2025: UNESCO","c":"nacional","f":"2026-11-03T06:55","r":"Un informe de la UNESCO registra 17 periodistas asesinados en México en 2024 y 2025, casi la mitad de los 37 casos de América Latina y el Caribe; le siguen Colombia con 6 y Perú con 4. En el mundo hubo 189 asesinatos en ese periodo, 20% más que en los dos años previos, y 86% de los crímenes sigue sin resolución judicial. El organismo consultó a México sobre 141 casos pendientes, cifra solo superada por Irak.","b":"","img":"estudio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/03/mexico-encabeza-en-al-crimenes-de-periodistas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-03-mexico-concluye-su-evaluacion-ante-el-gafi-los-resultados-se-publicara","t":"México concluye su evaluación ante el GAFI; los resultados se publicarán el 17 de diciembre","c":"economia","f":"2026-11-03T06:54","r":"La Secretaría de Hacienda informó que México terminó la Evaluación Mutua del Grupo de Acción Financiera Internacional, que revisa las medidas contra el lavado de dinero. Los trabajos técnicos del pleno concluyeron el 30 de octubre y el informe final, con las calificaciones técnicas y de efectividad, se dará a conocer el 17 de diciembre. El proceso fue coordinado por la Unidad de Inteligencia Financiera con Banxico, la FGR, la CNBV y otras dependencias.","b":"","img":"bolsa","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/negocios/2026/11/03/mexico-concluye-evaluacion-del-gafi/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-semar-liga-a-los-hermanos-pulido-lombera-detenidos-en-coahuayana-con-r","t":"Semar liga a los hermanos Pulido Lombera, detenidos en Coahuayana, con rutas marítimas de cocaína","c":"seguridad","f":"2026-11-03T06:53","r":"La Secretaría de Marina identificó a Bernardo, Leopoldo y Leobardo Pulido Lombera, detenidos en Coahuayana, Michoacán, como presuntos líderes de Los Pichilinguillos, grupo vinculado con Cárteles Unidos y con Juan José Farías, \"El Abuelo\". Según la Semar, controlaban la llegada de cocaína por mar a la costa de Aquila y la trasladaban a Apatzingán para su distribución en México y Estados Unidos. Las acusaciones aún deben probarse ante un juez.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/03/ligan-captura-de-3-con-rutas-de-droga-en-michoacan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-cae-una-avioneta-cerca-del-aeropuerto-de-pachuca-mueren-el-piloto-y-el","t":"Cae una avioneta cerca del aeropuerto de Pachuca; mueren el piloto y el copiloto","c":"estados","f":"2026-11-03T06:52","r":"Una aeronave Cessna con matrícula XB-AZG, de la empresa de capacitación Grupo Aeroespacial Avspace, se desplomó en la colonia Venta Prieta de Pachuca, Hidalgo, durante su ascenso tras despegar con rumbo a Cuernavaca, informó la Agencia Federal de Aviación Civil. Cayó a unos 500 metros de la pista y se incendió; murieron el piloto y el copiloto. Las causas se investigan y la avenida El Tezontle fue cerrada.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/11/03/se-desploma-avioneta-en-pachuca-mueren-2/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-detienen-a-tres-hombres-uno-menor-de-edad-por-el-ataque-a-la-feria-gan","t":"Detienen a tres hombres, uno menor de edad, por el ataque a la Feria Ganadera de Culiacán","c":"seguridad","f":"2026-11-03T06:51","r":"Elementos de la policía estatal de Sinaloa y del Ejército detuvieron en el sector Barrancos de Culiacán a tres personas, entre ellas un menor, presuntamente relacionadas con los disparos contra la fachada de la Feria Ganadera. Les aseguraron dos rifles AK-47, un rifle M15, dos pistolas, más de 600 cartuchos y dosis de metanfetamina, cocaína y fentanilo. Fueron puestos a disposición de la autoridad competente.","b":"","img":"ganado","foto":"","cred":"","src":[["Extraoficial","https://extraoficial.mx/caen-tres-armados-entre-ellos-un-menor-presuntamente-ligados-al-ataque-a-balazos-contra-la-feria-ganadera-de-culiacan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-la-asf-detecta-un-probable-dano-de-87-millones-en-fondos-federales-de","t":"La ASF detecta un probable daño de 87 millones en fondos federales de salud en Veracruz","c":"estados","f":"2026-11-03T06:50","r":"En la segunda entrega de la revisión de la Cuenta Pública 2025, la Auditoría Superior de la Federación observó un posible perjuicio de 87.4 millones de pesos en recursos del FASSA administrados por el gobierno de Veracruz. La mayor parte, 86.9 millones, corresponde al pago de nómina de 2024 con fondos de 2025 sin autorización ni documentación. Son hallazgos preliminares que el estado puede solventar.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/11/03/hallan-desvio-de-87-mdp-en-fondos-federales-de-salud-en-veracruz/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-el-tipo-de-cambio-fix-para-este-martes-queda-en-18-7962-pesos-por-dola","t":"El tipo de cambio FIX para este martes queda en 18.7962 pesos por dólar","c":"economia","f":"2026-11-03T06:49","r":"El Banco de México publicó en el Diario Oficial un tipo de cambio FIX de 18.7962 pesos por dólar para este martes. En ventanilla bancaria la divisa se ofrecía a la venta en 18.9452 pesos. En el mercado, el peso cerró el lunes en torno a 18.57 por dólar, en una semana marcada por las elecciones en Estados Unidos y la decisión de tasas de Banxico del jueves.","b":"","img":"bolsa","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/economia/dolar/como-esta-el-tipo-de-cambio-del-peso-con-el-dolar-estadounidense-este-martes-3-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-liberan-a-un-parroco-de-culiacan-tras-tres-dias-de-secuestro-la-dioces","t":"Liberan a un párroco de Culiacán tras tres días de secuestro; la diócesis denuncia que fue torturado","c":"seguridad","f":"2026-11-03T06:48","r":"La Diócesis de Culiacán informó que el sacerdote Clemente Morales Topete, párroco de Jesucristo Resucitado, fue privado de la libertad durante tres días, golpeado y con quemaduras graves, antes de ser liberado con vida. El comunicado, difundido por el obispo Jesús Herrera Quiñónez, señala que sus captores lo amenazaron y le exigieron información que no tenía.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/11/03/torturan-por-tres-dias-a-parroco-que-fue-secuestrado/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-fijan-fianza-de-30-mil-dolares-a-agente-de-ice-acusado-de-atropellar-a","t":"Fijan fianza de 30 mil dólares a agente de ICE acusado de atropellar a un mexicano en Houston","c":"nacional","f":"2026-11-03T06:47","r":"Mario Alberto Morales, agente de ICE de 33 años, se entregó el lunes y el juez Matthew Peneguy le fijó una fianza de 30 mil dólares, menos de los 75 mil que pidió la fiscalía. Está acusado de agresión agravada con arma mortal por atropellar el 10 de octubre en un estacionamiento de Houston, Texas, a Miguel Parra Hernández, trabajador de la construcción mexicano de 48 años.","b":"","img":"texas","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/03/libre-agente-de-ice-que-arrollo-a-paisano/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-la-gasolina-magna-promedia-23-70-pesos-por-litro-en-el-pais-la-premium","t":"La gasolina Magna promedia 23.70 pesos por litro en el país; la Premium, 28.60","c":"economia","f":"2026-11-03T06:46","r":"El precio promedio nacional de la gasolina Magna fue de 23.703 pesos por litro, el de la Premium de 28.597 y el del diésel de 26.99, con datos de la Comisión Nacional de Energía del lunes 2 de noviembre, informó Infobae.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/03/nacionales-asi-quedo-el-precio-de-la-gasolina-hoy-en-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-el-iecm-propone-838-millones-de-pesos-para-partidos-en-la-eleccion-cap","t":"El IECM propone 838 millones de pesos para partidos en la elección capitalina de 2027","c":"cdmx","f":"2026-11-03T06:45","r":"El Consejo General del Instituto Electoral de la Ciudad de México aprobó un proyecto de presupuesto de 2,707.9 millones de pesos para 2027, de los cuales 838.1 millones serían financiamiento para partidos: 627.4 millones para actividades ordinarias, 18.8 millones para actividades específicas y 192 millones para campañas. La propuesta se enviará a la Jefatura de Gobierno y a la Secretaría de Administración y Finanzas.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/03/preve-iecm-destinar-8381-mdp-para-financiamiento-de-partidos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-el-frente-frio-4-trae-lluvias-a-14-estados-y-rachas-de-hasta-70-km-h-e","t":"El frente frío 4 trae lluvias a 14 estados y rachas de hasta 70 km/h en Sonora y Chihuahua","c":"nacional","f":"2026-11-03T06:44","r":"El Servicio Meteorológico Nacional prevé chubascos en 14 estados, entre ellos Sonora, Chihuahua, Jalisco, Michoacán, Guerrero, Oaxaca, Chiapas, Veracruz y la península de Yucatán, por el frente frío número 4. Se esperan rachas de 50 a 70 km/h en Sonora y Chihuahua y máximas de 35 a 40 grados en zonas de Sinaloa, Michoacán, Guerrero y Oaxaca. Una zona de baja presión al suroeste de Baja California tiene 70% de probabilidad de volverse ciclón en siete días.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/03/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-martes-3-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-rusia-y-ucrania-retomaran-negociaciones-en-abu-dabi-el-10-y-11-de-novi","t":"Rusia y Ucrania retomarán negociaciones en Abu Dabi el 10 y 11 de noviembre con mediación de EU","c":"internacional","f":"2026-11-03T06:43","r":"Las conversaciones de paz entre Rusia y Ucrania, con mediación de Estados Unidos, se reanudarán en Abu Dabi el 10 y 11 de noviembre, con un asesor de Vladimir Putin al frente de la delegación rusa, según EFE. Mientras tanto, ataques rusos con misiles y drones alcanzaron instalaciones energéticas en tres regiones ucranianas e infraestructura portuaria en Odesa.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/03/temas-del-dia-de-internacional-del-martes-3-de-noviembre-de-2026-1200-gmt/"],["N+","https://www.nmas.com.mx/internacional/rusia-anuncia-dialogo-con-ucrania-para-noviembre-eua-sera-intermediario/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-armadoras-en-eu-presionan-al-congreso-para-prohibir-de-forma-permanent","t":"Armadoras en EU presionan al Congreso para prohibir de forma permanente los autos chinos","c":"economia","f":"2026-11-03T06:42","r":"La Alianza para la Innovación Automotriz, que agrupa a fabricantes como General Motors, Toyota y Volkswagen, pidió al Congreso estadounidense aprobar en la sesión posterior a las elecciones un veto permanente a los vehículos chinos, informó Reuters. Su presidente, John Bozzella, citó riesgos de vigilancia. Un comité del Senado aprobó la iniciativa en julio y la versión de la Cámara tiene más de 100 copatrocinadores.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón / Reuters","https://www.razon.com.mx/negocios/2026/11/03/sector-automotor-urge-prohibicion-de-carros-chinos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-atletico-de-madrid-recibe-al-bayern-en-la-jornada-4-de-la-champions-ta","t":"Atlético de Madrid recibe al Bayern en la jornada 4 de la Champions; también juegan Barcelona y Villarreal","c":"deportes","f":"2026-11-03T06:41","r":"El Atlético de Madrid enfrenta este martes al Bayern Múnich en el Metropolitano, estadio donde nunca ha perdido ante el club alemán. En la misma jornada 4 de la fase de liga se juegan Barcelona contra Aston Villa, Villarreal contra PSG, Manchester United contra Roma y Feyenoord contra Inter de Milán, entre otros partidos.","b":"","img":"estadio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/deportes/2026/11/03/atletico-nunca-ha-perdido-ante-el-bayern-como-local/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-03-la-argentina-josefina-licitra-gana-el-premio-sor-juana-ines-de-la-cruz","t":"La argentina Josefina Licitra gana el Premio Sor Juana Inés de la Cruz 2026 con la novela Crac","c":"entretenimiento","f":"2026-11-03T06:40","r":"La escritora argentina Josefina Licitra, nacida en La Plata en 1975, obtuvo el Premio de Literatura Sor Juana Inés de la Cruz 2026 por su novela Crac, publicada por Seix Barral. El galardón, dotado con 15 mil dólares, se entregará el 2 de diciembre en el Auditorio Juan Rulfo durante la Feria Internacional del Libro de Guadalajara.","b":"","img":"bellas","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/cultura/2026/11/03/josefina-licitra-conquista-el-premio-sor-juana-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-renuncian-19-funcionarios-cercanos-a-guadalupe-taddei-en-el-ine-cuatro","t":"Renuncian 19 funcionarios cercanos a Guadalupe Taddei en el INE; cuatro más se fueron el fin de semana","c":"politica","f":"2026-11-02T18:59","r":"Suman 19 las renuncias de funcionarios del INE cercanos a la expresidenta Guadalupe Taddei, según Expansión: 15 la semana pasada y cuatro más el fin de semana, entre ellos Juan Manuel Vázquez, Pablo Chirinos, Sergio Uzeta y Jorge Moreno Toscano. Taddei anunció su salida el 25 de octubre entre señalamientos de irregularidades en contrataciones y vínculos con proveedores. Blanca Yassahara Cruz García es presidenta provisional y la Cámara de Diputados prevé designar a la titular definitiva en diciembre.","b":"","img":"ine","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/02/renuncias-ine-caso-guadalupe-taddei"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-diputados-votaran-este-martes-los-cambios-del-senado-a-la-ley-del-isr","t":"Diputados votarán este martes los cambios del Senado a la Ley del ISR y la convocatoria para la nueva presidenta del INE","c":"politica","f":"2026-11-02T18:58","r":"El pleno de la Cámara de Diputados discutirá el martes 3 de noviembre las modificaciones del Senado a la Ley del Impuesto Sobre la Renta y el acuerdo para emitir la convocatoria que elegirá a la nueva presidenta del INE, informó Ricardo Monreal. La Comisión de Presupuesto empezará el jueves el análisis del Presupuesto de Egresos 2027, que llegará al pleno el 9, 10 y 11 de noviembre. El miércoles se prevé una sesión solemne en memoria de Cuauhtémoc Cárdenas.","b":"","img":"senado","foto":"","cred":"","src":[["El Demócrata","https://www.eldemocrata.com/843711/este-martes-en-san-lazaro-se-discutira-en-el-pleno-la-reforma-a-la-ley-del-isr-y-convocatoria-para-renovar-la-presidencia-del-ine-monreal/"],["MVS Noticias","https://mvsnoticias.com/nacional/2026/11/1/convocatoria-para-sustituir-a-taddei-y-presupuesto-2027-aprobaran-diputados-751990.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-el-peso-cierra-en-18-57-por-dolar-y-gana-1-2-en-el-dia-suma-dos-sesion","t":"El peso cierra en 18.57 por dólar y gana 1.2% en el día; suma dos sesiones al alza","c":"economia","f":"2026-11-02T18:57","r":"El tipo de cambio cerró el lunes en 18.57 pesos por dólar en promedio, frente a 18.79 del cierre previo, una apreciación de alrededor de 1.2%, según datos de Dow Jones citados por Infobae. Suma dos días de baja. Los mercados atienden esta semana las elecciones intermedias en EU y la decisión de Banxico del jueves.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/precio-del-dolar-hoy-en-mexico-cotizacion-de-cierre-del-2-de-noviembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-la-sre-confirma-la-muerte-de-un-mexicano-en-el-choque-de-trenes-en-esp","t":"La SRE confirma la muerte de un mexicano en el choque de trenes en España; era el hidrocálido desaparecido","c":"nacional","f":"2026-11-02T18:56","r":"La Cancillería confirmó la muerte de un ciudadano mexicano en el choque de trenes ocurrido el 28 de octubre en Urda, Toledo, después de que las autoridades españolas identificaran a la persona que seguía desaparecida. Según El Financiero, se trataría de Fernando de Jesús Calvillo Silva, de 45 años y originario de Aguascalientes, quien viajaba en un tren de Renfe. La SRE apoyará la repatriación y, si la familia lo pide, los gastos funerarios.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/02/sre-confirma-un-mexicno-muerto-en-el-choque-de-dos-trenes-en-espana-seria-fernando-calvillo/"],["El Imparcial","https://www.elimparcial.com/mexico/2026/11/02/sre-confirma-muerte-de-mexicano-en-choque-de-trenes-en-espana-apoyara-la-repatriacion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-el-brent-se-desploma-7-6-y-cierra-en-104-77-dolares-el-wti-baja-a-96-4","t":"El Brent se desploma 7.6% y cierra en 104.77 dólares; el WTI baja a 96.46 por la expectativa de diálogo entre EU e Irán","c":"economia","f":"2026-11-02T18:55","r":"El barril de Brent terminó el lunes en 104.77 dólares, 8.66 dólares menos que el viernes, su mayor caída diaria en meses, y el WTI de diciembre bajó 7.36% a 96.46 dólares, de acuerdo con Infobae. El ajuste se dio tras la carta del vicepresidente JD Vance a Irán para retomar negociaciones y el envío de una delegación iraní a Doha. El cambio de contrato del Brent de diciembre a enero exagera parte de la comparación.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/02/el-petroleo-brent-cayo-mas-de-7-ante-las-expectativas-de-dialogo-entre-estados-unidos-e-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-iran-dice-que-podria-reabrir-ormuz-en-dos-dias-si-eu-acepta-sus-condic","t":"Irán dice que podría reabrir Ormuz en dos días si EU acepta sus condiciones; Vance propone retomar el diálogo","c":"internacional","f":"2026-11-02T18:54","r":"El vicepresidente de EU, JD Vance, envió una carta al secretario del Consejo Supremo de Seguridad Nacional iraní, Mohsen Rezaei, para reanudar las negociaciones, e Irán mandó una delegación a Doha, donde Qatar intercambia mensajes entre ambas partes. Teherán afirma que podría reabrir el estrecho de Ormuz en dos días si Washington acepta condiciones como el cese de combates en la región, el descongelamiento de activos y el fin de sanciones petroleras. Los hutíes reportaron un ataque al aeropuerto saudí de Dammam.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/02/el-petroleo-brent-cayo-mas-de-7-ante-las-expectativas-de-dialogo-entre-estados-unidos-e-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-trump-cierra-campana-en-washington-en-la-vispera-de-las-intermedias-ya","t":"Trump cierra campaña en Washington en la víspera de las intermedias; ya votaron por anticipado más de 54 millones","c":"internacional","f":"2026-11-02T18:53","r":"Donald Trump preparó un mitin en la Explanada del Reflecting Pool de Washington tras 28 actos de campaña, en la víspera de las elecciones intermedias del martes 3 de noviembre. Según la AP, más de 54 millones de personas ya votaron por anticipado. Trump advirtió que vetará leyes si los demócratas ganan el Congreso, y un juez federal desechó una demanda del Departamento de Justicia sobre la certificación en Alaska, informó Telemundo.","b":"","img":"texas","foto":"","cred":"","src":[["Telemundo","https://www.telemundo.com/noticias/noticias-telemundo/elecciones-estados-unidos-2026/live-blog/elecciones-2026-una-democrata-sacude-contienda-clave-del-senado-al-res-rcna606984"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-banxico-decide-su-tasa-el-jueves-el-mercado-preve-que-la-mantenga-en-6","t":"Banxico decide su tasa el jueves: el mercado prevé que la mantenga en 6.50%; esta semana salen remesas y encuesta de expectativas","c":"economia","f":"2026-11-02T18:52","r":"El Banco de México anunciará su decisión de política monetaria el jueves 5 de noviembre y el consenso espera que deje la tasa de referencia en 6.50%, según la agenda económica de Amexi. El martes se publican la encuesta de expectativas de Banxico, las remesas de septiembre y el indicador IMEF; el jueves el Inegi difunde consumo e inversión de agosto. El viernes sale el reporte de empleo de octubre en EU.","b":"","img":"bolsa","foto":"","cred":"","src":[["Amexi","https://amexi.com.mx/economia-y-negocios/agenda-economica-mexico-2-6-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-academicos-de-la-udeg-advierten-que-una-derrota-republicana-podria-end","t":"Académicos de la UdeG advierten que una derrota republicana podría endurecer a Trump contra México","c":"politica","f":"2026-11-02T18:51","r":"Investigadores del Centro de Estudios de América del Norte de la Universidad de Guadalajara, José Arturo Santa Cruz y Miguel Alejandro Hiljar, señalaron que un Trump debilitado tras las intermedias podría subir aranceles o intensificar acciones contra cárteles, reportó Infobae. La presidenta Sheinbaum ha dicho que la revisión del T-MEC no depende del resultado electoral; la petición principal de México es reducir los aranceles de la Sección 232.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/elecciones-en-eeuu-expertos-advierten-sobre-posibles-arrebatos-de-donald-trump-contra-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-disparan-contra-la-fachada-de-la-feria-ganadera-de-culiacan-no-hay-her","t":"Disparan contra la fachada de la Feria Ganadera de Culiacán; no hay heridos y sigue un operativo","c":"seguridad","f":"2026-11-02T18:50","r":"Personas armadas dispararon la mañana del lunes contra las instalaciones de la Feria Ganadera, en el sector Barrancos de Culiacán, en una presunta agresión contra militares que vigilaban el lugar. La Secretaría de Seguridad Pública de Sinaloa informó que no hubo lesionados, que la fachada resultó dañada y que mantiene un operativo para localizar a los responsables.","b":"","img":"ganado","foto":"","cred":"","src":[["Los Noticieristas","https://losnoticieristas.com/policiaca/2026/11/seguridad-publica-mantiene-operativo-tras-ataque-a-balazos-en-la-feria-ganadera-en-culiacan-1159720/"],["Quadratín","https://www.quadratin.com.mx/justicia/disparan-contra-fachada-de-la-feria-ganadera-de-culiacan-sinaloa/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-hallan-sin-vida-a-una-integrante-de-la-guardia-nacional-en-un-departam","t":"Hallan sin vida a una integrante de la Guardia Nacional en un departamento de Culiacán; investigan como posible feminicidio","c":"seguridad","f":"2026-11-02T18:49","r":"Una mujer de 38 años, integrante de la Guardia Nacional, fue encontrada sin vida y con aparentes signos de violencia en un departamento del fraccionamiento Alturas del Sur, en Culiacán, alrededor de las 11:50 horas del lunes. Paramédicos confirmaron su muerte y la Fiscalía de Sinaloa, con el área especializada en feminicidios, tomó el caso; la causa de muerte no se ha confirmado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Extraoficial","https://extraoficial.mx/encuentran-muerta-a-una-integrante-de-la-guardia-nacional-en-alturas-del-sur-en-culiacan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-detienen-en-tlaquepaque-a-dos-hombres-que-dispararon-contra-policias-t","t":"Detienen en Tlaquepaque a dos hombres que dispararon contra policías tras una riña con cuatro heridos","c":"seguridad","f":"2026-11-02T18:48","r":"Policías de San Pedro Tlaquepaque, Jalisco, detuvieron a Luis Orlando \"N\", de 28 años, y Jesús Alberto \"N\", de 36, quienes según la versión oficial dispararon contra agentes en la colonia San Martín de las Flores. Uno de ellos resultó herido en el pecho y está fuera de peligro; ningún policía se lesionó. La búsqueda derivó de una riña previa en la que cuatro personas fueron baleadas.","b":"","img":"jalisco","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/jalisco/seguridad-en-jalisco-detienen-a-dos-hombres-tras-agresion-a-policias-de-tlaquepaque-20261102-0159.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-wall-street-cierra-mixto-el-nasdaq-cae-1-07-por-ventas-en-tecnologia-y","t":"Wall Street cierra mixto: el Nasdaq cae 1.07% por ventas en tecnología y el Dow sube 0.41%","c":"economia","f":"2026-11-02T18:47","r":"El S&P 500 bajó 0.51% a 7,541.40 puntos y el Nasdaq 1.07% a 25,164.32, mientras el Dow Jones avanzó 0.41% a 51,983.96, reportó El CEO. Las acciones de inteligencia artificial cayeron por dudas sobre sus grandes inversiones; Oracle perdió 8.85% tras emitir 10 mil millones de dólares en acciones. La Bolsa Mexicana no operó por el Día de Muertos.","b":"","img":"bolsa","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/bmv-ipc-wall-street-hoy-2-de-noviembre-de-2026-cierre/"],["El Informador","https://www.informador.mx/economia/wall-street-cierra-mixto-arrastrado-por-las-ventas-en-el-sector-tecnologico-20261102-0145.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-marvell-comprara-lumentum-por-115-mil-millones-de-dolares-una-de-las-m","t":"Marvell comprará Lumentum por 115 mil millones de dólares, una de las mayores operaciones tecnológicas de la historia","c":"tecnologia","f":"2026-11-02T18:46","r":"Marvell Technology acordó adquirir a Lumentum, fabricante de láseres y componentes ópticos para centros de datos de inteligencia artificial, en una operación pagada en acciones por unos 115 mil millones de dólares. Los accionistas de Lumentum recibirán 4.5 acciones de Marvell por título, una prima de 23.9%, y el cierre se espera en el primer semestre de 2028, según SiliconANGLE. Las acciones de Marvell cayeron 12.72% en la sesión, de acuerdo con El CEO.","b":"","img":"tech","foto":"","cred":"","src":[["SiliconANGLE","https://siliconangle.com/2026/11/02/marvell-to-acquire-optical-component-maker-lumentum-in-massive-115b-deal/"],["El CEO","https://elceo.com/mercados/bmv-ipc-wall-street-hoy-2-de-noviembre-de-2026-cierre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-sheinbaum-recibe-en-palacio-nacional-a-mujeres-de-naucalpan-y-cumple-u","t":"Sheinbaum recibe en Palacio Nacional a mujeres de Naucalpan y cumple una promesa hecha durante su gira de informe","c":"nacional","f":"2026-11-02T18:45","r":"La presidenta Claudia Sheinbaum recibió el lunes en Palacio Nacional a un grupo de mujeres de San Francisco Chimalpa, Naucalpan, a quienes había prometido la visita durante un acto de su segundo informe. Les mostró su despacho y el salón \"Mujeres en la Historia\", y compartió un video del encuentro en redes sociales.","b":"","img":"palacio","foto":"","cred":"","src":[["En Blanco y Negro","https://enblancoynegro.com.mx/2026/11/02/sheinbaum-cumple-una-promesa-y-recibe-a-mujeres-de-naucalpan-en-palacio-nacional/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-aguacateros-de-michoacan-instalan-puntos-de-revision-fitosanitaria-y-s","t":"Aguacateros de Michoacán instalan puntos de revisión fitosanitaria y se deslindan de bloqueos tras destruir 52 toneladas","c":"estados","f":"2026-11-02T18:44","r":"Productores Unidos de Aguacate, de comunidades indígenas de Michoacán, anunciaron puntos de revisión en entradas y salidas de la zona productora, como 18 de Marzo y San Antonio Tierra Blanca, para verificar documentos y certificación de la fruta. Se deslindaron de bloqueos y retenciones de camiones. La medida sigue a la destrucción de 52 toneladas de aguacate de Jalisco, Colima y Nayarit en las que se detectaron larvas, con aval de Senasica.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/michoacan/aguacateros-michoacan-instalan-puntos-revision-fitosanitaria-se-deslindan-bloqueos/"],["El Imparcial","https://www.elimparcial.com/mexico/2026/11/02/destruyen-52-toneladas-de-aguacate-en-michoacan-por-posible-plaga/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-mueren-un-expolicia-jubilado-y-su-hijo-en-un-choque-frontal-en-la-carr","t":"Mueren un expolicía jubilado y su hijo en un choque frontal en la carretera a Sanalona, en Culiacán","c":"estados","f":"2026-11-02T18:43","r":"José Rodolfo, de 60 años, y su hijo Rodolfo, de 18, murieron la mañana del lunes cuando su auto cayó a un barranco tras chocar de frente con una camioneta que, según las primeras indagatorias, invadió el carril contrario en la carretera a Sanalona, Culiacán. Otras cinco personas resultaron heridas, entre ellas otro hijo en estado grave. La vía estuvo cerrada más de dos horas.","b":"","img":"carretera","foto":"","cred":"","src":[["Los Noticieristas","https://losnoticieristas.com/policiaca/2026/11/eran-un-expolicia-municipal-jubilado-y-su-hijo-los-fallecidos-en-el-encontronazo-de-sanalona-en-culiacan-1159766/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-el-panteon-de-xoco-recibe-a-mas-de-80-mil-visitantes-por-dia-de-muerto","t":"El Panteón de Xoco recibe a más de 80 mil visitantes por Día de Muertos; abre hasta las 23:00","c":"cdmx","f":"2026-11-02T18:42","r":"Más de 80 mil personas acudieron al Panteón de Xoco, en la alcaldía Benito Juárez, durante las celebraciones de Día de Muertos, que este año tuvieron como lema \"Piel de Maíz, Corazón de Dulce\". La alcaldía informó que el panteón permanecería abierto hasta las 23:00 horas de este lunes, con vigilancia policial en las zonas de mayor afluencia.","b":"","img":"ofrenda","foto":"","cred":"","src":[["ABC Noticias","https://abcnoticias.mx/cdmx/2026/11/2/panteon-de-xoco-recibe-a-mas-de-80-mil-visitantes-por-dia-de-muertos-294244.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-liga-de-expansion-leones-negros-morelia-y-piratas-abren-la-liguilla-la","t":"Liga de Expansión: Leones Negros, Morelia y Piratas abren la Liguilla; la ida se juega miércoles y jueves","c":"deportes","f":"2026-11-02T18:41","r":"La Liga de Expansión MX fijó los cuartos de final del Apertura 2026: La Paz contra Coyotes de Tlaxcala, Leones Negros contra Alacranes de Durango, Morelia contra Venados y Piratas de Veracruz contra Cancún FC. Los partidos de ida serán el 4 y 5 de noviembre y los de vuelta el 7 y 8, con los mejor clasificados como locales en la vuelta.","b":"","img":"estadio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/deportes/liga-de-expansion-mx-confirma-fechas-y-horarios-de-la-liguilla-20261102-0143.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-godzilla-minus-zero-el-gato-con-sombrero-y-klara-y-el-sol-entre-los-es","t":"Godzilla Minus Zero, El gato con sombrero y Klara y el sol, entre los estrenos de la semana en cines de México","c":"entretenimiento","f":"2026-11-02T18:40","r":"La cartelera mexicana recibe el jueves 5 de noviembre Godzilla Minus Zero, secuela de Godzilla Minus One; la animada El gato con sombrero, basada en Dr. Seuss; Klara y el sol, adaptación de la novela de Kazuo Ishiguro, y la cinta mexicana Ceniza en la boca. El miércoles 4 se proyecta el concierto Rammstein: Live in Mexico City. En plataformas llegan la segunda temporada de Palomas negras en Netflix y Stick en Apple TV+.","b":"","img":"bellas","foto":"","cred":"","src":[["Imagen Radio","https://www.imagenradio.com.mx/entretenimiento/que-ver-cine-streaming-todos-estrenos-2-8-noviembre-mexico"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-morena-pide-revisar-los-contratos-del-ine-desde-la-gestion-de-lorenzo","t":"Morena pide revisar los contratos del INE desde la gestión de Lorenzo Córdova y niega haber designado a Taddei","c":"politica","f":"2026-11-02T07:20","r":"Morena exigió investigar el manejo de recursos del INE tanto en la presidencia de Lorenzo Córdova como en la de Guadalupe Taddei, y afirmó que la llegada de Taddei en 2023 «no fue una designación nuestra», pues ocurrió por insaculación en la Cámara de Diputados. El partido citó un contrato de 2015 con la empresa Jet Van para arrendar vehículos por cerca de mil millones de pesos. Córdova rechaza los señalamientos y sostiene que la ASF auditó su gestión sin hallar irregularidades graves.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/morena-exige-investigar-contratos-del-ine-y-se-deslinda-de-guadalupe-taddei-no-fue-una-designacion-nuestra/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-la-fgr-aclara-que-la-suspension-concedida-a-ernesto-ruffo-no-cierra-su","t":"La FGR aclara que la suspensión concedida a Ernesto Ruffo no cierra su proceso por delitos en materia de hidrocarburos","c":"politica","f":"2026-11-02T07:19","r":"La Fiscalía General de la República informó que la suspensión definitiva que una jueza de distrito en Toluca otorgó el 29 de octubre al exgobernador de Baja California Ernesto Ruffo Appel no equivale a un sobreseimiento ni a un fallo sobre su culpabilidad. La medida solo impide pasar a juicio oral mientras se resuelve un amparo; Ruffo sigue vinculado a proceso y, según la FGR, «la investigación en su contra continúa».","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/aclara-fgr-que-suspension-en-el-caso-de-ernesto-ruffo-no-significa-que-se-haya-terminado-su-proceso-penal-la-investigacion-en-su-contra-continua/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-pensiones-del-bienestar-el-ultimo-pago-del-ano-arranca-este-martes-3-c","t":"Pensiones del Bienestar: el último pago del año arranca este martes 3 con la letra A; adultos mayores recibirán 6,400 pesos","c":"economia","f":"2026-11-02T07:18","r":"La Secretaría del Bienestar comenzará el martes 3 de noviembre la dispersión del bimestre noviembre-diciembre, la última de 2026, según el calendario por primera letra del apellido que presentó Leticia Ramírez Amaya. Los depósitos terminarán el 27 de noviembre con las letras W a Z y no habrá pagos los fines de semana ni el lunes 16. Adultos mayores recibirán 6,400 pesos; Mujeres con Bienestar y personas con discapacidad, 3,100 pesos.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/10/29/calendario-pagos-pension-bienestar-noviembre-2026"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-el-brent-cae-casi-3-a-110-dolares-por-la-expectativa-de-un-acuerdo-ent","t":"El Brent cae casi 3% a 110 dólares por la expectativa de un acuerdo entre EU e Irán para reabrir Ormuz","c":"economia","f":"2026-11-02T07:17","r":"El petróleo Brent para entrega en enero bajaba 2.82% a unos 110.23 dólares por barril en las primeras horas del lunes en Londres, ante el optimismo por las conversaciones indirectas entre Washington y Teherán con mediación de Qatar. Trump dijo que no atacará Irán antes de las elecciones del martes. El reporte de dos petroleros que chocaron con minas en Ormuz limitó la baja; la OPEP+ mantuvo su oferta de diciembre.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/02/el-petroleo-brent-baja-casi-un-3-hasta-los-110-dolares-pendiente-de-iran/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-02-iran-reporta-que-otros-dos-petroleros-chocaron-con-minas-en-ormuz-uno","t":"Irán reporta que otros dos petroleros chocaron con minas en Ormuz; uno quedó envuelto en llamas","c":"internacional","f":"2026-11-02T07:16","r":"La Guardia Revolucionaria iraní informó que dos petroleros más chocaron con minas navales en el estrecho de Ormuz mientras navegaban, según su versión, por una ruta no autorizada y con los sistemas de identificación apagados. Uno de ellos, un superpetrolero, sufrió una fuerte explosión. No se informaron banderas ni víctimas. Irán suma unos 30 incidentes con buques en tres semanas, mientras negocia con EU por medio de Qatar.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/02/otros-dos-petroleros-chocan-con-minas-en-ormuz-en-plenas-negociaciones-segun-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-eu-vota-este-martes-en-las-intermedias-las-ultimas-encuestas-dan-venta","t":"EU vota este martes en las intermedias; las últimas encuestas dan ventaja de hasta 10 puntos a los demócratas","c":"internacional","f":"2026-11-02T07:15","r":"Las elecciones intermedias del martes 3 de noviembre definirán el control de la Cámara de Representantes y del Senado, hoy en manos republicanas. En la intención de voto genérica, Emerson College da 52% a los demócratas y 42% a los republicanos, e Ipsos 53% contra 44%; Ipsos ubica la aprobación de Trump en 32%. El costo de vida es el tema que más pesa entre los votantes.","b":"","img":"ultimahora","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/us/actualidad-us/elecciones-2026-las-encuestas-finales-antes-del-dia-de-la-eleccion/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-el-peso-abre-la-semana-en-18-74-por-dolar-banxico-no-publica-el-fix-po","t":"El peso abre la semana en 18.74 por dólar; Banxico no publica el FIX por el día inhábil bancario","c":"economia","f":"2026-11-02T07:14","r":"El tipo de cambio abrió el lunes en 18.74 pesos por dólar, 0.26% por debajo del cierre previo de 18.79, según Infobae. Banxico no publica hoy el FIX porque el 2 de noviembre es inhábil para la banca; el tipo de cambio para solventar obligaciones quedó en 18.8148. El peso perdió alrededor de 4.5% en octubre y esta semana estará atento a las elecciones en EU y a la decisión de Banxico.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/dolar-hoy-en-mexico-cotizacion-de-apertura-del-2-de-noviembre/"],["N+","https://www.nmas.com.mx/economia/dolar/como-esta-tipo-de-cambio-peso-dolar-estadounidense-mexico-lunes-2-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-detienen-a-un-mando-y-dos-policias-de-nezahualcoyotl-por-presunto-secu","t":"Detienen a un mando y dos policías de Nezahualcóyotl por presunto secuestro","c":"seguridad","f":"2026-11-02T07:13","r":"Fuerzas federales, con participación de la Defensa, la Guardia Nacional y la FGR, detuvieron en cateos nocturnos simultáneos a Jesús «N», José «N» y Salim «N», un mando y dos agentes en activo de la policía de Nezahualcóyotl, señalados por su presunta participación en secuestros. Fueron llevados a la FEMDO. En Ixtapaluca, dos agentes de tránsito fueron aprehendidos por presuntamente retener a un chofer para exigir 40 mil pesos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Independiente","https://elindependiente.mx/valle/2026/11/02/detienen-a-mando-policiaco-y-dos-uniformados-de-neza-por-presunto-secuestro/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-un-bombardeo-del-ejercito-venezolano-contra-un-campamento-del-eln-en-a","t":"Un bombardeo del Ejército venezolano contra un campamento del ELN en Apure deja al menos 19 muertos","c":"internacional","f":"2026-11-02T07:12","r":"El Ejército de Venezuela atacó el viernes un campamento de la guerrilla colombiana ELN cerca de Buena Vista del Meta, en el estado Apure, con un saldo de al menos 19 muertos, según la ONG Fundaredes y fuentes citadas por AFP. Una fuente militar anónima dijo que hubo apoyo de inteligencia de EU. El gobierno venezolano no había emitido información oficial; analistas lo ven como un cambio de doctrina frente a la guerrilla.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Diario Libre / AFP","https://www.diariolibre.com/mundo/america-latina/2026/11/01/19-muertos-en-bombardeo-militar-contra-campamento-del-eln-en-venezuela/3707753"],["El Espectador","https://www.elespectador.com/mundo/venezuela/lo-que-se-sabe-del-bombardeo-del-ejercito-venezolano-a-la-guerrilla-del-eln-en-apure/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-hoy-no-hay-clases-la-sep-confirma-que-el-regreso-a-las-aulas-tras-el-p","t":"Hoy no hay clases: la SEP confirma que el regreso a las aulas tras el puente de Día de Muertos es el martes 3","c":"nacional","f":"2026-11-02T07:11","r":"Los alumnos de educación básica de las 32 entidades no tienen clases este lunes 2 de noviembre; el regreso es el martes 3, de acuerdo con el calendario escolar 2026-2027 de la SEP. Los siguientes días sin clases del mes serán el viernes 13 (registro de calificaciones), el lunes 16 (Revolución Mexicana) y el viernes 27 (Consejo Técnico Escolar).","b":"","img":"unam","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/hay-clases-este-lunes-2-de-noviembre-sep-aclara-cuando-termina-el-megapuente-por-dia-de-muertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-sheinbaum-no-tendra-mananera-este-lunes-por-dia-de-muertos-la-conferen","t":"Sheinbaum no tendrá mañanera este lunes por Día de Muertos; la conferencia vuelve el martes 3","c":"nacional","f":"2026-11-02T07:10","r":"La presidenta Claudia Sheinbaum suspendió su conferencia matutina de este 2 de noviembre por las celebraciones de Día de Muertos, como anunció el viernes en Palacio Nacional. «Nos vemos el 3 de noviembre, martes», dijo al despedirse.","b":"","img":"palacio","foto":"","cred":"","src":[["Yahoo Noticias / El Universal","https://es-us.noticias.yahoo.com/sheinbaum-suspende-ma%C3%B1anera-2-noviembre-101624856.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-sentencian-a-cinco-anos-de-prision-a-el-pozoles-senalado-como-lider-de","t":"Sentencian a cinco años de prisión a «El Pozoles», señalado como líder de La Unión Tepito","c":"seguridad","f":"2026-11-02T07:09","r":"Un juez federal condenó a Brayan Mauricio Miranda, «El Pozoles», a cinco años de cárcel y una multa por posesión de narcóticos con fines de comercio. Fue detenido en octubre de 2023 en la colonia Roma Norte con casi medio kilo de marihuana, 538 gramos de metanfetamina y 18.6 gramos de cocaína. La FGR lo identifica como líder de La Unión Tepito; tiene otra orden de aprehensión por desaparición cometida por particulares.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/dictan-sentencia-de-5-anos-contra-el-pozoles-senalado-como-uno-de-los-lideres-de-la-union-tepito/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-sonora-eleva-la-proteccion-civil-a-rango-constitucional-a-un-ano-del-i","t":"Sonora eleva la protección civil a rango constitucional a un año del incendio de Waldo's en Hermosillo","c":"estados","f":"2026-11-02T07:08","r":"El gobernador Alfonso Durazo publicó una reforma que reconoce la protección civil como un derecho humano y crea un instituto autónomo de gestión de riesgos, cuyo titular deberá ratificar el Congreso por dos terceras partes. La reforma, aprobada por unanimidad, se anunció el 1 de noviembre, a un año del incendio en la tienda Waldo's que dejó 24 muertos. «El Estado no tiene derecho a fallar», dijo Durazo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/sonora-eleva-la-proteccion-civil-a-rango-constitucional-un-ano-despues-del-incendio-en-tienda-de-hermosillo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-caen-en-toluca-el-chulo-y-el-gil-senalados-por-extorsionar-y-despojar","t":"Caen en Toluca «El Chulo» y «El Gil», señalados por extorsionar y despojar a una comerciante","c":"estados","f":"2026-11-02T07:07","r":"La Fiscalía del Estado de México detuvo a Erick Jesús «N» y José Alfredo «N», presuntos integrantes de La Nueva Familia Michoacana, acusados de exigir pagos mensuales a una mujer de 59 años, quitarle su bodega en 2025 y agredirla en septiembre pasado. Eran objetivos de la Operación Restitución, que suma 2,876 inmuebles asegurados en 91 municipios y 1,859 devueltos a sus dueños.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/caen-por-extorsion-el-chulo-y-el-gil-operadores-de-la-nueva-familia-michoacana-en-toluca/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-cruz-azul-vence-2-1-al-leon-suma-cuatro-triunfos-seguidos-y-empata-en","t":"Cruz Azul vence 2-1 al León, suma cuatro triunfos seguidos y empata en puntos con América y Chivas","c":"deportes","f":"2026-11-02T07:06","r":"Con goles de Andrés Montaño (56') y José Paradela (72'), Cruz Azul derrotó 2-1 al León en la jornada 15 del Apertura 2026; José Alvarado descontó en el tiempo agregado. La Máquina llegó a 29 puntos, los mismos que América y Chivas, y es tercera por diferencia de goles. León se quedó con 22 unidades.","b":"","img":"estadio","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/deportes/cruz-azul-derrota-2-1-al-leon-y-ya-es-tercero-de-la-liga-mx/"],["Vamos Azul","https://vamoscruzazul.bolavip.com/noticias/tabla-de-posiciones-actualizada-asi-queda-cruz-azul-en-la-jornada-15-del-apertura-2026-axSys1V52miG"],["El Tiempo MX","https://eltiempomx.com/noticia/2026/cruz-azul-vence-2-1-a-leon-y-suma-su-cuarta-victoria-consecutiva.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-mixquic-celebra-esta-noche-su-tradicional-alumbrada-en-el-panteon-de-s","t":"Mixquic celebra esta noche su tradicional Alumbrada en el panteón de San Andrés","c":"cdmx","f":"2026-11-02T07:05","r":"La Alumbrada de San Andrés Mixquic, en Tláhuac, será este lunes 2 de noviembre a partir de las 20:00 horas, cuando las familias encienden velas y copal sobre las tumbas adornadas. Hasta hoy también hay exhibiciones de juego de pelota prehispánico de 18:00 a 21:00 en distintos puntos del pueblo.","b":"","img":"ofrenda","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/sociedad/cuando-es-alumbrada-mixquic-dia-muertos-2026-fechas-y-calendario-actividades-1/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-muere-en-la-ciudad-de-mexico-juan-atkins-pionero-del-techno-de-detroit","t":"Muere en la Ciudad de México Juan Atkins, pionero del techno de Detroit, a los 64 años","c":"entretenimiento","f":"2026-11-02T07:04","r":"El productor Juan Atkins murió la noche del sábado 31 de octubre en la capital, donde tenía programada una presentación; según Billboard, fue hallado inconsciente en su habitación de hotel y su muerte se confirmó en un hospital. Su agencia lo anunció el domingo. No hay causa oficial. Integró el trío Belleville Three, fundó Cybotron y el sello Metroplex, y grabó como Model 500.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/02/de-que-murio-juan-atkins-pionero-del-techno-que-fue-encontrado-sin-vida-en-un-hotel-de-la-cdmx/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-el-papa-leon-xiv-viaja-esta-semana-a-uruguay-argentina-y-peru-en-su-pr","t":"El papa León XIV viaja esta semana a Uruguay, Argentina y Perú en su primera gira por Sudamérica","c":"internacional","f":"2026-11-02T07:03","r":"El Vaticano confirmó que el papa León XIV visitará del 6 al 17 de noviembre diez ciudades: Montevideo, Paysandú y Florida en Uruguay; Buenos Aires, Córdoba y Luján en Argentina, y Lima, Chiclayo, Cuzco y Pucallpa en Perú. La Santa Sede informó que se recupera bien de una cirugía y que no requerirá tratamiento oncológico adicional.","b":"","img":"vaticano","foto":"","cred":"","src":[["NTN24","https://www.ntn24.com/noticias-actualidad/me-llena-de-alegria-regresar-el-papa-leon-xiv-confirma-que-estara-en-sudamerica-desde-el-proximo-6-de-noviembre-661514"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-john-ternus-nuevo-ceo-de-apple-dice-que-la-empresa-no-lanzara-intelige","t":"John Ternus, nuevo CEO de Apple, dice que la empresa no lanzará inteligencia artificial «solo por lanzarla»","c":"tecnologia","f":"2026-11-02T07:02","r":"En una entrevista con Wired, John Ternus, quien sustituyó a Tim Cook el 1 de septiembre, dijo que Apple incorporará IA en sus productos solo cuando aporte valor real a los usuarios. Evitó responder si la compañía va rezagada, planteó que los agentes de IA podrían sustituir algunas aplicaciones y reiteró que la privacidad y la seguridad de los datos siguen como prioridades.","b":"","img":"tech","foto":"","cred":"","src":[["En Blanco y Negro","https://enblancoynegro.com.mx/2026/11/01/nuevo-ceo-de-apple-revela-su-estrategia-con-la-inteligencia-artificial-no-queremos-lanzarla-solo-por-lanzarlajohn/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-02-la-superluna-del-castor-la-luna-llena-mas-brillante-de-2026-se-vera-la","t":"La Superluna del Castor, la luna llena más brillante de 2026, se verá la noche del 24 de noviembre","c":"tecnologia","f":"2026-11-02T07:01","r":"La luna llena de noviembre coincidirá con el perigeo, el punto de su órbita más cercano a la Tierra, por lo que se verá más grande y brillante. Alcanzará su fase llena a las 08:53 del 24 de noviembre, hora del centro de México; como no será visible esa mañana en la capital, se recomienda observarla desde las 18:02 de ese día, cuando sale.","b":"","img":"tech2","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/tendencias/2026/10/30/la-superluna-del-castor-cuando-y-como-ver-la-luna-llena-mas-brillante-del-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-uruapan-marcha-a-un-ano-del-asesinato-de-carlos-manzo-grecia-quiroz-pi","t":"Uruapan marcha a un año del asesinato de Carlos Manzo; Grecia Quiroz pide a Sheinbaum investigar «absolutamente todo»","c":"seguridad","f":"2026-11-01T18:45","r":"Unas 5,000 personas marcharon este domingo en Uruapan, Michoacán, convocadas por la alcaldesa Grecia Quiroz, al cumplirse un año del asesinato de su esposo, el exalcalde Carlos Manzo. Al llegar a la Pérgola Municipal, donde ocurrió el ataque, Quiroz y la madre de Manzo develaron una estatua de bronce. La alcaldesa pidió a la presidenta Sheinbaum una investigación sin límites y aclaró que su exigencia no es partidista. La Fiscalía de Michoacán reporta 33 detenidos y un avance de 90% en el caso; el dirigente estatal de Morena, Jesús Mora, cuestionó los motivos de la marcha.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://infobae.com/mexico/2026/11/01/grecia-quiroz-exige-a-sheinbaum-investigar-hasta-las-ultimas-consecuencias-el-asesinato-de-carlos-manzo"],["Uno TV","https://www.unotv.com/estados/michoacan/a-un-ano-del-asesinato-de-carlos-manzo-actos-conmemorativos-y-avances-de-la-investigacion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-morena-se-deslinda-de-guadalupe-taddei-y-pide-que-su-renuncia-no-cierr","t":"Morena se deslinda de Guadalupe Taddei y pide que su renuncia no cierre las investigaciones en el INE","c":"politica","f":"2026-11-01T18:44","r":"En un comunicado, Morena se deslindó de Guadalupe Taddei tras su renuncia a la presidencia del INE y sostuvo que su llegada al cargo en 2023, por insaculación en la Cámara de Diputados, no fue una designación del partido. Pidió revisar también las administraciones anteriores, incluida la de Lorenzo Córdova, y aclarar quién autorizó los contratos cuestionados, qué proveedores participaron y quién se benefició.","b":"","img":"ine","foto":"","cred":"","src":[["Proyecto Puente","https://proyectopuente.com.mx/2026/11/01/morena-se-deslinda-de-guadalupe-taddei-y-exige-investigar-corrupcion-pasada-y-presente-en-el-ine"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-antonelli-se-corona-campeon-de-la-f1-en-el-autodromo-verstappen-gana-e","t":"Antonelli se corona campeón de la F1 en el Autódromo; Verstappen gana el GP de México y Checo Pérez termina 17","c":"deportes","f":"2026-11-01T18:43","r":"Andrea Kimi Antonelli aseguró su primer título de Fórmula 1 al terminar tercero en el Gran Premio de México, donde le bastaba quedar noveno. Max Verstappen ganó la carrera, su sexta victoria en el Autódromo Hermanos Rodríguez, siete décimas por delante de Lewis Hamilton. La prueba tuvo bandera roja en la vuelta 45 por un choque de Valtteri Bottas. Sergio Pérez, con Cadillac, acabó en el lugar 17 tras una parada lenta y una penalización de cinco segundos por exceso de velocidad en pits.","b":"","img":"autodromo","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/max-verstappen-victoria-mexico-f1-2026-reporte-carrera-antonelli-campeon-checo-perez-resultado"],["Infobae","https://www.infobae.com/mexico/deportes/2026/11/01/gp-mexico-2026-en-vivo-sigue-a-checo-perez-en-la-formula-1-paradas-en-pits-y-la-pelea-por-el-podio-minuto-a-minuto/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-la-opep-mantiene-sin-cambios-sus-cuotas-de-produccion-para-diciembre-p","t":"La OPEP+ mantiene sin cambios sus cuotas de producción de petróleo para diciembre","c":"economia","f":"2026-11-01T18:42","r":"Los siete países del subgrupo de la OPEP+ acordaron este domingo mantener sin cambios sus metas de producción de petróleo para diciembre. Volverán a reunirse el 29 de noviembre, el mismo día en que se prevé la reunión del grupo completo. La decisión llega mientras aumentan los envíos por el estrecho de Ormuz y Arabia Saudita reactivó en octubre una ruta de exportación por el mar Rojo.","b":"","img":"pemex","foto":"","cred":"","src":[["Bloomberg Línea","https://www.bloomberglinea.com/mercados/opep-mantiene-sin-cambios-los-objetivos-de-produccion-de-petroleo-para-diciembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-el-pan-exige-a-morena-asumir-su-responsabilidad-por-la-crisis-del-ine","t":"El PAN exige a Morena asumir su responsabilidad por la crisis del INE y propone revertir la reforma de 2024","c":"politica","f":"2026-11-01T18:41","r":"El dirigente nacional del PAN, Jorge Romero, afirmó que Morena debe asumir su responsabilidad política por la crisis del INE y anunció una contrarreforma para que los nombramientos de directores ejecutivos vuelvan a requerir ocho de 11 votos del Consejo General, requisito que se eliminó en octubre de 2024. También pidió que la Cámara de Diputados elija a quien sustituya a Taddei con un proceso transparente. El PAN presentó el 27 de octubre una denuncia ante la FGR por seis presuntos delitos.","b":"","img":"ine","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/politica/2026/11/1/pan-exige-a-morena-asumir-su-responsabilidad-politica-sobre-taddei-y-la-crisis-del-ine-382959.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-lorenzo-cordova-culpa-a-morena-del-contexto-de-impunidad-en-el-ine-y-d","t":"Lorenzo Córdova culpa a Morena del «contexto de impunidad» en el INE y defiende contratos de su gestión","c":"politica","f":"2026-11-01T18:40","r":"El expresidente del INE Lorenzo Córdova atribuyó a Morena tanto la llegada de Guadalupe Taddei en 2023 como la reforma de octubre de 2024 que debilitó los contrapesos internos del instituto. Sobre los señalamientos en su contra, dijo haber identificado tres contratos con empresas relacionadas por 40 mil, 80 mil y 400 mil pesos, todos por licitación, y se dijo dispuesto a que se revisen de nuevo.","b":"","img":"ine","foto":"","cred":"","src":[["Dossier Político / Aristegui Noticias","https://dossierpolitico.com/2026/11/01/morena-creo-un-contexto-de-impunidad-para-taddei-en-el-ine-cordova/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-iran-negocia-con-mediacion-de-qatar-un-plan-de-dos-dias-para-reabrir-o","t":"Irán negocia con mediación de Qatar un plan de dos días para reabrir Ormuz; Trump dice que no atacará antes de las elecciones","c":"internacional","f":"2026-11-01T18:39","r":"El canciller iraní, Abbas Araghchi, dijo que su país negocia con mediadores un plan de dos días para reabrir el estrecho de Ormuz y que el avance depende de las respuestas de Estados Unidos. La propuesta original, presentada en septiembre ante la ONU, era de siete días. Donald Trump, que mantiene el bloqueo naval, afirmó el sábado que no atacará a Irán antes de las elecciones intermedias del martes y que las pláticas van bien.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Heraldo (Colombia)","https://www.elheraldo.co/mundo/2026/11/01/iran-continua-las-negociaciones-indirectas-con-ee-uu-para-reabrir-ormuz-en-dos-dias/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-ataque-armado-en-un-centro-de-rehabilitacion-de-mazatlan-deja-dos-muer","t":"Ataque armado en un centro de rehabilitación de Mazatlán deja dos muertos y un herido","c":"seguridad","f":"2026-11-01T18:38","r":"Hombres armados dispararon la tarde de este domingo contra un centro de rehabilitación en la colonia Felipe Ángeles, en Mazatlán, Sinaloa. Dos hombres murieron en el lugar y un tercero fue trasladado herido a un hospital. Corporaciones de los tres niveles de gobierno acordonaron la zona; no se han informado detenciones.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Luz Noticias","https://www.luznoticias.mx/2026-11-01/policiaca/ataque-armado-en-mazatlan-deja-dos-muertos-y-un-herido-en-centro-de-rehabilitacion/313024"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-slim-refuerza-su-apuesta-petrolera-zamajal-multiplica-sus-ingresos-y-g","t":"Slim refuerza su apuesta petrolera: Zamajal multiplica sus ingresos y GSM Bronco gana un contrato mixto con Pemex","c":"economia","f":"2026-11-01T18:37","r":"Zamajal, la petrolera de Grupo Carso, reportó ingresos por 2,984.3 millones de pesos en el tercer trimestre, 446.7% más que un año antes, y prepara un programa de inversión para 2027 centrado en los campos Ichalkil y Pokoch. Además, GSM Bronco obtuvo el campo Macavil bajo el esquema de contratos mixtos de Pemex, con un horizonte de desarrollo de 20 años.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/carlos-slim-refuerza-su-apuesta-por-el-petroleo-firma-contratos-con-pemex-e-invierte-en-refinerias-de-estados-unidos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-matan-a-un-taquero-y-hieren-a-otro-hombre-en-un-ataque-en-culiacan","t":"Matan a un taquero y hieren a otro hombre en un ataque en Culiacán","c":"estados","f":"2026-11-01T18:36","r":"Un hombre identificado como Saúl, que trabajaba en el puesto de tacos El Compaye, en la avenida Revolución esquina con Amado Nervo, en Culiacán, murió a balazos alrededor de las 11:00 horas de este domingo. Otro hombre, Jorge Alejandro, resultó herido y recibió atención médica.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín Sinaloa","https://sinaloa.quadratin.com.mx/ataque-en-taqueria-de-culiacan-deja-un-muerto-y-un-herido-2/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-asesinan-a-un-conductor-de-transporte-publico-en-el-ocotito-guerrero","t":"Asesinan a un conductor de transporte público en El Ocotito, Guerrero","c":"estados","f":"2026-11-01T18:35","r":"Un chofer de transporte público identificado como Uriel fue asesinado a tiros dentro de su unidad poco antes de las 7:00 horas de este domingo en la calle principal del centro de El Ocotito, en el municipio de Chilpancingo. La Fiscalía de Guerrero realizó las diligencias en el lugar.","b":"","img":"carretera","foto":"","cred":"","src":[["Azteca Guerrero","https://www.aztecaguerrero.com/policiaca/asesinan-a-conductor-de-transporte-publico-en-el-ocotito/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-asesinan-a-un-comerciante-de-aguacate-en-apatzingan-michoacan","t":"Asesinan a un comerciante de aguacate en Apatzingán, Michoacán","c":"seguridad","f":"2026-11-01T18:34","r":"Un hombre que se dedicaba a la comercialización de aguacate fue asesinado a balazos en la avenida Lucio Blanco, colonia Independencia, en Apatzingán. Policías municipales y de la Guardia Civil lo encontraron sin signos vitales; la Fiscalía de Michoacán investiga el móvil.","b":"","img":"ultimahora","foto":"","cred":"","src":[["A Tiempo","https://atiempo.mx/justicia/asesinan-a-comerciante-de-aguacate-en-apatzingan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-alito-moreno-busca-una-alianza-pri-pan-en-chihuahua-rumbo-a-2027-en-un","t":"Alito Moreno busca una alianza PRI-PAN en Chihuahua rumbo a 2027 en un acto con Maru Campos","c":"politica","f":"2026-11-01T18:33","r":"El dirigente nacional del PRI, Alejandro Moreno, se dijo dispuesto a construir acuerdos con el PAN en Chihuahua durante el informe legislativo del diputado Alejandro Domínguez, al que asistieron la gobernadora Maru Campos y la dirigente panista Daniela Álvarez. No hay todavía un convenio formal de coalición para la gubernatura de 2027.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Quadratín Chihuahua","https://chihuahua.quadratin.com.mx/politica/alito-moreno-busca-concretar-alianza-pri-pan-en-chihuahua-maru-campos-y-daniela-alvarez-coinciden-en-encuentro-politico"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-censo-de-inegi-suben-58-1-las-solicitudes-de-transparencia-sin-respues","t":"Censo de Inegi: suben 58.1% las solicitudes de transparencia sin respuesta en los estados","c":"nacional","f":"2026-11-01T18:32","r":"El Censo Nacional de Transparencia de Inegi reporta que las solicitudes de información pendientes en los organismos estatales pasaron de 93 a 147 entre 2022 y 2024, mientras las recibidas cayeron 32.1%, a 12,488. El gasto de esos organismos llegó a 1,506.6 millones de pesos, 11.5% más. Inegi advirtió que los datos se levantaron durante la transición tras la reforma que extinguió al INAI.","b":"","img":"palacio","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/transparencia-en-mexico-peticiones-sin-respuesta-suben-58-1-y-el-presupuesto-estatal-crece-11-5-reporta-inegi/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-pensionados-del-imss-de-la-ley-de-1973-y-del-issste-recibiran-su-aguin","t":"Pensionados del IMSS de la ley de 1973 y del ISSSTE recibirán su aguinaldo en noviembre","c":"economia","f":"2026-11-01T18:31","r":"El IMSS confirmó que depositará en noviembre el aguinaldo a pensionados por cesantía en edad avanzada o vejez de la ley vigente hasta el 30 de junio de 1997; el monto equivale a una mensualidad de la pensión. Quienes se pensionaron con la ley actual no reciben esta prestación. El ISSSTE también lo paga este mes, junto con la pensión.","b":"","img":"imss","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/economia/cuando-dan-aguinaldo-pensionados-imss-2026-quienes-si-y-quienes-no-cobran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-vinculan-a-proceso-al-presunto-mataperros-de-la-condesa-seguira-en-el","t":"Vinculan a proceso al presunto «mataperros» de la Condesa; seguirá en el Reclusorio Norte","c":"cdmx","f":"2026-11-01T18:30","r":"Un juez de control vinculó a proceso por maltrato animal a Salvador «N», de 58 años, y le dictó prisión preventiva en el Reclusorio Norte. Se le señala de colocar al menos 14 cebos con un insecticida altamente tóxico en calles y parques de la colonia Condesa, donde murieron cuatro perros. El Código Penal capitalino prevé de dos a seis años de prisión por este delito.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-1-de-noviembre-se-cumple-un-ano-del-asesinato-de-carlos-manzo-exalcalde-de-uruapan/"],["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/cuanto-tiempo-podria-pasar-prision-mata-perros-condesa"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-sheinbaum-presenta-el-altar-de-dia-de-muertos-de-palacio-nacional","t":"Sheinbaum presenta el altar de Día de Muertos de Palacio Nacional","c":"nacional","f":"2026-11-01T18:29","r":"La presidenta Claudia Sheinbaum mostró en un video el altar de Día de Muertos instalado en Palacio Nacional, con fotografías, platillos y caminos de cempasúchil, y explicó el origen náhuatl de la flor. «Recordar también es una forma de mantener viva la memoria», dijo.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/sheinbaum-presenta-altar-de-dia-de-muertos-en-palacio-nacional-recordar-tambien-es-mantener-viva-la-memoria/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-trump-dice-que-flavio-bolsonaro-puede-quedarse-en-eu-el-tiempo-que-qui","t":"Trump dice que Flávio Bolsonaro puede quedarse en EU «el tiempo que quiera», tras su salida de Brasil","c":"internacional","f":"2026-11-01T18:28","r":"Desde Mar-a-Lago, Donald Trump afirmó que el senador brasileño Flávio Bolsonaro, quien perdió la elección ante Lula, puede permanecer en Estados Unidos el tiempo que desee, aunque dijo que no planea reunirse con él. Bolsonaro salió de Brasil por Argentina pese a una orden judicial que le prohibía abandonar el país; la cancillería brasileña citó al encargado de negocios argentino.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/01/donald-trump-aseguro-que-flavio-bolsonaro-podra-quedarse-el-tiempo-que-quiera-en-estados-unidos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-sismo-de-magnitud-4-3-sacude-la-costa-de-chiapas-no-se-reportan-danos","t":"Sismo de magnitud 4.3 sacude la costa de Chiapas; no se reportan daños","c":"estados","f":"2026-11-01T18:27","r":"El Servicio Sismológico Nacional registró este domingo un sismo de magnitud 4.3 con epicentro a 68 kilómetros al suroeste de Ciudad Hidalgo, Chiapas, a 11.5 kilómetros de profundidad. No se informaron daños ni personas lesionadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Azteca Veracruz","https://www.aztecaveracruz.com/noticias/se-escucho-un-tronido-sismo-sorprende-a-mexico-este-1-de-noviembre-cual-fue-su-magnitud/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-conade-entrega-el-premio-nacional-de-deportes-2026-a-12-ganadores-cues","t":"Conade entrega el Premio Nacional de Deportes 2026 a 12 ganadores; cuestionan que rebasó lo previsto en la convocatoria","c":"deportes","f":"2026-11-01T18:26","r":"La Conade anunció a 12 ganadores del Premio Nacional de Deportes 2026 en siete categorías, entre ellos Isaac del Toro en deporte profesional y Guillermo Ochoa en trayectoria. Un análisis de Infobae señala que cuatro categorías superaron el número de premios que fijaba la convocatoria.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/conade-ignoro-su-propio-reglamento-al-anunciar-a-los-ganadores-del-premio-nacional-de-deportes-2026-sin-respetar-la-convocatoria/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-sheinbaum-los-trenes-de-pasajeros-y-la-vivienda-aportan-cerca-de-un-pu","t":"Sheinbaum: los trenes de pasajeros y la vivienda aportan cerca de un punto del PIB este año","c":"economia","f":"2026-11-01T06:45","r":"Al supervisar el tramo Querétaro-Irapuato del tren México-Querétaro-Guanajuato, la presidenta Claudia Sheinbaum atribuyó parte del crecimiento de 3.2% anual del tercer trimestre, reportado por el Inegi, a la obra pública y la vivienda, que según dijo suman cerca de un punto del PIB en 2026. Andrés Lajous informó que el tramo mide unos 102 kilómetros, tendrá estaciones en Apaseo, Celaya, Cortazar, Villagrán, Salamanca e Irapuato y genera más de 9 mil empleos; el primer tren a Querétaro llegaría en junio de 2027 para iniciar pruebas.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/trenes-de-pasajeros-y-vivienda-impulsan-la-economia-de-mexico-sheinbaum-destaca-crecimiento-del-pib/"],["El Universal","https://www.eluniversal.com.mx/nacion/sheinbaum-supervisa-obras-del-tren-queretaro-irapuato-la-acompanan-kuri-y-libia-dennise/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-senadores-de-morena-impulsaran-una-reforma-al-articulo-41-para-blindar","t":"Senadores de Morena impulsarán una reforma al artículo 41 para blindar al INE contra la corrupción","c":"politica","f":"2026-11-01T06:44","r":"Tras la renuncia de Guadalupe Taddei a la presidencia del INE el 26 de octubre, la bancada de Morena en el Senado anunció que promoverá una reforma constitucional al artículo 41 con candados contra la corrupción y los conflictos de interés en el instituto. El senador Manuel Huerta planteó además impedir que exconsejeros se afilien a partidos o creen nuevas fuerzas políticas al dejar el cargo, y dijo que los problemas podrían ser anteriores a la gestión de Taddei. Se trata de una propuesta; no hay iniciativa votada.","b":"","img":"ine","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/mexico/morena-propone-reformar-ley-del-ine-para-combatir-corrupcion-y-limitar-facultades/"],["La Jornada","https://www.jornada.com.mx/2026/10/31/politica/004n3pol?partner=rss"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-termina-el-horario-de-verano-en-la-frontera-norte-baja-california-y-41","t":"Termina el horario de verano en la frontera norte: Baja California y 41 municipios atrasan el reloj una hora","c":"nacional","f":"2026-11-01T06:43","r":"A las 2:00 de este domingo 1 de noviembre terminó el horario estacional en la franja fronteriza, por lo que los relojes se atrasaron una hora. El ajuste aplica en todo Baja California y en 41 municipios de Chihuahua, Coahuila, Nuevo León, Tamaulipas y Sonora (en Nuevo León solo Anáhuac); el resto del país no cambia de horario.","b":"","img":"palacio","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/cambio-de-horario-2026-cuando-se-atrasa-el-reloj-y-en-que-estados-y-municipios-de-mexico/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-lluvias-de-hasta-75-mm-en-baja-california-y-sonora-mexicali-abre-cinco","t":"Lluvias de hasta 75 mm en Baja California y Sonora; Mexicali abre cinco albergues","c":"nacional","f":"2026-11-01T06:42","r":"El Servicio Meteorológico Nacional prevé para este domingo lluvias de 50 a 75 milímetros en el norte y centro de Baja California y el norte y oeste de Sonora por un río atmosférico y una vaguada en altura, y de 25 a 50 mm en el norte de Baja California Sur. La Protección Civil de Baja California instaló cinco albergues en la ciudad y el valle de Mexicali, alertó por rachas de 40 a 60 km/h y temperaturas de hasta 5 grados bajo cero en zonas de montaña, y pidió no cruzar arroyos ni calles inundadas.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/baja-california-activa-cinco-albergues-ante-pronostico-de-lluvias-intensas-preven-acumulados-superiores-a-50-milimetros/"],["Infobae (SMN)","https://www.infobae.com/mexico/2026/11/01/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-domingo-1-de-noviembre-lluvias-muy-fuertes-en-baja-california-y-sonora/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-01-emboscan-a-una-patrulla-del-ejercito-en-ario-de-rosales-michoacan-un-m","t":"Emboscan a una patrulla del Ejército en Ario de Rosales, Michoacán: un militar muerto y dos heridos","c":"seguridad","f":"2026-11-01T06:41","r":"En la madrugada del sábado 31 de octubre, presuntos integrantes de un grupo criminal dispararon con rifles de asalto desde la maleza contra vehículos de la 5ª Compañía de Infantería No Encuadrada, de la XXI Zona Militar, cerca de El Ortigal, en Ario de Rosales. Un militar murió y dos resultaron heridos y fueron llevados a un hospital militar, según la Guardia Civil. Los atacantes huyeron y se desplegó un operativo de búsqueda en la zona y municipios vecinos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Latinus","https://latinus.us/mexico/2026/10/31/ataque-armado-en-contra-de-militares-deja-un-elemento-muerto-y-dos-heridos-en-michoacan-181130.html"],["La Prensa de Coahuila","https://laprensadecoahuila.com.mx/2026/10/31/ataque-armado-en-michoacan-cobra-la-vida-de-militar-y-deja-dos-lesionados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-ormuz-la-armada-irani-reporta-el-incendio-de-otro-petrolero-tras-choca","t":"Ormuz: la Armada iraní reporta el incendio de otro petrolero tras chocar con una mina","c":"internacional","f":"2026-11-01T06:40","r":"La Armada de Irán informó el sábado por la noche que un petrolero se incendió al chocar con una mina al este del estrecho de Ormuz, en una zona que calificó de prohibida; no identificó la bandera ni reportó víctimas. Irán contabiliza al menos 26 incidentes con barcos en tres semanas, 20 de ellos por minas. Mientras tanto, Donald Trump dijo en Mar-a-Lago que EU no tiene «tanta prisa» por cerrar un acuerdo con Teherán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/01/la-armada-irani-informa-del-incendio-de-otro-petrolero-tras-chocar-con-una-mina-en-ormuz/"],["Moncloa.com","https://www.moncloa.com/2026/11/01/trump-iran-negociaciones-ataques-3n-3459461/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-trump-confia-en-sorprender-en-las-intermedias-pese-a-una-aprobacion-de","t":"Trump confía en «sorprender» en las intermedias pese a una aprobación de 31% en la encuesta Reuters/Ipsos","c":"internacional","f":"2026-11-01T06:39","r":"A menos de 72 horas de los comicios del martes 3 de noviembre, Donald Trump dijo en una fiesta de Halloween en Mar-a-Lago que a los republicanos les irá «muy bien» y que retomará mítines en Iowa y Kansas este domingo. La encuesta Reuters/Ipsos le da 31% de aprobación, y Decision Desk asigna a los demócratas 80% de probabilidad de recuperar la Cámara de Representantes y 57% de ganar el Senado, hoy con 219 y 53 escaños republicanos, respectivamente.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/01/donald-trump-mostro-su-optimismo-de-cara-a-las-elecciones-de-medio-termino-en-estados-unidos-nos-ira-muy-bien/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-muere-rosina-del-villar-dirigente-de-morena-en-baja-california","t":"Muere Rosina del Villar, dirigente de Morena en Baja California","c":"politica","f":"2026-11-01T06:38","r":"La presidenta del comité estatal de Morena en Baja California, Rosina del Villar, falleció la tarde del sábado 31 de octubre en el Hospital General número 1 del IMSS en Tijuana, donde estaba internada tras sufrir una caída. Las autoridades no han informado oficialmente la causa de la muerte.","b":"","img":"palacio","foto":"","cred":"","src":[["Punto Norte","https://puntonorte.info/2026/10/31/muere-en-el-imss-rosina-del-villar-la-dirigente-estatal-de-morena"],["Grupo Animal","https://grupoanimal.mx/baja-california/politica/morena-rosina-el-villar-fallecimiento-baja-california"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-ataques-en-mazatlan-y-culiacan-durante-la-noche-de-halloween-detienen","t":"Ataques en Mazatlán y Culiacán durante la noche de Halloween; detienen a un hombre por un feminicidio","c":"seguridad","f":"2026-11-01T06:37","r":"El sábado 31 de octubre, en Mazatlán, un joven de 18 años murió baleado en el fraccionamiento Santa Fe y en la colonia Jaripillo un hombre fue asesinado dentro de un taller de motocicletas; además, un grupo armado intentó entrar a instalaciones de la Jumapam sin causar daños. En Culiacán atacaron a balazos a un repartidor en motocicleta e incendiaron una casa en Colinas de San Miguel. La Fiscalía de Sinaloa informó la detención de un hombre por un feminicidio en Culiacán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Línea Directa","https://lineadirectaportal.com/policiaca/autoridades-despliegan-operativos-preventivos-y-atienden-reportes-este-31-de-octubre-en-sinaloa-2026-11-01__1731428"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-la-opep-decide-hoy-si-mueve-su-produccion-de-diciembre-con-el-brent-ar","t":"La OPEP+ decide hoy si mueve su producción de diciembre con el Brent arriba de 110 dólares","c":"economia","f":"2026-11-01T06:36","r":"Ministros de siete países de la OPEP+ —Arabia Saudita, Rusia, Irak, Kuwait, Kazajistán, Argelia y Omán— se reúnen este domingo por videoconferencia para decidir el bombeo de diciembre. El Brent cerró la semana en 114.8 dólares, subió cerca de 15% en octubre y acumula más de 60% desde finales de febrero; los analistas prevén que el grupo congele su oferta por tercer mes. La conferencia ministerial completa será el 29 de noviembre.","b":"","img":"pemex","foto":"","cred":"","src":[["Radio Mundial (EFE)","https://radiomundial.com.ve/la-opep-evalua-si-modifica-su-produccion-petrolera-en-diciembre/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/01/temas-del-dia-de-efe-internacional-del-domingo-1-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-diputada-berenice-martinez-deja-morena-por-mc-movimiento-ciudadano-ya","t":"Diputada Berenice Martínez deja Morena por MC; Movimiento Ciudadano ya es la mayor bancada del Congreso de Nuevo León","c":"estados","f":"2026-11-01T06:35","r":"Berenice Martínez Díaz, hija de la senadora Judith Díaz, se sumó a Movimiento Ciudadano y denunció gritos, insultos y amenazas dentro de la bancada morenista. Con ella, MC tiene 12 diputados frente a 11 del PAN, 11 del PRI y 5 de Morena, que empezó la legislatura con 9; es la cuarta baja de Morena en menos de cuatro semanas. Ningún partido alcanza los 28 votos para reformas constitucionales o para superar vetos del gobernador Samuel García.","b":"","img":"palacio","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/estados/2026/10/31/diputada-deja-a-morena-por-mc-y-altera-equilibro-legislativo-en-nuevo-leon-382905.html"],["ABC Noticias","https://abcnoticias.mx/local/2026/10/31/movimiento-ciudadano-suma-a-berenice-martinez-y-deja-a-morena-sin-una-diputada-en-el-congreso-de-nl-294066.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-rusia-vuelve-a-golpear-la-red-electrica-de-ucrania-drones-ucranianos-d","t":"Rusia vuelve a golpear la red eléctrica de Ucrania; drones ucranianos dañan una refinería en Nizhni Nóvgorod","c":"internacional","f":"2026-11-01T06:34","r":"Más de 650 localidades de la región de Zhitómir quedaron sin luz y casi 100 mil usuarios seguían sin electricidad en Dnipropetrovsk la mañana del domingo tras ataques rusos; en Kiev hubo cortes de emergencia. Por su parte, el gobernador de Nizhni Nóvgorod informó que más de 100 drones fueron derribados y que una empresa industrial de Kstovo sufrió daños graves; medios independientes la identificaron como una refinería de Lukoil. En Jersón expira este domingo el alto el fuego pactado para evacuar a civiles de Oleshki.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/01/rusia-ataca-infraestructura-electrica-en-varias-regiones-de-ucrania/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/01/temas-del-dia-de-efe-internacional-del-domingo-1-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-antonelli-puede-coronarse-hoy-en-el-autodromo-le-basta-terminar-noveno","t":"Antonelli puede coronarse hoy en el Autódromo: le basta terminar noveno en el GP de México","c":"deportes","f":"2026-11-01T06:33","r":"Kimi Antonelli llega a la carrera de las 14:00 con 365 puntos, 123 más que George Russell y 124 más que Lewis Hamilton, por lo que un noveno lugar le da el título. Con 20 años y 68 días sería el campeón más joven de la Fórmula 1 y superaría la marca de Sebastian Vettel (23 años y 134 días, en 2010). Los organizadores preparan un festejo con mariachi si el italiano se corona en el Hermanos Rodríguez.","b":"","img":"autodromo","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/deportes/gp-de-mexico-2026-kimi-antonelli-a-un-paso-de-ser-el-campeon-mas-joven-de-la-f1-que-necesita-para-coronarse/"],["Excélsior","https://www.excelsior.com.mx/deportes/gp-ciudad-mexico-alista-festejo-especial-para-posible-coronacion-antonelli"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-america-empata-2-2-con-toluca-y-comparte-el-liderato-con-chivas-ambos","t":"América empata 2-2 con Toluca y comparte el liderato con Chivas, ambos con 29 puntos","c":"deportes","f":"2026-11-01T06:32","r":"En la jornada 15 del Apertura 2026, Federico Viñas adelantó al Toluca al minuto 41; Henry Martín empató al 62, Alexis Vega puso el 2-1 para los Diablos tras revisión del VAR y Henry Martín igualó de penal. Santiago Bueno, del América, fue expulsado al 81 y se perderá el Clásico ante Pumas; Andrés Pereira, del Toluca, también vio la roja. Toluca es quinto con 24 puntos.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/america-sobrevive-diabluras-toluca-expone-liderato"],["ESPN","https://www.espn.com/soccer/match/_/gameId/401876913"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-chivas-vence-4-2-al-atlante-con-doblete-de-santiago-sandoval-y-alcanza","t":"Chivas vence 4-2 al Atlante con doblete de Santiago Sandoval y alcanza los 29 puntos","c":"deportes","f":"2026-11-01T06:31","r":"En el Estadio Akron, Santiago Sandoval anotó a los minutos 8 y 53, y Efraín Álvarez marcó al 64 en la victoria del Guadalajara, que también se benefició de un autogol; Martín Sarrafiore y Jhojan Julio, de penal, descontaron para Atlante. En otros partidos del sábado, Pachuca goleó 3-0 a Tigres y Monterrey empató 1-1 con Tijuana. Este domingo juegan Santos-Necaxa y Cruz Azul-León.","b":"","img":"estadio","foto":"","cred":"","src":[["Plaza de Armas","https://plazadearmas.com.mx/chivas-golea-y-asalta-el-liderato-del-apertura-2026/"],["Fox Sports","https://www.foxsports.com.mx/2026/10/31/asi-marcha-la-tabla-general-del-apertura-2026-de-la-liga-mx-resultados-y-liguilla-al-momento/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-larry-page-supera-a-michael-dell-y-es-la-tercera-persona-mas-rica-del","t":"Larry Page supera a Michael Dell y es la tercera persona más rica del mundo, según Forbes","c":"economia","f":"2026-11-01T06:30","r":"El cofundador de Google sumaba unos 234,400 millones de dólares, frente a 229,200 millones de Michael Dell, cuya fortuna cayó unos 17,500 millones después de que las acciones de Dell Technologies bajaran más de 10% tras el débil pronóstico de Intel. La sesión también restó unos 30 mil millones a Elon Musk, cuya fortuna ronda los 886,800 millones, en medio de dudas de los inversionistas sobre la rentabilidad del gasto en inteligencia artificial.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/10/31/larry-page-cofundador-de-google-se-convierte-en-la-tercera-persona-mas-rica-del-mundo-y-desplaza-a-michael-dell/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-familiares-de-un-operador-de-grua-asesinado-en-naucalpan-protestan-con","t":"Familiares de un operador de grúa asesinado en Naucalpan protestan con su ataúd en Periférico Norte","c":"estados","f":"2026-11-01T06:29","r":"Familiares, amigos y unos 200 transportistas se reunieron cerca del Parque Naucalli con el féretro de Raúl Fernández Fernández, operador de grúa que, según sus allegados, fue atacado en Lomas Verdes por negarse a pagar una cuota de extorsión. Exigieron a la Fiscalía del Estado de México detener a los responsables.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-31-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-preven-diez-concentraciones-en-la-cdmx-este-domingo-de-dia-de-muertos","t":"Prevén diez concentraciones en la CDMX este domingo de Día de Muertos, la mayoría en la Cuauhtémoc","c":"cdmx","f":"2026-11-01T06:28","r":"Para este 1 de noviembre se anunciaron diez actos en la capital, varios con ofrendas: familias de víctimas de feminicidio marcharán a las 16:00 del Hemiciclo a Juárez al Antimonumento contra el Feminicidio por avenida Juárez, el Comité 68 montará un altar en Tlatelolco y otros colectivos instalarán ofrendas en el Zócalo, la Cineteca y el INPI. Se prevén afectaciones viales, sobre todo en avenida Juárez.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/01/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-1-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-netflix-estrena-la-caida-de-el-mayo-serie-documental-sobre-la-captura","t":"Netflix estrena «La caída de El Mayo», serie documental sobre la captura de Ismael Zambada","c":"entretenimiento","f":"2026-11-01T06:27","r":"La miniserie de tres episodios, dirigida por Darren Foster y Miguel Fernández Flores, reconstruye cómo Ismael «El Mayo» Zambada llegó en julio de 2024 a un aeródromo de Nuevo México junto a Joaquín Guzmán López, y plantea si fue un secuestro, una traición o una operación secreta. Incluye testimonios de agentes, políticos, periodistas y familias afectadas por la violencia, además de expedientes judiciales de México y EU.","b":"","img":"estudio","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/espectaculos/2026/10/15/netflix-estrenara-la-caida-de-el-mayo-este-29-de-octubre-de-que-trata-la-serie/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/01/temas-del-dia-de-efe-internacional-del-domingo-1-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-01-detectan-319-extensiones-maliciosas-de-chrome-con-13-4-millones-de-des","t":"Detectan 319 extensiones maliciosas de Chrome con 13.4 millones de descargas que desvían las búsquedas","c":"tecnologia","f":"2026-11-01T06:26","r":"El investigador John Tuckner, de Socket, identificó extensiones que se presentaban como convertidores de PDF, buscadores con IA o herramientas de navegación segura y que cambiaban el buscador predeterminado para pasar las consultas por servidores de sus operadores y cobrar publicidad. Muchas ya fueron retiradas de la Chrome Web Store, pero se recomienda revisar permisos y eliminar extensiones desconocidas si el buscador cambia sin autorización.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/10/31/detectan-319-extensiones-maliciosas-de-google-chrome-que-manipulan-las-busquedas-y-ponen-en-riesgo-a-millones-de-usuarios/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-canelo-alvarez-vence-por-decision-unanime-a-christian-mbilli-en-riad-y","t":"Canelo Álvarez vence por decisión unánime a Christian Mbilli en Riad y recupera el título supermediano del CMB","c":"deportes","f":"2026-10-31T18:45","r":"El tapatío ganó en las tres tarjetas (115-112, 116-111 y 117-110) tras 12 asaltos en Riad, Arabia Saudita, y volvió a ceñirse el cinturón de las 168 libras del Consejo Mundial de Boxeo. Álvarez había perdido sus cuatro cinturones supermedianos ante Terence Crawford en septiembre de 2025 y no gana por nocaut desde su pelea contra Caleb Plant en 2021.","b":"","img":"estadio","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/boxeo/resultado-de-las-tarjetas-canelo-alvarez-vs-mbilli-asi-fue-la-decision-para-el-titulo-del-mexicano/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/canelo-alvarez-derrota-a-christian-mbilli-y-recupera-el-campeonato-mundial-supermediano-del-cmb"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-el-tren-mexico-queretaro-lleva-32-de-avance-el-gobierno-preve-construi","t":"El Tren México-Querétaro lleva 32% de avance; el gobierno prevé construir unos 2,500 km de vías con 700 mil millones de pesos","c":"nacional","f":"2026-10-31T18:44","r":"Al supervisar la obra en Polotitlán, Estado de México, la presidenta Claudia Sheinbaum informó que el tren va conforme al programa y que ya se tiene 90% del derecho de vía. La ruta de unos 230 km irá de Buenavista a Querétaro, con estaciones en Tula y San Juan del Río, 47 trenes diésel-eléctricos que se fabrican en Ciudad Sahagún y un trayecto estimado de dos horas. La obra está a cargo de ingenieros militares de la Defensa.","b":"","img":"carretera","foto":"","cred":"","src":[["Informador","https://www.informador.mx/mexico/tren-mexico-queretaro-sheinbaum-reporta-un-avance-del-32-en-el-proyecto-ferroviario-20261031-0101.html"],["Por Esto","https://poresto.com/mexico/2026/10/31/presidenta-mexico-anuncia-inversion-mil-mdp-trenes-mexico-queretaro-alcanza-avance.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-los-ingresos-del-gobierno-caen-2-8-real-a-septiembre-los-petroleros-se","t":"Los ingresos del gobierno caen 2.8% real a septiembre; los petroleros se desploman 21.5%","c":"economia","f":"2026-10-31T18:43","r":"De enero a septiembre los ingresos presupuestarios sumaron 6.30 billones de pesos, según Hacienda; solo en septiembre bajaron 28.4%. Los ingresos petroleros cayeron 21.5% por la alta base de 2025, cuando el gobierno inyectó capital extraordinario a Pemex; el ISR bajó 5.3% y el IEPS de combustibles 9.2% por los estímulos que dejaron de recaudar unos 80 mil millones de pesos. Hacienda mantiene la meta de cerrar el año con un déficit de 4.1% del PIB.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/menos-dinero-para-mexico-en-2026-hacienda-reporta-caida-de-los-ingresos-petroleros-isr-y-del-ieps/"],["Forbes México","https://forbes.com.mx/ingresos-publicos-caen-28-en-septiembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-remanentes-de-vance-dejan-dos-muertos-en-guaymas-y-obligan-a-evacuar-u","t":"Remanentes de Vance dejan dos muertos en Guaymas y obligan a evacuar una clínica del IMSS en San José del Cabo","c":"estados","f":"2026-10-31T18:42","r":"Dos hombres murieron en Guaymas, Sonora, cuando la corriente arrastró su auto bajo un puente cerca del bulevar Tetabiate. En San José del Cabo, Baja California Sur, el agua rebasó las barreras de la clínica 6 del IMSS, que fue desalojada, y los bomberos rescataron a 12 personas; en Elota, Sinaloa, unas 50 personas fueron llevadas a un albergue. El SMN prevé más lluvias fuertes en el noroeste con el frente frío 4.","b":"","img":"lluvia","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/31/estados/022n1est"],["SinEmbargo","https://www.sinembargo.mx/4896677/lluvias-golpean-a-sonora-sinaloa-y-bcs-reportan-2-muertos-inundaciones-y-mas-danos/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-la-deuda-publica-amplia-llega-a-19-55-billones-de-pesos-52-6-del-pib-e","t":"La deuda pública amplia llega a 19.55 billones de pesos, 52.6% del PIB; el déficit sube 23.1% a septiembre","c":"economia","f":"2026-10-31T18:41","r":"El Saldo Histórico de los Requerimientos Financieros del Sector Público creció 5.3% nominal frente a diciembre de 2025, según el informe trimestral de Hacienda. El déficit presupuestario fue de 968,533 millones de pesos, aunque quedó por debajo de lo programado por menor gasto; el costo financiero bajó 3.7% real y la inversión física creció 8%. Hacienda prevé cerrar 2026 con una deuda de 54% del PIB.","b":"","img":"bolsa","foto":"","cred":"","src":[["Poder y Crítica","https://www.poderycritica.com/aumenta-4-5-la-deuda-publica-de-mexico-e-ingresos-del-gobierno-caen-2-8-a-septiembre/"],["Hoja de Ruta Digital","https://hojaderutadigital.mx/informes-sobre-la-situacion-economica-las-finanzas-publicas-y-la-deuda-publica-al-tercer-trimestre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-hamilton-logra-la-pole-del-gp-de-mexico-con-ferrari-checo-perez-saldra","t":"Hamilton logra la pole del GP de México con Ferrari; Checo Pérez saldrá en el lugar 21","c":"deportes","f":"2026-10-31T18:40","r":"Lewis Hamilton marcó 1:16.514 en el Autódromo Hermanos Rodríguez, nueve milésimas mejor que George Russell; detrás saldrán Charles Leclerc, el líder Kimi Antonelli y Max Verstappen. Sergio Pérez, de Cadillac, quedó eliminado en la Q1 y arrancará penúltimo. La carrera es este domingo a las 14:00, y Antonelli podría asegurar el título con un noveno lugar.","b":"","img":"autodromo","foto":"","cred":"","src":[["TUDN","https://www.tudn.com/formula-1/lewis-hamilton-logra-pole-position-en-gp-de-mexico-en-que-lugar-saldra-checo-perez"],["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/10/31/resultados-qualy-gp-mexico-2026-parrilla-de-salida-checo-perez/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-sheinbaum-pide-a-la-sep-construir-mas-preparatorias-en-celaya-al-entre","t":"Sheinbaum pide a la SEP construir más preparatorias en Celaya al entregar becas Benito Juárez","c":"politica","f":"2026-10-31T18:39","r":"En el CBTIS 198 de Celaya, Guanajuato, la presidenta dijo que la meta es que ningún joven deje la escuela por falta de dinero e instruyó al secretario Mario Delgado a coordinarse con la gobernadora Libia Dennise García y el alcalde Juan Miguel Ramírez para abrir más planteles. Después revisó el proyecto del tren Querétaro-Irapuato en la estación de Celaya.","b":"","img":"estudio","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/guanajuato/estado/2026/10/31/sheinbaum-pide-al-titular-de-la-sep-y-a-libia-dennise-construir-mas-preparatorias-en-celaya-535462.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-sheinbaum-busca-duplicar-la-matricula-de-la-universidad-rosario-castel","t":"Sheinbaum busca duplicar la matrícula de la Universidad Rosario Castellanos a 240 mil alumnos en 2030","c":"nacional","f":"2026-10-31T18:38","r":"Al inaugurar un plantel en Tecozautla, Hidalgo, la presidenta dijo que la universidad pasará de 120 mil a al menos 240 mil estudiantes durante el sexenio. El nuevo campus tiene 300 alumnos en Medicina, Turismo Comunitario, Administración y Derecho; la rectora Alma Herrera anunció que en marzo de 2027 se abrirá Ciencias Agroecológicas y Ganadería Sustentable.","b":"","img":"unam","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/sheinbaum-revela-que-busca-duplicar-la-matricula-de-la-universidad-nacional-rosario-castellanos-hasta-240-mil-alumnos-para-el-2030/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-unos-1-6-millones-de-personas-asisten-al-decimo-gran-desfile-de-dia-de","t":"Unos 1.6 millones de personas asisten al décimo Gran Desfile de Día de Muertos en la CDMX","c":"cdmx","f":"2026-10-31T18:37","r":"El recorrido, con unos 4 mil artistas, salió a las 14:00 de la Diana Cazadora y terminó en el Zócalo, con homenajes a Juan Gabriel y a Emilio \"Indio\" Fernández. La SSC desplegó 1,572 policías, drones y un helicóptero; no se reportaron incidentes. Las celebraciones de Día de Muertos dejarían unos 53 mil millones de pesos en el país, 7% más que en 2025.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Aristegui Noticias","https://aristeguinoticias.com/3110/kiosko/desfile-de-dia-de-muertos-reune-a-1-6-millones-en-cdmx/"],["Uno TV","https://www.unotv.com/turismo/en-vivo-asi-se-vive-el-gran-desfile-de-dia-de-muertos-en-la-ciudad-de-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-garcia-harfuch-gradua-en-campeche-a-166-elementos-de-la-marina-y-la-ss","t":"García Harfuch gradúa en Campeche a 166 elementos de la Marina y la SSPC para combatir al crimen organizado","c":"seguridad","f":"2026-10-31T18:36","r":"En el centro de adiestramiento de Infantería de Marina en Champotón se graduaron 152 marinos y 14 integrantes de la Unidad Nacional de Operaciones de la SSPC, la primera vez que esta participa, en cinco especialidades como paracaidismo y operaciones urbanas. El secretario de Seguridad dijo que el crimen organizado corrompe y daña al país, y pidió a los graduados actuar con \"disciplina, inteligencia y respeto a la ley\".","b":"","img":"palacio","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/campeche/2026/10/31/harfuch-encabeza-campeche-ceremonia-graduacion-elementos-especializados-combatir-crimen-organizado.html"],["Informador","https://www.informador.mx/mexico/harfuch-crimen-organizado-corrompe-y-hace-dano-a-mexico-20261031-0099.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-ines-gomez-mont-sigue-bajo-custodia-de-ice-en-el-broward-transitional","t":"Inés Gómez Mont sigue bajo custodia de ICE en el Broward Transitional Center de Florida","c":"seguridad","f":"2026-10-31T18:35","r":"El registro de detenidos de ICE consultado este sábado ubica a la exconductora en ese centro de Pompano Beach. En México tiene una orden de aprehensión por presunta defraudación fiscal equiparada y es investigada también por delincuencia organizada, peculado y operaciones con recursos de procedencia ilícita; la FGR atribuyó su aseguramiento al intercambio de información con EU.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/donde-esta-ines-gomez-mont-este-es-el-centro-de-ice-en-florida-donde-permanece-detenida/"],["La Razón","https://www.razon.com.mx/entretenimiento/2026/10/31/ines-gomez-mont-permanece-detenida-en-centro-migratorio-de-florida/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-gasolinas-cierran-octubre-con-la-magna-en-23-70-pesos-por-litro-hacien","t":"Gasolinas cierran octubre con la Magna en 23.70 pesos por litro; Hacienda mantiene 100% de estímulo al diésel","c":"economia","f":"2026-10-31T18:34","r":"Según PetroIntelligence, este sábado el litro de Magna promedió 23.699 pesos, la Premium 28.597 y el diésel 26.994. Para la semana del 31 de octubre al 6 de noviembre, Hacienda fijó en el DOF un estímulo fiscal de 43.56% para la Magna, 45.45% para la Premium y 100% para el diésel, con lo que este no paga IEPS.","b":"","img":"pemex","foto":"","cred":"","src":[["Línea Directa","https://lineadirectaportal.com/mexico/precios-de-terror-con-estos-costos-octubre-despide-a-los-combustibles-en-mexico-2026-10-31__1731134"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-ceci-flores-pide-a-sheinbaum-y-a-durazo-reforzar-una-tecnica-forense-p","t":"Ceci Flores pide a Sheinbaum y a Durazo reforzar una técnica forense para identificar cuerpos por sus tatuajes","c":"nacional","f":"2026-10-31T18:33","r":"La fundadora de Madres Buscadoras de Sonora solicitó ampliar el uso de la técnica de rehidratación cadavérica del doctor Alejandro Hernández Cárdenas, que permite recuperar tatuajes en cuerpos en descomposición, para acelerar identificaciones. Afirmó que hay miles de cuerpos sin identificar en el país.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/ceci-flores-pide-a-sheinbaum-y-alfonso-durazo-reforzar-tecnica-forense-que-permite-identificar-cuerpos-a-traves-de-tatuajes/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-iran-descarta-reunirse-con-eu-mientras-un-superpetrolero-choca-con-una","t":"Irán descarta reunirse con EU mientras un superpetrolero choca con una mina en Ormuz","c":"internacional","f":"2026-10-31T18:32","r":"El canciller Abbas Araghchi dijo a Al Jazeera que no hay planes de reunión con funcionarios estadounidenses, pese a que Trump afirmó que el diálogo sigue. La Guardia Revolucionaria informó que un superpetrolero con más de 2 millones de barriles sufrió una explosión al tocar una mina; Irán contabiliza 26 incidentes con buques en tres semanas. El canciller alemán Friedrich Merz estimó el costo de la guerra para Europa en más de 100 mil millones de euros.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/31/el-regimen-de-iran-cerro-las-puertas-a-las-negociaciones-con-eeuu-no-hay-planes-de-reunion/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-ataques-rusos-dejan-sin-luz-a-280-mil-hogares-en-ucrania-drones-ucrani","t":"Ataques rusos dejan sin luz a 280 mil hogares en Ucrania; drones ucranianos incendian una refinería en Ufa","c":"internacional","f":"2026-10-31T18:31","r":"Unos 200 mil hogares de Dnipropetrovsk y 80 mil de la región de Kiev perdieron la electricidad; Zelenski acusó a Rusia de atacar infraestructura civil. Moscú dijo haber derribado 433 drones sobre 19 regiones, y en Briansk murieron dos personas. Ucrania atacó la refinería Bashneft-Novoil, su primera operación de ese tipo en casi un mes.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Filo News","https://www.filo.news/noticia/2026/10/31/rusia-ataco-instalaciones-energeticas-de-ucrania-y-dejo-a-280-000-familias-sin-luz"],["Diario Crónica","https://www.diariocronica.com.ar/noticias/2026/10/31/175365-ataques-cruzados-con-drones-destruyen-infraestructura-energetica-en-ucrania-y-refinerias-en-rusia"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-a-tres-dias-de-las-elecciones-intermedias-en-eu-ya-votaron-por-anticip","t":"A tres días de las elecciones intermedias en EU ya votaron por anticipado casi 40 millones de personas","c":"internacional","f":"2026-10-31T18:30","r":"Hasta el 29 de octubre se habían emitido 39.6 millones de votos anticipados. Una encuesta de Cygnal da a los demócratas 52% de intención de voto frente a 43% de los republicanos, y la aprobación de Trump está en 33%. Un juez federal en California rechazó apartar hasta 20 mil boletas de presuntos no ciudadanos, como pedía el Departamento de Justicia, que apelará.","b":"","img":"texas","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/estados-unidos/washington/midterms-usa-2026-en-vivo-como-llega-donald-trump-a-las-elecciones-y-quien-gana-entre-democratas-y-nid30102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-detienen-en-tulancingo-al-exsecretario-de-seguridad-de-aquixtla-puebla","t":"Detienen en Tulancingo al exsecretario de Seguridad de Aquixtla, Puebla, acusado de tortura y robo","c":"estados","f":"2026-10-31T18:29","r":"La Procuraduría de Hidalgo, en coordinación con la Fiscalía de Puebla, cumplió una orden de aprehensión contra Luis Miguel \"N\" en la colonia Centro de Tulancingo. Se le acusa de tortura, robo agravado y tratos crueles contra dos personas.","b":"","img":"carretera","foto":"","cred":"","src":[["Informador","https://informador.mx/mexico/cae-en-hidalgo-luis-miguel-n-exsecretario-de-seguridad-de-aquixtla-puebla-20261031-0100.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-quad-anuncia-mas-de-85-millones-de-dolares-para-llevar-inteligencia-ar","t":"Quad anuncia más de 85 millones de dólares para llevar inteligencia artificial al Indopacífico","c":"tecnologia","f":"2026-10-31T18:28","r":"Los cancilleres de EU, Japón, India y Australia acordaron en Atlanta, al margen de la reunión ministerial del G20, aportar asistencia técnica y financiera para el acceso a la IA y para recuperar minerales críticos de residuos electrónicos; EU pondrá 10 millones. También pidieron garantizar la navegación en Ormuz y el mar Rojo.","b":"","img":"tech","foto":"","cred":"","src":[["El Heraldo (Colombia)","https://elheraldo.co/mundo/2026/10/31/ee-uu-japon-india-y-australia-destinaran-usd85-millones-para-acceso-a-tecnologias-de-ia"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-una-empresa-de-eu-afirma-haber-tratado-a-un-paciente-con-un-virus-dise","t":"Una empresa de EU afirma haber tratado a un paciente con un virus diseñado por inteligencia artificial","c":"tecnologia","f":"2026-10-31T18:27","r":"Radical Numerics, de San Francisco, dijo que administró bacteriófagos diseñados por su modelo Omnii-1 a un paciente con una infección de E. coli resistente a antibióticos, en un uso compasivo. No ha revelado el resultado clínico ni ha publicado en revistas con revisión de pares, y especialistas piden cautela.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/10/31/laboratorio-afirma-haber-inyectado-virus-disenado-con-ia-en-un-humano-para-tratar-infeccion-resistente-a-antibioticos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-muere-el-hijo-de-meses-de-el-komander-el-cantante-cancela-su-presentac","t":"Muere el hijo de meses de El Komander; el cantante cancela su presentación en Nuevo León","c":"entretenimiento","f":"2026-10-31T18:26","r":"Alfredo Ríos confirmó en redes la muerte de su hijo José Eliseo Ríos Ávila, ocurrida el viernes. Su equipo canceló el concierto de este sábado en Hidalgo, Nuevo León, y pidió respeto a la privacidad de la familia. No se ha informado la causa.","b":"","img":"estadio","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/espectaculos/famosos/muere-el-hijo-de-el-komander-cantante-cancela-concierto-en-nuevo-leon/"],["Milenio","https://www.milenio.com/espectaculos/famosos/el-komander-cancela-concierto-nuevo-leon-muerte-hijo"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-mexico-rechaza-que-texas-reclame-nueve-islas-del-rio-bravo-la-frontera","t":"México rechaza que Texas reclame nueve islas del río Bravo: «La frontera no puede modificarse por decisión de un gobierno estatal»","c":"nacional","f":"2026-10-31T06:49","r":"La SRE respondió a la comisionada de la Oficina General de Tierras de Texas, Dawn Buckingham, quien afirmó que nueve islas del río pertenecen a ese estado. La Cancillería recordó que, según el Tratado de Límites de 1970, la frontera sigue el centro del cauce normal del río y que solo la Comisión Internacional de Límites y Aguas puede determinar de qué lado queda cada isla.","b":"","img":"texas","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/mexico-responde-a-texas-la-frontera-no-puede-cambiarse-unilateralmente/"],["Infobae","https://www.infobae.com/mexico/2026/10/31/modificaciones-en-la-frontera-con-eeuu-mexico-rechaza-que-texas-tenga-autoridad-para-reclamar-islas-del-rio-bravo/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-pemex-reduce-82-su-perdida-en-el-tercer-trimestre-10-795-millones-de-p","t":"Pemex reduce 82% su pérdida en el tercer trimestre: 10,795 millones de pesos; sus ingresos crecen 28.5%","c":"economia","f":"2026-10-31T06:48","r":"La petrolera perdió 10,795 millones de pesos entre julio y septiembre, frente a 61,242 millones un año antes, con ingresos de 486,779 millones y utilidad de operación de 97,591 millones. Procesó 1.143 millones de barriles diarios de crudo, el nivel más alto desde 2014, y su deuda financiera bajó a 77,600 millones de dólares, 9% menos que al cierre de 2025.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/30/pemex-pierde-605-millones-de-dolares-en-tercer-trimestre-de-2026-pese-a-mayores-ingresos/"],["La Silla Rota","https://lasillarota.com/negocios/2026/10/30/pemex-aumenta-285-sus-ingresos-y-reduce-deuda-en-el-tercer-trimestre-de-2026-535270.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-seis-civiles-murieron-por-los-narcobloqueos-en-matamoros-retiran-72-ve","t":"Seis civiles murieron por los narcobloqueos en Matamoros; retiran 72 vehículos y se normaliza la circulación","c":"seguridad","f":"2026-10-31T06:47","r":"Tras la captura de «El Titán», mando de Los Ciclones del Cártel del Golfo, murieron cuatro integrantes de una familia que chocaron contra un autobús incendiado en la carretera Matamoros-Reynosa, un hombre de Texas que se impactó con un vehículo quemado y una niña de siete años por un disparo. Las autoridades retiraron 72 unidades, 52 de ellas calcinadas, y reportan carreteras libres.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/seis-personas-ajenas-a-los-enfrentamientos-murieron-por-los-narcobloqueos-en-matamoros-tras-caida-de-el-titan/"],["La Jornada","https://www.jornada.com.mx/2026/10/31/estados/021n3est?partner=rss"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-sheinbaum-sobre-taddei-lo-primero-que-tiene-que-haber-es-una-auditoria","t":"Sheinbaum sobre Taddei: «Lo primero que tiene que haber es una auditoría»; la FGR decidiría si hay delito","c":"politica","f":"2026-10-31T06:46","r":"Luego de que el consejero Arturo Castillo pidiera prisión preventiva para la expresidenta del INE por presunto abuso de funciones y enriquecimiento ilícito, la presidenta dijo que primero debe auditarse el manejo de los contratos y que, si hay un asunto penal, corresponde a la Fiscalía. Responsabilizó a Lorenzo Córdova de la llegada de Taddei al instituto electoral de Sonora en 2014 y propuso licitaciones abiertas.","b":"","img":"ine","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/10/30/primero-auditoria-y-si-hay-asunto-penal-que-intervenga-la-fgr-sheinbaum-sobre-taddei-382855.html"],["Uno TV","https://www.unotv.com/nacional/consejero-ine-prision-preventiva-para-guadalupe-taddei/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-31-sheinbaum-cierra-la-reconstruccion-en-hidalgo-2-259-familias-recibiran","t":"Sheinbaum cierra la reconstrucción en Hidalgo: 2,259 familias recibirán 400 mil pesos para vivienda","c":"estados","f":"2026-10-31T06:45","r":"En Pachuca, la presidenta entregó los apoyos para familias que perdieron su vivienda por las lluvias de octubre de 2025, en 23 municipios y 228 localidades; el monto supera los 900 millones de pesos y se pagará en tres ministraciones. El apoyo federal total para Hidalgo ronda los 8 mil millones de pesos, a los que el gobierno estatal sumó 4,577 millones.","b":"","img":"lluvia","foto":"","cred":"","src":[["El Universal Hidalgo","https://www.eluniversalhidalgo.com.mx/estado/cierra-claudia-sheinbaum-etapa-de-reconstruccion-en-hidalgo-con-apoyo-total-de-8-mil-millones/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-sheinbaum-monta-guardia-ante-el-feretro-de-cuauhtemoc-cardenas-en-bell","t":"Sheinbaum monta guardia ante el féretro de Cuauhtémoc Cárdenas en Bellas Artes junto a Lázaro Cárdenas Batel y Clara Brugada","c":"nacional","f":"2026-10-31T06:44","r":"La presidenta regresó a la capital tras sus actos en Zumpango y Pachuca para el homenaje de cuerpo presente al fundador del PRD en el Palacio de Bellas Artes, organizado por la familia y la Secretaría de Cultura. Hizo guardia de honor con el hijo del político, jefe de la Oficina de la Presidencia, y con la jefa de Gobierno, y en un breve mensaje lo describió como un hombre valiente.","b":"","img":"bellas","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/10/30/sheinbaum-rinde-homenaje-a-cuauhtemoc-cardenas-en-bellas-artes-382869.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-el-imss-incorpora-47-equipos-medicos-en-39-hospitales-entre-ellos-20-u","t":"El IMSS incorpora 47 equipos médicos en 39 hospitales, entre ellos 20 ultrasonidos 3D","c":"nacional","f":"2026-10-31T06:43","r":"En la conferencia matutina del viernes, el IMSS informó la entrega de 47 equipos especializados para 39 hospitales: 20 ultrasonidos con visualización 3D, 17 electrocardiógrafos y monitores multiparamétricos para terapia intensiva. La entrega es parte de 12 acciones en 120 días derivadas de una consulta piso por piso al personal, encabezada por Zoé Robledo.","b":"","img":"imss","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-30-de-octubre-de-2026/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-30-de-octubre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-la-mezcla-mexicana-de-petroleo-cierra-el-viernes-en-106-8-dolares-por","t":"La mezcla mexicana de petróleo cierra el viernes en 106.8 dólares por barril","c":"economia","f":"2026-10-31T06:42","r":"El precio estimado de la mezcla mexicana de exportación fue de 106.8 dólares por barril al cierre del viernes 30 de octubre. En el tercer trimestre, el precio promedio de la mezcla fue de 85.38 dólares, 38.7% más que un año antes, según el reporte de Pemex.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/precio-de-la-mezcla-mexicana-de-petroleo-de-este-viernes-30-de-octubre/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/30/pemex-pierde-605-millones-de-dolares-en-tercer-trimestre-de-2026-pese-a-mayores-ingresos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-wall-street-suma-su-tercera-semana-de-perdidas-el-nasdaq-cae-2-84-su-p","t":"Wall Street suma su tercera semana de pérdidas; el Nasdaq cae 2.84%, su peor día desde junio","c":"economia","f":"2026-10-31T06:41","r":"El viernes, el S&P 500 bajó 1.80% a 7,580 puntos, el Nasdaq retrocedió 2.84% a 25,440 y el Dow Jones perdió 1.09% a 51,770, según cifras preliminares. Los reportes de Intel y Amazon reavivaron las dudas sobre la rentabilidad de la inversión en inteligencia artificial. El S&P 500 y el Nasdaq terminaron octubre en terreno negativo; el Dow cerró el mes con ganancia.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / AP","https://www.infobae.com/estados-unidos/2026/10/30/viernes-negro-para-wall-street-cerro-su-tercera-semana-en-baja-por-las-ventas-de-acciones-tecnologicas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-la-marina-niega-que-un-helicoptero-haya-disparado-contra-civiles-en-ma","t":"La Marina niega que un helicóptero haya disparado contra civiles en Matamoros; la Fiscalía investiga el origen de los tiros","c":"seguridad","f":"2026-10-31T06:40","r":"El Sector Naval de Matamoros rechazó versiones difundidas en redes de que una aeronave de la Marina disparó contra la población durante la jornada violenta del jueves; según sus bitácoras, el helicóptero realizaba un traslado de tropas. La Fiscalía de Tamaulipas investiga de dónde provinieron los disparos que mataron a una niña de siete años; la versión del helicóptero proviene del testimonio de un familiar.","b":"","img":"carretera","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/tamaulipas/seguridad/balaceras-bloqueos-matamoros-tamaulipas-dejan-seis-muertos-noticias-hoy-tras-violencia/"],["Infobae","https://www.infobae.com/mexico/2026/10/31/seis-personas-ajenas-a-los-enfrentamientos-murieron-por-los-narcobloqueos-en-matamoros-tras-caida-de-el-titan/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-ataques-en-culiacan-y-mazatlan-detienen-a-tres-hombres-tras-una-persec","t":"Ataques en Culiacán y Mazatlán; detienen a tres hombres tras una persecución por el asesinato de un motociclista","c":"estados","f":"2026-10-31T06:39","r":"En Culiacán, tres hombres fueron detenidos en la colonia Los Mezcales tras una persecución, señalados por atacar a balazos a un motociclista que murió. El viernes también se reportaron homicidios en la colonia Las Cerezas de Culiacán y en Mazatlán, donde fue hallado el cuerpo de una mujer en un canal de la marina. Autoridades destruyeron 2,045 litros de precursores químicos en comunidades de Culiacán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Línea Directa","https://lineadirectaportal.com/policiaca/atienden-hechos-en-sinaloa-y-logran-detenciones-durante-este-viernes-30-de-octubre-2026-10-30__1731042"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-nuevo-frente-frio-entrara-esta-noche-por-el-noroeste-preven-lluvias-fu","t":"Nuevo frente frío entrará esta noche por el noroeste; prevén lluvias fuertes en Baja California y Sonora","c":"nacional","f":"2026-10-31T06:38","r":"El Servicio Meteorológico Nacional prevé lluvias en 24 estados este sábado, con acumulados de 25 a 50 milímetros en Baja California y Sonora, y chubascos en entidades como Chihuahua, Nuevo León, Tamaulipas, Guerrero, Oaxaca y la península de Yucatán. Habrá heladas de -5 a 0 °C en zonas serranas de Baja California, Chihuahua y Durango. En la capital se espera una máxima de 25 a 27 °C.","b":"","img":"lluvia","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/clima/pronostico-clima-mexico-31-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-una-jueza-federal-frena-las-amenazas-del-gobierno-de-trump-contra-func","t":"Una jueza federal frena las amenazas del gobierno de Trump contra funcionarios electorales a días de los comicios","c":"internacional","f":"2026-10-31T06:37","r":"La jueza de distrito Trina Thompson dictó una orden de restricción temporal que impide a los departamentos de Justicia y de Seguridad Nacional amenazar con procesos penales a funcionarios electorales o exigirles separar boletas o depurar padrones. La demanda la presentó una coalición de sindicatos y organizaciones civiles, entre ellas LULAC. Las elecciones intermedias son el martes 3 de noviembre.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/31/una-jueza-estadounidense-ordena-detener-la-campana-de-presion-de-trump-contra-los-funcionarios-electorales/"],["Diario Libre","https://www.diariolibre.com/usa/actualidad/2026/10/30/jueza-federal-detiene-procesamientos-penales-a-funcionarios-electorales/3706393"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-iran-afirma-que-destruyo-un-dron-naval-enemigo-y-que-varios-petroleros","t":"Irán afirma que destruyó un dron naval «enemigo» y que varios petroleros se incendiaron en Ormuz","c":"internacional","f":"2026-10-31T06:36","r":"La Armada del Ejército iraní informó el viernes que destruyó un vehículo de superficie no tripulado en la zona oriental del estrecho de Ormuz y que varios petroleros a los que calificó de «infractores» se incendiaron en distintos incidentes en esa vía marítima, según la cadena estatal china CGTN. No precisó cuántos buques resultaron afectados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["CGTN Español","https://espanol.cgtn.com/2026/10/31/ARTI1793412464773315"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-el-gran-desfile-de-dia-de-muertos-sale-hoy-a-las-14-00-de-la-diana-caz","t":"El Gran Desfile de Día de Muertos sale hoy a las 14:00 de la Diana Cazadora rumbo al Zócalo","c":"cdmx","f":"2026-10-31T06:35","r":"El recorrido de este sábado 31 de octubre partirá de la glorieta de la Diana Cazadora y seguirá por Paseo de la Reforma, avenida Juárez y 5 de Mayo hasta el Zócalo, donde está la ofrenda monumental. Habrá homenajes a Juan Gabriel, Juan Rulfo, Nelly Campobello y Emilio «El Indio» Fernández. Se recomiendan como alternativas viales Circuito Interior, Eje 1 Norte, avenida Chapultepec, Izazaga y Fray Servando.","b":"","img":"ofrenda","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/entretenimiento/2026/10/29/desfile-de-dia-de-muertos-2026-cdmx-fecha-hora-ruta-donde-ver-calles-cerradas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-el-metro-abrira-a-las-5-00-el-domingo-en-cinco-lineas-por-el-gran-prem","t":"El Metro abrirá a las 5:00 el domingo en cinco líneas por el Gran Premio de México","c":"cdmx","f":"2026-10-31T06:34","r":"Las líneas 1, 2, 3, 7 y 9 del Metro iniciarán servicio a las 5:00 horas el domingo 1 de noviembre, día de la carrera. Del viernes al domingo opera un dispositivo especial en la Línea 9 con 510 elementos de la SSC y 40 vigilantes, con mayor presencia en las estaciones Velódromo, Ciudad Deportiva y Puebla.","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/31/metro-cdmx-ampliara-horario-de-apertura-por-el-gran-premio-de-mexico-2026-habra-operativo-especial-en-linea-9/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-intel-se-desploma-28-6-en-wall-street-su-peor-caida-desde-1974-pese-a","t":"Intel se desploma 28.6% en Wall Street, su peor caída desde 1974, pese a superar las expectativas de utilidad","c":"tecnologia","f":"2026-10-31T06:33","r":"La acción de Intel cayó 28.6% el viernes porque su pronóstico de ganancias decepcionó, aunque su utilidad trimestral fue mayor a la esperada. Nvidia bajó 4.2% y fue el mayor lastre del S&P 500, mientras Coinbase perdió 10.6% tras el hackeo a Binance. El bitcoin cayó por debajo de 77,000 dólares, cuando a inicios de mes superaba los 86,000.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae / AP","https://www.infobae.com/estados-unidos/2026/10/30/viernes-negro-para-wall-street-cerro-su-tercera-semana-en-baja-por-las-ventas-de-acciones-tecnologicas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-atlas-gana-1-0-en-san-luis-sube-al-segundo-lugar-y-queda-a-un-punto-de","t":"Atlas gana 1-0 en San Luis, sube al segundo lugar y queda a un punto del líder América","c":"deportes","f":"2026-10-31T06:32","r":"Florian Monzón marcó al minuto 63 el único gol del partido ante el Atlético de San Luis, en la jornada 15 del Apertura 2026. Atlas suma 27 puntos, con ocho victorias, tres empates y cuatro derrotas, y se ubica a una unidad del América, que este sábado recibe al Toluca.","b":"","img":"estadio","foto":"","cred":"","src":[["Diario de México","https://www.diariodemexico.com/arena-deportiva/atlas-vence-san-luis-escala-segundo-lugar-apertura-2026"],["MundoNow","https://www.mundonow.com/previa-fin-de-semana-liga-mx-laliga-premier-mls-30-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-pumas-vence-2-1-al-puebla-con-un-gol-de-alvaro-angulo-al-final-y-se-ac","t":"Pumas vence 2-1 al Puebla con un gol de Álvaro Angulo al final y se acerca a la Liguilla","c":"deportes","f":"2026-10-31T06:31","r":"En la jornada 15 del Apertura 2026, Pumas ganó en el Estadio Cuauhtémoc. Juninho Vieira abrió el marcador, Puebla empató por medio de Moreno y Álvaro Angulo anotó el tanto del triunfo sobre la hora. Con el resultado, los universitarios llegaron a 20 puntos y se colocaron en el noveno lugar antes de los partidos del sábado.","b":"","img":"unam","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/deportes/2026/10/30/pumas-vence-de-manera-agonica-al-puebla-con-gol-de-alvaro-angulo-y-los-felinos-suenan-con-liguilla/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-31-gael-garcia-bernal-cierra-la-seminci-de-valladolid-con-hombre-al-agua","t":"Gael García Bernal cierra la Seminci de Valladolid con «Hombre al agua», su tercera película como director","c":"entretenimiento","f":"2026-10-31T06:30","r":"El cineasta mexicano presenta este sábado en la clausura de la 71.ª Semana Internacional de Cine de Valladolid, en España, su tercer largometraje de ficción como director, en el que también actúa. La cinta es una comedia sobre masculinidad y ascenso social que parte de un socorrista cubano que rescata a un empresario mexicano; en el reparto figuran Ricky Martin, Esmeralda Pimentel, Débora Nascimento y Natalia Oreiro.","b":"","img":"bellas","foto":"","cred":"","src":[["Plano Informativo","https://planoinformativo.com/1173602/tercer-largometraje-de-gael-garcia-bernal-cerrara-la-71-seminci-de-valladolid"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-capturan-en-miami-a-ines-gomez-mont-la-fgr-confirma-que-hubo-intercamb","t":"Capturan en Miami a Inés Gómez Mont; la FGR confirma que hubo intercambio de información con EU","c":"seguridad","f":"2026-10-30T19:42","r":"La Fiscalía General de la República confirmó la detención de la expresentadora Inés Gómez Mont en Miami, Florida, como resultado del intercambio de información con el gobierno de Estados Unidos. La FGR indicó que tiene una orden de aprehensión vigente en México por su probable participación en defraudación fiscal equiparada y que dará más detalles después. Gómez Mont y su esposo, Víctor Manuel Álvarez Puga, salieron del país en 2021 y han sido señalados por un presunto desvío de cerca de 3 mil millones de pesos; aún no se ha informado si México pedirá su extradición o deportación.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/fgr-confirma-colaboracion-con-eeuu-para-captura-de-ines-gomez-mont-en-miami/"],["Infobae","https://www.infobae.com/mexico/2026/10/30/capturan-a-ines-gomez-mont-en-florida-lleva-anos-profuga-de-la-justicia-mexicana/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-sheinbaum-propone-llevar-los-restos-de-cuauhtemoc-cardenas-a-la-rotond","t":"Sheinbaum propone llevar los restos de Cuauhtémoc Cárdenas a la Rotonda de las Personas Ilustres","c":"nacional","f":"2026-10-30T19:40","r":"Durante el homenaje de cuerpo presente en el Palacio de Bellas Artes, la presidenta Claudia Sheinbaum propuso a la familia que los restos de Cuauhtémoc Cárdenas descansen en la Rotonda de las Personas Ilustres y pidió a Gobernación atender el trámite. Lo describió como un hombre valiente que \"está en la historia de México\". Sus hijos Lázaro, Cuauhtémoc y Camila Cárdenas Batel colocaron la bandera sobre el féretro; miles de personas acudieron al recinto y hubo guardias de honor con Sheinbaum, Clara Brugada, Gerardo Fernández Noroña y Édgar Amador.","b":"","img":"bellas","foto":"","cred":"","src":[["Amexi","https://amexi.com.mx/nacional/rinden-homenaje-cuauhtemoc-cardenas-palacio-bellas-artes/"],["Yahoo Noticias","https://es-us.noticias.yahoo.com/adi%C3%B3s-cuauht%C3%A9moc-c%C3%A1rdenas-palacio-bellas-232920395.html"],["SinEmbargo","https://www.sinembargo.mx/4896146/los-mexicanos-le-dan-el-ultimo-adios-a-cuauhtemoc-cardenas-en-bellas-artes-en-vivo/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-la-nina-de-7-anos-que-murio-en-el-operativo-contra-el-titan-en-matamor","t":"La niña de 7 años que murió en el operativo contra El Titán en Matamoros era estadounidense; envían 450 militares","c":"seguridad","f":"2026-10-30T19:38","r":"La menor que murió de un disparo durante la persecución para detener a Axel Alfredo Cárdenas Rodríguez, El Titán, en Matamoros, era una niña estadounidense de siete años que viajaba con su madre y otros familiares; la madre resultó herida en un pie. La Fiscalía de Tamaulipas abrió una investigación para saber si el disparo vino desde tierra o desde el aire. La Defensa envió 450 elementos y dos helicópteros Black Hawk a la región tras los narcobloqueos en Matamoros, Río Bravo y Padilla.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/era-estadounidense-la-nina-de-siete-anos-que-murio-en-operativo-contra-sobrino-de-osiel-cardenas-guillen/"],["Infobae","https://www.infobae.com/mexico/2026/10/30/narcobloqueos-por-detenciones-de-criminales-no-son-una-constante-dice-sheinbaum-tras-quema-de-autos-en-tamaulipas/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-el-peso-cierra-octubre-con-una-caida-de-4-y-suma-ocho-semanas-de-perdi","t":"El peso cierra octubre con una caída de 4% y suma ocho semanas de pérdidas frente al dólar","c":"economia","f":"2026-10-30T19:36","r":"El peso terminó el viernes en 18.80 unidades por dólar, con datos del Banco de México, una ganancia de 0.18% en el día pero una pérdida de 0.77% en la semana y de 4% en octubre; al cierre de septiembre estaba en 18.08. Analistas de Monex y Banco Base atribuyeron el retroceso a la fortaleza del dólar, la incertidumbre comercial y el menor diferencial de tasas con EU, y anticiparon volatilidad en noviembre con episodios cercanos a 19 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["EFE / Infobae","https://www.infobae.com/america/agencias/2026/10/30/el-peso-mexicano-suma-ocho-semanas-de-perdidas-frente-al-dolar-y-cae-un-4-en-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-sheinbaum-afirma-que-los-narcobloqueos-tras-detenciones-no-son-la-cons","t":"Sheinbaum afirma que los narcobloqueos tras detenciones \"no son la constante\" y que hay un plan para carreteras","c":"politica","f":"2026-10-30T19:34","r":"En su conferencia matutina, la presidenta Claudia Sheinbaum dijo que la violencia registrada el jueves en Matamoros tras la captura de El Titán no es habitual, pues todos los días se detiene a presuntos delincuentes. Agregó que la Defensa y la Guardia Nacional tienen un plan de acción para cuando se bloquean carreteras. El detenido y una segunda persona fueron trasladados a la Ciudad de México y puestos a disposición de la FEMDO.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/narcobloqueos-por-detenciones-de-criminales-no-son-una-constante-dice-sheinbaum-tras-quema-de-autos-en-tamaulipas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-la-bolsa-mexicana-cierra-octubre-con-un-alza-de-8-67-en-69-779-puntos","t":"La Bolsa mexicana cierra octubre con un alza de 8.67% en 69,779 puntos","c":"economia","f":"2026-10-30T19:32","r":"El S&P/BMV IPC terminó el viernes prácticamente sin cambios (-0.01%) en 69,779.2 unidades y acumuló un avance de 8.67% en octubre, después de cuatro meses de caídas. En el día destacaron Grupo Bimbo (+4.22%) y Megacable (+3.99%), mientras BBVA México cayó 6.04% y Grupo México 4.01%. Gabriela Siller, de Banco Base, atribuyó el desempeño mensual a los buenos reportes trimestrales de las empresas.","b":"","img":"bolsa","foto":"","cred":"","src":[["EFE / ABC Color","https://www.abc.com.py/internacionales/2026/10/30/la-bolsa-mexicana-cierra-octubre-con-avance-del-867-y-se-ubica-en-697792-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-el-brent-sube-2-4-a-117-64-dolares-su-mayor-cierre-desde-mayo-por-ataq","t":"El Brent sube 2.4% a 117.64 dólares, su mayor cierre desde mayo, por ataques a petroleros en Ormuz","c":"economia","f":"2026-10-30T19:30","r":"El crudo Brent para diciembre cerró el viernes en 117.64 dólares por barril, un alza de 2.4%, y el WTI en 104.12 dólares (+2.08%). Ambos acumularon más de 13% en octubre, su cuarto mes consecutivo al alza. El impulso vino de nuevos ataques contra buques petroleros en el estrecho de Ormuz y del temor a una escalada entre Estados Unidos e Irán, además de ataques con drones ucranianos a refinerías rusas.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/30/el-petroleo-suma-cuatro-meses-de-alzas-y-alcanzo-su-mayor-cierre-desde-mayo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-concanaco-preve-ventas-por-235-mil-millones-de-pesos-en-el-buen-fin-20","t":"Concanaco prevé ventas por 235 mil millones de pesos en el Buen Fin 2026, con menor crecimiento","c":"economia","f":"2026-10-30T19:28","r":"El Buen Fin se realizará del 13 al 17 de noviembre con más de 200 mil establecimientos participantes, informó Concanaco Servytur. Su presidente, Octavio de la Torre, estimó una derrama de 235 mil millones de pesos, 7.3% más que en 2025, un avance menor al de 26.1% del año anterior. Calculó que 79% de las ventas serán en tiendas físicas; Profeco presentó su comparador de precios para la temporada.","b":"","img":"centro","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/negocios/buen-fin-2026-concanaco-estima-ventas-235-mil-millones-de-pesos-menor-crecimiento/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-mexico-propone-en-el-g20-cinco-prioridades-ante-las-tensiones-geopolit","t":"México propone en el G20 cinco prioridades ante las tensiones geopolíticas","c":"politica","f":"2026-10-30T19:26","r":"El canciller Roberto Velasco participó en Atlanta en la reunión de ministros de Exteriores del G20, encabezada por el secretario de Estado Marco Rubio. Propuso fortalecer la diplomacia y el papel de la ONU, garantizar que la ayuda humanitaria llegue a quien la necesita, proteger las cadenas de suministro de bienes esenciales, atender las causas del desplazamiento como la pobreza y asegurar financiamiento humanitario previsible.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/mexico-propone-en-el-g20-cinco-prioridades-para-enfrentar-las-tensiones-geopoliticas-globales/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-hidalgo-lidera-el-crecimiento-economico-estatal-en-el-segundo-trimestr","t":"Hidalgo lidera el crecimiento económico estatal en el segundo trimestre; Morelos registra la peor caída","c":"estados","f":"2026-10-30T19:24","r":"Según el Indicador Trimestral de la Actividad Económica Estatal del INEGI, Hidalgo creció 8.5% anual entre abril y junio de 2026, seguido de Colima (5.8%) y Veracruz (5.1%). En el otro extremo, Morelos cayó 5.8%, Quintana Roo 3.7%, Campeche 2.4%, Puebla 2.3% y Coahuila 1.1%.","b":"","img":"carretera","foto":"","cred":"","src":[["Mundo Ejecutivo","https://mundoejecutivo.com.mx/actualidad/hidalgo-y-colima-lideran-el-crecimiento-de-la-actividad-economica-estatal-en-2t2026/"],["INEGI","https://www.inegi.org.mx/temas/itaee/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-detienen-en-xochitepec-a-el-chorejas-senalado-como-lider-de-los-aparic","t":"Detienen en Xochitepec a El Chorejas, señalado como líder de Los Aparicio en Morelos","c":"estados","f":"2026-10-30T19:22","r":"La Agencia de Investigación Criminal de Morelos, con apoyo de la FGR, detuvo en Atlacholoaya, municipio de Xochitepec, a Axel Arturo \"N\", alias El Chorejas, señalado como líder del grupo Los Aparicio. Se le acusa de homicidio calificado y tentativa de homicidio por un ataque ocurrido el 25 de julio de 2025 en Huazulco, Temoac. Sus padres, señalados como fundadores del grupo, también están presos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/detienen-a-el-chorejas-lider-de-los-aparicio-banda-dedicada-a-la-extorsion-asesinato-y-trafico-de-drogas-en-morelos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-lydia-cacho-encara-a-mario-marin-en-la-audiencia-final-por-tortura-la","t":"Lydia Cacho encara a Mario Marín en la audiencia final por tortura; la jueza tiene 60 días para sentenciar","c":"estados","f":"2026-10-30T19:20","r":"En la audiencia de vista celebrada el jueves en el penal del Altiplano, la periodista Lydia Cacho confrontó al exgobernador de Puebla Mario Marín, exigió la pena máxima y una disculpa pública por su detención y tortura en 2005. Marín sostuvo que no hay pruebas de que él lo ordenara. La jueza María José Pech Sáenz tiene hasta 60 días naturales para emitir la sentencia; antes debe resolverse un amparo de la defensa que pide prisión domiciliaria.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Capital Puebla","https://capitalpuebla.com/2026/10/29/lydia-cacho-encaro-a-mario-marin-en-audiencia-clave-la-jueza-dictara-sentencia-en-60-dias/"],["Uno TV","https://www.unotv.com/estados/puebla/confrontacion-lydia-cacho-mario-marin/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-envian-al-reclusorio-norte-al-presunto-envenenador-de-perros-de-la-con","t":"Envían al Reclusorio Norte al presunto envenenador de perros de la Condesa","c":"cdmx","f":"2026-10-30T19:18","r":"Salvador \"N\", de 58 años, fue trasladado al Reclusorio Preventivo Norte, donde un juez definirá su situación por el delito de maltrato animal. Se le relaciona con la muerte de cuatro perros envenenados en la Condesa; otros dos sobrevivieron y siguen en observación. La investigación inició el 27 de octubre tras un reporte al 911 de una veterinaria, y la orden de aprehensión se cumplió el viernes tras el análisis de videos.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/el-mataperros-de-la-condesa-es-trasladado-al-reclusorio-preventivo-norte-juez-definira-su-situacion/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-s-p-eleva-la-calificacion-de-aeromexico-de-b-a-bb","t":"S&P eleva la calificación de Aeroméxico de B+ a BB-","c":"economia","f":"2026-10-30T19:16","r":"S&P Global Ratings subió la calificación crediticia de Grupo Aeroméxico en escala global de B+ a BB- y la de sus notas con vencimiento en 2029 y 2031 de BB- a BB. La agencia destacó la rentabilidad y disciplina financiera de la aerolínea pese a los mayores costos del sector, su modelo de servicio premium y una liquidez sólida.","b":"","img":"bolsa","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/negocios/aeromexico-mejora-calificacion-crediticia-sp/"],["SEC (6-K)","https://www.sec.gov/Archives/edgar/data/0001561861/000156186126000086/a2026-10x28spupgradevf.htm"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-binance-suspende-retiros-tras-un-hackeo-que-estima-en-6-300-millones-d","t":"Binance suspende retiros tras un hackeo que estima en 6,300 millones de dólares","c":"tecnologia","f":"2026-10-30T19:14","r":"La plataforma de criptomonedas Binance informó de un ataque que habría comprometido retiros por unos 6,300 millones de dólares; sus socios congelaron cerca de 3 mil millones en la cadena de bloques, incluidos unos 971 millones de Tether y 823 millones de Circle. Los depósitos ya operan, pero los retiros siguen pausados y la empresa prevé reanudarlos en 48 horas; aseguró que cubrirá las pérdidas con su fondo SAFU. El bitcoin cayó cerca de 3.9%, a unos 77,600 dólares.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/economia/2026/10/30/que-se-sabe-sobre-el-hackeo-a-binance-y-cuando-se-habilitaria-el-retiro-de-fondos/"],["Bloomberg Línea","https://www.bloomberglinea.com/mercados/binance-investiga-un-posible-hackeo-mientras-tether-y-circle-congelan-us2300-millones-y-el-bitcoin-cae/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-trump-cancela-sus-mitines-en-kansas-e-iowa-a-dias-de-las-elecciones-in","t":"Trump cancela sus mítines en Kansas e Iowa a días de las elecciones intermedias","c":"internacional","f":"2026-10-30T19:12","r":"El presidente Donald Trump suspendió los actos presenciales que tenía previstos el sábado en Kansas y el domingo en Iowa y los sustituirá por participaciones virtuales, informó el Comité Nacional Republicano. Su presidente, Joe Gruters, lo presentó como parte de una ofensiva de 72 horas para movilizar votantes antes de las elecciones del martes 3 de noviembre.","b":"","img":"texas","foto":"","cred":"","src":[["EFE / Infobae","https://www.infobae.com/america/agencias/2026/10/30/trump-cancela-sus-mitines-en-iowa-y-kansas-y-los-sustituye-por-actos-virtuales/"],["Univision","https://www.univision.com/noticias/politica/elecciones-en-estados-unidos-2026/trump-cancela-mitines-en-kansas-e-iowa-y-apuesta-por-mitines-telefonicos-para-llegar-a-mas-votantes"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-leclerc-domina-el-viernes-del-gp-de-mexico-checo-perez-termina-18-en-l","t":"Leclerc domina el viernes del GP de México; Checo Pérez termina 18° en la segunda práctica","c":"deportes","f":"2026-10-30T19:10","r":"Charles Leclerc (Ferrari) fue el más rápido en la segunda práctica libre del Gran Premio de la Ciudad de México con 1:17.827, por delante de Lando Norris y George Russell, tras haber liderado también la primera sesión. Sergio Pérez, con Cadillac, terminó en el lugar 18. La sesión tuvo una bandera roja por un contacto entre Max Verstappen y Liam Lawson, y Lewis Hamilton detuvo su auto por una falla de potencia.","b":"","img":"autodromo","foto":"","cred":"","src":[["Formula 1","https://www.formula1.com/en/latest/article/fp2-leclerc-tops-eventful-second-practice-from-norris-and-russell-at-mexico-city-grand-prix.5iyjNG9TZGc6DfLTacb05D"],["Infobae","https://www.infobae.com/mexico/2026/10/30/como-le-fue-a-checo-perez-en-la-practica-2-del-gran-premio-de-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-canelo-alvarez-y-christian-mbilli-dan-el-peso-para-su-pelea-por-el-tit","t":"Canelo Álvarez y Christian Mbilli dan el peso para su pelea por el título del CMB en Riad","c":"deportes","f":"2026-10-30T19:08","r":"Saúl Canelo Álvarez marcó 167.7 libras y Christian Mbilli 167.8 en la ceremonia de pesaje en Riad, Arabia Saudita, por lo que la pelea por el campeonato supermediano del Consejo Mundial de Boxeo queda confirmada para este sábado 31 de octubre. La función iniciará alrededor de las 11:00 y el combate estelar se espera hacia las 15:00, hora del centro de México.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/30/canelo-alvarez-y-christian-mbilli-superan-la-bascula-y-quedan-listos-para-disputar-el-titulo-mundial-del-cmb-en-arabia-saudita/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-asesinan-en-chetumal-a-bernardo-chale-expolicia-estatal-y-luchador-con","t":"Asesinan en Chetumal a Bernardo Chalé, expolicía estatal y luchador conocido como Darkness","c":"estados","f":"2026-10-30T19:06","r":"Bernardo Federico Chalé Barea, exagente de la Policía Estatal de Quintana Roo y luchador profesional con el nombre de Darkness, fue asesinado a balazos en su domicilio de la colonia Nachicocom, en Chetumal. De acuerdo con medios locales citados por Infobae, el crimen ocurrió la noche del 28 de octubre.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/asesinan-a-expolicia-y-luchador-frente-a-su-esposa-e-hijos-en-quintana-roo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-el-papa-leon-xiv-vota-por-correo-en-las-elecciones-intermedias-de-esta","t":"El papa León XIV vota por correo en las elecciones intermedias de Estados Unidos","c":"internacional","f":"2026-10-30T19:04","r":"El papa León XIV emitió su voto por correo para las elecciones intermedias del 3 de noviembre en Estados Unidos, consideradas decisivas para el gobierno de Donald Trump, informó Uno TV. El costo de vida aparece como una de las principales preocupaciones de los votantes.","b":"","img":"vaticano","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/todo-en-uno-tv/noticias-de-hoy-30-de-octubre-de-2026-en-un-minuto-hasta-las-1300-horas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-cuauhtemoc-cardenas-recibe-hoy-un-homenaje-de-cuerpo-presente-en-el-pa","t":"Cuauhtémoc Cárdenas recibe hoy un homenaje de cuerpo presente en el Palacio de Bellas Artes","c":"nacional","f":"2026-10-30T06:56","r":"La familia Cárdenas Batel aplazó la cremación para que el fundador del PRD, fallecido el miércoles a los 92 años, sea despedido este viernes en el vestíbulo de Bellas Artes, en un acto abierto al público convocado por el INBAL. Según Latinus, la presidenta Sheinbaum se reunió con los tres hijos del ingeniero para organizar el homenaje; sería la primera vez que el recinto rinde este tributo a un político desde el de Heberto Castillo en 1997.","b":"","img":"bellas","foto":"","cred":"","src":[["Quinto Poder","https://quinto-poder.mx/alza-la-voz/2026/10/30/homenaje-a-cuauhtemoc-cardenas-en-bellas-artes-lo-que-se-sabe--72793.html"],["Latinus","https://latinus.us/mexico/2026/10/29/cuauhtemoc-cardenas-recibira-homenaje-de-cuerpo-presente-en-bellas-artes-180942.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-zedillo-afirma-en-madrid-que-mexico-vive-una-autocracia-electoral-y-ad","t":"Zedillo afirma en Madrid que México vive una \"autocracia electoral\" y advierte sobre los comicios de 2027","c":"politica","f":"2026-10-30T06:55","r":"En un foro de la revista Letras Libres en Madrid, el expresidente Ernesto Zedillo sostuvo que el país ya no reúne los atributos de una democracia. Advirtió que en 2027 podrían usarse recursos públicos y apoyo del crimen organizado a favor del partido gobernante, criticó la reforma judicial y la desaparición de los órganos autónomos, y comparó el riesgo con el caso de Venezuela.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/29/vivimos-una-autocracia-electoral-zedillo-advierte-sobre-las-condiciones-para-votar-en-mexico-en-2027/"],["Dossier Político","https://dossierpolitico.com/2026/10/29/ernesto-zedillo-advierte-que-mexico-ya-no-reune-los-atributos-necesarios-para-considerarse-una-democracia/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-pese-a-la-peticion-de-todos-los-partidos-el-ine-aprueba-17-de-24-nombr","t":"Pese a la petición de todos los partidos, el INE aprueba 17 de 24 nombramientos en los OPLE propuestos en la gestión de Taddei","c":"politica","f":"2026-10-30T06:54","r":"En la primera sesión encabezada por la presidenta provisional Blanca Cruz, el Consejo General avaló 17 designaciones, entre ellas las presidencias de los institutos electorales de Puebla y Colima, aunque representantes de todos los partidos pidieron aplazarlas. Cinco cargos quedaron vacantes, los casos de Guerrero y Oaxaca se retiraron y el Consejo acordó no tomar en cuenta las evaluaciones hechas por Guadalupe Taddei, además de revisar sus contratos.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/30/pese-a-queja-de-partidos-avala-ine-nombramientos-de-taddei-en-ople/"],["Latinus","https://latinus.us/mexico/2026/10/29/ine-declara-receso-por-posible-influencia-de-taddei-en-nombramiento-de-consejeros-de-los-ople-180909.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-detenido-en-matamoros-era-el-titan-mando-de-los-ciclones-del-cartel-de","t":"Detenido en Matamoros era \"El Titán\", mando de Los Ciclones del Cártel del Golfo ligado al ataque contra un custodio del consulado de EU","c":"seguridad","f":"2026-10-30T06:53","r":"Omar García Harfuch identificó al detenido como Axel Alfredo Cárdenas Rodríguez, alias \"El Titán\", señalado como segundo al mando de la facción Los Ciclones y emparentado con la familia de Osiel Cárdenas Guillén. Fue capturado el jueves por el Ejército y la Guardia Nacional cuando conducía una camioneta de lujo; el secretario lo vinculó con el ataque del 17 de mayo en que murió un agente que resguardaba el consulado estadounidense. Tras el arresto hubo narcobloqueos en Matamoros, Río Bravo y Padilla.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/cae-en-matamoros-axel-alfredo-el-titan-operador-del-cartel-del-golfo-y-familiar-de-osiel-cardenas-guillen/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-30-la-embajada-de-eu-reporta-una-caida-de-95-en-las-detenciones-en-la-fro","t":"La embajada de EU reporta una caída de 95% en las detenciones en la frontera sur en los últimos 12 meses","c":"nacional","f":"2026-10-30T06:52","r":"En un balance de la cooperación bilateral, la embajada estadounidense informó que las detenciones de la Patrulla Fronteriza en la frontera suroeste bajaron 95%, que México incautó más de 500 toneladas de droga y que realizó 96 extradiciones y 92 traslados de presos a EU. El embajador Ronald Johnson dijo en el foro del Instituto Milken que la designación de cárteles como terroristas no busca justificar bombardeos, sino ampliar sanciones financieras.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/embajada-de-eeuu-en-mexico-reporta-reduccion-de-95-en-detenciones-fronterizas-en-los-ultimos-12-meses/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-trabajadores-del-imss-realizan-hoy-una-nueva-megamarcha-en-la-cdmx-exi","t":"Trabajadores del IMSS realizan hoy una nueva megamarcha en la CDMX; exigen 10% de aumento directo","c":"cdmx","f":"2026-10-30T06:51","r":"Trabajadores activos y jubilados del Seguro Social convocaron a movilizaciones este viernes en la capital, a partir de las 10:00 y de las 15:00 horas, con posibles horarios distintos en los estados. Rechazan el paquete de 8% (4% al salario y 4% en ayuda de vivienda) y piden 10% directo, un congreso nacional extraordinario del sindicato, la salida de su dirigencia y solución a la falta de medicinas y personal.","b":"","img":"imss","foto":"","cred":"","src":[["ADN40","https://www.adn40.mx/ciudad/2026-10-27/hora-en-la-que-empieza-la-megamarcha-nacional-del-imss-30-de-octubre/"],["Uno TV","https://www.unotv.com/nacional/trabajadores-del-imss-anuncian-megamarcha-nacional-para-el-30-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-hay-661-mil-mexicanos-menos-en-edad-de-trabajar-en-eu-y-las-remesas-qu","t":"Hay 661 mil mexicanos menos en edad de trabajar en EU y las remesas quedan en riesgo, advierte el Cemla","c":"economia","f":"2026-10-30T06:50","r":"Un análisis del Centro de Estudios Monetarios Latinoamericanos con datos de la Oficina del Censo de EU indica que, entre enero y septiembre, la población migrante mexicana en edad laboral cayó 5.8% frente al mismo lapso de 2025, a 10.68 millones. Los ocupados bajaron en 442 mil, sobre todo en la construcción, y la masa salarial anual de este grupo se redujo 4.2% desde su máximo, lo que presiona los envíos de dinero.","b":"","img":"bolsa","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/negocios/2026/10/30/remesas-peligran-por-mas-de-medio-millon-de-mexicanos-menos-en-eu/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-el-peso-abre-el-viernes-en-18-88-por-dolar-y-acumula-una-perdida-de-1","t":"El peso abre el viernes en 18.88 por dólar y acumula una pérdida de 1.15% en la semana","c":"economia","f":"2026-10-30T06:49","r":"El tipo de cambio inició la última sesión de la semana en 18.88 pesos por dólar, un alza de 0.09% para la divisa estadounidense, según datos de Dow Jones citados por Infobae. El dólar suma dos sesiones al alza y 1.15% en la semana. El Banco de México publicó un tipo de cambio FIX de 18.8148 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/30/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-30-de-octubre/"],["Uno TV","https://www.unotv.com/dolar-hoy/dolar-cotiza-en-18-81-pesos-este-viernes-30-de-octubre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-las-petroleras-europeas-duplican-sus-ganancias-por-los-altos-margenes","t":"Las petroleras europeas duplican sus ganancias por los altos márgenes de refinación; Pemex aún no reporta su tercer trimestre","c":"economia","f":"2026-10-30T06:48","r":"Shell ganó 10,810 millones de dólares ajustados en el tercer trimestre, casi el doble que un año antes, y TotalEnergies elevó su utilidad 127%, impulsadas por márgenes de refinación más altos durante la guerra en Medio Oriente. Pemex, que perdió unos 28 mil millones de pesos en el primer semestre, todavía no publica sus cifras del periodo; ExxonMobil y Chevron reportan este viernes.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/29/las-petroleras-multiplicaron-sus-ganancias-por-el-salto-en-el-precio-del-crudo-la-guerra-en-medio-oriente/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-la-fgr-asegura-1-5-millones-de-litros-de-combustible-ilegal-en-reynosa","t":"La FGR asegura 1.5 millones de litros de combustible ilegal en Reynosa y supera sus resultados de 2025 contra el huachicol","c":"seguridad","f":"2026-10-30T06:47","r":"En cateos del 16 de octubre en Reynosa, Tamaulipas, la Fiscalía General de la República aseguró alrededor de 1.5 millones de litros de diésel, gasolinas y otros combustibles, más de 100 vehículos —71 de ellos autotanques— y detuvo a dos personas ya vinculadas a proceso. De enero a octubre suma 121 vinculaciones a proceso y 60 sentencias por delitos de hidrocarburos, contra 103 y 34 en todo 2025.","b":"","img":"pemex","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nacional/policiaca/2026/10/29/fgr-asegura-15-millones-de-litros-de-huachicol-y-detiene-a-11-personas-751743.html"],["La Razón","https://www.razon.com.mx/mexico/2026/10/29/fgr-asegura-15-millones-de-litros-de-hidrocarburos-y-supera-resultados-de-2025/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-marina-detiene-en-el-aicm-a-cuatro-personas-tres-llevaban-mas-de-47-ki","t":"Marina detiene en el AICM a cuatro personas; tres llevaban más de 47 kilos de presunta droga rumbo a España y Corea del Sur","c":"seguridad","f":"2026-10-30T06:46","r":"En operativos separados en el aeropuerto capitalino, la Semar y Aduanas detuvieron a dos hombres con unos 19.9 kilos de aparente cocaína con destino a España y a otro con cerca de 21.4 kilos de aparente metanfetamina y 6.1 de cocaína rumbo a Corea del Sur. Un cuarto detenido fue señalado por manipular equipaje documentado. Los detenidos quedaron a disposición de la FGR.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/capturan-en-el-aicm-a-cuatro-traficantes-con-mas-de-45-kilos-de-cocaina-y-metanfetamina-intentaban-volar-a-espana-y-corea-del-sur/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-grecia-quiroz-acusa-a-la-fiscalia-de-michoacan-de-querer-desarticular","t":"Grecia Quiroz acusa a la Fiscalía de Michoacán de querer desarticular su gobierno tras el arresto de su secretaria de Bienestar","c":"estados","f":"2026-10-30T06:45","r":"La alcaldesa de Uruapan afirmó que la detención de Rosa Alejandra Vargas Rauda, acusada de encubrimiento por favorecimiento en el caso del asesinato de Carlos Manzo, tiene fines político-electorales contra su gobierno y el Movimiento del Sombrero, aunque dijo estar dispuesta a colaborar. La Fiscalía informó que la funcionaria fue puesta a disposición de una jueza de control y que actuará sin distinción de cargos.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/10/30/detienen-a-secretaria-de-bienestar-de-uruapan-por-crimen-de-manzo/"],["Infobae","https://www.infobae.com/mexico/2026/10/29/grecia-quiroz-acusa-a-la-fiscalia-de-michoacan-de-intentar-desarticular-su-gobierno-tras-detencion-de-secretaria-de-bienestar-de-uruapan/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-detienen-en-mexicali-a-el-bocho-con-162-gramos-de-fentanilo-y-una-pist","t":"Detienen en Mexicali a \"El Bocho\" con 162 gramos de fentanilo y una pistola","c":"estados","f":"2026-10-30T06:44","r":"La Fuerza Estatal de Seguridad Ciudadana de Baja California arrestó a Juan Antonio \"N\", de 29 años, en la colonia Valle Nuevo de Mexicali. Las autoridades lo señalan como presunto encargado de la logística de venta de droga en el Valle de Mexicali para una facción ligada al Cártel de Sinaloa. Fue entregado a la FGR por portación de arma y posesión de droga.","b":"","img":"carretera","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/mxl/policiaca/2026/10/29/cae-el-bocho-en-mexicali-con-162-gramos-de-fentanilo-y-una-pistola-calibre-40/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-sube-a-15-la-cifra-de-muertos-por-el-ataque-ruso-con-dron-contra-la-es","t":"Sube a 15 la cifra de muertos por el ataque ruso con dron contra la estación de tren de Dnipró","c":"internacional","f":"2026-10-30T06:43","r":"Las autoridades de la región de Dnipropetrovsk informaron que una persona hospitalizada murió, con lo que suman 15 víctimas del ataque del jueves contra la estación ferroviaria de Dnipró, en el centro-este de Ucrania. La compañía Ukrzaliznytsia dijo que se había declarado alerta aérea y detenido el tráfico de trenes antes del impacto.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/30/aumentan-a-15-los-muertos-por-el-ataque-de-rusia-contra-una-estacion-de-tren-en-dnipro-ucrania/"],["Swissinfo","https://www.swissinfo.ch/spa/un-ataque-con-dron-ruso-causa-14-muertos-en-una-estaci%C3%B3n-de-tren-en-ucrania/92295687"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-christine-lagarde-dejara-la-presidencia-del-bce-el-7-de-febrero-de-202","t":"Christine Lagarde dejará la presidencia del BCE el 7 de febrero de 2027, nueve meses antes de concluir su mandato","c":"internacional","f":"2026-10-30T06:42","r":"El Banco Central Europeo confirmó la salida anticipada de su presidenta, cuyo periodo terminaba en octubre de 2027. Lagarde explicó que ya no puede mantener la neutralidad que exige el cargo y que quiere opinar sobre temas más allá de la política monetaria. Aún no hay sucesor; analistas mencionan a Klaas Knot y a Pablo Hernández de Cos.","b":"","img":"paris","foto":"","cred":"","src":[["BCE","https://www.ecb.europa.eu/press/pr/date/2026/html/ecb.pr261029~abbb6dc64b.en.html"],["Euronews","https://www.euronews.com/2026/10/29/i-cannot-remain-neutral-lagarde-finally-explains-her-early-ecb-exit"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-delcy-rodriguez-promete-elecciones-en-venezuela-con-un-arbitro-renovad","t":"Delcy Rodríguez promete elecciones en Venezuela con un árbitro renovado, pero no fija fecha","c":"internacional","f":"2026-10-30T06:41","r":"En un mensaje en la televisión estatal, la presidenta encargada dijo que los comicios se harán con una autoridad electoral renovada y observación internacional, pero condicionó la convocatoria a una reforma judicial y a la convivencia democrática. La oposición de María Corina Machado y Edmundo González pide votar en 2027, y el Departamento de Estado respalda una hoja de ruta con renovación del CNE y del Supremo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/internacional/2026/10/29/delcy-rodriguez-descarta-convocar-elecciones-a-corto-plazo-el-horizonte-politico-no-se-mide-por-una-382784.html"],["El Universal (Colombia)","https://www.eluniversal.com.co/mundo/2026/10/29/delcy-rodriguez-asegura-que-habra-elecciones-libres-en-venezuela/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-comienzan-las-practicas-del-gran-premio-de-mexico-checo-perez-correra","t":"Comienzan las prácticas del Gran Premio de México; Checo Pérez correrá en casa su carrera 300 en la F1","c":"deportes","f":"2026-10-30T06:40","r":"El piloto de Cadillac regresa al Autódromo Hermanos Rodríguez por primera vez desde 2024 y llegará a 300 grandes premios, una cifra que, según Uno TV, solo otros seis pilotos han alcanzado. Las prácticas libres son este viernes a las 12:30 y 16:00 horas; la clasificación, el sábado a las 15:00, y la carrera, el domingo a las 14:00. Pérez dijo que su meta es hacer avanzar a su equipo.","b":"","img":"autodromo","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/deportes/checo-perez-celebra-sus-300-gps-de-formula-1-revela-los-3-momentos-favoritos-de-su-carrera/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-mexico-queda-fuera-del-mundial-femenil-sub-17-al-perder-2-1-con-nigeri","t":"México queda fuera del Mundial Femenil Sub-17 al perder 2-1 con Nigeria en octavos","c":"deportes","f":"2026-10-30T06:39","r":"La selección mexicana cayó en Marruecos ante Nigeria, que se adelantó con goles de Oluebube Umejiaku al minuto 39 y de Mary Dunstan al 70. Emily Delgado descontó para México ya en tiempo de compensación, al 99, sin tiempo para buscar el empate.","b":"","img":"estadio","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/futbol/futbol-femenil/mexico-eliminado-mundial-sub17/"],["Mediotiempo","https://www.mediotiempo.com/futbol/seleccion-femenil-sub-17/resumen-partido-nigeria-vs-mexico-2-1-mundial-sub-17-femenil-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-daddy-yankee-estrena-la-postal-album-de-15-canciones-sobre-distintas-f","t":"Daddy Yankee estrena \"La Postal\", álbum de 15 canciones sobre distintas formas de amor","c":"entretenimiento","f":"2026-10-30T06:38","r":"El cantante puertorriqueño lanza este 30 de octubre un disco conceptual en el que cada tema funciona como una carta a un tipo de amor: de pareja, familiar y propio. El primer sencillo es \"BOTZ\" (Bésame Otra Vez). Llega un año después de \"Lamento en baile\", con el que puso fin al retiro que había anunciado en 2022.","b":"","img":"estudio","foto":"","cred":"","src":[["El Colombiano","https://www.elcolombiano.com/inicio/daddy-yankee-la-postal-album-octubre-2026-EO42193623"]],"dest":false,"a":"Redacción"},{"id":"2026-10-30-eu-prohibe-a-laboratorios-chinos-probar-y-certificar-aparatos-electron","t":"EU prohíbe a laboratorios chinos probar y certificar aparatos electrónicos para su mercado","c":"tecnologia","f":"2026-10-30T06:37","r":"La Comisión Federal de Comunicaciones (FCC) votó 3-0 excluir a laboratorios y organismos certificadores de China y de otros países sin acuerdos de reconocimiento mutuo con EU. Los laboratorios estadounidenses tendrán hasta diciembre de 2028 para ampliar su capacidad. El presidente de la FCC, Brendan Carr, defendió la medida como parte de la política comercial de Trump.","b":"","img":"tech","foto":"","cred":"","src":[["DiarioBitcoin","https://www.diariobitcoin.com/regulacion/ee-uu-excluye-a-laboratorios-chinos-de-las-pruebas-para-dispositivos-electronicos/"],["NTD","https://www.ntd.com/fcc-votes-3-0-to-ban-chinese-labs-from-testing-electronics-for-us-market_1182377.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-sheinbaum-hace-guardia-de-honor-por-cuauhtemoc-cardenas-en-el-panteon","t":"Sheinbaum hace guardia de honor por Cuauhtémoc Cárdenas en el Panteón Francés: «Venimos a abrazar a la familia»","c":"nacional","f":"2026-10-29T18:39","r":"Por la mañana, la presidenta repasó en su conferencia la trayectoria del exjefe de Gobierno y fundador del PRD, fallecido a los 92 años. Después acudió al Panteón Francés de la Ciudad de México, donde permaneció de las 12:24 a las 13:15 horas. Su gobierno hablará con la familia para organizar un homenaje en los próximos días.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/29/sheinbaum-despide-a-cuauhtemoc-cardenas-venimos-a-abrazar-a-la-familia-dice-desde-el-panteon-frances/"],["Infobae","https://www.infobae.com/mexico/2026/10/29/en-vivo-la-mananera-de-la-presidenta-claudia-sheinbaum-hoy-29-de-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-sheinbaum-llama-coyotes-a-los-proveedores-de-papeleria-electoral-y-pro","t":"Sheinbaum llama «coyotes» a los proveedores de papelería electoral y propone que Talleres Gráficos produzca el material","c":"politica","f":"2026-10-29T18:38","r":"La presidenta afirmó que el problema del INE va más allá de Guadalupe Taddei, de quien dijo que «traicionó la confianza» del país. Acusó a empresas con más de 20 años de contratos de funcionar como intermediarias y pidió investigarlas. Planteó fortalecer a Talleres Gráficos de México para producir la mayor parte del material electoral y abrir licitaciones para el resto.","b":"","img":"ine","foto":"","cred":"","src":[["La Política Online","https://www.lapoliticaonline.com/mexico/politica-mx/sheinbaum-dice-que-el-problema-del-ine-son-los-proveedores-coyotes-e-impulsa-una-empresa-estatal-9018/"],["Infobae","https://www.infobae.com/mexico/2026/10/29/en-vivo-la-mananera-de-la-presidenta-claudia-sheinbaum-hoy-29-de-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-captura-de-un-objetivo-prioritario-en-matamoros-desata-narcobloqueos-e","t":"Captura de un «objetivo prioritario» en Matamoros desata narcobloqueos en Tamaulipas; EU pide a su personal resguardarse","c":"seguridad","f":"2026-10-29T18:37","r":"La Secretaría de Seguridad de Tamaulipas informó que fuerzas federales detuvieron en Matamoros a un objetivo prioritario, sin revelar su identidad. Tras el arresto hubo bloqueos con transporte de carga y ponchallantas en carreteras y calles de Matamoros y Río Bravo. El consulado de Estados Unidos ordenó a su personal permanecer en sus instalaciones y la Secretaría de Educación estatal suspendió las clases del turno vespertino.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/eeuu-emite-alerta-de-seguridad-en-matamoros-por-los-narcobloqueos-y-violencia-generada-tras-detencion-de-objetivo-prioritario/"],["ADN40","https://www.adn40.mx/mexico/2026-10-29/bloqueos-con-transportes-de-carga-en-tamaulipas-aparecen-ponchallantas-en-varias-carreteras-y-calles-de-matamoros/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-el-peso-pierde-mas-de-1-y-cierra-en-18-83-por-dolar-tras-el-fuerte-cre","t":"El peso pierde más de 1% y cierra en 18.83 por dólar tras el fuerte crecimiento de la economía de EU","c":"economia","f":"2026-10-29T18:36","r":"El dólar terminó el jueves en 18.83 pesos, frente a 18.64 del cierre previo, un avance de 1.05% según datos de Dow Jones citados por Infobae. El cierre del Banco de México lo ubicó en 18.84. La moneda se debilitó después de que el PIB estadounidense creció más de lo esperado en el tercer trimestre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/dolar-hoy-en-mexico-cotizacion-de-cierre-del-29-de-octubre/"],["ABC Color (EFE)","https://www.abc.com.py/internacionales/2026/10/29/la-bolsa-de-mexico-gana-un-087-en-sesion-mixta-en-el-mundo-y-sube-a-6978741-unidades/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-suman-15-renuncias-en-el-ine-tras-la-salida-de-taddei-se-van-tambien-l","t":"Suman 15 renuncias en el INE tras la salida de Taddei; se van también los llamados «sobrinos»","c":"politica","f":"2026-10-29T18:35","r":"La presidenta provisional del INE, Blanca Cruz, informó de 12 renuncias voluntarias en la oficina de la Presidencia, que se suman a tres salidas solicitadas por el Consejo General. Entre quienes se van está el jefe de oficina, Carlos Daniel Luna. El instituto consultará al Órgano Interno de Control antes de pagar finiquitos y evalúa pedir la renuncia del secretario ejecutivo, Roberto Félix.","b":"","img":"ine","foto":"","cred":"","src":[["Aristegui Noticias","https://aristeguinoticias.com/2910/mexico/suman-15-renuncias-en-el-ine-tras-la-salida-de-guadalupe-taddei/"],["Excélsior","https://www.excelsior.com.mx/nacional/inician-renuncias-sobrinos-taddei-ine"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-sheinbaum-pide-deslindar-responsabilidades-por-los-10-muertos-de-la-to","t":"Sheinbaum pide deslindar responsabilidades por los 10 muertos de la tormenta Rachel en Ensenada","c":"nacional","f":"2026-10-29T18:34","r":"La presidenta dijo que deberá determinarse la responsabilidad de las autoridades por las personas arrastradas por las lluvias en Ensenada, Baja California, el 10 de octubre. Sostuvo que sí hubo avisos y refugios, y que la zona más golpeada fue Maneadero. Anunció que en noviembre arrancará un sistema de alerta telefónica para comunidades alejadas.","b":"","img":"huracan","foto":"","cred":"","src":[["Punto Norte","https://puntonorte.info/2026/10/29/sheinbaum-pide-deslinde-de-responsabilidades-por-los-10-muertos-que-dejo-tormenta-en-ensenada"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-detienen-a-la-secretaria-de-bienestar-de-uruapan-por-presunto-encubrim","t":"Detienen a la secretaria de Bienestar de Uruapan por presunto encubrimiento en el asesinato de Carlos Manzo","c":"seguridad","f":"2026-10-29T18:33","r":"La Fiscalía de Michoacán detuvo a Rosa Alejandra «N» en el fraccionamiento Infonavit Balcones de Uruapan, tras un cateo. Quedó a disposición de una jueza de control. La fiscalía reporta 34 detenidos y 18 órdenes de aprehensión por el homicidio del exalcalde, a días del primer aniversario del crimen.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/10/29/detienen-a-secretaria-del-bienestar-de-uruapan-la-acusan-de-encubrir-el-asesinato-de-carlos-manzo/"],["Infobae","https://www.infobae.com/mexico/2026/10/29/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-29-de-octubre-la-dea-uso-a-el-vicentillo-para-intentar-doblegar-a-el-mayo-zambada-revela-docuserie-de-netflix/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-la-economia-de-eu-crece-3-4-en-el-tercer-trimestre-impulsada-por-la-in","t":"La economía de EU crece 3.4% en el tercer trimestre, impulsada por la inversión en inteligencia artificial","c":"economia","f":"2026-10-29T18:32","r":"El Departamento de Comercio informó que el PIB estadounidense creció 3.4% entre julio y septiembre. El gasto de los consumidores aumentó 3.8% y la inversión en equipo de procesamiento de información subió 37.4%. La inversión en vivienda cayó 3.3%, con hipotecas cerca de 7%.","b":"","img":"bolsa","foto":"","cred":"","src":[["La Opinión","https://laopinion.com/2026/10/29/el-pib-de-estados-unidos-crecio-un-3-4-a-tasa-anualizada-en-el-tercer-trimestre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-jose-cuervo-se-desploma-en-la-bolsa-su-utilidad-cae-84-6-y-pierde-unos","t":"José Cuervo se desploma en la Bolsa: su utilidad cae 84.6% y pierde unos 6,600 millones de pesos de valor","c":"economia","f":"2026-10-29T18:31","r":"Las acciones de Becle llegaron a caer 14.3% y la BMV suspendió temporalmente su operación; cerraron con una baja de 12.29%. En el tercer trimestre sus ventas bajaron 15.3%, a 9,253 millones de pesos, y su utilidad neta fue de 633 millones. La empresa atribuyó el resultado a una demanda más débil, el tipo de cambio y cambios de distribuidores en EU.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/10/29/jose-cuervo-se-hunde-acciones-se-desploman-y-pierde-6-600-mdp-en-capitalizacion-bursatil"],["ABC Color (EFE)","https://www.abc.com.py/internacionales/2026/10/29/la-bolsa-de-mexico-gana-un-087-en-sesion-mixta-en-el-mundo-y-sube-a-6978741-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-la-bolsa-mexicana-sube-0-87-y-cierra-en-69-787-puntos-acumula-8-68-en","t":"La Bolsa Mexicana sube 0.87% y cierra en 69,787 puntos; acumula 8.68% en octubre","c":"economia","f":"2026-10-29T18:30","r":"El S&P/BMV IPC ganó 0.87% y terminó en 69,787.41 unidades, su segundo avance en tres sesiones. Destacaron OMA (+5.75%), Chedraui (+3.87%) y Cemex (+3.75%), mientras José Cuervo encabezó las pérdidas. Según Actinver, el índice sube 8.52% en lo que va del año.","b":"","img":"bolsa","foto":"","cred":"","src":[["ABC Color (EFE)","https://www.abc.com.py/internacionales/2026/10/29/la-bolsa-de-mexico-gana-un-087-en-sesion-mixta-en-el-mundo-y-sube-a-6978741-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-el-brent-baja-0-38-a-114-88-dolares-tras-reportes-de-una-carta-de-vanc","t":"El Brent baja 0.38% a 114.88 dólares tras reportes de una carta de Vance a Irán","c":"economia","f":"2026-10-29T18:29","r":"El crudo de referencia europeo cerró en 114.88 dólares y el WTI cayó 0.76%, a 102. El Wall Street Journal reportó que el vicepresidente JD Vance escribió a Mohsen Rezai, del Consejo Supremo de Seguridad Nacional iraní, para retomar el diálogo. El mercado lo leyó como una señal de menor probabilidad de un ataque en las próximas semanas.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/29/el-petroleo-cae-tras-los-contactos-entre-estados-unidos-e-iran-que-reavivan-la-expectativa-de-negociaciones/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-matan-a-un-agente-ministerial-en-un-ataque-contra-la-base-de-la-amic-e","t":"Matan a un agente ministerial en un ataque contra la base de la AMIC en Magdalena de Kino, Sonora","c":"estados","f":"2026-10-29T18:28","r":"Alberto Guzmán Aguiar murió por disparos hechos desde el exterior del edificio de la Agencia Ministerial de Investigación Criminal, en el centro de Magdalena de Kino, hacia las 19:44 horas del miércoles. La Fiscalía de Sonora condenó el ataque y abrió una investigación; no se reportan detenidos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/estados/sonora/muere-agente-de-la-amic-tras-ataque-armado-a-base-en-sonora/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-sinaloa-suspende-clases-del-turno-vespertino-en-todo-el-estado-por-las","t":"Sinaloa suspende clases del turno vespertino en todo el estado por las lluvias de Vance","c":"estados","f":"2026-10-29T18:27","r":"La Secretaría de Educación Pública y Cultura de Sinaloa suspendió este jueves las clases vespertinas en escuelas públicas y privadas de todos los niveles. La medida fue preventiva ante el pronóstico de lluvias por los remanentes de Vance, informado por Protección Civil estatal.","b":"","img":"lluvia","foto":"","cred":"","src":[["Azteca Sinaloa","https://www.aztecasinaloa.com/noticias/se-suspenden-clases-en-el-turno-vespertino-en-estos-municipios-de-sinaloa/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-abre-la-ofrenda-monumental-del-zocalo-con-una-catrina-de-32-metros-est","t":"Abre la ofrenda monumental del Zócalo con una Catrina de 32 metros; estará hasta el 2 de noviembre","c":"cdmx","f":"2026-10-29T18:26","r":"La instalación, con entrada gratuita, rinde homenaje a José Guadalupe Posada. La Catrina de cartonería busca un récord Guinness y se acompaña de unas 100 mil plantas de cempasúchil, tapetes de aserrín y esculturas de ajolotes. Se puede llegar por las estaciones Zócalo, Allende y Pino Suárez del Metro.","b":"","img":"ofrenda","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/yo-soi-tu/2026/10/29/ofrenda-monumental-del-zocalo-2026-fecha-y-hora-para-ver-534960.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-recuento-final-en-israel-el-likud-gana-27-escanos-pero-el-bloque-de-ne","t":"Recuento final en Israel: el Likud gana 27 escaños, pero el bloque de Netanyahu se queda en 53","c":"internacional","f":"2026-10-29T18:25","r":"Con todos los votos contados, el bloque de Netanyahu suma 53 de los 120 escaños y el de Gadi Eisenkot, 48; la mayoría es de 61. Los partidos árabes, con 19 asientos, no pertenecen a ningún bloque, por lo que ninguno puede gobernar sin ellos o sin diputados rivales.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/29/netanyahu-gana-elecciones-en-israel-pero-su-bloque-no-logra-mayoria-segun-recuento-final/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-checo-perez-admite-que-cadillac-necesita-un-milagro-para-sumar-puntos","t":"Checo Pérez admite que Cadillac «necesita un milagro» para sumar puntos en su Gran Premio 300","c":"deportes","f":"2026-10-29T18:24","r":"En la conferencia previa al Gran Premio de México, el piloto dijo que frenos, motor y la salida serán clave por la dificultad para rebasar en la altura de la capital. Cadillac aún no suma puntos en su primera temporada. La carrera será el domingo 1 de noviembre a las 14:00 horas en el Autódromo Hermanos Rodríguez.","b":"","img":"autodromo","foto":"","cred":"","src":[["ABC Noticias","https://abcnoticias.mx/deportes/2026/10/29/checo-perez-admite-que-cadillac-necesita-un-milagro-para-sumar-puntos-en-el-gp-de-mexico-2026-293920.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-muere-patrick-stewart-el-capitan-picard-y-el-profesor-xavier-a-los-86","t":"Muere Patrick Stewart, el capitán Picard y el profesor Xavier, a los 86 años","c":"entretenimiento","f":"2026-10-29T18:23","r":"Su familia informó en Instagram que el actor británico murió el lunes 26 de octubre en su casa de Los Ángeles, tras una breve enfermedad de Alzheimer. Con más de seis décadas de carrera, fue nombrado caballero en 2010.","b":"","img":"estudio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/espectaculos/2026/10/29/muere-patrick-stewart-el-profesor-x-de-los-x-men-a-los-86-anos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-netflix-estrena-la-caida-de-el-mayo-docuserie-de-tres-episodios-sobre","t":"Netflix estrena «La caída de El Mayo», docuserie de tres episodios sobre la captura de Zambada","c":"entretenimiento","f":"2026-10-29T18:22","r":"La serie, dirigida por Darren Foster y Miguel Fernández Flores, reconstruye cómo Ismael Zambada quedó bajo custodia de EU el 25 de julio de 2024. Entre sus revelaciones, la DEA facilitó dos llamadas entre «El Vicentillo» y su padre para convencerlo de entregarse.","b":"","img":"estudio","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/espectaculos/2026/10/15/netflix-estrenara-la-caida-de-el-mayo-este-29-de-octubre-de-que-trata-la-serie/"],["Infobae","https://www.infobae.com/mexico/2026/10/29/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-29-de-octubre-la-dea-uso-a-el-vicentillo-para-intentar-doblegar-a-el-mayo-zambada-revela-docuserie-de-netflix/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-alphabet-se-hunde-12-2-por-su-gasto-en-inteligencia-artificial-y-arras","t":"Alphabet se hunde 12.2% por su gasto en inteligencia artificial y arrastra al Nasdaq","c":"tecnologia","f":"2026-10-29T18:21","r":"La matriz de Google cerró en 283.82 dólares después de reportar un flujo de caja libre negativo de 9,065 millones de dólares, por gastos de capital de 51,355 millones. El Nasdaq perdió 1.38%, el S&P 500 0.3% y el Dow Jones 0.25%.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/29/wall-street-cierra-en-rojo-lastrado-por-alphabet-matriz-de-google-que-cae-un-122/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-amazon-vende-201-900-millones-de-dolares-en-el-trimestre-aws-crece-39","t":"Amazon vende 201,900 millones de dólares en el trimestre; AWS crece 39%","c":"tecnologia","f":"2026-10-29T18:20","r":"Las ventas netas de Amazon subieron 12% en el tercer trimestre y su nube, AWS, facturó 46,000 millones de dólares. La utilidad operativa llegó a 28,100 millones y la neta a 20,700 millones. Para el cuarto trimestre prevé ventas de 240,000 a 247,000 millones.","b":"","img":"tech2","foto":"","cred":"","src":[["Amazon","https://ir.aboutamazon.com/news-release/news-release-details/2026/Amazon-com-Announces-Third-Quarter-Results/default.aspx"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-muere-cuauhtemoc-cardenas-a-los-92-anos-fundador-del-prd-y-primer-jefe","t":"Muere Cuauhtémoc Cárdenas a los 92 años, fundador del PRD y primer jefe de Gobierno electo de la capital","c":"politica","f":"2026-10-29T07:19","r":"Cuauhtémoc Cárdenas Solórzano murió el miércoles 28 de octubre en la Ciudad de México, a los 92 años. Hijo del expresidente Lázaro Cárdenas, fue gobernador de Michoacán (1980-1986), encabezó el Frente Democrático Nacional en la elección de 1988, fundó el PRD en 1989, fue tres veces candidato presidencial (1988, 1994 y 2000) y en 1997 se convirtió en el primer jefe de Gobierno del Distrito Federal elegido por voto popular. No se ha informado la causa de su muerte.","b":"","img":"palacio","foto":"","cred":"","src":[["El Cronista","https://www.cronista.com/mexico/actualidad-mx/muere-cuauhtemoc-cardenas-a-los-92-anos-figura-clave-de-la-transicion-democratica-en-mexico/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/29/sheinbaum-despide-a-cuauhtemoc-cardenas-como-un-referente-imprescindible-de-mexico/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-hacienda-la-actividad-economica-crecio-3-7-anual-en-septiembre-su-mejo","t":"Hacienda: la actividad económica creció 3.7% anual en septiembre, su mejor mes desde 2023","c":"economia","f":"2026-10-29T07:18","r":"El secretario de Hacienda, Edgar Amador, dijo en un foro del Milken Institute que a la economía mexicana le está yendo bien. Según la estimación oportuna del INEGI, la actividad creció 3.7% anual en septiembre, la tasa más alta para un mes desde septiembre de 2023, tras 3.4% en julio y 3.5% en agosto. Amador destacó que las exportaciones subieron 30% de enero a septiembre y que la deuda pública cerraría 2026 en 54% del PIB.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/10/29/economia-gana-momentum-y-preserva-alza-al-tercer-trimestre-edgar-amador/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-la-marina-detiene-en-tuxtepec-a-el-semaforo-senalado-como-sucesor-de-e","t":"La Marina detiene en Tuxtepec a «El Semáforo», señalado como sucesor de «El Tanque» en el CJNG","c":"seguridad","f":"2026-10-29T07:17","r":"Elementos de Marina, SSPC y la FGR detuvieron en San Juan Bautista Tuxtepec, Oaxaca, a Carlos «N», alias «El Semáforo», identificado como presunto sucesor de Iván «N», «El Tanque», detenido el 5 de octubre en Zapopan. También fue arrestada Ana Gabriela «N», presunta operadora logística. Se aseguraron armas, granadas, drogas y vehículos valuados en 8.8 millones de pesos; ambos fueron trasladados a la Ciudad de México.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/10/28/otro-golpe-al-cjng-marina-detiene-en-oaxaca-a-el-semaforo-presunto-sucesor-de-el-tanque/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-el-ine-tendria-nueva-presidencia-hasta-el-6-o-7-de-diciembre-preve-mon","t":"El INE tendría nueva presidencia hasta el 6 o 7 de diciembre, prevé Monreal","c":"politica","f":"2026-10-29T07:16","r":"Ricardo Monreal, presidente de la Jucopo en San Lázaro, estimó que la Cámara de Diputados podría elegir a quien sustituya a Guadalupe Taddei el 6 o 7 de diciembre, si no hay contratiempos. Un comité técnico de cinco personas evaluará aspirantes y propondrá cinco perfiles; la designación requiere dos terceras partes de los diputados presentes y, si no se logra, se recurre a la insaculación. Mientras tanto, Blanca Cruz García preside el instituto de forma provisional.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/nueva-presidencia-del-ine-se-podria-definir-hasta-diciembre-advierte-ricardo-monreal/"],["PorEsto","https://www.poresto.com/mexico/2026/10/28/ricardo-monreal-preve-presidencia-ine-diciembre-convocatoria-saldra-noviembre.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-29-sheinbaum-despide-a-cuauhtemoc-cardenas-un-referente-imprescindible-pa","t":"Sheinbaum despide a Cuauhtémoc Cárdenas: «un referente imprescindible» para la nación","c":"politica","f":"2026-10-29T07:15","r":"La presidenta Claudia Sheinbaum lamentó en redes sociales la muerte de Cuauhtémoc Cárdenas, a quien llamó líder histórico de la izquierda y hombre de principios firmes que transformó la vida política del país. Recordó que encabezó en 1988 un movimiento democrático pacífico y afirmó que debió ser reconocido como presidente tras esa elección. Su hijo, Lázaro Cárdenas Batel, es jefe de la Oficina de la Presidencia.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/29/sheinbaum-despide-a-cuauhtemoc-cardenas-como-un-referente-imprescindible-de-mexico/"],["Excélsior","https://www.excelsior.com.mx/nacional/transformo-pais-sheinbaum-lamenta-muerte-cuauhtemoc-cardenas"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-asesinan-en-chenalho-al-defensor-tsotsil-reynaldo-perez-la-onu-habia-a","t":"Asesinan en Chenalhó al defensor tsotsil Reynaldo Pérez; la ONU había alertado de amenazas en su contra","c":"estados","f":"2026-10-29T07:14","r":"Reynaldo Pérez Pérez, defensor de derechos humanos tsotsil, fue asesinado a tiros la tarde del miércoles en la comunidad de Yabteclum, Chenalhó, Chiapas, por dos hombres en motocicleta, según el fiscal Jorge Luis Llaven Abarca, quien prometió cero impunidad. En 2025, relatores de la ONU advirtieron al gobierno mexicano de amenazas y ataques contra él; era beneficiario del Mecanismo de Protección.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/29/asesinan-a-reynaldo-perez-defensor-de-derechos-humanos-en-chiapas-la-onu-habia-alertado-sobre-amenazas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-remanentes-de-vance-dejaran-lluvias-muy-fuertes-en-sinaloa-este-jueves","t":"Remanentes de Vance dejarán lluvias muy fuertes en Sinaloa este jueves","c":"nacional","f":"2026-10-29T07:13","r":"El Servicio Meteorológico Nacional prevé lluvias muy fuertes en el centro y sur de Sinaloa, y fuertes en el sur de Baja California Sur, Chihuahua, Coahuila, Durango y Nayarit, por los remanentes de Vance, que después dejarían de afectar al país. Se esperan heladas de hasta -5 °C en sierras de Baja California, Chihuahua y Durango. En la capital, máxima de 24 a 26 °C y posibles chubascos por la tarde.","b":"","img":"lluvia","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/clima-en-mexico-hoy-jueves-29-octubre-remanentes-vance-dejan-fuertes-lluvias"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-choque-de-trenes-en-toledo-suben-a-69-los-muertos-y-un-mexicano-sigue","t":"Choque de trenes en Toledo: suben a 69 los muertos y un mexicano sigue desaparecido","c":"internacional","f":"2026-10-29T07:12","r":"El presidente de Castilla-La Mancha, Emiliano García-Page, elevó a 69 la cifra de muertos por el choque entre un AVE de Renfe y un Iryo cerca de Urda; 53 heridos siguen hospitalizados y 15 en estado crítico. Las primeras indagatorias apuntan a un error humano tras una avería. México informó que al menos un connacional sigue desaparecido y siete sufrieron heridas leves y ya fueron dados de alta.","b":"","img":"ultimahora","foto":"","cred":"","src":[["elDiario.es","https://www.eldiario.es/castilla-la-mancha/accidente-tren-urda-ultima-hora-directo-servicios-emergencia-siguen-zona-accidente-53-heridos-hospitalizados_133_13623403.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-privan-de-la-libertad-a-seis-jovenes-en-culiacan-reportan-que-cuatro-f","t":"Privan de la libertad a seis jóvenes en Culiacán; reportan que cuatro fueron localizados","c":"seguridad","f":"2026-10-29T07:11","r":"Un grupo armado que viajaba en al menos cuatro vehículos se llevó la noche del martes a seis jóvenes del fraccionamiento Villas del Real, al oriente de Culiacán; uno fue identificado como Jesús Emilio, de 18 años. Medios locales informaron que cuatro fueron hallados con vida horas después; de los otros dos no se tenía información. La Fiscalía de Sinaloa abrió una investigación.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/10/29/levantan-sicarios-a-6-jovenes-en-culiacan/"],["Revista Espejo","https://revistaespejo.com/2026/10/29/localizan-con-vida-a-jovenes-privados-de-la-libertad-en-culiacan"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-matan-al-regidor-priista-adan-rodriguez-y-a-su-esposa-en-indaparapeo-m","t":"Matan al regidor priista Adán Rodríguez y a su esposa en Indaparapeo, Michoacán","c":"estados","f":"2026-10-29T07:10","r":"El regidor de Indaparapeo Adán Rodríguez Ávalos, del PRI, y su esposa fueron asesinados en un ataque armado en la comunidad de El Triunfo, municipio vecino de Morelia. El PRI de Michoacán condenó el crimen y exigió una investigación inmediata. Las autoridades no habían informado detalles del ataque.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Indicio Michoacán","https://indiciomich.com/condena-pri-michoacan-asesinato-del-regidor-de-indaparapeo-adan-rodriguez-avalos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-el-peso-abre-el-jueves-cerca-de-18-70-por-dolar-tras-la-decision-de-la","t":"El peso abre el jueves cerca de 18.70 por dólar tras la decisión de la Fed","c":"economia","f":"2026-10-29T07:09","r":"El tipo de cambio abrió el jueves en 18.6974 pesos por dólar, un alza de 0.40% para el billete verde, según Investing.com citado por Heraldo Binario. El FIX publicado por Banxico en el DOF quedó en 18.6673. Gabriela Siller, de Banco Base, atribuyó la reciente fortaleza del peso a un debilitamiento generalizado del dólar.","b":"","img":"bolsa","foto":"","cred":"","src":[["Heraldo Binario","https://www.heraldobinario.com.mx/tendencias/2026/10/29/precio-del-peso-mexicano-a-dolar-hoy-29-de-octubre-a-cuanto-abre-su-cotizacion-43121.html"],["ABC Noticias","https://abcnoticias.mx/negocios/2026/10/29/el-dolar-cede-el-terreno-al-peso-mexicano-asi-se-cotiza-hoy-jueves-29-de-octubre-293819.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-mexico-quiere-cerrar-la-revision-del-t-mec-antes-de-fin-de-ano-pese-a","t":"México quiere cerrar la revisión del T-MEC antes de fin de año, pese a las elecciones en EU","c":"economia","f":"2026-10-29T07:08","r":"La Secretaría de Economía busca concluir la revisión del T-MEC antes de que termine 2026 y lograr un mejor trato en aranceles a autos, acero y aluminio; Marcelo Ebrard ve difícil otra ronda antes de las elecciones intermedias del 3 de noviembre en Estados Unidos. UBS asigna 50% de probabilidad a que los demócratas ganen ambas cámaras y considera poco probable una ruptura del tratado.","b":"","img":"senado","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/10/27/t-mec-elecciones-eu-que-cambia-para-mexico"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-cdmx-suma-5-226-personas-desaparecidas-prepara-una-busqueda-metropolit","t":"CDMX suma 5,226 personas desaparecidas; prepara una búsqueda metropolitana en noviembre","c":"cdmx","f":"2026-10-29T07:07","r":"La jefa de Gobierno, Clara Brugada, informó que 5,226 personas siguen sin ser localizadas en la capital y anunció una Gran Búsqueda Metropolitana con el Estado de México y Morelos a inicios de noviembre. Se sumarán 100 policías de investigación, 50 agentes del Ministerio Público y 87 buscadores; los 51 compromisos con familias suman un aumento multianual de más de 460 millones de pesos.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Crónica de Hoy","https://www.cronica.com.mx/metropoli/2026/10/27/cdmx-reporta-5-mil-226-personas-desaparecidas-anuncia-busqueda-metropolitana/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-con-90-del-conteo-el-bloque-de-netanyahu-suma-53-escanos-lejos-de-la-m","t":"Con 90% del conteo, el bloque de Netanyahu suma 53 escaños, lejos de la mayoría","c":"internacional","f":"2026-10-29T07:06","r":"Con alrededor de 90% de los votos contados en Israel, los partidos aliados de Benjamín Netanyahu reunían 53 de los 120 escaños, frente a 67 de la oposición, que incluye 48 del bloque de Eisenkot y 19 de partidos de mayoría árabe; se necesitan 61 para gobernar. La certificación oficial se espera el viernes y el presidente Isaac Herzog pidió agotar las negociaciones para evitar otra elección.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/29/en-vivo-elecciones-parlamentarias-en-israel/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-hegseth-destituye-al-jefe-de-estrategia-del-estado-mayor-conjunto-mien","t":"Hegseth destituye al jefe de estrategia del Estado Mayor Conjunto mientras EU evalúa atacar de nuevo a Irán","c":"internacional","f":"2026-10-29T07:05","r":"El secretario de Defensa, Pete Hegseth, removió al teniente general Brett Sylvia, director de estrategia, planes y política del Estado Mayor Conjunto, sin explicar el motivo, informó CNN. Funcionarios dijeron a esa cadena que las fuerzas en Medio Oriente podrían lanzar operaciones mayores contra Irán dentro de 96 horas tras una orden, más probablemente después de las elecciones intermedias.","b":"","img":"ultimahora","foto":"","cred":"","src":[["CNN en Español (vía ABC17)","https://abc17news.com/cnn-spanish/2026/10/29/hegseth-destituye-al-principal-estratega-del-pentagono-ante-posibles-nuevos-ataques-contra-iran-segun-fuente/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-flavio-bolsonaro-se-proclama-lider-de-brasil-desde-florida-y-no-recono","t":"Flávio Bolsonaro se proclama «líder de Brasil» desde Florida y no reconoce su derrota ante Lula","c":"internacional","f":"2026-10-29T07:04","r":"Tras llegar a Florida pese a una orden judicial que le impedía salir de Brasil, el senador Flávio Bolsonaro se presentó en X como «líder de Brasil», luego de llamarse «verdadero presidente», y acusó un fraude electoral sin pruebas. Perdió la segunda vuelta del domingo frente a Lula da Silva por unos 4.4 millones de votos. El Departamento de Estado dijo que daría visas a él y a su familia.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/estados-unidos/flavio-bolsonaro-dice-que-es-el-lider-de-brasil-nid28102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-cerveceros-campeones-milwaukee-gana-4-1-a-los-rays-y-conquista-su-prim","t":"¡Cerveceros campeones! Milwaukee gana 4-1 a los Rays y conquista su primera Serie Mundial","c":"deportes","f":"2026-10-29T07:03","r":"Los Cerveceros de Milwaukee vencieron 4-1 a los Rays en el Juego 5 en el Tropicana Field y ganaron la Serie Mundial 4-1, el primer título de su historia. Jacob Misiorowski lanzó 5.2 entradas sin carrera; William Contreras dio un doble de dos carreras en la sexta y el novato Cooper Pratt aportó un hit y un elevado de sacrificio. Trevor Megill sacó el último out.","b":"","img":"beisbol","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/brewers-milwaukee-hacen-historia-y-conquistan-primera-serie-mundial"],["CNN en Español (vía ABC17)","https://abc17news.com/cnn-spanish/2026/10/28/los-brewers-de-milwaukee-se-coronan-campeones-de-la-serie-mundial-por-primera-vez-en-la-historia/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-america-empata-1-1-con-xolos-en-el-azteca-y-deja-abierta-la-pelea-por","t":"América empata 1-1 con Xolos en el Azteca y deja abierta la pelea por el liderato","c":"deportes","f":"2026-10-29T07:02","r":"En el partido pendiente de la jornada 7, Elías Manoel adelantó a Tijuana al minuto 12 y Miguel Borja empató al 19. América llegó a 28 puntos, dos más que Cruz Azul y Guadalajara; Xolos, con 21, es séptimo. Tijuana terminó con diez jugadores por una expulsión revisada en el VAR.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/29/america-empata-1-1-con-xolos-en-el-azteca-y-arriesga-el-liderato-de-la-liga-mx/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-gran-premio-de-mexico-practicas-el-viernes-clasificacion-el-sabado-y-c","t":"Gran Premio de México: prácticas el viernes, clasificación el sábado y carrera el domingo a las 14:00","c":"deportes","f":"2026-10-29T07:01","r":"La actividad en el Autódromo Hermanos Rodríguez arranca el viernes 30 de octubre con las prácticas libres 1 (12:30) y 2 (16:00). El sábado 31 habrá práctica 3 a las 11:30 y clasificación a las 15:00; la carrera, a 71 vueltas, comenzará el domingo 1 de noviembre a las 14:00, con Checo Pérez de vuelta en casa con Cadillac.","b":"","img":"autodromo","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/10/27/gp-de-mexico-2026-horarios-mapa"]],"dest":false,"a":"Redacción"},{"id":"2026-10-29-amazon-presenta-hoy-sus-resultados-del-tercer-trimestre","t":"Amazon presenta hoy sus resultados del tercer trimestre","c":"tecnologia","f":"2026-10-29T07:00","r":"Amazon dará a conocer este jueves 29 de octubre sus resultados del tercer trimestre de 2026 y realizará su llamada con analistas a las 17:00 horas del este de Estados Unidos (15:00 del centro de México), que se transmitirá en vivo en su sitio para inversionistas.","b":"","img":"tech","foto":"","cred":"","src":[["Amazon","https://www.aboutamazon.com/md/news/company-news/amazon-earnings-q3-2026-report"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-sheinbaum-y-lemus-presentan-un-plan-de-25-mil-millones-de-pesos-para-e","t":"Sheinbaum y Lemus presentan un plan de 25 mil millones de pesos para el agua de Guadalajara","c":"nacional","f":"2026-10-28T18:59","r":"Los gobiernos federal y de Jalisco invertirán en conjunto 25 mil millones de pesos para mejorar el abasto y la calidad del agua en la zona metropolitana de Guadalajara. El plan, presentado en la mañanera con el titular de Conagua, Efraín Morales, incluye los acueductos Chapala-Guadalajara y Calderón-San Gaspar, la renovación de la potabilizadora Miravalle 1 —que surte 42% de la ciudad—, el saneamiento del canal de Las Pintas y nuevos colectores para frenar descargas al lago de Chapala. El gobernador Pablo Lemus aseguró que no habrá deuda, privatización ni aumento de tarifas.","b":"","img":"jalisco","foto":"","cred":"","src":[["Animal Político","https://grupoanimal.mx/politica/sheinbaum-mananera-28-octubre-2026-minuto-minuto"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-28-octubre-2026-minuto-minuto-vivo-n6336239"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-la-marina-abate-en-guasave-a-chuy-penuelas-operador-del-cartel-de-guas","t":"La Marina abate en Guasave a ‘Chuy Peñuelas’, operador del Cártel de Guasave por quien la DEA ofrecía 5 millones de dólares","c":"seguridad","f":"2026-10-28T18:58","r":"El secretario de Seguridad, Omar García Harfuch, informó que fuerzas de la Marina abatieron el lunes 26 de octubre a Jesús González Peñuelas, alias ‘Chuy Peñuelas’, y a César Peñuelas Ruiz en Estación Bamoa, municipio de Guasave, Sinaloa. Harfuch lo describió como uno de los operadores del Cártel de Guasave; el gobierno de Estados Unidos, a través de la DEA, ofrecía 5 millones de dólares por información para capturarlo. En el operativo se aseguraron cuatro vehículos con reporte de robo, tres armas largas, cargadores y cartuchos, que quedaron a disposición de la FGR.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/mexico/harfuch-abaten-en-sinaloa-a-chuy-penuelas-buscado-por-la-dea-ofrecian-5-millones-de-dolares-por-el-20261028-0039.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-sheinbaum-sobre-taddei-si-cometio-ilicitos-en-el-ine-que-se-investigue","t":"Sheinbaum sobre Taddei: “Si cometió ilícitos en el INE, que se investigue”; niega que fuera militante de Morena","c":"politica","f":"2026-10-28T18:57","r":"En su conferencia del miércoles, la presidenta Claudia Sheinbaum rechazó que Guadalupe Taddei hubiera sido militante de Morena o nombrada por ese partido. Recordó que llegó al OPLE de Sonora en 2014 con aval del Consejo General del INE, entonces presidido por Lorenzo Córdova, y que en 2023 fue elegida por sorteo en la Cámara de Diputados al no alcanzarse la mayoría de dos tercios. Sobre los contratos bajo revisión, dijo que si hubo ilícitos deben investigarse.","b":"","img":"ine","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-28-octubre-2026-minuto-minuto-vivo-n6336239"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-sinaloa-suma-12-asesinatos-y-8-secuestros-en-un-dia-harfuch-se-reune-e","t":"Sinaloa suma 12 asesinatos y 8 secuestros en un día; Harfuch se reúne en Culiacán con la gobernadora interina","c":"seguridad","f":"2026-10-28T18:56","r":"Reportes preliminares contabilizan 12 personas asesinadas el martes en Sinaloa, sobre todo en Culiacán y Mazatlán, y 8 privadas de la libertad, entre ellas seis jóvenes llevados por un grupo armado en Villas del Real, Culiacán. El miércoles, Omar García Harfuch llegó a Culiacán, se reunió con la gobernadora interina Graciela Domínguez Nava y con mandos estatales en el C4. Sheinbaum explicó que las visitas del gabinete de seguridad responden al aumento de homicidios en los últimos dos meses; el almirante Raymundo Morales irá más adelante esta semana.","b":"","img":"ultimahora","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/sinaloa/violencia-en-sinaloa-deja-12-muertos-y-8-secuestrados-harfuch-se-reune-con-autoridades/"],["Infobae","https://www.infobae.com/mexico/2026/10/28/presencia-de-harfuch-en-sinaloa-es-debido-al-incremento-de-homicidios-en-el-estado-explica-sheinbaum-vamos-a-garantizar-la-paz/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-la-fed-deja-su-tasa-entre-3-75-y-4-dos-integrantes-votaron-por-subirla","t":"La Fed deja su tasa entre 3.75% y 4%; dos integrantes votaron por subirla","c":"economia","f":"2026-10-28T18:55","r":"La Reserva Federal de Estados Unidos mantuvo sin cambios su tasa de referencia en un rango de 3.75% a 4%, como esperaba el mercado. La decisión tuvo 10 votos a favor; la gobernadora Lisa Cook y la presidenta de la Fed de Cleveland, Beth Hammack, propusieron un alza de un cuarto de punto. El comité reconoció que la inflación sigue elevada —3.7% anual en septiembre— y dijo que necesita más datos para definir su postura; entre las presiones mencionó la energía por el conflicto con Irán y los aranceles.","b":"","img":"bolsa","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/internacional/fed-mantiene-sus-tasas-de-interes-entre-3-75-y-4-dias-antes-de-elecciones-legislativas-en-ee-uu/"],["El Financiero","https://www.elfinanciero.com.mx/economia/2026/10/28/tasa-de-interes-de-la-fed-decision-hoy-en-cuanto-quedo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-choque-de-dos-trenes-de-alta-velocidad-en-toledo-deja-al-menos-64-muer","t":"Choque de dos trenes de alta velocidad en Toledo deja al menos 64 muertos; la SRE activa atención consular","c":"internacional","f":"2026-10-28T18:54","r":"Un tren AVE de Renfe alcanzó a un tren de Iryo en la línea Madrid-Sevilla, entre Mora y Urda (Toledo), poco antes de las 9:00 horas del miércoles; dos vagones cayeron por un terraplén. Entre ambos trenes viajaban unas 540 personas. El presidente de Castilla-La Mancha, Emiliano García-Page, dio un balance provisional de 64 fallecidos y unos 80 heridos, cifra que puede aumentar. La Cancillería mexicana envió condolencias y puso a disposición el teléfono de emergencia de la embajada en España: +34 660 862 625; no ha informado de connacionales afectados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/mexico-expresa-condolencias-a-espana-por-el-accidente-de-trenes-de-alta-velocidad-en-toledo-activan-atencion-a-connacionales/"],["La Nación","https://www.lanacion.com.ar/el-mundo/choque-de-trenes-en-toledo-las-fotos-y-videos-mas-impactantes-de-la-tragedia-en-espana-nid28102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-el-ine-cancela-contratos-y-revisa-los-perfiles-nombrados-por-taddei-tr","t":"El INE cancela contratos y revisa los perfiles nombrados por Taddei tras la renuncia de tres directores","c":"politica","f":"2026-10-28T18:53","r":"La presidenta provisional del INE, Blanca Cruz García, ordenó revisar a los funcionarios designados por Guadalupe Taddei y cancelar contratos, luego de que renunciaran los titulares de Recursos Materiales y Servicios, Igualdad de Género y Servicios de Informática, señalados por su vínculo con el contratista José Alfredo Hernández. Según El Universal, personas colocadas por el llamado ‘clan Taddei’ en al menos 13 organismos electorales locales habrían favorecido contratos con su consorcio.","b":"","img":"ine","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/las-de-hoy-28-de-octubre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-el-peso-cierra-en-18-63-por-dolar-y-gana-0-21-tras-la-decision-de-la-f","t":"El peso cierra en 18.63 por dólar y gana 0.21% tras la decisión de la Fed; la Bolsa cae 0.76%","c":"economia","f":"2026-10-28T18:52","r":"El tipo de cambio terminó la sesión del miércoles en alrededor de 18.63 pesos por dólar, una apreciación de 0.21% para la moneda mexicana tras el anuncio de la Reserva Federal. El tipo de cambio FIX de Banxico se ubicó en 18.6673. En la Bolsa Mexicana, el índice S&P/BMV IPC cerró en 69,182.39 puntos, con una baja de 0.76%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Investing.com","https://mx.investing.com/news/forex-news/peso-mexicano-recibe-un-empujon-de-la-fed-precio-del-dolar-hoy-cayo-al-cierre-3819319"],["El Mañana","https://elmanana.com.mx/nacional/2026/10/28/precio-del-dolar-al-cierre-hoy-28-de-octubre-de-2026-en-mexico-183433.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-exportaciones-suman-record-de-627-mil-millones-de-dolares-de-enero-a-s","t":"Exportaciones suman récord de 627 mil millones de dólares de enero a septiembre, 30.3% más","c":"economia","f":"2026-10-28T18:51","r":"Las ventas de México al exterior acumularon 627,194 millones de dólares en los primeros nueve meses del año, un máximo histórico y 30.3% más que un año antes, según publicó El Economista. En septiembre crecieron 38% anual y sumaron ocho meses con alzas de dos dígitos; las manufacturas no automotrices subieron 53%, impulsadas por la demanda estadounidense de equipo de cómputo.","b":"","img":"bolsa","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/las-de-hoy-28-de-octubre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-el-brent-sube-1-26-a-115-32-dolares-tras-el-ataque-huti-a-la-refineria","t":"El Brent sube 1.26% a 115.32 dólares tras el ataque hutí a la refinería saudí de Ras Tanura","c":"economia","f":"2026-10-28T18:50","r":"El petróleo Brent para diciembre cerró en 115.32 dólares por barril, 1.26% más, y el WTI avanzó 2.88% a 102.78 dólares. El mercado reaccionó al ataque con misiles que los rebeldes hutíes se atribuyeron contra Ras Tanura, la mayor refinería de Arabia Saudita, y al temor de una nueva escalada en Medio Oriente tras las elecciones legislativas de Estados Unidos del 3 de noviembre.","b":"","img":"pemex","foto":"","cred":"","src":[["Diario de Yucatán / EFE","https://www.yucatan.com.mx/economia-2/2026/10/28/suben-los-precios-del-petroleo-por-tension-en-medio-oriente-el-brent-supera-los-115-y-el-wti-los-102-dolares.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-sheinbaum-responde-a-marine-le-pen-esta-mal-informada-sobre-la-mexican","t":"Sheinbaum responde a Marine Le Pen: “Está mal informada” sobre la ‘mexicanización’ de los cárteles","c":"politica","f":"2026-10-28T18:49","r":"Consultada sobre la afirmación de la dirigente francesa Marine Le Pen de que Francia no caerá en la ‘mexicanización de los cárteles’, la presidenta respondió que está mal informada. En la misma conferencia dijo que la integración económica con Estados Unidos es amplia pero debe mantenerse con soberanía, y sobre la salida de Flávio Bolsonaro de Brasil comentó que ‘se explica solo’.","b":"","img":"paris","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-28-octubre-2026-minuto-minuto-vivo-n6336239"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-abre-el-puente-amado-nervo-entre-bahia-de-banderas-y-puerto-vallarta-a","t":"Abre el puente Amado Nervo entre Bahía de Banderas y Puerto Vallarta; ahorrará hasta 40 minutos","c":"estados","f":"2026-10-28T18:48","r":"La presidenta Sheinbaum inauguró a distancia, durante su conferencia matutina, el puente Amado Nervo, que une Bahía de Banderas, Nayarit, con Puerto Vallarta, Jalisco. La obra reducirá hasta 40 minutos los traslados en esa zona turística. La mandataria afirmó que en su sexenio se construyen 402 puentes en el país.","b":"","img":"carretera","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-28-octubre-2026-minuto-minuto-vivo-n6336239"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-jalisco-toma-el-control-de-la-potabilizadora-de-toluquilla-en-manos-pr","t":"Jalisco toma el control de la potabilizadora de Toluquilla, en manos privadas desde 2012","c":"estados","f":"2026-10-28T18:47","r":"El gobernador Pablo Lemus anunció que el gobierno estatal asumió el control de la planta potabilizadora número 4 de Toluquilla, operada por particulares desde 2012, porque no cumplió lo comprometido. Lemus atribuyó la contaminación en Las Pintas, la zona más afectada de la metrópoli, a inundaciones que llevaron agua residual y desbordes de algunas fábricas al canal.","b":"","img":"jalisco","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-28-octubre-2026-minuto-minuto-vivo-n6336239"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-la-onu-vuelve-a-pedir-el-fin-del-embargo-a-cuba-pero-con-130-votos-el","t":"La ONU vuelve a pedir el fin del embargo a Cuba, pero con 130 votos, el menor apoyo en años","c":"internacional","f":"2026-10-28T18:46","r":"La Asamblea General aprobó la resolución cubana contra el embargo de Estados Unidos con 130 votos a favor, 17 en contra y 25 abstenciones. En 2025 había obtenido 165 votos a favor y 7 en contra. Entre los nuevos votos en contra están Colombia, Costa Rica, Ecuador, Guatemala y Austria; Alemania se abstuvo por primera vez desde 2002.","b":"","img":"habana","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/28/la-onu-renueva-la-resolucion-contra-el-embargo-de-eeuu-a-cuba-con-130-votos-a-favor/"],["CiberCuba","https://www.cibercuba.com/noticias/2026-10-28-u1-e74-s27061-nid344063-resolucion-contra-embargo-pierde-fuerza-onu-35-votos"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-flavio-bolsonaro-llega-a-florida-pese-a-la-prohibicion-judicial-de-sal","t":"Flávio Bolsonaro llega a Florida pese a la prohibición judicial de salir de Brasil","c":"internacional","f":"2026-10-28T18:45","r":"Tras perder la segunda vuelta del 25 de octubre ante Lula da Silva, Flávio Bolsonaro salió de Brasil hacia Argentina, voló a Guayaquil en avión privado y llegó a Florida, según la AFP. El juez Alexandre de Moraes le había ordenado entregar sus pasaportes y le prohibió salir del país; la Policía Federal investiga cómo cruzó sin registro migratorio. Enfrenta indagatorias por presunto lavado de dinero y evasión de divisas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Imagen Radio","https://www.imagenradio.com.mx/noticias/por-que-salio-flavio-bolsonaro-brasil-que-acusan"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-azure-ingresa-33-200-millones-de-dolares-en-el-trimestre-y-crece-48-mi","t":"Azure ingresa 33,200 millones de dólares en el trimestre y crece 48%; Microsoft factura récord","c":"tecnologia","f":"2026-10-28T18:44","r":"Microsoft reportó ingresos trimestrales récord de 92,300 millones de dólares. Por primera vez desglosó en dólares su nube Azure, que facturó 33,200 millones, 48% más que hace un año y por encima de lo que esperaban los analistas. Azure ya representa cerca de 36% de los ingresos de la empresa.","b":"","img":"tech","foto":"","cred":"","src":[["TechCrunch","https://techcrunch.com/2026/10/28/microsoft-just-shared-azures-actual-revenue-in-dollars-33-2-billion/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-google-cloud-duplica-sus-ingresos-pero-la-utilidad-de-alphabet-cae-en","t":"Google Cloud duplica sus ingresos, pero la utilidad de Alphabet cae en el tercer trimestre","c":"tecnologia","f":"2026-10-28T18:43","r":"Alphabet ingresó 127,600 millones de dólares entre julio y septiembre, 25% más que un año antes. Google Cloud facturó 30,700 millones, un alza de 103%. La utilidad neta fue de 26,200 millones, menor a la del año previo, afectada por una pérdida de 8,700 millones en inversiones en acciones; su gasto en propiedades y equipo llegó a 51,400 millones.","b":"","img":"tech","foto":"","cred":"","src":[["Unite.AI","https://www.unite.ai/alphabet-posts-25-revenue-growth-as-google-cloud-jumps-103/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-checo-perez-renueva-con-cadillac-hasta-2029-en-la-semana-de-su-gran-pr","t":"Checo Pérez renueva con Cadillac hasta 2029 en la semana de su Gran Premio 300","c":"deportes","f":"2026-10-28T18:42","r":"Cadillac confirmó la extensión del contrato de Sergio Pérez por varios años, al menos hasta la temporada 2029, en vísperas del Gran Premio de la Ciudad de México. El piloto dijo estar plenamente comprometido para los próximos tres años; el director del equipo, Dan Towriss, lo llamó una pieza integral. No se revelaron los términos económicos.","b":"","img":"autodromo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/28/checo-perez-extiende-su-contrato-con-cadillac-hasta-el-2029/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-checo-perez-recorre-reforma-en-su-cadillac-ante-miles-de-aficionados","t":"Checo Pérez recorre Reforma en su Cadillac ante miles de aficionados","c":"deportes","f":"2026-10-28T18:41","r":"Sergio Pérez manejó el monoplaza de Cadillac por Paseo de la Reforma, entre la Diana Cazadora y el Ángel de la Independencia, en una exhibición previa al Gran Premio de México. Saludó a los aficionados y dio giros en la glorieta. El operativo incluyó 102 policías. El fin de semana de carreras va del 30 de octubre al 1 de noviembre en el Autódromo Hermanos Rodríguez; la carrera es el domingo a las 14:00 horas.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/28/checo-perez-recorre-el-paseo-de-la-reforma-en-su-cadillac-en-el-showrun-de-la-cdmx-previo-al-gran-premio-de-mexico/"],["Quinta Fuerza","https://quintafuerza.mx/mexico/video-checo-perez-deleita-miles-fans-cadillac-paseo-reforma/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-dia-de-muertos-las-figuras-del-espectaculo-que-murieron-en-2026","t":"Día de Muertos: las figuras del espectáculo que murieron en 2026, de Germán Medina a El Komanche","c":"entretenimiento","f":"2026-10-28T18:40","r":"A días del Día de Muertos, Infobae recordó a figuras del espectáculo que fallecieron este año: Germán Medina, de 21 años, en un accidente en la autopista Tepic-Matanchén en agosto; Gera Rosillo, el 23 de octubre en la carretera Celaya-Salvatierra; el streamer Carlos Mauricio Gómez, ‘El Komanche’, de 30 años, hallado sin vida en Monterrey el 25 de octubre, y José Guadalupe Fuentes Ochoa, ‘Baby Face’, de 79 años, en septiembre.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/dia-de-muertos-famosos-que-nos-dejaron-antes-de-tiempo-este-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-senado-exime-a-automotrices-y-gasolineras-del-tope-a-deducciones-la-le","t":"Senado exime a automotrices y gasolineras del tope a deducciones; la Ley del ISR vuelve a Diputados","c":"politica","f":"2026-10-28T06:53","r":"El pleno del Senado aprobó la noche del martes la Ley de Ingresos y la Ley Federal de Derechos para 2027 sin cambios, por lo que ambas pasan al Ejecutivo. En cambio, modificó la Ley del ISR con una reserva de Morena al artículo 78E que exime a la producción automotriz y a la venta de gasolina y diésel del límite a deducciones para empresas con ingresos de más de 50 millones de pesos; por ese cambio, la ley regresa a la Cámara de Diputados. La oposición criticó el techo de endeudamiento de hasta 1.7 billones de pesos.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/28/senado-aprueba-cambios-al-isr-y-aumentos-en-cuotas-de-servicios-y-tramites-para-2027/"],["Uno TV","https://www.unotv.com/nacional/senado-aprueba-paquete-economico-2027-ley-del-isr-vuelve-a-diputados/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-el-gabinete-de-seguridad-inicia-visitas-de-supervision-en-sinaloa-trev","t":"El gabinete de seguridad inicia visitas de supervisión en Sinaloa; Trevilla fue el primero","c":"seguridad","f":"2026-10-28T06:52","r":"Por instrucción de la presidenta Claudia Sheinbaum, los titulares de seguridad federal comenzaron una agenda de visitas de supervisión a Sinaloa, estado golpeado desde hace más de dos años por la pugna entre Los Mayos y Los Chapitos. El secretario de la Defensa, Ricardo Trevilla, acudió el martes 27; Omar García Harfuch (SSPC) y el almirante Raymundo Pedro Morales (Marina) lo harán en otros días de esta semana.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/28/estados/026n4est?partner=rss"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-vance-ya-tormenta-tropical-traera-lluvias-de-hasta-150-mm-a-sinaloa-na","t":"Vance, ya tormenta tropical, traerá lluvias de hasta 150 mm a Sinaloa, Nayarit y Durango","c":"nacional","f":"2026-10-28T06:51","r":"La tormenta tropical Vance se ubicaba a unos 470 kilómetros al oeste-suroeste de Manzanillo, Colima, según Conagua. El Servicio Meteorológico Nacional prevé para este miércoles lluvias muy fuertes con puntuales intensas (75 a 150 mm) en el sur de Sinaloa, el norte de Nayarit y el sur de Durango, y fuertes en Baja California Sur, Jalisco y Zacatecas, además de rachas de viento y oleaje elevado en la costa del Pacífico.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-miercoles-28-de-octubre-vance-amenaza-con-lluvias-intensas/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-la-inseguridad-eleva-hasta-25-los-costos-de-las-fabricas-de-electronic","t":"La inseguridad eleva hasta 25% los costos de las fábricas de electrónicos, advierte Canieti","c":"economia","f":"2026-10-28T06:50","r":"Directivos de la Cámara Nacional de la Industria Electrónica (Canieti) señalaron que la violencia en estados manufactureros aumenta entre 15% y 25% los costos de proteger mercancías, con rastreo satelital, escoltas y traslados en caravana, y que hay inversiones detenidas por ese motivo. La electrónica es desde mayo el principal sector exportador del país, impulsada por la demanda de servidores para inteligencia artificial.","b":"","img":"tech2","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/empresas/2026/10/28/inseguridad-encarece-hasta-25-por-ciento-la-produccion-de-electronicos-en-mexico/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-28-reportan-que-la-esposa-de-cuauhtemoc-blanco-fue-retenida-en-nueva-york","t":"Reportan que la esposa de Cuauhtémoc Blanco fue retenida en Nueva York; el diputado lo niega","c":"politica","f":"2026-10-28T06:49","r":"La revista Proceso informó, con base en fuentes cercanas al legislador, que Natalia Rezende, esposa del diputado de Morena Cuauhtémoc Blanco, habría sido retenida hace un par de semanas en un aeropuerto de Nueva York por llevar efectivo sin declarar, que justificó como donativo a una iglesia, y que le habrían retirado la visa. Blanco negó la versión, la calificó de falsa y la atribuyó a un \"tema político\" de otros partidos.","b":"","img":"senado","foto":"","cred":"","src":[["La Razón","https://razon.com.mx/mexico/2026/10/27/esposa-de-cuauhtemoc-blanco-habria-sido-detenida-en-eu-el-lo-niega-y-acusa-tema-politico"],["Proceso","https://www.proceso.com.mx/nacional/2026/10/27/detienen-en-nueva-york-a-natalia-rezende-esposa-de-cuauhtemoc-blanco-382639.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-la-fed-anuncia-hoy-su-decision-de-tasas-casi-todos-los-analistas-esper","t":"La Fed anuncia hoy su decisión de tasas; casi todos los analistas esperan una pausa","c":"economia","f":"2026-10-28T06:48","r":"La Reserva Federal de Estados Unidos concluye este miércoles su reunión de política monetaria y comunica su decisión a las 14:00 horas de Nueva York. El rango de su tasa está en 3.75%-4.00% tras la alza de septiembre. En una encuesta de Reuters, 94 de 100 economistas prevén que la mantenga sin cambios ahora y todos esperan un aumento en diciembre, ante una inflación persistente y un petróleo arriba de 100 dólares.","b":"","img":"bolsa","foto":"","cred":"","src":[["GBM / Reuters","https://gbm.com/media/noticia/economistas-coinciden-en-que-la-fed-no-subira-las-tasas-en-octubre-lo-hara-de-nuevo-en-diciembre/"],["Admiral Markets","https://admiralmarkets.com/es/analytics/traders-blog/decision-de-la-fed-octubre-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-el-peso-abre-el-miercoles-en-18-63-por-dolar-con-una-ganancia-de-0-24","t":"El peso abre el miércoles en 18.63 por dólar, con una ganancia de 0.24%","c":"economia","f":"2026-10-28T06:47","r":"El tipo de cambio inició la jornada en un promedio de 18.63 pesos por dólar, 0.24% por debajo del precio previo de 18.68, con datos de Dow Jones citados por Infobae. En la última semana el dólar retrocede 0.28% frente al peso. Los mercados esperan la decisión de la Reserva Federal y los reportes de grandes tecnológicas.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-28-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-volaris-pierde-26-millones-de-dolares-en-el-tercer-trimestre-pese-a-in","t":"Volaris pierde 26 millones de dólares en el tercer trimestre pese a ingresos récord","c":"economia","f":"2026-10-28T06:46","r":"La aerolínea reportó ingresos de 1,038 millones de dólares entre julio y septiembre, 32.4% más que un año antes, pero cerró con una pérdida neta de 26 millones, frente a una utilidad de 6 millones en 2025. El costo promedio del combustible subió 57.4%, a 4.10 dólares por galón. Transportó cerca de 9 millones de pasajeros, 14.3% más, y prevé un margen EBITDAR anual de alrededor de 21%.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Stock Titan (reporte de Volaris)","https://www.stocktitan.net/news/VLRS/volaris-reports-financial-results-for-the-third-quarter-2026-1-yrwbyr0bt3rt.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-el-huachicol-fiscal-costaria-mas-de-113-mil-millones-de-pesos-si-se-su","t":"El huachicol fiscal costaría más de 113 mil millones de pesos si se suma la evasión de IVA","c":"nacional","f":"2026-10-28T06:45","r":"El gobierno federal reportó pérdidas por 61,785 millones de pesos en IEPS en 2025 por combustibles que ingresaron sin pagar impuestos, pero esa cifra no incluye el IVA. Francisco Barnés, exsubsecretario de Hidrocarburos de la Sener y socio de Cifra2 Consultores, estima que la evasión de IVA superaría los 52,000 millones, con lo que el quebranto total rondaría los 113,785 millones de pesos, según Expansión.","b":"","img":"pemex","foto":"","cred":"","src":[["Expansión","https://expansion.mx/empresas/2026/10/26/huachicol-fiscal-perdidas-evasion-del-iva"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-localizan-con-vida-al-sacerdote-clemente-morales-desaparecido-en-culia","t":"Localizan con vida al sacerdote Clemente Morales, desaparecido en Culiacán desde el sábado","c":"estados","f":"2026-10-28T06:44","r":"La Secretaría de Seguridad Pública de Sinaloa informó que el sacerdote Clemente Morales, de quien no se sabía nada desde el 24 de octubre, fue localizado con vida. En el mismo estado sigue sin aparecer José Luis Vega Parra, médico del penal de El Castillo en Mazatlán, visto por última vez el viernes en El Rosario.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/28/estados/026n4est?partner=rss"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-dejan-una-cabeza-humana-junto-al-palacio-municipal-de-mazatlan-con-un","t":"Dejan una cabeza humana junto al palacio municipal de Mazatlán con un mensaje al padre de la alcaldesa","c":"estados","f":"2026-10-28T06:43","r":"En la madrugada del martes 27 se localizó una cabeza humana dentro de una hielera cerca de la oficina de Ingresos del palacio municipal de Mazatlán, con un mensaje dirigido al padre de la presidenta municipal, Estrella Palacios. La Jornada reportó el hallazgo en medio de la ola de violencia que vive el estado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/28/estados/026n4est?partner=rss"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-mexico-y-estados-unidos-realizan-el-ejercicio-aereo-amalgam-eagle-2026","t":"México y Estados Unidos realizan el ejercicio aéreo Amalgam Eagle 2026 en la frontera","c":"seguridad","f":"2026-10-28T06:42","r":"La Secretaría de la Defensa Nacional y las fuerzas aéreas del Comando Norte de Estados Unidos llevaron a cabo el ejercicio Amalgam Eagle 2026 en la franja fronteriza, con vuelos reales y operaciones simuladas centradas en interceptar vuelos no autorizados. Las autoridades indicaron que busca mejorar la coordinación en el espacio aéreo compartido con respeto a la soberanía de ambos países.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/fuerzas-aereas-mexico-y-estados-unidos-realizan-ejercicio-amalgam-eagle-2026-frontera"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-trump-dice-que-la-guerra-con-iran-se-reanudara-en-un-par-de-semanas-tr","t":"Trump dice que la guerra con Irán se reanudará \"en un par de semanas\", tras las elecciones","c":"internacional","f":"2026-10-28T06:41","r":"En un mitin en Lubbock, Texas, en apoyo al republicano Ken Paxton, el presidente Donald Trump afirmó el martes por la noche que el conflicto con Irán volverá en un par de semanas, después de las elecciones intermedias del 3 de noviembre, e insistió en que Teherán no puede tener un arma nuclear. También sostuvo que la gasolina bajará cuando termine la guerra.","b":"","img":"texas","foto":"","cred":"","src":[["Moncloa.com","https://www.moncloa.com/2026/10/28/trump-iran-guerra-legislativas-3n-3456863/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-la-onu-vota-hoy-por-34a-vez-la-resolucion-de-cuba-contra-el-embargo-eu","t":"La ONU vota hoy por 34ª vez la resolución de Cuba contra el embargo; EU pide rechazarla","c":"internacional","f":"2026-10-28T06:40","r":"La Asamblea General de Naciones Unidas vota este miércoles la resolución cubana que pide poner fin al embargo de Estados Unidos, que la isla presenta desde 1992. En el debate del martes, el embajador estadounidense Mike Waltz pidió votar en contra y negó que exista un bloqueo. En 2025 la resolución obtuvo 165 votos a favor, frente a 187 en 2024.","b":"","img":"habana","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/cuba/2026/10/27/el-embajador-estadounidense-pide-a-la-asamblea-general-rechazar-la-resolucion-cubana-contra-el-embargo/"],["Noticias ONU","https://news.un.org/es/story/2026/10/1542112"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-la-cdmx-desplegara-11-mil-policias-en-120-panteones-por-dia-de-muertos","t":"La CDMX desplegará 11 mil policías en 120 panteones por Día de Muertos","c":"cdmx","f":"2026-10-28T06:39","r":"La Secretaría de Seguridad Ciudadana capitalina activará del 30 de octubre al 2 de noviembre un operativo en 120 cementerios de las 16 alcaldías, donde espera 1.5 millones de visitantes. Participarán 11 mil policías, 720 vehículos, 20 motopatrullas y ocho ambulancias del ERUM, con sobrevuelos en panteones como San Andrés Mixquic y San Nicolás Tolentino.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/dia-de-muertos-2026-en-ciudad-de-mexico-inicia-operativo-de-seguridad-en-120-panteones/"],["El Congresista","https://elcongresista.mx/seguridad/operativo-seguridad-dia-muertos-cdmx-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-checo-perez-rodara-hoy-en-reforma-con-su-cadillac-antes-de-su-gran-pre","t":"Checo Pérez rodará hoy en Reforma con su Cadillac antes de su Gran Premio 300","c":"deportes","f":"2026-10-28T06:38","r":"Sergio Pérez hará una exhibición a las 10:00 horas en Paseo de la Reforma, entre la Diana Cazadora y el Ángel de la Independencia, como antesala del Gran Premio de México que se corre este fin de semana en el Autódromo Hermanos Rodríguez. Habrá cierres en la zona; las autoridades sugieren usar los carriles laterales, Insurgentes y Circuito Interior. Operarán 102 policías.","b":"","img":"angel","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/10/28/show-run-de-checo-perez-en-reforma-todos-los-detalles-en-vivo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-los-rays-evitan-la-barrida-vencen-4-3-a-los-cerveceros-en-12-entradas","t":"Los Rays evitan la barrida: vencen 4-3 a los Cerveceros en 12 entradas y fuerzan el quinto juego","c":"deportes","f":"2026-10-28T06:37","r":"Tampa Bay remontó en la parte baja de la duodécima entrada, luego de que Cooper Pratt pusiera arriba a Milwaukee con un jonrón, y ganó con un sencillo del emergente Ben Williamson. Los Cerveceros siguen arriba 3-1 en la Serie Mundial; el quinto juego es este miércoles en el Tropicana Field.","b":"","img":"beisbol","foto":"","cred":"","src":[["La Opinión","https://laopinion.com/2026/10/28/los-rays-evitan-la-barrida-de-los-brewers-y-prolongan-la-serie-mundial/"],["Diario Libre","https://www.diariolibre.com/deportes/beisbol/2026/10/28/mlb-los-rays-evitan-la-barrida-en-una-victoria-en-12-entradas/3703172"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-microsoft-y-alphabet-reportan-hoy-con-el-gasto-en-inteligencia-artific","t":"Microsoft y Alphabet reportan hoy, con el gasto en inteligencia artificial bajo la lupa","c":"tecnologia","f":"2026-10-28T06:36","r":"Las dos tecnológicas publicarán sus resultados trimestrales este miércoles al cierre de Wall Street. Analistas esperan que los ingresos de Alphabet crezcan 25.2% y los de Microsoft 16.7%. En el trimestre previo, Azure creció 43% y Google Cloud 82%; los inversionistas buscan señales de que la inversión en IA se traduce en ingresos.","b":"","img":"tech","foto":"","cred":"","src":[["DiarioBitcoin","https://www.diariobitcoin.com/tecnologia/alphabet-y-microsoft-afrontan-una-prueba-decisiva-sobre-el-gasto-en-inteligencia-artificial/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-ernesto-chavana-patea-un-dron-en-vivo-y-golpea-en-el-rostro-a-una-mode","t":"Ernesto Chavana patea un dron en vivo y golpea en el rostro a una modelo; ofrece disculpas","c":"entretenimiento","f":"2026-10-28T06:35","r":"Durante una transmisión del programa Es Show, de Multimedios en Monterrey, el conductor Ernesto Chavana pateó un dron que volaba bajo y el aparato golpeó en la cara a la modelo Isabella Rojas. Ella recibió atención médica y volvió al foro con lesiones aparentemente leves. Chavana se disculpó al aire y la producción dijo que él cubrirá los gastos.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/renuncias-en-vivo-y-detencion-de-colaboradores-las-otras-polemicas-de-ernesto-chavana/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-28-kim-kardashian-vuelve-con-todo-vale-la-segunda-temporada-llega-a-disne","t":"Kim Kardashian vuelve con \"Todo Vale\": la segunda temporada llega a Disney+ el 4 de noviembre","c":"entretenimiento","f":"2026-10-28T06:34","r":"La serie de abogadas de divorcio protagonizada por Kim Kardashian, Naomi Watts, Niecy Nash-Betts, Sarah Paulson y Glenn Close estrenará su segunda temporada en Disney+ el miércoles 4 de noviembre con tres episodios; el resto saldrá cada semana hasta el 2 de diciembre. Cauã Reymond se suma al elenco.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/kim-kardashian-llega-a-mexico-con-todo-vale-de-que-trata-la-serie-y-cuando-se-estrena-la-segunda-temporada/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-termina-el-paro-de-transportistas-segob-y-canacar-acuerdan-retirar-blo","t":"Termina el paro de transportistas: Segob y Canacar acuerdan retirar bloqueos y abrir mesas de diálogo","c":"nacional","f":"2026-10-27T18:40","r":"Tras una reunión de trabajo este martes, la Secretaría de Gobernación informó que la Canacar y otras organizaciones del autotransporte se comprometieron a retirar de forma definitiva los bloqueos carreteros y suspender las protestas, que el lunes alcanzaron 19 estados. A cambio se instalarán mesas con las dependencias correspondientes sobre seguridad carretera, infraestructura, temas fiscales, seguridad social y condiciones laborales, coordinadas por la Subsecretaría de Gobernación. En la reunión también participó la Concanaco Servytur.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/27/segob-acuerda-con-canacar-retirar-bloqueos-tras-paro-nacional-en-19-estados/"],["Excélsior","https://www.excelsior.com.mx/nacional/segob-y-canacar-instalan-mesa-dialogo-demandas-transportistas"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-el-senado-aprueba-la-ley-de-ingresos-2027-por-10-6-billones-de-pesos-y","t":"El Senado aprueba la Ley de Ingresos 2027 por 10.6 billones de pesos y un techo de deuda de 1.7 billones","c":"economia","f":"2026-10-27T18:38","r":"El pleno del Senado aprobó la Ley de Ingresos de la Federación para 2027, que prevé recaudar 10.63 billones de pesos, de los cuales unos 6.26 billones serían ingresos tributarios, y autoriza un endeudamiento interno neto de hasta 1.7 billones. En lo general hubo 79 votos a favor de Morena, PVEM y PT y 34 en contra de PAN, PRI y MC. El paquete elimina el tope de 300 millones de pesos a la condonación de multas y recargos en el programa de regularización y sube de 983 a 1,158 pesos el derecho que pagan los visitantes extranjeros. El oficialismo dijo que no hay impuestos nuevos; la oposición cuestionó el nivel de deuda.","b":"","img":"senado","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/27/senado-aprueba-ley-de-ingresos-2027-por-106-billones-de-pesos/"],["Milenio","https://www.milenio.com/politica/senado-aprueba-la-ley-de-ingresos-2027"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-imss-sube-8-el-salario-de-504-mil-trabajadores-por-encima-del-6-8-apro","t":"IMSS sube 8% el salario de 504 mil trabajadores, por encima del 6.8% aprobado","c":"nacional","f":"2026-10-27T18:36","r":"En la conferencia matutina, el IMSS anunció que su personal en activo recibirá un ajuste de 8% desde este 27 de octubre: 4% al salario tabular y 4% a la ayuda de renta, frente al 6.8% avalado por el Congreso. El incremento adicional cuesta 5,229 millones de pesos. Como ejemplo, el pago neto mensual de un médico especialista con un año de antigüedad pasaría de 36,896 a 39,120 pesos. El anuncio forma parte de un plan de 12 acciones en 120 días que incluye basificar a 10,939 trabajadores y atender 31,701 cirugías rezagadas, con fecha límite del 24 de febrero.","b":"","img":"imss","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-martes-27-octubre-2026-minuto-minuto-vivo-n6336231"],["Infobae","https://www.infobae.com/mexico/2026/10/27/la-mananera-de-la-presidenta-claudia-sheinbaum-hoy-27-de-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-blanca-cruz-garcia-es-elegida-presidenta-provisional-del-ine-tras-la-s","t":"Blanca Cruz García es elegida presidenta provisional del INE tras la salida de Taddei","c":"politica","f":"2026-10-27T18:34","r":"Las y los consejeros del INE designaron a Blanca Yassahara Cruz García como presidenta provisional del Consejo General, luego de la renuncia de Guadalupe Taddei. Abogada originaria de Huajuapan de León, Oaxaca, trabajó en juntas distritales del INE en Puebla de 2011 a 2022 y presidió el instituto electoral poblano desde noviembre de 2022. Permanecerá en el cargo hasta que la Cámara de Diputados nombre a la presidencia definitiva con dos terceras partes de los votos; quien llegue completará el periodo que vence en 2032.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/27/de-puebla-a-la-presidencia-provisional-del-ine-quien-es-blanca-yassahara-cruz-garcia-y-hasta-cuando-estara-al-frente-del-instituto/"],["La Razón","https://www.razon.com.mx/mexico/2026/10/27/blanca-cruz-garcia-fue-elegida-presidenta-provisional-del-consejo-general-del-ine/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-sheinbaum-pide-a-la-asf-auditar-todos-los-contratos-del-ine-con-taddei","t":"Sheinbaum pide a la ASF auditar todos los contratos del INE, con Taddei y con Córdova","c":"politica","f":"2026-10-27T18:32","r":"La presidenta Claudia Sheinbaum solicitó a la Auditoría Superior de la Federación revisar los contratos del INE durante las gestiones de Guadalupe Taddei y Lorenzo Córdova, y que se informe desde cuándo existen los vínculos con los contratistas señalados. Dijo que la revisión permitiría deslindar responsabilidades si hubo corrupción. Recordó que en el sexenio anterior la UIF congeló cuentas de algunas de esas empresas, pero que un amparo levantó la medida.","b":"","img":"palacio","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/mananera-sheinbaum-hoy-27-octubre-2026-piden-revision-asf-ine/"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-martes-27-octubre-2026-minuto-minuto-vivo-n6336231"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-diputados-aprueban-la-cuenta-publica-2024-con-65-mil-millones-de-pesos","t":"Diputados aprueban la Cuenta Pública 2024 con 65 mil millones de pesos aún por aclarar","c":"politica","f":"2026-10-27T18:30","r":"La Cámara de Diputados aprobó con 321 votos a favor y 117 en contra el dictamen de la Cuenta Pública 2024, último año del gobierno de Andrés Manuel López Obrador. La ASF detectó irregularidades por unos 67 mil millones de pesos, de los que se han recuperado alrededor de 2 mil millones; quedan pendientes 65,169 millones, de ellos 59,363 millones en gasto federalizado. PAN y PRI pidieron dar seguimiento a cada observación.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/camara-de-diputados-aprueba-la-cuenta-publica-de-2024-ultimo-ano-amlo-con-65-mil-millones-de-pesos-por-aclarar/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-diputados-avalan-en-lo-general-la-ley-de-inversion-extranjera-con-revi","t":"Diputados avalan en lo general la Ley de Inversión Extranjera con revisión por seguridad nacional","c":"economia","f":"2026-10-27T18:28","r":"Con 314 votos a favor y 117 en contra, la Cámara de Diputados aprobó en lo general la reforma a la Ley de Inversión Extranjera, ya avalada por el Senado. Crea una revisión previa por seguridad nacional cuando capital extranjero busque más de 49% del control de empresas mexicanas en sectores estratégicos, y suma a la Comisión Nacional de Inversiones Extranjeras a los titulares de Defensa, Marina, SSPC y la Agencia de Transformación Digital. La oposición advirtió riesgos para la certeza jurídica; queda pendiente la discusión en lo particular.","b":"","img":"senado","foto":"","cred":"","src":[["Político MX","https://politico.mx/2026/10/27/diputados-aprueban-en-lo-general-la-ley-de-inversion-extranjera/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-la-modalidad-40-no-desaparece-asegura-el-imss-quienes-ya-se-pensionaro","t":"La Modalidad 40 no desaparece, asegura el IMSS; quienes ya se pensionaron conservan su monto","c":"nacional","f":"2026-10-27T18:26","r":"Zoé Robledo, director del IMSS, afirmó que la Modalidad 40 seguirá en la ley como régimen de continuidad voluntaria y que las pensiones ya otorgadas no cambiarán. Explicó que las nuevas restricciones buscan frenar esquemas de financiamiento que, según el instituto, trasladan el costo al Estado; el IMSS ha presentado 115 denuncias y habrá un periodo provisional de seis meses para analizar el esquema. También advirtió una posible evasión de aportaciones que afectaría a unos 77 mil conductores de Uber.","b":"","img":"imss","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-martes-27-octubre-2026-minuto-minuto-vivo-n6336231"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-mexico-vuelve-al-deficit-comercial-en-septiembre-606-millones-de-dolar","t":"México vuelve al déficit comercial en septiembre: 606 millones de dólares pese a exportaciones récord","c":"economia","f":"2026-10-27T18:24","r":"Según datos del INEGI, la balanza comercial registró en septiembre un déficit de 606 millones de dólares, tras un superávit de 605 millones en agosto. Las exportaciones sumaron 77,797 millones, 37.9% más que hace un año, y las importaciones 78,403 millones, con un alza de 33.1%. El superávit no petrolero bajó a 2,748 millones. En enero-septiembre el país acumula un superávit de 9,254 millones de dólares.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/10/27/exportaciones-mexico-septiembre-2026-deficit-comercial"],["Forbes México","https://forbes.com.mx/mexico-reporta-un-deficit-comercial-de-606-1-millones-de-dolares-en-septiembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-el-peso-cede-0-65-y-cierra-en-18-68-por-dolar-antes-de-la-decision-de","t":"El peso cede 0.65% y cierra en 18.68 por dólar antes de la decisión de la Fed","c":"economia","f":"2026-10-27T18:22","r":"El peso terminó el martes en 18.6798 unidades por dólar, según Banxico, con lo que cortó dos jornadas de ganancias; en el día osciló entre 18.61 y 18.70. El índice del dólar subió 0.37% y los inversionistas esperan el anuncio de política monetaria de la Reserva Federal de este miércoles. En ventanilla, BBVA vendía en 18.96 y Banamex en 19.17.","b":"","img":"bolsa","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/tipo-de-cambio-peso-dolar-hoy-27-de-octubre-de-2026/"],["Infobae","https://www.infobae.com/mexico/2026/10/27/dolar-hoy-en-mexico-cotizacion-de-cierre-del-27-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-el-brent-baja-1-67-y-cierra-en-113-88-dolares-por-la-diplomacia-en-med","t":"El Brent baja 1.67% y cierra en 113.88 dólares por la diplomacia en Medio Oriente","c":"economia","f":"2026-10-27T18:20","r":"El crudo Brent para diciembre cerró en 113.88 dólares por barril en Londres, 1.93 dólares menos que el lunes, aunque al inicio de la sesión rozó los 117. Los inversionistas reaccionaron a los esfuerzos diplomáticos en la región y estaban atentos a las elecciones en Israel. Analistas advirtieron que los ataques a buques en Ormuz y la caída de exportaciones por el golfo Pérsico mantienen limitada la oferta.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/agencias/2026/10/27/el-crudo-brent-baja-un-167-y-cierra-por-debajo-de-los-114-dolares/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-fgr-desarticula-una-celula-de-secuestradores-ligada-al-asesinato-de-un","t":"FGR desarticula una célula de secuestradores ligada al asesinato de un agente federal en Almoloya","c":"seguridad","f":"2026-10-27T18:18","r":"La Fiscalía General de la República informó que detuvo a cinco presuntos integrantes de una célula dedicada al secuestro en el Estado de México, vinculada al asesinato de un agente de la Policía Federal Ministerial el 12 de octubre en Almoloya. Un juez vinculó a proceso a cuatro de ellos; el quinto, señalado como negociador y detenido el 22 de octubre, espera su audiencia inicial. La investigación, a cargo de la FEMDO, partió de un secuestro ocurrido en Toluca.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/28/fgr-desarticula-celula-de-secuestradores-ligada-al-asesinato-de-un-agente-federal-en-almoloya/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-atacan-a-agentes-de-la-sspc-en-celaya-durante-un-operativo-contra-robo","t":"Atacan a agentes de la SSPC en Celaya durante un operativo contra robo a transporte; muere un agresor","c":"seguridad","f":"2026-10-27T18:16","r":"Elementos de la Secretaría de Seguridad y Protección Ciudadana fueron agredidos a balazos en Celaya, Guanajuato, cuando atendían el reporte de un robo a transporte de carga. Según informó Omar García Harfuch, uno de los presuntos atacantes murió y otro resultó herido, pero escapó; las autoridades lo buscan. No se reportaron agentes lesionados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/27/agreden-a-elementos-de-la-sspc-durante-operativo-contra-robo-a-transporte-en-celaya-muere-un-atacante/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-balean-en-culiacan-una-casa-que-vecinos-ligan-a-rocha-moya-al-dia-sigu","t":"Balean en Culiacán una casa que vecinos ligan a Rocha Moya; al día siguiente hieren a un hombre afuera","c":"estados","f":"2026-10-27T18:14","r":"Un grupo armado disparó la noche del lunes contra una vivienda de la colonia Chapultepec, en Culiacán, que se presume ligada al gobernador con licencia Rubén Rocha Moya, aunque las autoridades no lo han confirmado. La fachada y la puerta quedaron con múltiples impactos y no hubo heridos. La mañana del martes, un hombre fue herido de bala mientras esperaba en una camioneta frente a la misma casa. No hay comunicado oficial sobre los hechos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/27/balean-casa-presuntamente-ligada-al-gobernador-con-licencia-ruben-rocha-moya-en-culiacan/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-hijos-de-un-campesino-secuestrado-en-ajuchitlan-guerrero-piden-ayuda-a","t":"Hijos de un campesino secuestrado en Ajuchitlán, Guerrero, piden ayuda a Sheinbaum tras más de un mes","c":"estados","f":"2026-10-27T18:12","r":"Domingo Atanacio Quirino, de 50 años, es el único de ocho campesinos secuestrados en Ajuchitlán del Progreso, en la sierra de Guerrero, que sigue sin ser localizado después de más de un mes. Sus hijos difundieron un tercer video en una semana en el que piden la intervención de la presidenta Claudia Sheinbaum, del secretario Omar García Harfuch y de la gobernadora Evelyn Salgado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/27/en-vivo-seguridad-narcotrafico-y-crimen-hoy-27-de-octubre-en-mexico-los-santelices-pierden-primer-round-contra-la-uif-por-bloqueo-de-cuentas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-gran-premio-de-mexico-atraera-a-mas-de-450-mil-personas-la-cdmx-amplia","t":"Gran Premio de México atraerá a más de 450 mil personas; la CDMX amplía horarios de Metro y RTP","c":"cdmx","f":"2026-10-27T18:10","r":"El gobierno capitalino prevé que más de 450 mil personas asistan a las actividades del Gran Premio de México 2026. Juan Pablo de Botton, secretario de Administración y Finanzas, anunció la ampliación de horarios del Metro, la RTP y los transportes eléctricos. El miércoles 28 se realizará el Show Run de Checo Pérez en Paseo de la Reforma.","b":"","img":"autodromo","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/10/27/efecto-checo-en-cdmx-traera-a-450-mil-visitantes-por-el-gran-premio-de-mexico-2026/"],["Expansión","https://expansion.mx/tendencias/2026/10/27/gran-premio-de-mexico-2026-rutas-y-alternativas-para-llegar"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-el-likud-de-netanyahu-gana-por-poco-en-israel-pero-la-oposicion-sumari","t":"El Likud de Netanyahu gana por poco en Israel, pero la oposición sumaría más escaños","c":"internacional","f":"2026-10-27T18:08","r":"Los sondeos a boca de urna de las elecciones israelíes dan al Likud de Benjamín Netanyahu unos 25 escaños, frente a 23 de Yashar!, del exgeneral Gadi Eisenkot; el bloque opositor tendría más asientos, aunque sin mayoría, y los partidos árabes podrían ser decisivos. La participación fue de 77.7%, la más alta desde 1999. Con apenas una fracción de las mesas contadas, el escrutinio podría extenderse hasta el mediodía del miércoles.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/agencias/2026/10/27/los-primeros-datos-del-escrutinio-en-israel-dan-la-victoria-al-likud-seguido-de-yashar/"],["elDiario.es","https://www.eldiario.es/internacional/netanyahu-gana-primeras-elecciones-israel-genocidio-no-podra-formar-gobierno-sondeos_1_13619855.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-liga-mx-a-tres-jornadas-del-cierre-america-lidera-con-27-puntos-y-nadi","t":"Liga MX: a tres jornadas del cierre, América lidera con 27 puntos y nadie tiene la Liguilla asegurada","c":"deportes","f":"2026-10-27T18:06","r":"El América encabeza el Apertura 2026 con 27 unidades y el miércoles juega su partido pendiente ante Tijuana; lo siguen Cruz Azul y Chivas con 26. Restan tres jornadas y nueve puntos en disputa, y entre el noveno y el decimosexto lugar hay solo seis puntos de diferencia. Necaxa y Juárez ya están eliminados matemáticamente.","b":"","img":"estadio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/deportes/liga-mx-tres-jornadas-definiran-el-destino-de-16-equipos-20261027-0068.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-streamers-despiden-a-el-komanche-hallado-sin-vida-en-monterrey-a-los-3","t":"Streamers despiden a El Komanche, hallado sin vida en Monterrey a los 30 años","c":"entretenimiento","f":"2026-10-27T18:04","r":"Carlos Mauricio Gómez, conocido como Komanche, streamer salvadoreño con más de 1.7 millones de seguidores en Twitch, fue localizado sin vida el 25 de octubre en Monterrey, Nuevo León. Las autoridades no han informado la causa de muerte y el caso sigue en investigación. Creadores como Rubius, Ibai Llanos, AuronPlay y El Mariana publicaron mensajes de despedida.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Síntesis","https://sintesis.mx/2026/10/27/despiden-komanche-muerte/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-openai-lanza-gpt-6-1-terra-un-modelo-para-tareas-de-oficina-que-usa-la","t":"OpenAI lanza GPT-6.1 Terra, un modelo para tareas de oficina que usa la computadora y cuesta menos","c":"tecnologia","f":"2026-10-27T18:02","r":"OpenAI presentó GPT-6.1 Terra, un modelo de gama media que, según la empresa, combina razonamiento visual, uso de la computadora y redacción para tareas como llenar formularios o leer planos. En la API cuesta 1 dólar por millón de tokens de entrada y 5 de salida, frente a 2 y 12 de su antecesor. Está disponible para suscriptores Plus, Pro, Enterprise y Edu y tiene una ventana de contexto de 1.05 millones de tokens. La mayoría de los resultados de desempeño provienen de pruebas de la propia OpenAI.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/10/27/openai-lanzo-gpt-61-terra-un-modelo-de-ia-que-usa-la-computadora-y-cuesta-la-mitad/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-paro-de-transportistas-sigue-por-tiempo-indefinido-canacar-exige-reuni","t":"Paro de transportistas sigue por tiempo indefinido; Canacar exige reunirse con Sheinbaum","c":"nacional","f":"2026-10-27T07:20","r":"Canacar, Hamotac, Fematrac e Indeco anunciaron que mantendrán la protesta hasta obtener compromisos concretos del gobierno federal sobre seguridad en carreteras y condiciones de operación. Piden reunirse con la presidenta Claudia Sheinbaum y fijar mesas de diálogo con fechas de cumplimiento. Gobernación reportó el lunes 38 puntos de protesta en 19 estados, con 858 personas y 691 vehículos; la Canacar sostiene que la movilización abarca los 32 estados y que esas cifras no son correctas. Canapat, Conatram y ANTP rechazaron los bloqueos y siguen en diálogo con las autoridades.","b":"","img":"carretera","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/27/estados/030n1est"],["Amexi","https://amexi.com.mx/nacional/paro-transportistas-continuara-indefinido-afectaciones-viales/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-consejeros-del-ine-definen-hoy-quien-ocupara-la-presidencia-provisiona","t":"Consejeros del INE definen hoy quién ocupará la presidencia provisional tras la salida de Taddei","c":"politica","f":"2026-10-27T07:19","r":"Los consejeros electorales se reúnen este martes a las 8:30 horas para elegir a quien encabezará el INE de forma provisional, luego de que la renuncia de Guadalupe Taddei se formalizó ante la Cámara de Diputados. El consejero Uuc-kib Espadas pidió que la designación sea por unanimidad; tras el acuerdo, deberá convocarse en un máximo de 24 horas a una sesión extraordinaria del Consejo General. El PRI, por medio de su representante Emilio Suárez Licona, rechazó que el interinato quede en manos del consejero Arturo Castillo, exfundador de Morena, y pidió que el cargo lo ocupe una mujer. La Cámara de Diputados nombrará después a quien concluya el periodo, que termina en 2032.","b":"","img":"ine","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/26/quien-tomara-las-riendas-del-ine-este-martes-definiran-a-sustituto-de-guadalupe-taddei/"],["Vanguardia","https://vanguardia.com.mx/noticias/pri-rechaza-interinato-en-el-ine-de-consejero-exfundador-de-morena-CC24402275"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-organo-de-control-del-ine-abre-41-expedientes-sobre-contratos-de-la-ge","t":"Órgano de control del INE abre 41 expedientes sobre contratos de la gestión de Taddei; indaga a 18 empresas","c":"politica","f":"2026-10-27T07:18","r":"El Órgano Interno de Control del INE, encabezado por Víctor Hugo Carvente, informó a la Cámara de Diputados que tiene abiertos 41 procesos: 16 investigaciones y 25 indagatorias adicionales en materia de contrataciones. Revisa a 23 personas, de las cuales 15 son servidores o exservidores del instituto, y a 18 empresas. La auditoría cubre del 1 de diciembre de 2024 al 31 de mayo de 2026 y derivó en 45 cédulas de observaciones; entre los posibles hallazgos están documentos falsos, ocultamiento de conflicto de interés, colusión y empresas sin capacidad técnica o económica.","b":"","img":"ine","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/politica/oic-ine-acorrala-red-contratos-taddei-investiga-15-funcionarios-18-empresas"],["La Silla Rota","https://lasillarota.com/nacion/2026/10/27/ine-15-funcionarios-bajo-investigacion-por-contratos-irregulares-de-taddei-534703.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-el-senado-vota-hoy-el-paquete-de-ingresos-2027-limites-a-deducciones-y","t":"El Senado vota hoy el paquete de ingresos 2027: límites a deducciones y menos requisitos para acreditar peajes","c":"economia","f":"2026-10-27T07:17","r":"El pleno del Senado discutirá este martes la Ley de Ingresos de la Federación, la reforma a la Ley del ISR y la Ley Federal de Derechos para 2027. Entre los cambios están límites a deducciones para empresas con ingresos de más de 50 millones de pesos en 2025 y la ampliación del programa de regularización del SAT, que puede reducir multas y recargos hasta 100%. Para acreditar hasta 50% de los peajes contra el ISR, los transportistas necesitarían activos por 250 millones de pesos; el sector pide subir el límite a 420 millones. El plazo para aprobar la parte de ingresos vence el 31 de octubre.","b":"","img":"senado","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/10/27/deducciones-condonacion-multas-empresas-senado"]],"dest":true,"a":"Redacción"},{"id":"2026-10-27-carla-humphrey-pide-quitar-a-los-funcionarios-que-taddei-nombro-por-su","t":"Carla Humphrey pide quitar a los funcionarios que Taddei nombró por su cuenta y revertir sus facultades extraordinarias","c":"politica","f":"2026-10-27T07:16","r":"La consejera del INE Carla Humphrey propuso que el Consejo General pida la renuncia de los funcionarios designados de manera unilateral por Guadalupe Taddei, aunque aclaró que el tema aún no se discute entre los consejeros. También pidió revertir la reforma que dio esas facultades a la presidencia del instituto y abrir auditorías internas y externas, incluida la de la Auditoría Superior. Señaló a los diputados que aprobaron esa reforma como los primeros responsables de romper la colegialidad del INE.","b":"","img":"ine","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/26/humphrey-pide-purga-en-el-ine-exige-renuncia-de-funcionarios-cercanos-a-taddei-y-quitar-superpoderes/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-trailer-choca-contra-unidades-del-bloqueo-en-la-mexico-toluca-y-provoc","t":"Tráiler choca contra unidades del bloqueo en la México-Toluca y provoca un incendio; hay dos heridos","c":"estados","f":"2026-10-27T07:15","r":"Hacia las 3:30 horas de este martes, un tráiler impactó a dos vehículos que formaban parte del bloqueo de transportistas en la carretera México-Toluca, a la altura del puente del Tren Interurbano, en Ocoyoacac; los tres se incendiaron. Hubo dos personas lesionadas, atendidas por bomberos y Protección Civil. Los carriles centrales hacia la Ciudad de México siguen cerrados, por lo que el paso es solo por los laterales, en intervalos de unos 20 minutos. El cierre suma casi 24 horas.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/27/incendio-en-la-carretera-mexico-toluca-tras-choque-de-traileres-durante-bloqueo-de-transportistas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-la-suprema-corte-y-el-sector-empresarial-lanzan-un-programa-de-dialogo","t":"La Suprema Corte y el sector empresarial lanzan un programa de diálogo \"Por la Certeza Jurídica\"","c":"nacional","f":"2026-10-27T07:14","r":"El ministro presidente Hugo Aguilar Ortiz, cinco ministros del pleno y representantes del CCE, la Asociación de Bancos de México, el Consejo Farmacéutico Mexicano y el Consejo de Empresas Globales presentaron un programa de vinculación con mesas de alto nivel, mesas técnicas y seminarios de capacitación. Abordará estabilidad regulatoria, inteligencia artificial, integridad corporativa, sistema financiero y propiedad industrial. La Corte aclaró que no se tratarán litigios concretos ni se influirá en criterios o sentencias.","b":"","img":"palacio","foto":"","cred":"","src":[["Político MX","https://politico.mx/2026/10/27/scjn-impulsa-programa-con-empresarios-para-fortalecer-la-certeza-juridica/"],["La Razón","https://www.razon.com.mx/mexico/2026/10/26/scjn-y-empresarios-impulsan-programa-de-certeza-juridica-en-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-israel-vota-en-elecciones-parlamentarias-netanyahu-llega-casi-empatado","t":"Israel vota en elecciones parlamentarias; Netanyahu llega casi empatado con Gadi Eisenkot","c":"internacional","f":"2026-10-27T07:13","r":"Unos 7.3 millones de israelíes están llamados a las urnas este martes, entre ellos más de medio millón que votan por primera vez. Las últimas encuestas muestran al primer ministro Benjamin Netanyahu prácticamente empatado con el exjefe militar Gadi Eisenkot, su principal rival, y ningún bloque con un camino claro para formar gobierno. Decenas de miles de israelíes viajaron desde el extranjero para votar. Es la primera elección desde los ataques del 7 de octubre de 2023.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/27/en-vivo-elecciones-parlamentarias-en-israel/"],["France 24","https://www.france24.com/es/medio-oriente/20261027-%F0%9F%94%B4-en-directo-i-abren-las-urnas-en-israel-el-pa%C3%ADs-vota-en-sus-primeras-elecciones-desde-los-ataques-del-7-de-octubre"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-trump-llama-una-perdida-de-tiempo-al-alto-el-fuego-con-iran-y-defiende","t":"Trump llama \"una pérdida de tiempo\" al alto el fuego con Irán y defiende el bloqueo en Ormuz","c":"internacional","f":"2026-10-27T07:12","r":"En un acto de campaña en Mississippi, rumbo a las elecciones intermedias del 3 de noviembre, el presidente Donald Trump dijo que nunca le gustó mucho el alto el fuego pactado con Irán. Defendió el bloqueo de Estados Unidos en el estrecho de Ormuz y afirmó que ningún buque ha cruzado en meses, salvo durante la breve tregua. Sus palabras llegan con las negociaciones de paz estancadas y tras advertencias de una posible reanudación de la ofensiva después de los comicios.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / Europa Press","https://infobae.com/america/agencias/2026/10/27/trump-describe-como-una-perdida-de-tiempo-el-alto-el-fuego-pactado-con-iran"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-la-mezcla-mexicana-cierra-en-104-68-dolares-el-brent-baja-0-78-por-exp","t":"La mezcla mexicana cierra en 104.68 dólares; el Brent baja 0.78% por expectativas de diálogo en Medio Oriente","c":"economia","f":"2026-10-27T07:11","r":"Los precios del petróleo bajaron el lunes por toma de utilidades y por la expectativa de nuevos esfuerzos diplomáticos en Medio Oriente. El Brent para diciembre cerró en 115.81 dólares por barril, 0.78% menos, y el WTI en 101.76 dólares, con una caída de 1.46%. La mezcla mexicana terminó en 104.68 dólares. La Reserva Estratégica de Petróleo de Estados Unidos bajó a 282.6 millones de barriles, su nivel más bajo desde octubre de 1982.","b":"","img":"pemex","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/27/mundo/028n2mun"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-el-peso-abre-el-martes-en-18-62-por-dolar-con-una-baja-de-0-26-frente","t":"El peso abre el martes en 18.62 por dólar, con una baja de 0.26% frente al cierre previo","c":"economia","f":"2026-10-27T07:10","r":"El dólar se cotizaba en promedio en 18.62 pesos al inicio de la jornada de este martes, 0.26% arriba del cierre anterior de 18.57, según datos de Dow Jones. En la última semana el billete verde acumula un alza de 1.05%. El lunes, Banxico reportó un cierre de 18.5588 pesos por dólar y fijó el FIX para este martes en 18.5798. Los analistas siguen de cerca la decisión de la Reserva Federal del miércoles.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/27/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-27-de-octubre/"],["N+","https://www.nmas.com.mx/economia/dolar/como-esta-tipo-de-cambio-peso-mexicano-dolar-estadounidense-martes-27-octubre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-detienen-en-mexicali-a-el-isra-senalado-como-lider-de-los-rusos-y-oper","t":"Detienen en Mexicali a \"El Isra\", señalado como líder de Los Rusos y operador de La Mayiza","c":"seguridad","f":"2026-10-27T07:09","r":"Israel \"N\", alias \"El Isra\", fue detenido la noche del domingo en un restaurante del bulevar Adolfo López Mateos, en Mexicali, informó la Secretaría de Seguridad Ciudadana de Baja California. Las autoridades lo consideraban objetivo prioritario. Fue trasladado a Sonora, donde tiene una orden de aprehensión por homicidio; también enfrenta otra por privación ilegal de la libertad. Se le relaciona con el asesinato de dos policías en Baja California y con un ataque en 2024 contra un mando de inteligencia estatal.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Político MX","https://politico.mx/2026/10/26/cae-en-mexicali-el-isra-presunto-lider-de-los-rusos-y-operador-de-la-mayiza"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-matan-a-una-agente-estatal-en-un-ataque-armado-en-tecate-hay-tres-dete","t":"Matan a una agente estatal en un ataque armado en Tecate; hay tres detenidos","c":"seguridad","f":"2026-10-27T07:08","r":"Una agente de la Fuerza Estatal de Seguridad Ciudadana murió y otro elemento y un civil resultaron heridos la tarde del lunes en un enfrentamiento afuera de una tienda de conveniencia en la colonia Nido de las Águilas, en Tecate, Baja California. La Secretaría de Seguridad Ciudadana estatal informó de tres detenidos y de un operativo con apoyo militar para localizar a otros posibles implicados. No se han dado a conocer las identidades de las víctimas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/tij/policiaca/2026/10/26/una-agente-sin-vida-y-a-otro-herido-tras-ataque-armado-contra-la-fuerza-estatal-en-tecate/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-la-policia-de-uruapan-opera-con-cerca-de-20-de-su-fuerza-dice-bedolla","t":"La policía de Uruapan opera con cerca de 20% de su fuerza, dice Bedolla; el estado enviará agentes de apoyo","c":"estados","f":"2026-10-27T07:07","r":"El gobernador de Michoacán, Alfredo Ramírez Bedolla, afirmó que la Policía Municipal de Uruapan trabaja con alrededor de 20% del personal que necesita, luego de que el ayuntamiento de Grecia Quiroz separó hace un mes a agentes que no aprobaron los exámenes de control de confianza. Instruyó a la Secretaría de Seguridad Pública estatal a apoyar con policías de cercanía, sobre todo para atender a comerciantes. En la última semana, diversos hechos violentos dejaron 10 muertos en el municipio.","b":"","img":"palacio","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/estados/michoacan/inseguridad-en-uruapan-bedolla-atribuye-ola-de-violencia-al-despido-masivo-de-policias-municipales/"],["Contramuro","https://www.contramuro.com/policia-de-uruapan-opera-con-menos-del-20-bedolla/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-cae-el-primo-jefe-de-plaza-de-los-cromos-en-ixtaltepec-oaxaca-en-opera","t":"Cae \"El Primo\", jefe de plaza de Los Cromos en Ixtaltepec, Oaxaca, en operativo con apoyo de un Black Hawk","c":"seguridad","f":"2026-10-27T07:06","r":"Fuerzas federales y estatales detuvieron en Asunción Ixtaltepec a Andrés \"N\", alias \"El Primo\", señalado como jefe de plaza de Los Cromos, célula ligada al CJNG, informó la Fiscalía de Oaxaca. Hubo nueve cateos simultáneos en Juchitán, Ixtaltepec, Salina Cruz, Tehuantepec y San Blas Atempa, con aseguramiento de armas, droga e inmuebles. Otras cuatro personas fueron detenidas, entre ellas un colombiano, presuntamente dedicadas al narcomenudeo y a préstamos \"gota a gota\".","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/26/en-operativo-con-un-black-hawk-cae-el-primo-jefe-de-plaza-de-los-cromos-en-ixtaltepec-oaxaca/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-padres-de-los-43-de-ayotzinapa-marchan-del-angel-al-hemiciclo-en-su-ac","t":"Padres de los 43 de Ayotzinapa marchan del Ángel al Hemiciclo en su acción global número 145","c":"cdmx","f":"2026-10-27T07:05","r":"Madres y padres de los 43 normalistas desaparecidos en 2014 marcharon la tarde del lunes del Ángel de la Independencia al Hemiciclo a Juárez, en la llamada 145 Acción Global por Ayotzinapa y México. Exigieron al Estado verdad, justicia y cárcel para los responsables. Las autoridades capitalinas estimaron una asistencia de unas 250 personas.","b":"","img":"angel","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/10/26/marchan-a-12-anos-del-caso-ayotzinapa-y-otras-manifestaciones-en-cdmx-hoy-26-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-cerveceros-aplastan-10-1-a-los-rays-y-quedan-a-un-triunfo-de-ganar-la","t":"Cerveceros aplastan 10-1 a los Rays y quedan a un triunfo de ganar la Serie Mundial","c":"deportes","f":"2026-10-27T07:04","r":"Milwaukee venció 10-1 a Tampa Bay en el Juego 3, en el Tropicana Field, y domina la serie 3-0. Robert Gasser lanzó seis entradas en blanco y permitió un solo hit, mientras Jackson Chourio conectó cuatro imparables. Los Cerveceros anotaron ocho carreras con dos outs en el quinto episodio; Christian Yelich y William Contreras produjeron las primeras carreras. Freddy Peralta, abridor de los Rays, no terminó la quinta entrada.","b":"","img":"beisbol","foto":"","cred":"","src":[["MLB.com","https://mlb.com/es/news/cerveceros-ganan-el-juego-3-de-la-serie-mundial-del-2026"],["El Tiempo","https://eltiempo.com/deportes/otros-deportes/cerveceros-arrollan-a-los-rays-y-quedan-a-un-triunfo-del-titulo-de-la-serie-mundial-de-beisbol-3596540"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-la-ofrenda-del-zocalo-abre-el-jueves-con-una-catrina-de-32-metros-que","t":"La ofrenda del Zócalo abre el jueves con una catrina de 32 metros que busca récord Guinness","c":"cdmx","f":"2026-10-27T07:03","r":"La Ofrenda Monumental del Zócalo estará abierta del jueves 29 de octubre al lunes 2 de noviembre y rendirá homenaje a José Guadalupe Posada. Su pieza central es una catrina de cartonería de 32 metros, con la que se busca superar el récord de la más alta del mundo, hoy de 28 metros en Puerto Vallarta. Tendrá cerca de 100 mil plantas de cempasúchil de productores de Suelo de Conservación, figuras de ajolotes e iluminación especial en los edificios de la plaza.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Chilango","https://www.chilango.com/que-hacer/ofrenda-monumental-zocalo-2026-record-catrina-mas-alta-del-mundo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-openai-afirma-que-uno-de-sus-modelos-refuto-la-hipotesis-del-tiempo-ex","t":"OpenAI afirma que uno de sus modelos refutó la Hipótesis del Tiempo Exponencial; expertos piden revisión independiente","c":"tecnologia","f":"2026-10-27T07:02","r":"OpenAI anunció el lunes que un modelo suyo encontró una refutación de la Hipótesis del Tiempo Exponencial, una conjetura central en la teoría de la computación, y que la prueba se verificó en el sistema Lean. Publicó el informe y el código en GitHub y donó 5 millones de dólares a la Fundación Simons para talleres sobre resultados producidos por IA. Los investigadores Russell Impagliazzo, Ramamohan Paturi y Ryan Williams, que ayudan a organizar la revisión, aclararon que su papel no certifica el resultado y pidieron un escrutinio independiente.","b":"","img":"tech","foto":"","cred":"","src":[["DiarioBitcoin","https://www.diariobitcoin.com/noticias/openai-afirma-que-su-modelo-de-ia-refuto-la-hipotesis-del-tiempo-exponencial/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-27-muere-a-los-46-anos-eric-bauza-la-voz-actual-de-bugs-bunny-y-el-pato-l","t":"Muere a los 46 años Eric Bauza, la voz actual de Bugs Bunny y el Pato Lucas","c":"entretenimiento","f":"2026-10-27T07:01","r":"El actor de doblaje Eric Bauza murió el domingo 25 de octubre en su casa, informó su familia en Instagram. Registros del médico forense de Los Ángeles citados por Variety atribuyen la muerte a una enfermedad cardiovascular hipertensiva, clasificada como natural. Bauza daba voz a Bugs Bunny, el Pato Lucas, Piolín, Porky y otros personajes de los Looney Tunes, y participó en Space Jam: A New Legacy y Coyote vs. Acme.","b":"","img":"estudio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/espectaculos/2026/10/26/muere-eric-bauza-actor-de-voz-de-bugs-bunny-a-los-46-anos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-diputados-reciben-la-renuncia-de-taddei-al-ine-la-jucopo-define-manana","t":"Diputados reciben la renuncia de Taddei al INE; la Jucopo define mañana la convocatoria para relevarla","c":"politica","f":"2026-10-26T18:55","r":"La Cámara de Diputados recibió este lunes la renuncia de Guadalupe Taddei Zavala a la presidencia del INE, con efectos el mismo día. En su carta afirma que el Instituto debe estar por encima de cualquier interés personal y que se retira con la satisfacción del deber cumplido. Ricardo Monreal informó que los coordinadores parlamentarios se reunirán el martes a las 8:30 para definir la convocatoria, que el miércoles se votaría en el Pleno.","b":"","img":"ine","foto":"","cred":"","src":[["El CEO","https://elceo.com/politica/diputados-reciben-renuncia-de-guadalupe-taddei-al-ine/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-paro-de-transportistas-segob-reporta-38-puntos-de-protesta-con-858-par","t":"Paro de transportistas: Segob reporta 38 puntos de protesta con 858 participantes y 691 vehículos","c":"nacional","f":"2026-10-26T18:54","r":"Con corte a las 9:30 horas, la Secretaría de Gobernación contabilizó 38 puntos de protesta del paro convocado por la Canacar y otras organizaciones, con 858 personas y 691 vehículos. Veracruz concentró ocho puntos, el Estado de México seis, y Nuevo León y Tlaxcala tres cada uno; hubo afectaciones en las autopistas México-Querétaro, México-Pachuca, México-Puebla y México-Toluca. Los transportistas exigen seguridad en carreteras y freno a asaltos y extorsiones.","b":"","img":"carretera","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/mexico/segob-reporta-38-puntos-de-protesta-y-858-participantes-en-paro-de-canacar/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-sheinbaum-califica-como-buena-decision-la-salida-de-taddei-y-pide-audi","t":"Sheinbaum califica como buena decisión la salida de Taddei y pide auditar al INE","c":"nacional","f":"2026-10-26T18:53","r":"La presidenta Claudia Sheinbaum dijo en su conferencia matutina que Guadalupe Taddei tomó una buena decisión al separarse de la presidencia del INE, y pidió que se investiguen los señalamientos de conflictos de interés y que se realice una auditoría. También condenó los comentarios misóginos contra la funcionaria y descartó que su salida provoque una crisis en el Instituto rumbo a la elección de 2027.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/presidencia/2026/10/26/renuncia-guadalupe-taddei-ine"],["Forbes México","https://forbes.com.mx/sheinbaum-dice-que-decision-de-taddei-de-dejar-el-ine-es-buena-critica-comentarios-misoginos-contra-funcionaria/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-sheinbaum-hay-avances-con-ee-uu-pero-todavia-no-hay-acuerdo-sobre-aran","t":"Sheinbaum: hay avances con EE.UU., pero todavía no hay acuerdo sobre aranceles a autos, acero y aluminio","c":"economia","f":"2026-10-26T18:52","r":"La presidenta respondió a Donald Trump, quien dijo que ambos gobiernos están cerca de un entendimiento, que las negociaciones van muy avanzadas pero aún falta resolver temas. Las pláticas se centran en los aranceles al sector automotriz y a la industria del acero y el aluminio, y las encabeza el secretario de Economía, Marcelo Ebrard. No dio fecha para concluirlas.","b":"","img":"palacio","foto":"","cred":"","src":[["Por Esto!","https://www.poresto.com/mexico/2026/10/26/presidenta-mexico-confirma-avances-acuerdo-comercial-trump-pacto-aranceles.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-monreal-advierte-que-la-renuncia-de-taddei-no-la-exime-de-responder-po","t":"Monreal advierte que la renuncia de Taddei no la exime de responder por presuntas irregularidades","c":"politica","f":"2026-10-26T18:51","r":"El coordinador de Morena en la Cámara de Diputados, Ricardo Monreal, sostuvo que dejar la presidencia del INE no libera a Guadalupe Taddei de posibles responsabilidades. Señaló que, si existen denuncias o indicios de irregularidades durante su gestión, deberán revisarse por las vías correspondientes aunque ya no ocupe el cargo.","b":"","img":"senado","foto":"","cred":"","src":[["La Querella Digital","https://www.laquerelladigital.com/renuncia-de-taddei-no-la-exime-de-investigar-presuntas-irregularidades-monreal/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-segob-se-reune-con-organizaciones-que-rechazan-el-paro-de-la-canacar-y","t":"Segob se reúne con organizaciones que rechazan el paro de la Canacar y reitera su llamado al diálogo","c":"nacional","f":"2026-10-26T18:50","r":"La secretaria de Gobernación, Rosa Icela Rodríguez, se reunió con representantes de Concamin, la ANTP y Canapat, entre otras organizaciones que se deslindaron del paro, junto con funcionarios de Hacienda, Seguridad e Infraestructura. Rodríguez agradeció su disposición a privilegiar el diálogo y el gobierno pidió a la Canacar evitar bloqueos que afectan el abasto. No se informó de acuerdos concretos.","b":"","img":"palacio","foto":"","cred":"","src":[["Grupo Animal","https://grupoanimal.mx/politica/segob-transportistas-paro-canacar-bloqueos"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-transportistas-bloquean-la-caseta-vieja-del-trebol-al-sur-de-culiacan","t":"Transportistas bloquean la caseta vieja del Trébol, al sur de Culiacán, y piden reunirse con la presidenta","c":"estados","f":"2026-10-26T18:49","r":"Transportistas de Sinaloa se sumaron al paro nacional con un bloqueo en la caseta vieja del Trébol, al sur de Culiacán. Exigen frenar las extorsiones y los asaltos en carreteras del estado, y una reunión con autoridades federales, incluida la presidenta Sheinbaum. Su vocero, Gerardo Serrano, dijo que permanecerán en el lugar por tiempo indefinido.","b":"","img":"carretera","foto":"","cred":"","src":[["Café Negro","https://cafenegroportal.com/transportistas-bloquean-vialidades-al-sur-de-culiacan-exigen-frenar-extorsiones-y-asaltos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-el-peso-se-aprecia-0-54-y-cierra-en-18-56-por-dolar-segun-banxico","t":"El peso se aprecia 0.54% y cierra en 18.56 por dólar, según Banxico","c":"economia","f":"2026-10-26T18:48","r":"El tipo de cambio cerró este lunes en 18.5588 pesos por dólar, una ganancia de 10 centavos para el peso frente a los 18.6601 de la sesión previa, de acuerdo con cifras de Banxico. El FIX quedó en 18.5798 y el euro cerró en 20.7992 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Heraldo Binario","https://www.heraldobinario.com.mx/tendencias/2026/10/26/noticia-43059.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-cemex-gana-407-millones-de-dolares-en-el-tercer-trimestre-55-mas-sus-v","t":"Cemex gana 407 millones de dólares en el tercer trimestre, 55% más; sus ventas en México suben 16%","c":"economia","f":"2026-10-26T18:47","r":"La cementera reportó una utilidad neta de 407 millones de dólares entre julio y septiembre, frente a 264 millones un año antes. Sus ventas crecieron 8%, a 4,590 millones de dólares, y el EBITDA subió 12%, a 990 millones. En México vendió 1,299 millones de dólares, 16% más; en lo que va del año la utilidad acumulada es 25% menor.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/26/la-mexicana-cemex-gana-407-millones-de-dolares-en-el-tercer-trimestre-de-2026-un-55-mas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-buscan-al-sacerdote-clemente-morales-desaparecido-en-culiacan-tras-sal","t":"Buscan al sacerdote Clemente Morales, desaparecido en Culiacán tras salir de una consulta médica","c":"seguridad","f":"2026-10-26T18:46","r":"Clemente Morales Topete, de 67 años y párroco de la iglesia Cristo Resucitado, desapareció el sábado 24 de octubre después de acudir a una consulta en el fraccionamiento Montebello, en Culiacán. La Comisión Estatal de Búsqueda emitió una ficha de localización, y la Diócesis de Culiacán y el Episcopado Mexicano pidieron apoyo para encontrarlo. Hasta el lunes se desconocía su paradero.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/26/en-vivo-seguridad-narcotrafico-y-crimen-hoy-en-mexico-26-de-octubre-desaparece-sacerdote-en-culiacan-tras-salir-de-una-consulta-medica/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-asesinan-a-un-agente-de-investigacion-de-puebla-en-tehuacan-mientras-a","t":"Asesinan a un agente de investigación de Puebla en Tehuacán mientras atendía un robo de auto","c":"seguridad","f":"2026-10-26T18:45","r":"Juan Jesús Hernández Mariscal, agente de la Agencia Estatal de Investigación adscrito al área de robo de vehículos, fue atacado a balazos la mañana del lunes en la colonia Tepeyac de Tehuacán. Viajaba en un vehículo particular con un acompañante, que resultó herido. Según reportes policiales, usaban un auto particular por falta de unidades oficiales.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Curul Puebla","https://curul.com.mx/asesinan-a-agente-de-la-aei-en-tehuacan-durante-ataque-armado-hay-otro-hombre-herido/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-jalisco-construira-una-nueva-potabilizadora-en-guadalajara-lemus-anunc","t":"Jalisco construirá una nueva potabilizadora en Guadalajara; Lemus anuncia plan de 25 mil millones con la Federación","c":"estados","f":"2026-10-26T18:44","r":"El gobernador Pablo Lemus anunció que la Planta Potabilizadora 1, que recibe agua de Chapala y data de 1964, será sustituida por una nueva. El primer módulo concluirá a finales de marzo de 2027 y la meta es alcanzar 3,000 litros por segundo en julio de ese año. Lemus dijo que el miércoles presentará con la presidenta Sheinbaum un paquete de unos 25 mil millones de pesos.","b":"","img":"jalisco","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ultima-hora/anuncia-pablo-lemus-construccion-nueva-planta-potabilizadora-e-inversion-25-mil-mdp"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-sinaloa-es-el-estado-con-mas-victimas-de-ataques-contra-funcionarios-y","t":"Sinaloa es el estado con más víctimas de ataques contra funcionarios y actores políticos en 2026: Data Cívica","c":"seguridad","f":"2026-10-26T18:43","r":"De enero a septiembre se registraron 39 víctimas de ataques contra funcionarios y actores políticos en Sinaloa, la cifra más alta del país, según el proyecto Votar entre balas de Data Cívica. Culiacán concentra 23 y Escuinapa 10; siete de cada diez víctimas pertenecían a corporaciones de seguridad.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Revista Espejo","https://revistaespejo.com/2026/10/26/sinaloa-registra-mas-victimas-de-ataques-contra-funcionarios-que-cualquier-otro-estado"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-iran-y-los-paises-del-pacto-de-la-meca-acuerdan-seguir-dialogando-para","t":"Irán y los países del pacto de La Meca acuerdan seguir dialogando para frenar una nueva escalada","c":"internacional","f":"2026-10-26T18:42","r":"Irán recibió en Teherán a representantes de Arabia Saudí, Pakistán y Turquía en su primera reunión cuatripartita, entre ellos el ministro de Defensa saudí, Jalid bin Salmán, y el jefe del Ejército paquistaní, Asim Munir. El comunicado final señala que seguirán conversando sobre paz y seguridad regional. El encuentro ocurre en medio de reportes de que EE.UU. e Israel preparan una nueva ofensiva.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/26/iran-y-los-paises-del-pacto-de-la-meca-acuerdan-seguir-dialogando-sobre-seguridad-regional/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-la-cdmx-sera-sede-del-foro-urbano-mundial-2028-de-onu-habitat-brugada","t":"La CDMX será sede del Foro Urbano Mundial 2028 de ONU-Hábitat; Brugada creará un comité promotor","c":"cdmx","f":"2026-10-26T18:41","r":"La jefa de Gobierno, Clara Brugada, y la directora de ONU-Hábitat, Anacláudia Rossbach, confirmaron que la capital recibirá el Foro Urbano Mundial del 31 de julio al 4 de agosto de 2028. Brugada dijo que servirá para evaluar la Agenda 2030 y construir una nueva agenda urbana, y anunció un comité con universidades, empresas y organizaciones civiles.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Hoguera","https://lahoguera.mx/cdmx-recibira-el-foro-urbano-mundial-2028-brugada-propone-una-agenda-urbana-pos-2030/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-charlyn-corral-hace-historia-gana-el-trofeo-gerd-muller-a-la-mejor-gol","t":"Charlyn Corral hace historia: gana el Trofeo Gerd Müller a la mejor goleadora en el Balón de Oro","c":"deportes","f":"2026-10-26T18:40","r":"La delantera mexicana de Pachuca se convirtió en la primera futbolista del país en ganar el premio a la máxima anotadora de la temporada, con 24 goles. En la gala celebrada en Londres superó a jugadoras como Alexia Putellas y Ewa Pajor.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/balon-oro-2026-charlyn-corral-mexicana-gana-premio-mejor-delantera-mundo"],["Ámbito","https://www.ambito.com/deportes/entrega-del-balon-oro-minuto-minuto-ya-se-revelo-el-top-30-al-11-n6338038"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-harry-kane-gana-el-balon-de-oro-2026-alexia-putellas-se-lleva-el-femen","t":"Harry Kane gana el Balón de Oro 2026; Alexia Putellas se lleva el femenil","c":"deportes","f":"2026-10-26T18:39","r":"El delantero inglés del Bayern Múnich se impuso a Kylian Mbappé y Lamine Yamal en la gala del Teatro Palladium de Londres, la primera fuera de Francia. Kane también ganó el Trofeo Gerd Müller con 73 goles. Alexia Putellas obtuvo el Balón de Oro femenino; Lamine Yamal y Vicky López, el Trofeo Kopa.","b":"","img":"estadio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/deportes/entrega-del-balon-oro-minuto-minuto-ya-se-revelo-el-top-30-al-11-n6338038"],["TUDN","https://www.tudn.com/futbol/balon-de-oro-2026-en-vivo-minuto-a-minuto-del-premio-al-mejor-jugador-del-mundo"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-checo-perez-correra-su-gran-premio-300-en-mexico-la-carrera-sera-el-do","t":"Checo Pérez correrá su Gran Premio 300 en México; la carrera será el domingo 1 de noviembre","c":"deportes","f":"2026-10-26T18:38","r":"El Gran Premio de México se disputará del 30 de octubre al 1 de noviembre en el Autódromo Hermanos Rodríguez. Sergio Pérez llegará a 300 carreras en la F1 y correrá por primera vez en casa con Cadillac. La clasificación será el sábado de 15:00 a 16:00 y la carrera arrancará el domingo a las 14:00, hora del centro.","b":"","img":"autodromo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/falta-una-semana-para-el-gran-premio-de-mexico-checo-perez-celebrara-300-carreras-de-la-formula-1-en-el-autodromo-hermanos-rodriguez/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-apple-presenta-un-nuevo-ipad-mini-con-pantalla-oled-en-mexico-costara","t":"Apple presenta un nuevo iPad mini con pantalla OLED; en México costará desde 16,999 pesos","c":"tecnologia","f":"2026-10-26T18:37","r":"El nuevo iPad mini tiene pantalla OLED de 8.5 pulgadas, chip A20 Pro de 2 nanómetros y certificación IP67. En México partirá de 16,999 pesos el modelo de 128 GB, unos 3,000 pesos más que la generación anterior. La preventa inicia el miércoles 28 de octubre y estará disponible el 6 de noviembre.","b":"","img":"tech","foto":"","cred":"","src":[["Expansión","https://expansion.mx/tecnologia/2026/10/26/apple-ipad-mini-2026-precio-caracteristicas-lanzamiento"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-cuba-presentara-esta-semana-ante-la-onu-su-resolucion-para-exigir-el-f","t":"Cuba presentará esta semana ante la ONU su resolución para exigir el fin del embargo de EE.UU.","c":"internacional","f":"2026-10-26T18:36","r":"Cuba llevará el martes y el miércoles a la Asamblea General de la ONU su proyecto de resolución contra el embargo estadounidense. Lo hará en medio de una grave crisis en la isla, un bloqueo petrolero y sanciones secundarias, según la agenda de la agencia EFE.","b":"","img":"habana","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/26/temas-del-dia-de-efe-internacional-del-lunes-26-de-octubre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-taddei-presenta-hoy-su-renuncia-a-la-presidencia-del-ine-ante-la-camar","t":"Taddei presenta hoy su renuncia a la presidencia del INE ante la Cámara de Diputados","c":"politica","f":"2026-10-26T07:00","r":"Guadalupe Taddei anunció el domingo en un comunicado que entregará este lunes su renuncia a la presidencia del INE ante la Cámara de Diputados. Dijo que se va \"con serenidad, dignidad y tranquilidad\" para proteger al instituto, en medio de señalamientos por contratos de materiales electorales y posibles conflictos de interés que investiga la Auditoría Superior de la Federación. Mientras San Lázaro designa a quien la sustituya, los consejeros elegirán entre ellos a una presidencia provisional, como prevé la ley electoral.","b":"","img":"ine","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/10/25/guadalupe-taddei-renuncia-ine"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-arranca-el-paro-nacional-de-transportistas-canacar-mantiene-bloqueos-p","t":"Arranca el paro nacional de transportistas: Canacar mantiene bloqueos parciales en 17 estados","c":"nacional","f":"2026-10-26T06:59","r":"Canacar, Fematrac, Hamotac e Indeco iniciaron este lunes, entre las 6:00 y las 8:00 horas, un paro indefinido con concentraciones y bloqueos parciales en carreteras de 17 entidades, entre ellas la CDMX, el Estado de México, Jalisco, Puebla y Nuevo León. Piden seguridad en las carreteras, regular las tarifas de grúas y corralones y cambios a la Ley de Ingresos 2027. La Segob informó que la mayoría de las organizaciones aceptó dialogar, pero Canacar sostuvo la convocatoria; la ANTAC se deslindó.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/26/bloqueos-de-transportistas-hoy-lunes-26-de-octubre-lista-de-carreteras-afectadas-por-paro-nacional/"],["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/10/26/paro-nacional-de-transportistas-en-vivo-en-que-carreteras-de-cdmx-y-edomex-hay-bloqueos-reporte-vial-hoy-26-de-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-vance-se-degrada-a-tormenta-tropical-pero-deja-lluvias-muy-fuertes-en","t":"Vance se degrada a tormenta tropical, pero deja lluvias muy fuertes en Jalisco, Colima, Michoacán y Guerrero","c":"nacional","f":"2026-10-26T06:58","r":"Vance perdió fuerza y pasó de huracán categoría 1 a tormenta tropical el domingo por la tarde, a unos 390 kilómetros al sur-suroeste de Punta San Telmo, Michoacán, con vientos de 110 km/h. El Servicio Meteorológico Nacional prevé lluvias de 50 a 75 milímetros en Jalisco, Colima, Michoacán y Guerrero, además de oleaje de 4 a 5 metros frente a las costas de Michoacán y Guerrero. Las autoridades advierten riesgo de deslaves, crecida de ríos e inundaciones en zonas bajas.","b":"","img":"huracan","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/noticia/2026/10/25/estados/huracan-vance-provocara-lluvias-de-riesgo-en-jalisco-colima-michoacan-y-guerrero"],["TV Azteca","https://www.tvazteca.com/aztecanoticias/clima-en-mexico-lunes-26-octubre-ciclon-vance-deja-lluvias-en-guerrero-y-michoacan"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-sheinbaum-defiende-el-sistema-de-salud-y-anuncia-que-el-hospital-vasco","t":"Sheinbaum defiende el sistema de salud y anuncia que el Hospital Vasco de Quiroga reabrirá en noviembre","c":"nacional","f":"2026-10-26T06:57","r":"En Morelia, la presidenta Claudia Sheinbaum rechazó que el sistema público de salud esté peor que en gobiernos anteriores, aunque admitió pendientes: \"todavía nos falta\", dijo. Anunció que el Hospital Vasco de Quiroga del ISSSTE, cerrado desde 2012, estará listo en noviembre, y entregó 931 viviendas del programa Vivienda para el Bienestar. Las familias tendrán desde enero de 2027 un consultorio de atención primaria con 60 medicamentos gratuitos.","b":"","img":"imss","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/25/sheinbaum-anuncia-reapertura-del-hospital-vasco-de-quiroga-del-issste-en-noviembre/"],["Infobae","https://www.infobae.com/mexico/2026/10/25/sheinbaum-defiende-al-sistema-de-salud-en-plena-crisis-del-imss-esta-mejor-que-antes/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-26-el-senado-debate-manana-la-ley-de-ingresos-2027-con-un-techo-de-deuda","t":"El Senado debate mañana la Ley de Ingresos 2027 con un techo de deuda de 1.7 billones de pesos","c":"economia","f":"2026-10-26T06:56","r":"El pleno del Senado discutirá el martes 27 de octubre la Ley de Ingresos 2027 y las reformas al ISR y a la Ley de Derechos. El paquete prevé ingresos por 10.6 billones de pesos, de los que 6.2 billones serían impuestos, y un techo de endeudamiento de 1.7 billones, el punto que la oposición votará en contra. También sube 17.8% el derecho para visitantes extranjeros sin permiso para trabajar, a 1,158 pesos.","b":"","img":"senado","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/26/politica/006n1pol?partner=rss"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-flavio-bolsonaro-desconoce-el-triunfo-de-lula-y-pedira-anular-la-elecc","t":"Flávio Bolsonaro desconoce el triunfo de Lula y pedirá anular la elección; el tribunal electoral niega alteraciones","c":"internacional","f":"2026-10-26T06:55","r":"Luiz Inácio Lula da Silva ganó la segunda vuelta con 51.79% de los votos frente a 48.21% de Flávio Bolsonaro, quien anunció acciones legales para anular los comicios porque un juez amplió dos horas el horario de votación por fallas en el transporte público. El presidente del Tribunal Superior Electoral, Kassio Nunes Marques, admitió que la medida causó dificultades, pero aseguró que no alteró el resultado y que observadores certificaron que no hubo interferencias.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Colombiano","https://www.elcolombiano.com/internacional/flavio-bolsonaro-no-reconce-resultados-elecciones-brasil-gana-lula-GD42724310"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-maria-corina-machado-vuelve-a-venezuela-tras-diez-meses-fuera-miles-la","t":"María Corina Machado vuelve a Venezuela tras diez meses fuera; miles la reciben en caravana a Caracas","c":"internacional","f":"2026-10-26T06:54","r":"La líder opositora venezolana y Nobel de la Paz 2025, María Corina Machado, reapareció el domingo en una iglesia de Santa Rosa, en Lara, y encabezó una caravana hasta Caracas, adonde llegó después de las 21:00 horas. \"Estoy aquí. Con ustedes\", escribió en X. Había salido en diciembre para recibir el Nobel en Oslo; el secretario de Estado de EE.UU., Marco Rubio, atribuyó su regreso a la mediación estadounidense.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/26/maria-corina-machado-regresa-a-venezuela-entre-una-multitud-que-exige-elecciones/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-el-peso-abre-la-semana-en-18-67-por-dolar-el-dolar-sube-1-35-en-una-se","t":"El peso abre la semana en 18.67 por dólar; el dólar sube 1.35% en una semana","c":"economia","f":"2026-10-26T06:53","r":"El tipo de cambio abrió este lunes en 18.67 pesos por dólar, según datos de Dow Jones citados por Infobae. En la última semana el dólar ganó 1.35% frente al peso y la volatilidad está por encima de su referencia. Los inversionistas siguen el paro de transportistas, la discusión del Paquete Económico 2027 en el Senado y la decisión de la Reserva Federal del miércoles.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/26/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-26-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-el-brent-cae-2-y-baja-a-109-dolares-por-toma-de-utilidades-tras-tocar","t":"El Brent cae 2% y baja a 109 dólares por toma de utilidades tras tocar máximos de seis meses","c":"economia","f":"2026-10-26T06:52","r":"El petróleo Brent bajaba 2.02%, a 109.45 dólares por barril, en las primeras operaciones de este lunes, y el WTI caía 2.32%, a 101.05 dólares. Los fondos venden después de un alza de cerca de 6% la semana pasada y de que el Brent cerrara el viernes en 116.72 dólares; además, Irán dijo que no habrá nuevos ataques de EE.UU. \"si prevalece la razón\". Los ataques hutíes contra instalaciones saudíes y cierres de oleoductos en Libia limitan la caída.","b":"","img":"pemex","foto":"","cred":"","src":[["Euribor.com.es","https://www.euribor.com.es/2026/10/26/precio-petroleo-hoy-26-octubre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-asesinan-a-balazos-a-santiago-vali-dirigente-sindical-del-transporte-e","t":"Asesinan a balazos a Santiago Vali, dirigente sindical del transporte, en un restaurante de Tuxpan","c":"seguridad","f":"2026-10-26T06:51","r":"Un hombre armado entró la noche del sábado a un restaurante de la carretera a Barra Norte, en Tuxpan, Veracruz, y disparó a corta distancia contra Santiago Vali Castillo, líder del sindicato SITRAC RM, que murió en el lugar. La Fiscalía de Veracruz investiga el caso, no reporta detenidos ni móvil, y las autoridades no lo han vinculado con el paro nacional de transportistas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://infobae.com/mexico/2026/10/26/asesinan-a-balazos-a-un-dirigente-sindical-en-un-restaurante-de-tuxpan-veracruz"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-atacan-a-balazos-a-una-pareja-de-adultos-mayores-en-su-casa-de-silao-l","t":"Atacan a balazos a una pareja de adultos mayores en su casa de Silao; la mujer muere","c":"seguridad","f":"2026-10-26T06:50","r":"Hombres armados dispararon más de diez veces dentro de una vivienda de la colonia Sopeña, en Silao, Guanajuato, la madrugada del domingo. Una mujer de la tercera edad murió en el lugar y su esposo fue hospitalizado con heridas graves. Una versión no confirmada por las autoridades indica que los agresores buscaban a un hijo de la pareja; el Ministerio Público abrió una carpeta de investigación.","b":"","img":"ultimahora","foto":"","cred":"","src":[["AM","https://www.am.com.mx/guanajuato/2026/10/25/pareja-fue-atacada-a-balazos-en-la-colonia-sopena-de-silao-1858833.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-salvador-zamora-deja-la-secretaria-general-de-gobierno-de-jalisco-rumb","t":"Salvador Zamora deja la Secretaría General de Gobierno de Jalisco rumbo a 2027; llega Carlos Arias","c":"estados","f":"2026-10-26T06:49","r":"El gobernador Pablo Lemus aceptó la renuncia de Salvador Zamora a la Secretaría General de Gobierno de Jalisco, con efectos inmediatos, y nombró en su lugar a Carlos Arias Madrid. Zamora dijo que se dedicará a su proyecto político rumbo al proceso electoral de 2027. Lemus pidió al nuevo titular reforzar la comunicación con los poderes públicos y los actores políticos.","b":"","img":"jalisco","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/jalisco/salvador-zamora-renuncia-a-la-secretaria-general-de-gobierno-de-jalisco-20261025-0078.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-crecen-las-protestas-por-agua-sucia-en-guadalajara-bloqueos-diarios-y","t":"Crecen las protestas por agua sucia en Guadalajara: bloqueos diarios y marchas contra los tandeos del SIAPA","c":"estados","f":"2026-10-26T06:48","r":"Vecinos de Guadalajara, Zapopan y Tonalá suman casi una semana de protestas por el agua contaminada y los tandeos del SIAPA. El sábado hubo tres bloqueos con al menos un millar de personas, incluidos colonos de Oblatos, San Andrés y Talpita que dicen llevar 21 días sin servicio, y el domingo marcharon al ayuntamiento y se manifestaron en la Minerva. Piden soluciones reales, transparencia en los proyectos hídricos y participar en las decisiones.","b":"","img":"jalisco","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/26/estados/028n1est?partner=rss"],["El Informador","https://www.informador.mx/jalisco/ciudadanos-toman-el-parque-rojo-para-exigir-agua-limpia-y-transparencia-de-gestion-hidrica-en-jalisco-20261025-0068.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-alcalde-de-juarez-dice-que-los-danos-por-el-desborde-de-la-montada-fue","t":"Alcalde de Juárez dice que los daños por el desborde de La Montada fueron menores a lo previsto; no hubo víctimas","c":"estados","f":"2026-10-26T06:47","r":"El presidente municipal de Ciudad Juárez, Héctor Ortiz Orpinel, afirmó que la limpieza de arroyos y las medidas preventivas redujeron los daños de las lluvias del sábado en el poniente de la ciudad, donde se desbordó el dique La Montada. Protección Civil confirmó viviendas inundadas, pero no reportó personas muertas ni lesionadas; las autoridades registraron 25 milímetros de lluvia.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Norte Digital","https://nortedigital.mx/limpieza-de-arroyos-redujo-danos-por-lluvias-sostiene-alcalde/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-brugada-inaugura-la-soberana-la-utopia-mas-grande-de-la-cdmx-y-recibe","t":"Brugada inaugura La Soberana, la Utopía más grande de la CDMX, y recibe el Pergamino de Honor de ONU-Hábitat","c":"cdmx","f":"2026-10-26T06:46","r":"La jefa de Gobierno, Clara Brugada, abrió la Utopía La Soberana en el Deportivo Hermanos Galeana, en San Juan de Aragón, la primera de Gustavo A. Madero. Costó 300 millones de pesos, ocupa más de 90 mil metros cuadrados y ofrecerá servicios gratuitos de salud, cuidados, cultura y deporte, con alberca semiolímpica y unidad de mamografía, para unos 100 mil vecinos. Brugada recibió además el Pergamino de Honor de ONU-Hábitat.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/10/25/clara-brugada-inaugura-utopia-la-soberana-en-la-gam-beneficia-a-mas-de-100-mil-habitantes/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-israel-vota-manana-en-elecciones-cerradas-las-encuestas-no-dan-mayoria","t":"Israel vota mañana en elecciones cerradas: las encuestas no dan mayoría a Netanyahu ni a la oposición","c":"internacional","f":"2026-10-26T06:45","r":"Unos 7.3 millones de israelíes están llamados a votar el martes 27 de octubre para renovar los 120 escaños de la Knéset. Encuestas de los canales 11 y 12 dan unos 50 escaños al bloque de Benjamin Netanyahu y entre 52 y 56 a la oposición, sin que nadie alcance los 61 necesarios. El exjefe del Ejército Gadi Eisenkot es su principal rival, mientras Netanyahu sigue en juicio por tres casos de corrupción.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Independiente","https://www.elindependiente.com/internacional/2026/10/26/claves-elecciones-israel-pais-guerra-futuro-netanyahu-juego/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-chivas-gana-en-monterrey-y-el-america-cae-ante-pachuca-el-liderato-que","t":"Chivas gana en Monterrey y el América cae ante Pachuca: el liderato queda a un punto","c":"deportes","f":"2026-10-26T06:44","r":"Chivas venció 1-0 a Monterrey con gol de Roberto Alvarado y un penal atajado por Raúl Rangel a Lucas Ocampos. En el Estadio Banorte, Pachuca derrotó 2-1 al América con goles de Alan Bautista y Oussama Idrissi, en la noche del homenaje a Memo Ochoa. Las Águilas siguen líderes con 27 puntos, uno arriba de Chivas y Cruz Azul, que goleó en Querétaro, a tres jornadas del final.","b":"","img":"estadio","foto":"","cred":"","src":[["Mediotiempo","https://www.mediotiempo.com/futbol/liga-mx/resumen-partido-america-vs-pachuca-jornada-14-apertura-2026"],["Claro Sports","https://www.clarosports.com/futbol/liga-mx/monterrey-vs-chivas-en-vivo-el-partido-de-la-jornada-14-de-la-liga-mx-resultado-y-goles-hoy-apertura-2026/"],["Fox Sports","https://www.foxsports.com.mx/2026/10/25/liga-mx-tabla-general-de-posiciones-al-terminar-jornada-14-del-torneo-apertura-2026-america-chivas-cruz-azul/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-rays-reciben-hoy-a-cerveceros-en-el-juego-3-de-la-serie-mundial-obliga","t":"Rays reciben hoy a Cerveceros en el Juego 3 de la Serie Mundial, obligados a ganar tras ir abajo 0-2","c":"deportes","f":"2026-10-26T06:43","r":"La Serie Mundial se muda a Tampa: el Juego 3 entre Rays y Cerveceros será este lunes a las 18:00 horas del centro de México en el Tropicana Field. Milwaukee domina 2-0 y le faltan dos victorias para el título, luego de remontar una desventaja de cuatro carreras en el segundo partido. En México se transmite por TUDN, ESPN y Fox.","b":"","img":"beisbol","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/beisbol/mlb/milwaukee-vs-brewers-vs-tampa-bay-rays-en-vivo-la-mlb-fecha-horario-y-donde-ver-el-juego-3-de-la-serie-mundial-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-lua-blanco-actriz-del-rebelde-brasileno-murio-por-complicaciones-de-un","t":"Lua Blanco, actriz del Rebelde brasileño, murió por complicaciones de un cáncer de intestino, confirma su familia","c":"entretenimiento","f":"2026-10-26T06:42","r":"La familia de Lua Blanco, quien interpretó a Roberta Messi en la versión brasileña de Rebelde (2011-2012), confirmó que murió a los 39 años por complicaciones de un cáncer de intestino diagnosticado unos dos meses antes. La actriz falleció el 18 de octubre en Río de Janeiro; su hermano, Daniel Blanco, dijo que había estado luchando contra la enfermedad en sus últimos meses.","b":"","img":"estudio","foto":"","cred":"","src":[["El Mañana","https://elmanana.com.mx/escena/2026/10/25/familiares-de-lua-blanco-actriz-de-rebelde-revelan-causa-de-muerte-183220.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-26-softbank-planea-invertir-50-mil-millones-de-dolares-en-ia-y-centros-de","t":"SoftBank planea invertir 50 mil millones de dólares en IA y centros de datos en Malasia, dice Anwar Ibrahim","c":"tecnologia","f":"2026-10-26T06:41","r":"El primer ministro de Malasia, Anwar Ibrahim, dijo que Masayoshi Son, jefe de SoftBank, prevé invertir 50 mil millones de dólares en inteligencia artificial y centros de datos en Sarawak y la Malasia peninsular. El monto equivale a cerca de una décima parte de la economía malaya y supera con mucho los compromisos de Microsoft, Google, Oracle y Amazon en ese país. SoftBank no había comentado el anuncio.","b":"","img":"tech","foto":"","cred":"","src":[["Fortune","https://fortune.com/2026/10/26/softbank-malaysia-50-billion-ai-investment/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-vinculan-a-proceso-al-exfiscal-de-chihuahua-cesar-jauregui-por-traicio","t":"Vinculan a proceso al exfiscal de Chihuahua César Jáuregui por traición a la patria; seguirá en el Altiplano","c":"politica","f":"2026-10-25T18:50","r":"Un juez federal vinculó a proceso este domingo a César Jáuregui Moreno, exfiscal de Chihuahua, por traición a la patria, y ordenó que siga en prisión preventiva en el penal del Altiplano. La FGR lo acusa de permitir que agentes extranjeros operaran sin autorización en un operativo antidrogas en la Sierra, en el que murieron cuatro personas. Su abogado, Héctor Villasana, sostiene que ninguna prueba muestra que lo autorizara o lo supiera y anunció un amparo; el delito prevé hasta 40 años de prisión.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/cesar-jauregui-seguira-en-el-altiplano-juez-lo-vincula-a-proceso-por-traicion-a-la-patria-en-el-caso-cia/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-paro-nacional-de-transportistas-del-lunes-26-llega-dividido-antac-y-ot","t":"Paro nacional de transportistas del lunes 26 llega dividido: ANTAC y otras organizaciones no participarán","c":"economia","f":"2026-10-25T18:49","r":"Organizaciones como CANACAR, HAMOTAC y FEMATRAC convocaron a un paro en las capitales de los 32 estados para este lunes 26 de octubre; piden frenar alzas en combustibles y casetas, más seguridad en carreteras y diálogo directo con la presidenta Sheinbaum. La Asociación Nacional Transportista (ANTAC) y Transportistas Unidos de Teloyucan se deslindaron. No hay una hora única de inicio: las convocatorias mencionan las 6:00 y las 8:00 horas, y se prevén afectaciones en autopistas y vías como el Circuito Exterior Mexiquense.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/25/bloqueo-transportistas-26-de-octubre-a-que-hora-empieza-ruta-calles-cerradas-alternativas/"],["Excélsior","https://www.excelsior.com.mx/nacional/fractura-paro-transportistas-amotac-antac-y-amtac-deslindan-bloqueos"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-proteccion-civil-despliega-misiones-de-coordinacion-en-cinco-estados-d","t":"Protección Civil despliega misiones de coordinación en cinco estados del Pacífico por el huracán Vance","c":"nacional","f":"2026-10-25T18:48","r":"Al mediodía de este domingo, Vance seguía como huracán categoría 1 a 515 km al sur de Manzanillo, Colima, con vientos de 120 km/h y rachas de 150 km/h, avanzando al noroeste a 7 km/h. La Coordinación Nacional de Protección Civil envía misiones de enlace a los puestos de mando de Michoacán, Colima, Jalisco, Nayarit y Sinaloa como medida preventiva, sin orden de evacuación. El SMN prevé lluvias de 50 a 75 mm en Jalisco, Colima, Michoacán y Guerrero y oleaje de hasta 5 metros.","b":"","img":"huracan","foto":"","cred":"","src":[["El Imparcial","https://elimparcial.com/mexico/2026/10/25/huracan-vance-pone-en-alerta-a-cinco-estados-del-pacifico-proteccion-civil-desplegara-operativo-ante-lluvias-muy-fuertes-y-oleaje-de-hasta-5-metros"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-mexico-cumple-con-ee-uu-el-primer-ano-del-ciclo-de-aguas-entrega-mas-d","t":"México cumple con EE.UU. el primer año del ciclo de aguas: entrega más de 430 millones de metros cúbicos","c":"nacional","f":"2026-10-25T18:47","r":"Los gobiernos de México y Estados Unidos informaron que México completó el primer año del ciclo 37 del Tratado de Aguas de 1944 con más de 430 millones de metros cúbicos del río Bravo, pese a la sequía. La SRE dijo que se cumplió sin poner en riesgo el derecho humano al agua. La secretaria de Agricultura de EE.UU., Brooke Rollins, confirmó al menos 350 mil acres-pie, pero dijo que Washington aún espera entregas continuas y que se salde el adeudo pendiente.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/mexico-entrega-mas-de-430-millones-de-metros-cubicos-a-eeuu-tras-dar-cumplimiento-al-tratado-de-aguas-de-1944/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-lula-gana-la-segunda-vuelta-en-brasil-ante-flavio-bolsonaro-y-logra-un","t":"Lula gana la segunda vuelta en Brasil ante Flávio Bolsonaro y logra un cuarto mandato","c":"internacional","f":"2026-10-25T18:46","r":"Con 99.81% de las urnas contadas, Luiz Inácio Lula da Silva obtenía 51.76% de los votos frente a 48.24% de Flávio Bolsonaro, según el sistema del Tribunal Superior Electoral. Es la cuarta vez que Lula gana la presidencia por voto directo, tras 2002, 2006 y 2022; gobernará de 2027 a 2031. Lula cumple 81 años dos días después de la elección.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Poder360","https://www.poder360.com.br/poder-eleicoes-2026/lula-e-eleito-pela-4a-vez-e-supera-recorde-de-longevidade-na-democracia/"],["Infobae","https://www.infobae.com/america/america-latina/2026/10/25/lula-da-silva-y-flavio-bolsonaro-se-disputan-la-presidencia-de-brasil-en-el-balotaje/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-vucic-reconoce-su-derrota-en-serbia-la-lista-de-estudiantes-gana-con-c","t":"Vucic reconoce su derrota en Serbia: la Lista de Estudiantes gana con cerca de 52%","c":"internacional","f":"2026-10-25T18:45","r":"Aleksandar Vucic admitió este domingo que su partido perdió las elecciones parlamentarias anticipadas, antes de los resultados oficiales. Con un conteo preliminar, la Lista de Estudiantes tenía alrededor de 52% de los votos y 138 de 250 escaños, por encima de los 126 necesarios para gobernar sola; el SNS de Vucic, cerca de 39.3% y 104 escaños. La participación rondó 70%, según datos preliminares.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/25/aleksandar-vucic-reconocio-la-derrota-ante-la-lista-de-estudiantes-en-las-elecciones-de-serbia/"],["France 24","https://www.france24.com/en/europe/20261025-serbia-s-vucic-concedes-defeat-in-historic-snap-election-with-record-turnout"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-capturan-en-hermosillo-a-el-chore-operador-de-los-gigios-buscado-por-e","t":"Capturan en Hermosillo a \"El Chore\", operador de Los Gigios buscado por EE.UU.","c":"seguridad","f":"2026-10-25T18:44","r":"Agentes de la AMIC de Sonora y de la FGR, en coordinación con Interpol, detuvieron en Hermosillo a Carlos Iván \"N\", alias \"El Chore\", señalado como operador de la célula Los Gigios. Fue arrestado con una orden de detención provisional con fines de extradición; según la Fiscalía de Sonora, EE.UU. lo requiere por conspiración para importar fentanilo y metanfetamina. Será trasladado a un penal federal mientras se resuelve su extradición.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/con-la-dea-tras-sus-huellas-los-crimenes-por-los-que-el-chore-operador-de-los-gigios-en-sonora-fue-capturado-para-su-extradicion/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-juicio-politico-o-desafuero-las-dos-vias-que-quedan-para-retirar-a-tad","t":"Juicio político o desafuero: las dos vías que quedan para retirar a Taddei del INE","c":"politica","f":"2026-10-25T18:43","r":"Ante la negativa de Guadalupe Taddei a renunciar, la ley electoral no prevé una vía directa para destituirla. Quedan dos caminos: un juicio político (artículo 110 constitucional), que inicia en la Cámara de Diputados y puede terminar con destitución e inhabilitación si lo aprueban dos tercios del Senado, o un desafuero (artículo 111) si hay una denuncia penal. Ricardo Monreal reconoció que la Cámara no puede pedirle la renuncia; Sheinbaum dijo que es una decisión personal.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/si-guadalupe-taddei-se-aferra-a-mantenerse-en-la-presidencia-del-ine-solo-restan-dos-opciones-para-que-deje-el-cargo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-se-desborda-el-dique-la-montada-en-ciudad-juarez-la-corriente-arrastra","t":"Se desborda el dique La Montada en Ciudad Juárez; la corriente arrastra al menos 10 vehículos","c":"estados","f":"2026-10-25T18:42","r":"Las lluvias del sábado elevaron el caudal de arroyos y canales en Ciudad Juárez, Chihuahua, y el dique La Montada se desbordó, con agua y lodo en calles del poniente de la ciudad. La corriente del arroyo de Las Víboras arrastró al menos 10 vehículos y varias viviendas de la colonia Fronteriza Baja quedaron incomunicadas; se cerró el viaducto Díaz Ordaz. No se reportan muertos ni heridos y aún no hay un balance oficial de daños.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/fuertes-lluvias-inundan-calles-arrastra-carros-y-deja-casas-incomunicadas-en-ciudad-juarez-se-desborda-el-dique-la-montada/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-hombres-armados-se-llevan-a-un-exempleado-del-supremo-tribunal-de-sina","t":"Hombres armados se llevan a un exempleado del Supremo Tribunal de Sinaloa en Culiacán","c":"seguridad","f":"2026-10-25T18:41","r":"Jesús Roberto \"N\", de 38 años y exempleado del Supremo Tribunal de Justicia de Sinaloa, fue privado de la libertad la tarde de este domingo, alrededor de las 14:00 horas, en una llantera de la avenida Nicolás Bravo, en la colonia Morelos de Culiacán. Según el reporte, hombres con armas largas lo obligaron a subir a un vehículo rojo. Policías confirmaron el hecho y la Fiscalía estatal entrevistó a testigos; no se conoce su paradero.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Noroeste","https://www.noroeste.com.mx/seguridad/privan-de-la-libertad-en-culiacan-a-ex-empleado-del-supremo-tribunal-de-justicia-de-sinaloa-HM26800997"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-semana-clave-para-la-economia-pib-del-tercer-trimestre-balanza-comerci","t":"Semana clave para la economía: PIB del tercer trimestre, balanza comercial y decisión de la Fed","c":"economia","f":"2026-10-25T18:40","r":"El INEGI publicará el martes 27 la balanza comercial de septiembre y el viernes 30 la estimación oportuna del PIB del tercer trimestre; ese día Hacienda dará su informe de finanzas públicas de septiembre. En Estados Unidos, la Reserva Federal anunciará su decisión de política monetaria el miércoles 28 y el jueves 29 se conocerán el PIB del tercer trimestre y la inflación PCE de septiembre.","b":"","img":"bolsa","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/25/economia/015n2eco?partner=rss"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-real-madrid-gana-el-clasico-en-el-camp-nou-con-doblete-de-mbappe-y-que","t":"Real Madrid gana el clásico en el Camp Nou con doblete de Mbappé y queda a tres puntos del Barcelona","c":"deportes","f":"2026-10-25T18:39","r":"El Real Madrid venció 1-2 al Barcelona en la jornada 10 de LaLiga. Kylian Mbappé abrió el marcador al minuto 41, Raphinha empató al 61 con asistencia de Pedri y Mbappé definió al 88 tras una jugada de Camavinga. El Barcelona llegaba líder con 27 puntos y pleno de victorias; con el resultado, el Madrid se coloca a tres unidades.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/espana/agencias/2026/10/25/1-2-el-real-madrid-derrota-al-barcelona-con-un-doblete-de-mbappe/"],["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/10/25/real-madrid-vs-barcelona-en-vivo-resultado-del-clasico-espanol/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-antonelli-gana-el-gran-premio-de-estados-unidos-checo-perez-termina-en","t":"Antonelli gana el Gran Premio de Estados Unidos; Checo Pérez termina en el lugar 19","c":"deportes","f":"2026-10-25T18:38","r":"Andrea Kimi Antonelli (Mercedes) ganó la carrera de Austin, fecha 18 del Mundial de Fórmula 1, con 13 segundos de ventaja sobre Charles Leclerc (Ferrari); Max Verstappen (Red Bull) fue tercero, seguido de Lewis Hamilton y Lando Norris. Sergio Pérez (Cadillac) acabó 19, a una vuelta. El Gran Premio de México es en una semana.","b":"","img":"autodromo","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/estados-unidos/victoria-de-andrea-kimi-antonelli-en-gp-de-estados-unidos-leclerc-fue-segundo-nid25102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-alberta-busca-limitar-servicios-a-residentes-temporales-podria-afectar","t":"Alberta busca limitar servicios a residentes temporales; podría afectar a trabajadores mexicanos","c":"economia","f":"2026-10-25T18:37","r":"En una consulta no vinculante del 19 de octubre, alrededor de 54% de los votantes de Alberta, Canadá, apoyó más control provincial sobre la inmigración y 56% limitar servicios como salud y educación a ciudadanos y residentes permanentes, según conteos no oficiales; los resultados oficiales saldrán el 29 de octubre. La premier Danielle Smith ha planteado una cuota de salud de hasta 1,900 dólares por trabajador. No está claro si los cambios tocarían el programa PTAT, por el que más de 25 mil mexicanos trabajaron en Canadá en 2025.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/mexicanos-en-canada-la-provincia-que-busca-restringir-derechos-de-trabajadores-migrantes/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-ataques-rusos-dejan-cuatro-muertos-y-22-heridos-en-la-region-de-dnipro","t":"Ataques rusos dejan cuatro muertos y 22 heridos en la región de Dnipro, Ucrania","c":"internacional","f":"2026-10-25T18:36","r":"Fuerzas rusas atacaron con drones y bombas aéreas tres distritos de la región de Dnipro la noche del sábado; murieron cuatro personas y 22 resultaron heridas, según las autoridades locales. En Vinnytsia, un dron alcanzó un edificio de departamentos y dejó seis heridos, y en Járkiv un ataque golpeó a rescatistas que atendían un hipermercado. Volodímir Zelenski dijo que en la última semana Rusia lanzó cerca de 2,300 drones y 48 misiles.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Euronews","https://www.euronews.com/2026/10/25/russian-strikes-on-ukraine-kill-four-and-injure-28-authorities-say"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-nace-raquel-tercera-hija-de-samuel-garcia-y-mariana-rodriguez","t":"Nace Raquel, tercera hija de Samuel García y Mariana Rodríguez","c":"estados","f":"2026-10-25T18:35","r":"El gobernador de Nuevo León, Samuel García, y Mariana Rodríguez anunciaron en redes sociales el nacimiento de su hija Raquel en la madrugada de este domingo 25 de octubre, con 3.080 kilos. Rodríguez fue internada el sábado en un hospital de San Pedro Garza García tras presentar contracciones; el parto estaba previsto para el miércoles 28.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/samuel-garcia-y-mariana-rodriguez-reciben-a-su-tercera-hija-tras-adelantarse-el-parto-asi-anunciaron-su-nacimiento/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-proponen-en-el-congreso-de-la-cdmx-reconocer-la-violencia-obstetrica-y","t":"Proponen en el Congreso de la CDMX reconocer la violencia obstétrica y crear un plan de parto","c":"cdmx","f":"2026-10-25T18:34","r":"La diputada Jannete Guerrero Maya (PT) presentó dos iniciativas: una para reformar la Ley de Salud capitalina e incluir un plan de parto que se anexe al expediente clínico, y otra para que la Ley General de Salud reconozca conductas de violencia obstétrica, como gritos, humillaciones o negar anestesia. La legisladora afirmó que una de cada tres mujeres en el país la ha sufrido. Las propuestas fueron turnadas a la Comisión de Salud.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/parir-sin-humillaciones-cdmx-busca-reconocer-violencia-obstetrica-en-la-ley-y-propone-plan-de-parto-humanizado/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-pumas-y-tigres-empatan-1-1-en-la-noche-del-homenaje-a-hugo-sanchez","t":"Pumas y Tigres empatan 1-1 en la noche del homenaje a Hugo Sánchez","c":"deportes","f":"2026-10-25T18:33","r":"En la jornada 14 del Apertura 2026, Pumas y Tigres igualaron 1-1 en el Estadio Olímpico Universitario: Robert Morales anotó al 56 y Juan Brunetta empató al 76. Antes del partido, el club homenajeó a Hugo Sánchez por los 50 años de su debut profesional, que fue ante Tigres en 1976; con Pumas jugó 194 partidos oficiales y marcó 102 goles.","b":"","img":"unam","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/25/pumas-empata-con-tigres-y-amarga-el-homenaje-a-hugo-sanchez-en-cu/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-manuel-el-flaco-ibanez-sigue-hospitalizado-por-una-ulcera-su-hija-dice","t":"Manuel \"El Flaco\" Ibáñez sigue hospitalizado por una úlcera; su hija dice que está estable","c":"entretenimiento","f":"2026-10-25T18:32","r":"Daniela Ibáñez contó a TVNotas que a su padre se le reventó una úlcera, lo que causó complicaciones digestivas y requirió un procedimiento médico. El actor permanece en observación en el Hospital ABC de Santa Fe, en la Ciudad de México. La familia sigue pidiendo donadores de sangre O negativo.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/por-que-sigue-hospitalizado-manuel-el-flaco-ibanez-su-hija-habla-de-la-enfermedad-que-enfrenta/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-ataque-armado-en-una-vivienda-de-escuinapa-sinaloa-deja-una-mujer-muer","t":"Ataque armado en una vivienda de Escuinapa, Sinaloa, deja una mujer muerta y un hombre herido","c":"seguridad","f":"2026-10-25T18:31","r":"Hombres armados irrumpieron en una casa de la colonia Ampliación Benito Juárez, en Escuinapa, la madrugada de este domingo. Una mujer de entre 30 y 35 años murió y Jesús \"N\", de 36 años, fue trasladado herido a un hospital. El Ejército acudió tras el aviso de vecinos y la Fiscalía estatal aseguró casquillos calibre 9 mm.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Luz Noticias","https://www.luznoticias.mx/2026-10-25/sinaloa/ataque-a-balazos-dentro-de-una-vivienda-deja-una-mujer-sin-vida-y-un-hombre-herido-en-escuinapa-/311805"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-juez-define-si-vincula-a-proceso-al-exfiscal-de-chihuahua-cesar-jaureg","t":"Juez define si vincula a proceso al exfiscal de Chihuahua César Jáuregui por traición a la patria","c":"politica","f":"2026-10-25T07:20","r":"El juez de control Ricardo Alfonso Santos Dorantes reanudó en privado, en el Centro de Justicia Penal Federal de Almoloya de Juárez, la audiencia en la que la FGR imputa traición a la patria a César Jáuregui Moreno, exfiscal general de Chihuahua, por la participación de agentes de la CIA en un operativo antidrogas en la sierra del estado. Su abogado, José Ramón Flores, sostuvo que no hay pruebas contundentes en su contra y que lo dicho por la fiscal Ernestina Godoy sobre presuntos casinos no forma parte de la carpeta. Jáuregui sigue en prisión preventiva en El Altiplano; al cierre no había resolución.","b":"","img":"palacio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/mexico/cesar-jauregui-enfrenta-audiencia-por-presunta-traicion-a-la-patria-20261025-0029.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-taddei-rechaza-dejar-la-presidencia-del-ine-no-me-voy-dice-ante-los-co","t":"Taddei rechaza dejar la presidencia del INE: \"No me voy\", dice ante los consejeros","c":"politica","f":"2026-10-25T07:19","r":"En una reunión virtual con consejeros electorales, Guadalupe Taddei negó que vaya a renunciar a la presidencia del INE y calificó las críticas como un \"golpeteo político\". Dijo que la Auditoría Superior de la Federación y el Órgano Interno de Control deben hacer las investigaciones sobre los contratos con proveedores, y anunció cambios en cargos ejecutivos y administrativos. La ASF abrió el 23 de octubre una investigación de oficio por posibles irregularidades; las acusaciones no han sido probadas.","b":"","img":"ine","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/nacion/2026/10/24/taddei-niega-que-vaya-a-dejar-el-puesto-en-el-ine-534451.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-abaten-en-sonora-a-el-meny-carranza-fugado-del-penal-de-hermosillo-hay","t":"Abaten en Sonora a \"El Meny Carranza\", fugado del penal de Hermosillo; hay cuatro detenidos","c":"seguridad","f":"2026-10-25T07:18","r":"Francisco Manuel Romero Carranza, \"El Meny\", señalado como operador de Los Fantasmas, murió en un enfrentamiento con la Marina cerca de San Antonio, Sonora, en un operativo con dos helicópteros, un avión y personal en tierra, informó el Gabinete de Seguridad. Cuatro acompañantes fueron detenidos y se aseguraron siete armas, 45 cargadores, cuatro vehículos y tres chalecos. Romero se había fugado del Cereso 2 de Hermosillo el 11 de julio; otros dos evadidos siguen prófugos con recompensa de un millón de pesos cada uno.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/abaten-a-el-meny-carranza-y-detienen-a-cuatro-mas-tras-enfrentamiento-armado-en-san-antonio-sonora/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-vance-sigue-como-huracan-categoria-1-y-mantiene-en-alerta-a-guerrero-m","t":"Vance sigue como huracán categoría 1 y mantiene en alerta a Guerrero, Michoacán, Colima y Jalisco","c":"nacional","f":"2026-10-25T07:17","r":"El SMN reportó que Vance se debilitó a categoría 1 con vientos sostenidos de 150 km/h y rachas de 185 km/h, a unos 540 km al suroeste de Acapulco y 640 km al sur de Manzanillo, avanzando lentamente al nor-noroeste. Para este domingo se prevén lluvias de 25 a 50 mm en zonas de Guerrero, Michoacán, Colima y Jalisco, y oleaje de 3 a 4 metros en las costas de Michoacán y Guerrero. Su trayectoria podría acercarlo a la costa como tormenta tropical hacia el 28 o 29 de octubre.","b":"","img":"huracan","foto":"","cred":"","src":[["La Voz de Michoacán","https://www.lavozdemichoacan.com.mx/clima-y-fenomenos/huracan-vance-debilita-categoria-1-costas-michoacan-guerrero-2026/"],["Infobae","https://www.infobae.com/mexico/2026/10/25/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-domingo-25-de-octubre-tres-estados-en-alerta-de-lluvias-por-vance/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-25-sheinbaum-cierra-su-gira-por-michoacan-con-entrega-de-viviendas-en-mor","t":"Sheinbaum cierra su gira por Michoacán con entrega de viviendas en Morelia","c":"nacional","f":"2026-10-25T07:16","r":"La presidenta Claudia Sheinbaum tiene programada para las 10:45 de este domingo la entrega de viviendas en el Infonavit Katania de Morelia, último acto de su gira de fin de semana por Michoacán. El sábado visitó Apatzingán, donde entregó créditos Finabien a mujeres y dijo que no hay cabida para la corrupción en su movimiento.","b":"","img":"palacio","foto":"","cred":"","src":[["Edomex Al Día","https://edomexaldia.com/este-domingo-25-de-octubre-la-presidenta-claudia-sheinbaum-entregara-vivienda-en-morelia/"],["El Imparcial","https://www.elimparcial.com/mexico/2026/10/24/claudia-sheinbaum-afirma-que-la-honestidad-es-indispensable-para-mantener-la-autoridad-moral-de-la-4t-y-sostiene-que-no-hay-cabida-para-la-corrupcion-durante-una-visita-a-apatzingan-donde-entrego-apoyos-economicos-a-mujeres-y-recibio-demandas-de-seguridad/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-ebrard-negocia-en-washington-bajar-aranceles-a-autos-acero-y-aluminio","t":"Ebrard negocia en Washington bajar aranceles a autos, acero y aluminio; Trump dice que el acuerdo está \"muy cerca\"","c":"economia","f":"2026-10-25T07:15","r":"El secretario de Economía, Marcelo Ebrard, informó desde Washington que avanzan las conversaciones con Estados Unidos para reducir los aranceles a autos, acero y aluminio, aunque no confirmó la fecha de la cuarta ronda de revisión del T-MEC. Donald Trump afirmó el viernes que están \"muy cerca de llegar a un acuerdo con México\". Según The Wall Street Journal, el secretario de Comercio, Howard Lutnick, estaría frenando la reducción de esos aranceles.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/marcelo-ebrard-revela-que-hay-avances-en-las-negociaciones-con-eeuu-sobre-aranceles-a-autos-aranceles-y-aluminio/"],["El Diario de Sonora","https://eldiariodesonora.com.mx/mexico/2026/10/24/mexico-ee-uu-muy-cerca-acuerdo-arancelario-ebrard-negocia-washington.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-intentan-linchar-en-ostuacan-chiapas-a-detenidos-por-el-feminicidio-de","t":"Intentan linchar en Ostuacán, Chiapas, a detenidos por el feminicidio de una niña y su abuela","c":"seguridad","f":"2026-10-25T07:14","r":"Decenas de habitantes de Ostuacán se reunieron la noche del sábado frente a la presidencia municipal y lanzaron piedras para impedir el traslado de los detenidos por los asesinatos de Miriam Cruz Alpuche, de 55 años, y su nieta Ariana, de 12; la policía estatal logró sacarlos. El gobernador Eduardo Ramírez confirmó las detenciones y pidió no hacer justicia por propia mano. Según el fiscal Jorge Luis Llaven, la niña murió por asfixia y presentaba signos de agresión sexual.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/intentan-linchar-en-ostuacan-chiapas-a-presuntos-feminicidas-de-una-nina-de-12-anos-y-su-abuela/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-muere-atropellado-mario-puga-activista-de-tepito-el-auto-huia-de-la-po","t":"Muere atropellado Mario Puga, activista de Tepito; el auto huía de la policía","c":"cdmx","f":"2026-10-25T07:13","r":"Mario García Puga, activista y fundador del Espacio Cultural Tepito, murió el sábado al ser embestido en su motocicleta eléctrica en el cruce de Tapicería y Herreros, colonia Morelos, por un vehículo en el que huían presuntos integrantes de una banda de robo de relojes. La jefa de Gobierno, Clara Brugada, lamentó su muerte, recordó que dirigió el PILARES de la Morelos e informó que los presuntos responsables fueron detenidos.","b":"","img":"centro","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/noticia/2026/10/24/capital/identifican-al-activista-mario-puga-como-victima-de-atropellamiento-en-la-morelos"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-trump-no-descarta-un-nuevo-ataque-contra-iran-teheran-advierte-que-no","t":"Trump no descarta un nuevo ataque contra Irán; Teherán advierte que no dejará entrar barcos de EE.UU. al Golfo","c":"internacional","f":"2026-10-25T07:12","r":"Donald Trump dijo a la prensa que \"existe la posibilidad\" de un nuevo ataque militar contra Irán, aunque aseguró que no ha tomado una decisión final y que también podría alcanzarse un acuerdo. El general iraní Ali Abdollahi respondió que no permitirán buques de la Armada estadounidense en el Golfo. Las negociaciones siguen estancadas y Washington mantiene un bloqueo naval a los puertos iraníes.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Semana / AFP","https://www.semana.com/mundo/articulo/donald-trump-no-descarta-un-nuevo-ataque-militar-de-ee-uu-contra-iran-existe-la-posibilidad/202654/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-dos-superpetroleros-con-mas-de-4-5-millones-de-barriles-quedan-varados","t":"Dos superpetroleros con más de 4.5 millones de barriles quedan varados tras chocar con minas en Ormuz","c":"economia","f":"2026-10-25T07:11","r":"La Guardia Revolucionaria de Irán informó que dos superpetroleros que cruzaban el sur del estrecho de Ormuz por una ruta no autorizada por Teherán chocaron con minas navales, se incendiaron y quedaron inmovilizados; sus tripulaciones los abandonaron. Juntos transportaban más de 4.5 millones de barriles de crudo. El cuerpo militar iraní contabiliza al menos 15 incidentes con barcos en diez días, mientras Estados Unidos afirma haber restablecido el paso por una ruta cercana a Omán.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/24/iran-informa-de-explosiones-e-incendios-en-otros-dos-superpetroleros-en-ormuz/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-cerveceros-remontan-un-0-4-vencen-5-4-a-rays-y-ponen-2-0-la-serie-mund","t":"Cerveceros remontan un 0-4, vencen 5-4 a Rays y ponen 2-0 la Serie Mundial","c":"deportes","f":"2026-10-25T07:10","r":"Milwaukee se impuso 5-4 a Tampa Bay en el segundo juego, en el American Family Field, tras ir abajo 4-0 en la primera entrada. Cooper Pratt, cuyo error había abierto el ataque de los Rays, dio el sencillo de la ventaja en la séptima, y el bullpen de los Cerveceros lanzó seis entradas sin permitir carrera; Abner Uribe ganó y Aaron Ashby se llevó el salvamento. El tercer juego será el lunes 26 en Tampa Bay.","b":"","img":"beisbol","foto":"","cred":"","src":[["Diario Deportes","https://diariodeportes.com.co/beisbol/los-cerveceros-volvieron-a-vencer-a-los-rays-remontando-5-4-cooper-pratt-el-heroe-del-juego/"],["MLB","https://mlb.com/es/news/cerveceros-ganan-el-juego-2-de-la-serie-mundial-del-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-la-fed-decide-el-miercoles-si-vuelve-a-subir-tasas-el-rango-esta-en-3","t":"La Fed decide el miércoles si vuelve a subir tasas; el rango está en 3.75%-4.00%","c":"economia","f":"2026-10-25T07:09","r":"La Reserva Federal de Estados Unidos anunciará su decisión de política monetaria el miércoles 28 de octubre, en una reunión que podría traer otra alza de tasas en medio de la inflación, días antes de las elecciones intermedias del 3 de noviembre. El rango de referencia está en 3.75%-4.00% desde el aumento de 25 puntos base del 16 de septiembre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/25/temas-del-dia-de-efe-internacional-del-domingo-25-de-octubre-0200-gmt/"],["Admiral Markets","https://admiralmarkets.com/es/analytics/traders-blog/decision-de-la-fed-octubre-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-miles-protestan-en-orleans-contra-la-ultraderecha-le-pen-lanza-hoy-su","t":"Miles protestan en Orleans contra la ultraderecha; Le Pen lanza hoy su campaña presidencial","c":"internacional","f":"2026-10-25T07:08","r":"Miles de personas marcharon el sábado en Orleans contra el congreso del Reagrupamiento Nacional, convocados por cerca de 50 partidos, sindicatos y asociaciones; las autoridades desplegaron casi 3 mil policías y gendarmes, además de helicópteros y drones. Este domingo Marine Le Pen arranca su campaña rumbo a la presidencial de 2027, y se espera que Jordan Bardella sea reelegido al frente del partido.","b":"","img":"paris","foto":"","cred":"","src":[["Euronews","https://www.euronews.com/2026/10/24/thousands-protest-against-far-right-national-rally-congress-in-france"],["Public Sénat","https://www.publicsenat.fr/actualites/politique/congres-du-rn-a-orleans-plusieurs-dizaines-de-milliers-de-contre-manifestants-attendus-samedi-selon-laurent-nunez"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-serbia-vota-en-elecciones-anticipadas-vucic-busca-ser-primer-ministro","t":"Serbia vota en elecciones anticipadas; Vucic busca ser primer ministro frente a la lista estudiantil","c":"internacional","f":"2026-10-25T07:07","r":"Serbia celebra este domingo elecciones parlamentarias anticipadas. Aleksandar Vucic, que dejó la presidencia por el límite de dos mandatos, encabeza la campaña de su Partido Progresista Serbio para convertirse en primer ministro. Enfrente compite la \"Lista estudiantil\", impulsada por el movimiento juvenil que encabezó meses de protestas e integrada por profesores, expertos y ciudadanos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["AJC / AP","https://www.ajc.com/news/2026/09/serbias-protesting-youth-formally-join-race-challenging-vucic-before-next-months-election/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/25/temas-del-dia-de-efe-internacional-del-domingo-25-de-octubre-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-mega-procesion-de-catrinas-recorre-hoy-reforma-cierres-viales-y-metrob","t":"Mega Procesión de Catrinas recorre hoy Reforma: cierres viales y Metrobús Línea 7 suspendida","c":"cdmx","f":"2026-10-25T07:06","r":"La decimotercera Mega Procesión de las Catrinas sale a las 18:00 h del Ángel de la Independencia por Reforma, avenida Juárez, Eje Central y 5 de Mayo hasta el Zócalo, con 36 contingentes; la llegada se estima hacia las 20:30 h. La Línea 7 del Metrobús suspenderá el tramo de Reforma durante el desfile y la estación Zócalo-Tenochtitlan podría tener restricciones. La SSC sugiere Circuito Interior, Eje 1 Norte y Eje 1 Oriente como alternativas.","b":"","img":"ofrenda","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/mega-procesion-de-catrinas-2026-calles-cerradas-horario-del-desfile-y-cambios-en-el-metrobus-y-metro-cdmx/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-smn-preve-lluvias-muy-fuertes-en-chihuahua-y-durango-con-posibles-torb","t":"SMN prevé lluvias muy fuertes en Chihuahua y Durango, con posibles torbellinos en el norte","c":"estados","f":"2026-10-25T07:05","r":"El Servicio Meteorológico Nacional pronosticó para este domingo lluvias muy fuertes, de 50 a 75 mm, en el este y sureste de Chihuahua y el norte de Durango, con rachas de hasta 70 km/h y posibles torbellinos o tornados en el norte de Chihuahua. También habrá lluvias fuertes en el oeste de Coahuila, sur de Tamaulipas, este de San Luis Potosí y centro de Veracruz.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-domingo-25-de-octubre-tres-estados-en-alerta-de-lluvias-por-vance/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-detienen-a-tres-mujeres-en-san-pedro-nl-tras-persecucion-un-policia-re","t":"Detienen a tres mujeres en San Pedro, NL, tras persecución; un policía resultó mordido","c":"estados","f":"2026-10-25T07:04","r":"Policías de San Pedro Garza García detuvieron a tres mujeres de 21, 24 y 43 años en el estacionamiento de una plaza de Valle Oriente, tras perseguir una camioneta sin placas que se pasó un alto en avenida Lázaro Cárdenas. Según el reporte, la conductora golpeó una patrulla al dar reversa y las mujeres agredieron a los agentes: uno sufrió una herida en la nariz y otro una mordida en el brazo. Cuatro menores que viajaban con ellas quedaron bajo resguardo.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/25/detienen-a-tres-mujeres-tras-persecucion-y-agresion-a-policias-en-san-pedro-nuevo-leon/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-fmf-abre-investigacion-formal-a-jugadores-del-tepatitlan-por-apuestas","t":"FMF abre investigación formal a jugadores del Tepatitlán por apuestas deportivas","c":"deportes","f":"2026-10-25T07:03","r":"La Comisión Disciplinaria de la Federación Mexicana de Futbol confirmó una investigación contra futbolistas del Tepatitlán FC, de la Liga de Expansión, por presuntos vínculos con apuestas; los investigados quedan suspendidos de forma provisional. El caso surgió por capturas de pantalla atribuidas al mediocampista Dieter Villalpando, quien fue excluido del partido ante Dorados. La FMF no ha revelado los nombres de los implicados.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/24/fmf-abre-investigacion-formal-contra-futbolistas-del-tepatitlan-fc-por-apuestas-deportivas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-apple-presenta-homeview-una-pantalla-para-el-hogar-con-una-siri-mas-pe","t":"Apple presenta HomeView, una pantalla para el hogar con una Siri más personalizada","c":"tecnologia","f":"2026-10-25T07:02","r":"Apple presentó HomeView, un dispositivo para el hogar con pantalla de siete pulgadas con el que busca competir con Amazon y Google. Puede controlar timbres, termostatos y cerraduras inteligentes y, según Reuters, usa datos del iPhone como mensajes, calendarios y listas para personalizar respuestas. Apple asegura que tiene medidas de privacidad y que reconoce a cada miembro de la familia.","b":"","img":"tech","foto":"","cred":"","src":[["Potosinoticias / Reuters","https://potosinoticias.com/2026/10/25/apple-apuesta-por-un-nuevo-dispositivo-para-impulsar-su-estrategia-de-inteligencia-artificial"]],"dest":false,"a":"Redacción"},{"id":"2026-10-25-los-robots-pato-de-nvidia-se-vuelven-virales-superan-20-mil-preventas","t":"Los robots pato de Nvidia se vuelven virales: superan 20 mil preventas en un día","c":"tecnologia","f":"2026-10-25T07:01","r":"Los Microduck, robots de unos 25 cm y 399 dólares fabricados por Pollen Robotics, superaron las 20 mil preventas en unas 24 horas después de que Jensen Huang jugó con ellos en la conferencia GTC de Nvidia en Berlín, según el director de Hugging Face, Clément Delangue. Los pedidos hechos ahora llegarían antes de Navidad.","b":"","img":"tech2","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/10/24/los-robots-pato-de-nvidia-que-duermen-y-juegan-tuvieron-20000-pedidos-de-preventa-en-un-dia/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-ee-uu-propuso-que-sus-agentes-acompanen-operativos-contra-carteles-en","t":"EE.UU. propuso que sus agentes acompañen operativos contra cárteles en México, según el NYT","c":"nacional","f":"2026-10-24T18:59","r":"De acuerdo con The New York Times, retomado por Infobae, Washington entregó a México en las últimas semanas un memorando en el que plantea que agentes estadounidenses participen en operativos contra cárteles dentro del país y que se amplíe el intercambio de inteligencia, con miras a mostrar resultados antes de las elecciones intermedias del 3 de noviembre. El gobierno mexicano rechazó operaciones conjuntas y ataques con drones; la presidenta Sheinbaum sostuvo que una intervención así violaría la soberanía nacional. La vocera de la Casa Blanca, Lauren Bis, insistió en que es inaceptable que organizaciones terroristas controlen territorios en México.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/eeuu-presiona-a-mexico-para-enviar-agentes-a-operativos-contra-carteles-de-droga-revela-nyt/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-el-ine-respalda-una-investigacion-a-fondo-tras-videos-del-hijo-de-tadd","t":"El INE respalda una investigación a fondo tras videos del hijo de Taddei con un contratista en París","c":"politica","f":"2026-10-24T18:58","r":"El Instituto Nacional Electoral emitió este sábado un comunicado en el que la presidencia del organismo apoya una investigación exhaustiva con respeto al debido proceso y afirma que ningún proceso de contratación, servidor público o proveedor está por encima de la ley. El mensaje llega después de que Latinus difundió videos de Jorge Francisco Piñeda Taddei, hijo de la consejera presidenta Guadalupe Taddei, en un hotel de lujo de París con el empresario José Alfredo Hernández Casillas, ligado a firmas que obtuvieron contratos de material electoral por alrededor de 245 millones de pesos. Taddei ha negado cualquier conflicto de interés.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/viaje-de-lujo-a-paris-exhibe-vinculo-entre-hijo-de-guadalupe-taddei-y-contratista-del-ine/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-vance-baja-a-huracan-categoria-1-y-podria-acercarse-a-mexico-como-torm","t":"Vance baja a huracán categoría 1 y podría acercarse a México como tormenta tropical el 29 de octubre","c":"nacional","f":"2026-10-24T18:57","r":"El Servicio Meteorológico Nacional informó que Vance se debilitó a categoría 1, con vientos sostenidos de 150 km/h y rachas de 185 km/h, mientras avanza hacia el nor-noroeste a 9 km/h. A las 16:00 horas la Semar lo ubicó a 530 km al sur-suroeste de Lázaro Cárdenas, Michoacán. Se prevé que mantenga esa categoría hasta el 27 de octubre y que alrededor del 29 se aproxime al país como tormenta tropical. Se esperan lluvias de 25 a 50 mm en Jalisco, Colima, Guerrero y Michoacán, y oleaje de 3 a 4 metros en costas de Michoacán y Guerrero.","b":"","img":"huracan","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/24/huracan-vance-se-debilita-a-categoria-1-frente-a-guerrero-y-michoacan-sigue-en-vivo-su-trayectoria/"],["Univision","https://www.univision.com/noticias/meteorologia/huracan-vance-hoy-24-de-octubre-que-categoria-tiene-y-hacia-donde-se-dirige"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-hacienda-recorta-el-estimulo-a-magna-y-premium-el-ieps-sube-a-3-46-y-2","t":"Hacienda recorta el estímulo a Magna y Premium: el IEPS sube a 3.46 y 2.78 pesos por litro","c":"economia","f":"2026-10-24T18:56","r":"Del 24 al 30 de octubre, la cuota de IEPS que pagan los consumidores por la gasolina Magna sube a 3.46 pesos por litro, desde 2.71 la semana previa, y la de Premium pasa de 1.91 a 2.78 pesos, luego de que Hacienda redujo el estímulo fiscal. El diésel se mantiene sin cuota por séptima semana consecutiva. Este sábado, el precio promedio nacional fue de 23.70 pesos por litro de Magna, 28.60 de Premium y 27.00 de diésel, con datos de la CNE y la Profeco.","b":"","img":"pemex","foto":"","cred":"","src":[["Cadena Política","https://cadenapolitica.com/2026/10/24/cuanto-pagaras-de-ieps-por-litro-de-gasolina-del-24-al-30-de-octubre/"],["Infobae","https://www.infobae.com/mexico/2026/10/24/gasolina-en-mexico-precio-de-la-magna-premium-y-diesel-este-sabado-24-de-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-sheinbaum-visita-apatzingan-por-primera-vez-pobladores-le-piden-un-pla","t":"Sheinbaum visita Apatzingán por primera vez; pobladores le piden un plan contra la violencia","c":"estados","f":"2026-10-24T18:55","r":"En su primera visita al municipio michoacano en dos años de gobierno, la presidenta Claudia Sheinbaum encabezó en la Unidad Deportiva de Apatzingán un acto sobre los créditos de Finabien para mujeres emprendedoras, de los que 56 mil 500 se han entregado en Michoacán. En los discursos no se habló de seguridad, pero asistentes llevaron mantas que pedían un plan de paz, y un hombre que perdió una pierna por una mina terrestre le solicitó ayuda. Según el gobernador Alfredo Ramírez Bedolla, la gira del fin de semana incluye Morelia y Pátzcuaro.","b":"","img":"palacio","foto":"","cred":"","src":[["Quadratín Michoacán","https://www.quadratin.com.mx/municipios/clamor-de-seguridad-y-paz-enmarcaron-visita-de-sheinbaum-a-apatzingan/"],["Esfera Noticias","https://esferanoticias.mx/2026/10/24/sheinbaum-estara-este-fin-de-semana-en-morelia-apatzingan-y-patzcuaro-bedolla/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-expertos-de-la-onu-piden-que-la-ley-general-contra-el-feminicidio-prot","t":"Expertos de la ONU piden que la ley general contra el feminicidio proteja también a mujeres trans","c":"nacional","f":"2026-10-24T18:54","r":"El Grupo de Trabajo de la ONU sobre discriminación contra mujeres y niñas y el experto independiente Graeme Reid recomendaron que la propuesta de ley general contra el feminicidio deje claro que abarca a todas las mujeres y niñas, incluidas las mujeres trans, y que las investigaciones no exijan determinar antes la identidad de género de la víctima. También pidieron protocolos uniformes, un registro de huérfanos por feminicidio y mecanismos para responsabilizar a instituciones que fallen en la protección. La SRE destacó las recomendaciones.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/ley-contra-el-feminicidio-en-mexico-onu-pide-garantizar-proteccion-para-mujeres-trans/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-calificadoras-preven-que-pemex-dependera-del-apoyo-federal-al-menos-ha","t":"Calificadoras prevén que Pemex dependerá del apoyo federal al menos hasta 2029 o 2030","c":"economia","f":"2026-10-24T18:53","r":"Moody's, HR Ratings y S&P Global Energy coinciden en que el gobierno no retirará su respaldo a Pemex en esta administración: Moody's lo supone al menos hasta 2030 y HR Ratings hasta 2029, pese a que se planteó que la petrolera dejaría de depender de Hacienda para sus pagos en 2027. La deuda financiera bajó de 97.6 mil millones de dólares en 2024 a 77.5 mil millones en el primer semestre de 2026, aunque los analistas atribuyen la caída sobre todo al apoyo gubernamental. Moody's advierte que sin ese respaldo la empresa incumpliría sus pagos.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/que-pasaria-con-pemex-si-deja-de-recibir-recursos-del-gobierno-federal/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-asesinan-a-una-policia-municipal-de-purisima-del-rincon-al-salir-de-su","t":"Asesinan a una policía municipal de Purísima del Rincón al salir de su turno","c":"seguridad","f":"2026-10-24T18:52","r":"Una agente de la Policía Municipal de Purísima del Rincón, Guanajuato, identificada de forma preliminar como María Angélica, de 31 años, fue atacada a balazos la mañana de este sábado en el Libramiento Sur, cerca del bulevar Las Torres, cuando se retiraba en motocicleta al terminar su turno. Al menos dos hombres le dispararon y huyeron en moto. Murió en el hospital. La Fiscalía de Guanajuato abrió una investigación y los agresores no han sido localizados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["López-Dóriga Digital","https://lopezdoriga.com/nacional/asesinan-a-mujer-policia-en-purisima-del-rincon-guanajuato-tenia-31-anos/"],["Milenio","https://www.milenio.com/policia/purisima-del-rincon-asesinan-mujer-policia-en-ataque-armado"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-matan-a-balazos-a-un-trabajador-del-c4i-en-mazatlan-hallan-unos-20-cas","t":"Matan a balazos a un trabajador del C4i en Mazatlán; hallan unos 20 casquillos","c":"seguridad","f":"2026-10-24T18:51","r":"Jehovan \"R\", exintegrante de Protección Civil municipal que laboraba en el sistema C4i, fue interceptado por hombres armados este sábado en la colonia San Fernando de Mazatlán, Sinaloa, mientras conducía una camioneta. Paramédicos confirmaron que ya no tenía signos vitales. Peritos de la Fiscalía estatal recogieron alrededor de 20 casquillos. Las autoridades no han informado un móvil ni detenciones.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Meganoticias","https://www.meganoticias.mx/culiacan/noticia/asesinan-a-trabajador-del-c4i-en-mazatl%C3%A1n/782194"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-sobreviviente-del-secuestro-masivo-en-ajuchitlan-relata-tres-semanas-d","t":"Sobreviviente del secuestro masivo en Ajuchitlán relata tres semanas de golpes y amenazas","c":"estados","f":"2026-10-24T18:50","r":"Uno de los pobladores del ejido El Balcón, en Ajuchitlán del Progreso, Guerrero, privados de la libertad el 24 de septiembre, describió a Infobae golpizas, amenazas de muerte y una dieta de tortillas y agua durante su cautiverio, atribuido a La Familia Michoacana. Afirma que en el campamento había unas 130 personas; el sacerdote José Filiberto Velázquez, del Centro Minerva Bello, habla de más de 100. Seis liberados regresaron a su comunidad el 23 de octubre, mientras que Domingo Atanacio Quirino sigue desaparecido.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/es-un-infierno-sobrevivio-a-un-secuestro-masivo-en-guerrero-y-revela-como-era-el-cautiverio-bajo-la-familia-michoacana/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-iran-prepara-planes-para-atacar-cables-submarinos-si-ee-uu-e-israel-vu","t":"Irán prepara planes para atacar cables submarinos si EE.UU. e Israel vuelven a bombardearlo","c":"internacional","f":"2026-10-24T18:49","r":"Dos altos funcionarios de seguridad iraníes dijeron a Reuters que Teherán tiene planes para dañar cables de comunicaciones en el golfo Pérsico si sufre un nuevo ataque; un mando de la Guardia Revolucionaria mencionó siete cables bajo el estrecho de Ormuz. En paralelo, Donald Trump advirtió en un mitin en Florida que podría lanzar \"otra pequeña Epic Fury\" si Irán no firma un acuerdo, y el Departamento de Estado redujo personal en varias embajadas de Medio Oriente.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://infobae.com/america/mundo/2026/10/24/iran-analiza-atacar-cables-submarinos-si-estados-unidos-e-israel-vuelven-a-bombardear-el-pais"],["Moncloa.com","https://moncloa.com/2026/10/24/trump-iran-ataques-embajadas-oriente-proximo-3454428"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-brasil-elige-presidente-este-domingo-con-lula-y-flavio-bolsonaro-en-em","t":"Brasil elige presidente este domingo con Lula y Flávio Bolsonaro en empate técnico","c":"internacional","f":"2026-10-24T18:48","r":"Luiz Inácio Lula da Silva y el senador Flávio Bolsonaro, hijo del expresidente Jair Bolsonaro, disputan este domingo 25 de octubre la segunda vuelta presidencial. La encuesta CNT/MDA divulgada este sábado da a Flávio 50.7% de los votos válidos y a Lula 49.3%, una diferencia dentro del margen de error; otros sondeos no coinciden en quién va adelante.","b":"","img":"ultimahora","foto":"","cred":"","src":[["República","https://republica.com/actualidad/lula-y-flavio-bolsonaro-se-enfrentan-este-domingo-para-definir-el-futuro-de-brasil-202610241570"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-protestas-en-francia-por-el-costo-de-vida-dejan-cerca-de-mil-detenidos","t":"Protestas en Francia por el costo de vida dejan cerca de mil detenidos","c":"internacional","f":"2026-10-24T18:47","r":"El ministro del Interior francés, Laurent Nuñez, informó que hacia las 19:30 horas locales de este sábado había cerca de mil detenidos en una nueva jornada de protestas contra el aumento del costo de la vida, frente a 385 a la misma hora del 17 de octubre. Hubo choques en París, Lyon, Lille y Nantes, y la policía usó gas lacrimógeno. La policía de París contó 110 mil manifestantes y la CGT, 250 mil. El gobierno desplegó 70 mil agentes.","b":"","img":"paris","foto":"","cred":"","src":[["Minuto60","https://www.minuto60.com/mundo/protestas-francia-hoy-cuantos-detenidos-hay-que-dijo-ministro/17706"],["El Espectador","https://www.elespectador.com/mundo/europa/francia-en-vivo-nueva-jornada-de-protestas-este-sabado/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-israel-desplaza-a-unas-2-mil-personas-en-hebron-y-netanyahu-anuncia-un","t":"Israel desplaza a unas 2 mil personas en Hebrón y Netanyahu anuncia una operación mayor en Cisjordania","c":"internacional","f":"2026-10-24T18:46","r":"Tras el ataque en un puesto de control cerca de Hebrón que mató a dos soldados israelíes, Israel cerró los accesos a la ciudad y ordenó evacuar viviendas; el ministro de Defensa, Israel Katz, habló de unas 2 mil personas desplazadas que no podrán volver hasta que termine la operación. Benjamin Netanyahu anunció una ofensiva de mayor escala en Cisjordania. La Autoridad Palestina pidió a la comunidad internacional medidas concretas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/el-mundo/israel-sube-la-presion-sobre-cisjordania-tras-el-asesinato-de-dos-soldados-2000-desplazados-y-una-nid24102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-hundimientos-de-hasta-40-centimetros-en-la-cdmx-danan-el-drenaje-y-agr","t":"Hundimientos de hasta 40 centímetros en la CDMX dañan el drenaje y agravan inundaciones","c":"cdmx","f":"2026-10-24T18:45","r":"Algunas zonas de la Ciudad de México registran hundimientos de hasta 40 centímetros, lo que deforma las pendientes del drenaje, que funciona por gravedad, y provoca estancamientos durante las lluvias. Miguel Ángel López, académico de la Ibero, explicó que cerca de 70% del agua de la capital sale de pozos profundos y que la escalinata del Ángel de la Independencia muestra una diferencia de más de dos metros respecto a 1910. Propone regular la extracción, rehabilitar redes y captar agua de lluvia.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/hundimientos-en-cdmx-afectan-al-drenaje-y-aumentan-los-problemas-durante-lluvias/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-la-inversion-mundial-en-infraestructura-de-ia-llegara-a-769-mil-millon","t":"La inversión mundial en infraestructura de IA llegará a 769 mil millones de dólares en 2026: McKinsey","c":"economia","f":"2026-10-24T18:44","r":"El informe Technology Trends Outlook 2026 de McKinsey estima que el gasto global en infraestructura de inteligencia artificial alcanzará 769 mil millones de dólares este año y que el software con agentes podría liberar hasta un billón de dólares en valor corporativo. La consultora advierte que el principal freno ya no es el acceso a la tecnología, sino la capacidad industrial y de las redes eléctricas: más de 2 mil 500 GW de proyectos de generación esperan conexión.","b":"","img":"tech2","foto":"","cred":"","src":[["MuyComputerPRO","https://muycomputerpro.com/2026/10/24/la-inversion-en-infraestructura-de-ia-alcanzara-los-769-000-millones-de-dolares-en-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-china-publica-18-medidas-para-introducir-la-ia-de-forma-gradual-y-prot","t":"China publica 18 medidas para introducir la IA de forma gradual y proteger empleos","c":"tecnologia","f":"2026-10-24T18:43","r":"El Consejo de Estado de China difundió directrices con 18 medidas para incorporar la inteligencia artificial poco a poco en sectores con mucha mano de obra, avisar con antelación a los trabajadores afectados, facilitar su reconversión y vigilar el impacto en el empleo. También busca combatir la discriminación algorítmica en la contratación. Las directrices no fijan obligaciones ni plazos para las empresas. China suma más de 700 millones de usuarios de IA generativa.","b":"","img":"tech","foto":"","cred":"","src":[["ABC Color (EFE)","https://www.abc.com.py/tecnologia/2026/10/24/china-pide-cautela-ante-la-sustitucion-de-trabajadores-por-ia/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-cerveceros-y-rays-juegan-el-segundo-de-la-serie-mundial-milwaukee-lide","t":"Cerveceros y Rays juegan el segundo de la Serie Mundial; Milwaukee lidera 1-0","c":"deportes","f":"2026-10-24T18:42","r":"Tras ganar 3-2 el primer juego, los Cerveceros de Milwaukee reciben este sábado a los Rays de Tampa Bay a las 18:00 horas del centro de México en el American Family Field, con Logan Henderson como abridor local. En México el partido se transmite por ESPN, FOX Sports, TUDN y MLB Season Pass.","b":"","img":"beisbol","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/10/24/jojo-romero-y-los-milwaukee-brewers-se-ponen-al-frente-en-la-serie-mundial-2026-a-que-hora-y-donde-ver-en-mexico-el-juego-2/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-docuserie-sostiene-que-la-cia-participo-en-la-busqueda-de-el-chapo-y-s","t":"Docuserie sostiene que la CIA participó en la búsqueda de El Chapo y se retiró tras la visita de Kate del Castillo","c":"entretenimiento","f":"2026-10-24T18:41","r":"Operación Cisne Negro, de N+ Docs, se estrena el 27 de octubre en Vix y repasa la fuga de Joaquín Guzmán Loera en 2015 y su recaptura en enero de 2016. Su director, Héctor Laso, afirma que la CIA tuvo un papel importante y dejó de colaborar después del encuentro de Kate del Castillo y Sean Penn con el capo. El exsecretario de Gobernación Miguel Ángel Osorio Chong confirmó que se pidió a México no intervenir para no poner en riesgo a dos estadounidenses. La serie revisó más de 12 mil páginas de expedientes.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/la-cia-participo-en-los-operativos-de-captura-de-el-chapo-guzman-reunion-de-kate-del-castillo-con-lider-del-cds-freno-colaboracion/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-muere-la-mama-de-la-influencer-kimberly-la-mas-preciosa","t":"Muere la mamá de la influencer Kimberly \"La Más Preciosa\"","c":"entretenimiento","f":"2026-10-24T18:40","r":"La creadora de contenido Kimberly \"La Más Preciosa\" anunció este sábado en Instagram la muerte de su madre con un mensaje de despedida. No informó la causa ni detalles sobre los servicios funerarios.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/muere-mama-de-kimberly-la-mas-preciosa-mi-vida-ya-no-sera-la-misma/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-vance-alcanza-vientos-de-175-km-h-frente-a-guerrero-y-podria-llegar-a","t":"Vance alcanza vientos de 175 km/h frente a Guerrero y podría llegar a categoría 3","c":"nacional","f":"2026-10-24T06:55","r":"De acuerdo con el reporte de las 21:00 horas del viernes, el huracán Vance, de categoría 2, se ubicaba a 615 kilómetros al sur-suroeste de Acapulco y a 800 kilómetros al sur-sureste de Manzanillo, con vientos sostenidos de 175 km/h y rachas de 210 km/h, mientras avanzaba al norte-noroeste a 11 km/h. El Centro Nacional de Huracanes prevé que se fortalezca durante la madrugada, posiblemente a categoría 3, antes de empezar a debilitarse el sábado. Conagua pronostica lluvias de 25 a 50 milímetros en Michoacán y la costa de Guerrero, además de oleaje peligroso y corrientes de resaca en el litoral sur y suroeste.","b":"","img":"huracan","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/huracan-vance-podria-alcanzar-categoria-3-trayectoria-y-efectos-en-las-costas"],["Eureka Medios","https://eurekamedios.mx/huracan-vance-se-fortalece-frente-a-guerrero-preven-lluvias-en-tres-estados/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-gobierno-compra-780-equipos-medicos-de-alta-tecnologia-y-ahorra-7-mil","t":"Gobierno compra 780 equipos médicos de alta tecnología y ahorra 7 mil millones en subastas","c":"nacional","f":"2026-10-24T06:54","r":"El subsecretario Eduardo Clark informó en la mañanera que concluyeron las subastas para adquirir cerca de 780 equipos de alta tecnología, entre ellos casi 500 mastógrafos, además de tomógrafos, resonadores y aceleradores lineales, con una inversión de más de 14 mil millones de pesos. Las subastas inversas bajaron el costo de unos 21 mil a 14 mil millones, un ahorro de 7 mil millones. Los primeros equipos llegarían el próximo mes y la mayoría operaría hacia junio de 2027; también se comprarán más de 20 mil equipos de mediana y baja tecnología, como ventiladores y monitores.","b":"","img":"imss","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-23-octubre-2026-minuto-minuto-vivo-n6336228"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-sheinbaum-crea-consejo-de-expertos-para-rastrear-cada-medicamento-del","t":"Sheinbaum crea consejo de expertos para rastrear cada medicamento del IMSS desde enero","c":"nacional","f":"2026-10-24T06:53","r":"La presidenta Claudia Sheinbaum presentó el Consejo Asesor para la Transformación Digital del Sector Salud, integrado por cuatro especialistas en logística, sistemas e investigación de operaciones, que diseñará una plataforma para pedir insumos en tiempo real, controlar almacenes e inventarios y acelerar la entrega a hospitales. El sistema público maneja unos 3 mil millones de piezas de medicamentos e insumos al año para más de mil hospitales y casi 15 mil unidades de primer nivel. Sheinbaum pidió resultados en un mes; la herramienta empezaría a operar en enero de 2027 en el IMSS e IMSS-Bienestar.","b":"","img":"imss","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/tras-reconocer-fallas-en-sistema-de-salud-sheinbaum-presenta-grupo-de-expertos-que-modernizara-el-imss-promete-avances-en-un-mes/"],["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/23/claudia-sheinbaum-mananera-temas-hoy-23-de-octubre-de-2026-en-vivo/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-sre-niega-a-senadores-el-uso-de-la-sala-para-diplomaticos-en-el-aicm-s","t":"SRE niega a senadores el uso de la sala para diplomáticos en el AICM; Sheinbaum pide \"cero privilegios\"","c":"politica","f":"2026-10-24T06:52","r":"El canciller Roberto Velasco confirmó que la Secretaría de Relaciones Exteriores rechazó una solicitud del Senado para que legisladores usaran el salón de protocolo del Aeropuerto Internacional de la Ciudad de México, reservado a diplomáticos. La presidenta Sheinbaum dijo que los legisladores no deben tener privilegios. El presidente del Senado, Higinio Martínez, aseguró que la Mesa Directiva nunca autorizó la petición, atribuyó la carta al secretario técnico Daniel Sibaja y la calificó como un error garrafal.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/sre-rechazo-solicitud-de-senadores-para-entrar-a-sala-vip-en-aicm-higinio-martinez-califica-solicitud-como-garrafal-error/"],["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/23/sheinbaum-dice-que-sre-bateo-solicitud-de-salones-vip-en-el-aicm-para-senadores-cero-privilegios/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-24-modalidad-40-suma-798-mil-pensiones-que-cuestan-246-mil-millones-de-pe","t":"Modalidad 40 suma 798 mil pensiones que cuestan 246 mil millones de pesos al año","c":"economia","f":"2026-10-24T06:51","r":"De acuerdo con cifras oficiales a octubre, unas 798 mil personas reciben pensión bajo la Modalidad 40 del IMSS, con una nómina de 20 mil 508 millones de pesos al mes, equivalente a cerca de 246 mil millones al año sin contar aguinaldo. Quienes ya están pensionados no tendrán afectaciones. El IMSS suspendió de forma temporal la opción de registrarse con un salario muy superior al real; especialistas del Tec de Monterrey y la Amafore señalaron que el gobierno federal cubre la diferencia cuando las aportaciones no alcanzan.","b":"","img":"imss","foto":"","cred":"","src":[["Almomento","https://almomento.mx/hay-798000-pensiones-asociadas-a-la-modalidad-40-cuestan-246000-millones-de-pesos-al-ano/"],["El Tiempo","https://www.tiempo.com.mx/economia/hay-798-mil-pensiones-modalidad-40-246-mil-millones-por-ano-octubre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-enviado-de-ee-uu-dice-que-un-ataque-a-iran-este-fin-de-semana-es-posib","t":"Enviado de EE.UU. dice que un ataque a Irán este fin de semana es posible; Trump se desmarca","c":"internacional","f":"2026-10-24T06:50","r":"Tom Barrack, embajador de Estados Unidos en Turquía y encargado del tema de Siria, respondió \"absolutamente\" al ser preguntado si podría haber un ataque contra Irán este fin de semana, en una entrevista durante una visita al Golfo. Barrack aclaró que Washington no busca un cambio de régimen. Cuestionado en Florida, el presidente Donald Trump dijo que no sabe nada al respecto. Las declaraciones presionaron a los mercados y al petróleo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Gestión / AFP","https://gestion.pe/mundo/internacional/eeuu-podria-atacar-a-iran-este-fin-de-semana-segun-diplomatico-estadounidense-noticia/"],["La Nación","https://www.lanacion.com.ar/estados-unidos/wall-street-cierra-a-la-baja-impactada-por-un-nuevo-repunte-del-petroleo-nid23102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-sheinbaum-pide-que-no-haya-ninguna-sombra-de-corrupcion-en-el-ine-rumb","t":"Sheinbaum pide que no haya \"ninguna sombra de corrupción\" en el INE rumbo a 2027","c":"politica","f":"2026-10-24T06:49","r":"En su conferencia del viernes, la presidenta Claudia Sheinbaum pidió que se hagan todas las auditorías necesarias al Instituto Nacional Electoral ante los señalamientos sobre contratistas y la cercanía de la consejera presidenta Guadalupe Taddei con un proveedor. Sobre si Taddei debe renunciar, dijo que es una decisión personal. También negó que Andrés Manuel López Obrador planee una gira en 2027.","b":"","img":"ine","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/23/claudia-sheinbaum-mananera-temas-hoy-23-de-octubre-de-2026-en-vivo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-pemex-niega-despidos-masivos-y-recorte-de-salarios-su-plantilla-baja-0","t":"Pemex niega despidos masivos y recorte de salarios; su plantilla baja 0.21% en 2026","c":"economia","f":"2026-10-24T06:48","r":"Petróleos Mexicanos negó que haya bajas masivas o reducciones en sus tabuladores salariales y precisó que los ajustes equivalen a una disminución de 0.21% de su plantilla en 2026. La empresa explicó que realiza evaluaciones de desempeño y una reestructura para eliminar duplicidades y niveles de mando innecesarios, y que las salidas se hacen con indemnización y prestaciones conforme a la ley.","b":"","img":"pemex","foto":"","cred":"","src":[["Diario de Tabasco","https://www.diariodetabasco.mx/negocios/2026/10/23/pemex-descarta-despidos-masivos-y-recortes-salariales-ajusta-su-plantilla-0-21-en-2026/"],["El Financiero","https://www.elfinanciero.com.mx/economia/2026/10/23/pemex-descarta-bajas-masivas-y-la-reduccion-de-los-tabuladores-salariales/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-detienen-a-cinco-hombres-que-dispararon-contra-policias-y-militares-en","t":"Detienen a cinco hombres que dispararon contra policías y militares en Concordia, Sinaloa","c":"seguridad","f":"2026-10-24T06:47","r":"La noche del viernes, en la zona de Zavala, municipio de Concordia, cinco civiles armados fueron detenidos después de atacar a elementos estatales y del Ejército; tres de ellos resultaron heridos. Las autoridades aseguraron cinco fusiles tipo AK-47, mil 150 cartuchos, 30 cargadores, siete chalecos tácticos y 14 placas balísticas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-ataque-armado-en-calzada-ermita-iztapalapa-deja-dos-muertos-detienen-a","t":"Ataque armado en Calzada Ermita, Iztapalapa, deja dos muertos; detienen a dos jóvenes","c":"seguridad","f":"2026-10-24T06:46","r":"Un ataque a balazos en Calzada Ermita, en la colonia Ampliación Ricardo Flores Magón de Iztapalapa, dejó dos personas muertas y una herida que fue trasladada a un hospital. Los agresores huyeron en motocicleta; con el apoyo de cámaras del C2 Oriente, policías los ubicaron en Iztacalco y detuvieron a dos hombres de 22 años, a quienes aseguraron un arma de fuego y el vehículo.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-wall-street-cierra-la-semana-a-la-baja-por-el-petroleo-y-dudas-sobre-l","t":"Wall Street cierra la semana a la baja por el petróleo y dudas sobre la IA","c":"economia","f":"2026-10-24T06:45","r":"El viernes, el Dow Jones cayó 1.23% a 52 mil 215 puntos, el S&P 500 bajó 0.52% a 7 mil 623 y el Nasdaq perdió 0.21% a 25 mil 955. En la semana, el Dow ganó 0.4%, mientras el S&P 500 y el Nasdaq retrocedieron 0.5% y 0.7%. Pesaron el alza del crudo por la tensión con Irán, las dudas sobre la rentabilidad del gasto en inteligencia artificial y un rendimiento del bono del Tesoro a 10 años cercano a 5%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/23/wall-street-cierra-en-rojo-tras-una-semana-volatil-centrada-en-el-petroleo-y-la-ia/"],["La Nación","https://www.lanacion.com.ar/estados-unidos/wall-street-cierra-a-la-baja-impactada-por-un-nuevo-repunte-del-petroleo-nid23102026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-tiroteo-en-las-afueras-de-paris-deja-un-muerto-francia-lo-investiga-co","t":"Tiroteo en las afueras de París deja un muerto; Francia lo investiga como terrorismo racista","c":"internacional","f":"2026-10-24T06:44","r":"Un hombre disparó desde su auto en tres puntos de Trappes y La Verrière, en el departamento de Yvelines, en menos de 15 minutos; una persona murió y varias resultaron heridas, entre ellas una niña de 12 años en estado grave. El agresor fue detenido. La fiscalía antiterrorista tomó el caso y el ministro del Interior, Laurent Nuñez, habló de un crimen terrorista con posible motivo racista; el presidente Emmanuel Macron lo condenó.","b":"","img":"paris","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/el-mundo/conmocion-en-un-suburbio-de-paris-un-tiroteo-dejo-un-muerto-y-varios-heridos-e-investigan-un-nid23102026/"],["Infobae","https://www.infobae.com/america/mundo/2026/10/23/ataque-terrorista-en-francia-un-muerto-y-cuatro-heridos-en-un-suburbio-de-paris/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-melania-trump-anuncia-un-alto-el-fuego-local-en-oleshky-ucrania-a-part","t":"Melania Trump anuncia un alto el fuego local en Oleshky, Ucrania, a partir del 29 de octubre","c":"internacional","f":"2026-10-24T06:43","r":"La Casa Blanca informó que Melania Trump medió un cese temporal de hostilidades entre fuerzas rusas y ucranianas en Oleshky, ciudad del sur de Ucrania bajo control ruso, para permitir la entrada de ayuda humanitaria y la evacuación de civiles por un corredor seguro. El diputado ucraniano David Arajamia confirmó el acuerdo; Moscú y Kiev nombraron equipos para coordinar la logística, incluido el desminado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["elDiario.es","https://www.eldiario.es/internacional/melania-trump-anuncia-alto-fuego-rusia-ucrania-ciudad-oleshky-mediado_1_13610460.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-trump-retira-aranceles-de-50-a-nueve-categorias-de-productos-de-canada","t":"Trump retira aranceles de 50% a nueve categorías de productos de Canadá","c":"internacional","f":"2026-10-24T06:42","r":"El presidente Donald Trump firmó un decreto que elimina los aranceles de 50% a nueve categorías de productos agrícolas y forestales canadienses, entre ellos madera contrachapada, algunos productos de papel y cajas de embalaje. La medida beneficia a productores de Maine, donde la senadora republicana Susan Collins, que pidió el cambio, está empatada en las encuestas con el demócrata Troy Jackson rumbo a la elección del 3 de noviembre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/10/23/donald-trump-elimino-aranceles-del-50-a-nueve-categorias-de-productos-canadienses/"],["El Financiero","https://www.elfinanciero.com.mx/mundo/2026/10/23/trump-perdona-aranceles-a-canada-para-ayudar-a-reeleccion-de-senadora-republicana-en-maine/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-detienen-en-juchitan-a-el-acido-ligado-a-cuatro-homicidios-y-a-los-cro","t":"Detienen en Juchitán a \"El Ácido\", ligado a cuatro homicidios y a Los Cromos","c":"estados","f":"2026-10-24T06:41","r":"La Fiscalía General del Estado de Oaxaca detuvo en Juchitán a un joven de 19 años identificado como J. S. A., alias \"El Ácido\", señalado como sicario de Los Cromos, grupo aliado del CJNG en el Istmo de Tehuantepec. Se le relaciona con al menos cuatro homicidios en Juchitán, ataques armados y extorsiones a unidades del transporte público.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-sismo-de-magnitud-4-7-sacude-la-costa-de-chiapas-esta-madrugada","t":"Sismo de magnitud 4.7 sacude la costa de Chiapas esta madrugada","c":"estados","f":"2026-10-24T06:40","r":"Un sismo de magnitud 4.7 se registró a la 01:31 horas a unos 90 kilómetros al suroeste de Ciudad Hidalgo, Chiapas, con una profundidad de 16 kilómetros. No se reportaron daños ni personas lesionadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/24/temblor-hoy-en-mexico-noticias-actividad-sismica-24-de-octubre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-paseo-nocturno-de-dia-de-muertos-cierra-hoy-reforma-de-18-00-a-22-00-h","t":"Paseo nocturno de Día de Muertos cierra hoy Reforma de 18:00 a 22:00 horas","c":"cdmx","f":"2026-10-24T06:39","r":"Este sábado se realiza el paseo nocturno en bicicleta por Día de Muertos, con un recorrido de 13 kilómetros de 18:00 a 22:00 horas. Paseo de la Reforma permanecerá cerrado a la circulación entre la Glorieta del Ahuehuete y la Glorieta de Cuitláhuac, por lo que se recomienda prever rutas alternas.","b":"","img":"angel","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/paseo-nocturno-en-cdmx-fecha-horario-y-ruta-por-dia-de-muertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-cerveceros-vencen-3-2-a-rays-en-un-cierre-de-infarto-y-toman-ventaja-e","t":"Cerveceros vencen 3-2 a Rays en un cierre de infarto y toman ventaja en la Serie Mundial","c":"deportes","f":"2026-10-24T06:38","r":"Milwaukee ganó el primer juego de la Serie Mundial luego de que Tampa Bay llenó las bases con dos outs en la novena; Trevor Megill ponchó a Jonathan DeLuca para terminar el partido. Jacob Misiorowski lanzó cinco entradas con una carrera limpia y William Contreras y Jackson Chourio produjeron carreras. El mexicano Jonathan Aranda se fue de 3-3 con una base por bolas y una anotada. El segundo juego es este sábado en Milwaukee.","b":"","img":"beisbol","foto":"","cred":"","src":[["SI México","https://www.si.com/mx/beisbol/los-cerveceros-vencieron-3-2-a-tampa-bay-en-el-primer-juego-de-la-serie-mundial"],["Teletica","https://www.teletica.com/baseball/milwaukee-vence-3-2-a-tampa-bay-en-el-primer-juego-de-la-serie-mundial-2026_419849"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-fuerza-regida-arrasa-en-los-billboard-latinos-con-ocho-premios-bad-bun","t":"Fuerza Regida arrasa en los Billboard latinos con ocho premios; Bad Bunny, artista del año","c":"entretenimiento","f":"2026-10-24T06:37","r":"Fuerza Regida fue el más premiado de los Premios Billboard de la Música Latina 2026, celebrados en Miami, con ocho galardones, entre ellos canción del año por \"Marlboro Rojo\" y artista regional mexicano del año. Bad Bunny, que no asistió, ganó siete, incluidos artista del año y gira del año. Karol G, Peso Pluma y Romeo Santos obtuvieron cuatro cada uno.","b":"","img":"estudio","foto":"","cred":"","src":[["Extra","https://www.extra.ec/noticia/farandula/premios-billboard-latinos-2026-rosalia-fuerza-regida-karol-g-ganadores-165774.html"],["Telemundo","https://www.telemundo51.com/entretenimiento/fuerza-regida-bad-bunny-encabezan-ganadores-premios-billboard-latinos/2839237/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-24-apple-queda-a-42-mil-millones-de-dolares-de-superar-a-nvidia-como-la-e","t":"Apple queda a 42 mil millones de dólares de superar a Nvidia como la empresa más valiosa","c":"tecnologia","f":"2026-10-24T06:36","r":"Tras cerrar el jueves en un récord de 348.22 dólares por acción, Apple alcanzó un valor de mercado de unos 5.08 billones de dólares, apenas 42 mil millones por debajo de Nvidia, cuyas acciones cayeron 4.4% en una jornada de ventas en semiconductores ligados a la inteligencia artificial. Apple reporta resultados el 2 de noviembre y Nvidia alrededor del 18.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/10/23/apple-quedo-a-solo-usd-42000-millones-de-superar-a-nvidia-como-la-empresa-mas-valiosa-del-mundo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-percepcion-de-inseguridad-baja-a-58-1-la-mas-baja-desde-que-existe-la","t":"Percepción de inseguridad baja a 58.1%, la más baja desde que existe la ENSU","c":"nacional","f":"2026-10-23T18:55","r":"En septiembre, 58.1% de la población adulta de 91 ciudades consideró inseguro vivir en su ciudad, frente a 59.8% en junio y 63% un año antes, según la Encuesta Nacional de Seguridad Pública Urbana del INEGI. El secretario Omar García Harfuch destacó que es el nivel más bajo desde que inició la encuesta en 2013. Irapuato (90.5%), Chilpancingo (86.9%) y Mazatlán (85.8%) registran la mayor percepción de inseguridad.","b":"","img":"palacio","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/nacion/2026/10/23/el-581-se-sintio-inseguro-en-su-ciudad-en-septiembre-informa-inegi-534277.html"],["Infobae","https://www.infobae.com/mexico/2026/10/23/harfuch-presume-nivel-mas-bajo-de-percepcion-de-inseguridad-en-el-pais-en-los-ultimos-13-anos-28-ciudades-registraron-mejoras-en-el-ultimo-ano/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-la-auditoria-superior-abre-una-investigacion-de-oficio-contra-el-ine","t":"La Auditoría Superior abre una investigación de oficio contra el INE","c":"politica","f":"2026-10-23T18:54","r":"Tras las acusaciones contra la consejera presidenta Guadalupe Taddei, la Auditoría Superior de la Federación anunció una investigación de oficio al INE y a los organismos electorales locales por presunto uso indebido de recursos. La ASF dijo contar con indicios de contrataciones irregulares, posibles conflictos de interés y triangulación de recursos en contratos con proveedores de papel y tintas electorales; Taddei ha calificado de infundados los señalamientos.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/tras-acusaciones-a-taddei-auditoria-superior-de-la-federacion-abre-investigacion-de-oficio-contra-el-ine/"],["La Razón","https://www.razon.com.mx/mexico/2026/10/23/asf-abre-investigacion-de-oficio-al-ine-y-oples-tras-senalamientos-por-contratos/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-montiel-reta-a-maru-campos-a-presentar-pruebas-la-fgr-confirma-la-vers","t":"Montiel reta a Maru Campos a presentar pruebas; la FGR confirma la versión de Sheinbaum","c":"politica","f":"2026-10-23T18:53","r":"La dirigente nacional de Morena, Ariadna Montiel, rechazó la acusación de la gobernadora de Chihuahua sobre supuestos nexos con el crimen organizado y le pidió llevar sus pruebas «ante las autoridades competentes». En la mañanera, Sheinbaum dijo que Campos no ha presentado ninguna prueba y le pidió declarar ante la fiscal Ernestina Godoy; horas después, la FGR confirmó que en la reunión Campos responsabilizó al exfiscal César Jáuregui por la presencia de extranjeros en Chihuahua.","b":"","img":"chihuahua","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/23/ariadna-montiel-responde-a-acusacion-de-maru-campos-que-le-dijo/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-vance-sube-a-huracan-categoria-2-y-podria-llegar-a-categoria-3-el-saba","t":"Vance sube a huracán categoría 2 y podría llegar a categoría 3 el sábado","c":"nacional","f":"2026-10-23T18:52","r":"A las 15:00 horas, el Servicio Meteorológico Nacional ubicó al huracán Vance a 685 kilómetros al sur-suroeste de Acapulco, con vientos sostenidos de 165 km/h y rachas de 205 km/h, desplazándose al noroeste a 7 km/h. Provoca lluvias fuertes en Michoacán y Guerrero, chubascos en Oaxaca y oleaje de hasta 3 metros en la costa guerrerense; se prevé que se mantenga en el mar sin tocar tierra.","b":"","img":"huracan","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/23/vance-sube-a-huracan-de-categoria-2-y-provoca-lluvias-en-michoacan-guerrero-y-oaxaca/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-la-economia-crece-0-6-en-agosto-por-encima-de-lo-esperado-inegi","t":"La economía crece 0.6% en agosto, por encima de lo esperado: INEGI","c":"economia","f":"2026-10-23T18:51","r":"El Indicador Global de la Actividad Económica avanzó 0.6% mensual en agosto en cifras desestacionalizadas, por encima del 0.3% que esperaba el consenso, y 3.5% frente a agosto de 2025. Las manufacturas subieron 1.2% y los servicios financieros 1.4%, mientras la minería cayó 1.6%. En enero-agosto la actividad acumula un alza anual de 1.7%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/10/23/economia-mexicana-crece-mas-de-lo-esperado-y-mejora-su-perspectiva-para-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-detienen-en-colima-a-mando-20-ligado-al-coche-bomba-contra-policias-en","t":"Detienen en Colima a «Mando 20», ligado al coche bomba contra policías en Coahuayana","c":"seguridad","f":"2026-10-23T18:50","r":"El secretario de Seguridad, Omar García Harfuch, informó la detención de David «N», alias «Mando 20», y de Sinuhe «N» y Cristian «N» en dos cateos en Tecomán, Colima. Según las autoridades, David «N» encabezaba una célula del CJNG y sería el autor intelectual del ataque con coche bomba del 6 de diciembre de 2025 frente a la Policía Comunitaria de Coahuayana, Michoacán, que dejó seis muertos y 11 heridos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/capturan-a-mando-20-lider-de-una-celula-del-cjng-involucrado-en-ataque-con-coche-bomba-a-policias-en-michoacan-que-dejo-seis-muertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-el-peso-cierra-en-18-65-por-dolar-pero-suma-su-septima-semana-de-perdi","t":"El peso cierra en 18.65 por dólar, pero suma su séptima semana de pérdidas","c":"economia","f":"2026-10-23T18:49","r":"El tipo de cambio cerró este viernes en 18.65 pesos por dólar, con una recuperación de 0.34% para el peso frente a los 18.71 del jueves, según datos de Dow Jones citados por Infobae. En la semana, el dólar ganó 0.84%; analistas atribuyen la presión a las tensiones en Medio Oriente, el alza del petróleo y mayores rendimientos de los bonos del Tesoro.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/precio-del-dolar-hoy-en-mexico-cotizacion-de-cierre-del-23-de-octubre/"],["Expansión","https://expansion.mx/mercados/2026/10/23/dolar-hoy-23-octubre-2026-peso-mexicano-bolsa-mexicana"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-el-brent-cierra-en-116-72-dolares-su-nivel-mas-alto-en-casi-seis-meses","t":"El Brent cierra en 116.72 dólares, su nivel más alto en casi seis meses, por ataques hutíes","c":"economia","f":"2026-10-23T18:48","r":"El petróleo Brent subió 3.14% y cerró en 116.72 dólares por barril, mientras el WTI avanzó 3.8% a 103.27 dólares, tras nuevos ataques de los hutíes contra Arabia Saudita. Estados Unidos ordenó la salida de su personal no esencial de la embajada en Riad y los consulados de Yeda y Dhahran. En México, el S&P/BMV IPC terminó casi sin cambios, con baja de 0.01% a 69,879.62 puntos.","b":"","img":"pemex","foto":"","cred":"","src":[["Azteca Noticias","https://www.tvazteca.com/aztecanoticias/asi-cerro-la-bolsa-mexicana-valores-hoy-23-octubre-2026"],["Moncloa.com","https://www.moncloa.com/2026/10/23/eeuu-personal-diplomatico-arabia-saudi-3453802/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-remueven-al-director-del-penal-el-castillo-de-mazatlan-tras-la-rina-qu","t":"Remueven al director del penal El Castillo de Mazatlán tras la riña que dejó 12 muertos","c":"seguridad","f":"2026-10-23T18:47","r":"La Secretaría de Seguridad Pública de Sinaloa retiró a Enrique Mora García de la dirección del centro penitenciario El Castillo, en Mazatlán. La medida busca facilitar las investigaciones internas y de la Fiscalía estatal sobre los enfrentamientos del 8 y 9 de octubre, en los que murieron 11 internos y un niño de dos años.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-hallan-sin-vida-a-ariana-scarlett-nina-de-12-anos-desaparecida-en-ostu","t":"Hallan sin vida a Ariana Scarlett, niña de 12 años desaparecida en Ostuacán, Chiapas","c":"estados","f":"2026-10-23T18:46","r":"Protección Civil de Chiapas informó el hallazgo del cuerpo de Ariana Scarlett Velázquez Cruz, de 12 años, la mañana de este viernes en Ostuacán. La menor había desaparecido junto con su abuela, Mirian Cruz Alpuche, cuando fueron a buscar una vaca a un rancho cercano; la abuela también fue localizada sin vida junto a un río. No se ha informado la causa de muerte.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-detienen-al-jefe-de-seguridad-publica-de-emiliano-zapata-tabasco","t":"Detienen al jefe de Seguridad Pública de Emiliano Zapata, Tabasco","c":"estados","f":"2026-10-23T18:45","r":"La Fiscalía General del Estado de Tabasco detuvo a Cleofas Juárez Lara, titular de Seguridad Pública del municipio de Emiliano Zapata, durante cateos realizados en la madrugada con la Fuerza Interinstitucional Olmeca. Las autoridades lo vinculan con narcomenudeo, cohecho y amenazas; fue detenido durante uno de los cateos, sin que mediara una orden de aprehensión.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-linea-a-del-metro-recupera-el-servicio-completo-tras-la-falla-en-la-ca","t":"Línea A del Metro recupera el servicio completo tras la falla en la catenaria","c":"cdmx","f":"2026-10-23T18:44","r":"El director del Metro, Adrián Rubalcava, informó que la Línea A quedó restablecida en su totalidad entre Pantitlán y La Paz, luego de que la ruptura de un elemento de la catenaria la noche del jueves obligó a operar en dos tramos. Durante la contingencia, las estaciones Tepalcates, Guelatao, Peñón Viejo y Acatitla permanecieron cerradas y la RTP dio apoyo a los usuarios.","b":"","img":"metro","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/metro-cdmx-restablece-la-linea-a-tras-falla-en-la-catenaria-persiste-el-caos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-brugada-entrega-3-mil-317-apoyos-de-vivienda-con-inversion-de-521-mill","t":"Brugada entrega 3 mil 317 apoyos de vivienda con inversión de 521 millones de pesos","c":"cdmx","f":"2026-10-23T18:43","r":"Desde la Utopía Mixiuhca, la jefa de Gobierno, Clara Brugada, entregó 3 mil 317 apoyos del programa Mejora de Vivienda: 2 mil 381 para mejoramiento, 665 para vivienda nueva progresiva y 271 para acciones de sustentabilidad, además de 300 escrituras. La inversión es de 521 millones de pesos; Brugada destacó que los créditos de Sevivienda no cobran intereses.","b":"","img":"zocalo","foto":"","cred":"","src":[["El Momento","https://elmomento.mx/entrega-clara-brugada-mas-de-3-mil-300-apoyos-de-vivienda/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-rusia-y-ucrania-negociaran-en-abu-dabi-en-noviembre-con-mediacion-de-e","t":"Rusia y Ucrania negociarán en Abu Dabi en noviembre con mediación de EE. UU.","c":"internacional","f":"2026-10-23T18:42","r":"El portavoz del Kremlin, Dmitri Peskov, informó que las conversaciones directas con Ucrania se celebrarán en Abu Dabi en la primera quincena de noviembre, con Estados Unidos como mediador; Moscú propuso una fecha cercana al 10 de noviembre. El mismo día ambos países intercambiaron 270 prisioneros de guerra, mientras Rusia dijo haber tomado 13 localidades ucranianas en la última semana.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Tiempo","https://www.eltiempo.com/mundo/europa/rusia-anuncia-negociacion-con-ucrania-en-abu-dabi-bajo-mediacion-de-estados-unidos-en-los-primeros-dias-de-noviembre-3595737"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-netanyahu-ordena-el-cierre-total-de-cisjordania-tras-un-ataque-armado","t":"Netanyahu ordena el cierre total de Cisjordania tras un ataque armado cerca de Hebrón","c":"internacional","f":"2026-10-23T18:41","r":"Dos atacantes abrieron fuego cerca de Hebrón y dejaron cinco israelíes heridos, dos de gravedad; ambos fueron abatidos por las fuerzas israelíes. El primer ministro Benjamín Netanyahu ordenó sellar Hebrón y cerrar por tiempo indefinido toda Cisjordania, a cuatro días de las elecciones generales del martes en Israel.","b":"","img":"ultimahora","foto":"","cred":"","src":[["elDiario.es","https://www.eldiario.es/internacional/netanyahu-ordena-cierre-cisjordania-dias-elecciones-ataque-cerca-hebron_1_13608925.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-lula-y-flavio-bolsonaro-llegan-empatados-al-ultimo-debate-antes-del-ba","t":"Lula y Flávio Bolsonaro llegan empatados al último debate antes del balotaje en Brasil","c":"internacional","f":"2026-10-23T18:40","r":"El presidente Luiz Inácio Lula da Silva y el senador Flávio Bolsonaro se enfrentan este viernes en el último debate televisado previo a la segunda vuelta del domingo. La encuesta de Datafolha publicada el jueves los ubica en empate técnico, con 50% cada uno, cuando dos semanas antes Bolsonaro aventajaba por cuatro puntos; según Quaest, los indecisos subieron de 7% a 14%.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/america-latina/2026/10/23/lula-y-flavio-bolsonaro-se-enfrentan-en-el-debate-decisivo-antes-del-balotaje-en-brasil/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-rommel-pacheco-promete-beca-a-los-62-atletas-que-iran-a-los-juegos-de","t":"Rommel Pacheco promete beca a los 62 atletas que irán a los Juegos de la Juventud en Dakar","c":"deportes","f":"2026-10-23T18:39","r":"Durante el abanderamiento en el CNAR, el titular de la Conade, Rommel Pacheco, aseguró que los 62 atletas de la delegación mexicana para los Juegos Olímpicos de la Juventud Dakar 2026 recibirán una beca sin importar su resultado; no precisó montos. La presidenta del COM, María José Alcalá, había señalado que la Conade no aportó recursos para el viaje, y Pacheco pidió dejar atrás la confrontación entre ambas instituciones.","b":"","img":"estadio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/deportes/2026/10/23/conade-promete-becas-a-los-atletas-de-jo-de-juventud/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-suspenden-al-arbitro-yonatan-peinado-por-omitir-los-insultos-de-brian","t":"Suspenden al árbitro Yonatan Peinado por omitir los insultos de Brian Rodríguez","c":"deportes","f":"2026-10-23T18:38","r":"La Comisión de Arbitraje suspendió a Yonatan Peinado, cuarto árbitro del América contra Monterrey de la jornada 11, por no reportar en la cédula los insultos que le dirigió el jugador azulcrema Brian Rodríguez. La Comisión consideró más grave haber faltado a la verdad en su declaración que la omisión misma; no se informó la duración del castigo.","b":"","img":"estadio","foto":"","cred":"","src":[["Fox Sports","https://www.foxsports.com.mx/2026/10/22/comision-de-arbitraje-suspende-a-silbante-al-que-brian-rodriguez-insulto-llamando-chupa-p/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-restauran-el-antimonumento-de-la-guarderia-abc-para-una-pelicula-de-ga","t":"Restauran el antimonumento de la Guardería ABC para una película de Gael García Bernal","c":"entretenimiento","f":"2026-10-23T18:37","r":"Trabajadores restauran la estructura metálica del antimonumento a los 49 niños de la Guardería ABC, colocada frente a la Suprema Corte en la Ciudad de México. Según los propios trabajadores, la pieza se usará como elemento escenográfico de una película de ficción sobre el incendio de 2009 en Hermosillo, dirigida por Gael García Bernal.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/restauran-antimonumento-de-la-guarderia-abc-frente-a-la-scjn-para-filmar-pelicula-de-gael-garcia/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-indice-latinoamericano-de-ia-ubica-a-mexico-en-el-lugar-8-de-20-paises","t":"Índice latinoamericano de IA ubica a México en el lugar 8 de 20 países","c":"tecnologia","f":"2026-10-23T18:36","r":"El Índice Latinoamericano de Inteligencia Artificial (ILIA) 2026 colocó a México en el octavo sitio entre 20 países de la región, con 52 de 100 puntos; Chile, Brasil y Uruguay encabezan la lista. El país registra 466 empresas dedicadas a la IA, la segunda cifra más alta después de Brasil, y 63 maestrías especializadas, la mayor oferta entre los evaluados.","b":"","img":"tech","foto":"","cred":"","src":[["En Blanco y Negro","https://enblancoynegro.com.mx/2026/10/23/mexico-queda-fuera-de-los-primeros-lugares-de-inteligencia-artificial-en-america-latina/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-81ae13da0158","t":"Somos y Paz podrán competir en las elecciones de 2027 en Jalisco","c":"politica","f":"2026-10-23T17:31","r":"La llegada de estos dos partidos también modificará la distribución del dinero público destinado a las fuerzas políticas","b":"Los partidos políticos Somos y Paz podrán competir en las elecciones de 2027 en Jalisco, luego de recibir su acreditación ante el Instituto Electoral y de Participación Ciudadana del Estado.\n\nDurante una sesión extraordinaria, celebrada este 22 de octubre, el IEPC Jalisco revisó las solicitudes de ambos partidos, que ya contaban con registro nacional ante el INE, pero necesitaban acreditar su representación en la entidad.\n\nCon esta decisión, podrán tener representantes ante el organismo electoral y recibir los recursos públicos que les correspondan.\n\n\"Se acredita el partido político nacional, Partido Paz, ante el Instituto Electoral y de Participación Ciudadana del Estado de Jalisco\", explicó Omar Ernesto Andujo Bitar, de la Secretaría Ejecutiva del IEPC Jalisco\n\nDurante la discusión, la consejera del IEPC Jeanine García González pidió explicar con mayor claridad por qué los partidos recibieron su acreditación hasta ahora, cuando su registro nacional estaba vigente desde julio.\n\nSe explicó que era necesario completar requisitos relacionados con sus órganos directivos y la documentación de sus representantes.\n\n\"Ahora que ya se ha determinado su, sus órganos directivos y etcétera, todo lo que establecen ahí los lineamientos, es que ahora sí ya se le tiene por acreditado\", dijo la funcionaria.\n\nLa llegada de estos dos partidos también modificará la distribución del dinero público destinado a las fuerzas políticas en Jalisco. La propuesta aprobada en Comisión contempla que Somos y Paz reciban aproximadamente 878 mil pesos mensuales cada uno durante noviembre y diciembre.\n\nEsto implicaría ajustes a los recursos que actualmente reciben Movimiento Ciudadano, Morena, PAN, PRI y Partido Verde.\n\nEn total, se contempla repartir 85 millones 662 mil pesos entre ocho partidos durante los últimos dos meses del año. Sin embargo, las nuevas cantidades todavía deberán ser votadas por el Consejo General del IEPC la próxima semana.","img":"","foto":"/img/subidas/Captura de pantalla 2026-10-23 a la(s) 4.52.16 p.m..png","cred":"","src":[],"dest":true,"a":"Redacción"},{"id":"2026-10-23-vance-se-intensifica-a-huracan-categoria-1-frente-a-las-costas-de-guer","t":"Vance se intensifica a huracán categoría 1 frente a las costas de Guerrero","c":"nacional","f":"2026-10-23T06:59","r":"Vance se convirtió en huracán categoría 1 la madrugada de este viernes, a unos 710 kilómetros al sur-suroeste de Acapulco, con vientos sostenidos de 140 km/h, rachas de 165 km/h y avance hacia el nor-noroeste a 9 km/h. Se prevén lluvias fuertes en las costas de Guerrero y el centro-suroeste de Michoacán, chubascos en Oaxaca y oleaje de 2 a 3 metros. El pronóstico indica que podría llegar a categoría 2 este viernes y a categoría 3 el sábado.","b":"","img":"huracan","foto":"","cred":"","src":[["Meganoticias","https://www.meganoticias.mx/ixtapa-zihuatanejo/noticia/vance-se-intensifica-a-hurac%C3%A1n-categor%C3%ADa-1-prev%C3%A9n-lluvias-en-tres-estados/781792"],["UnoTV","https://www.unotv.com/clima/pronostico-meteorologico-mexico-23-octubre/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-maru-campos-afirma-que-discutio-a-gritos-con-sheinbaum-por-el-caso-cia","t":"Maru Campos afirma que discutió a gritos con Sheinbaum por el caso CIA y acusa a Ariadna Montiel","c":"politica","f":"2026-10-23T06:58","r":"La gobernadora de Chihuahua, María Eugenia Campos, relató en una entrevista con Latinus que en su reunión del 19 de septiembre con la presidenta Claudia Sheinbaum, en Ciudad Juárez, ambas levantaron la voz durante varios minutos por el operativo de El Pinal en el que participaron agentes estadounidenses. Campos dijo que en ese encuentro señaló a la dirigente nacional de Morena, Ariadna Montiel, de tener vínculos con el crimen organizado en Chihuahua. Sheinbaum rechazó que exista un conflicto y atribuyó los dichos a una campaña partidista.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/a-gritos-maru-campos-revela-detalles-de-su-reunion-con-sheinbaum-por-caso-cia-en-chihuahua/"],["Proceso","https://www.proceso.com.mx/nacional/estados/2026/10/22/maru-campos-desata-escandalo-revela-gritos-con-sheinbaum-y-acusa-a-ariadna-montiel-382399.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-interpol-retira-las-fichas-rojas-contra-ines-gomez-mont-y-victor-alvar","t":"Interpol retira las fichas rojas contra Inés Gómez Mont y Víctor Álvarez Puga","c":"nacional","f":"2026-10-23T06:57","r":"Interpol canceló las fichas rojas que pesaban desde hace cinco años sobre la conductora Inés Gómez Mont y su esposo, Víctor Manuel Álvarez Puga, acusados por la FGR de peculado, lavado de dinero y delincuencia organizada por un presunto desvío de unos 2 mil 950 millones de pesos. La orden de aprehensión emitida en México en 2021 sigue vigente. La presidenta Claudia Sheinbaum dijo que el gobierno pedirá restablecer las fichas y buscará la extradición desde Estados Unidos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/ines-gomez-mont-y-victor-alvarez-puga-los-4-motivos-que-llevaron-a-interpol-a-cancelar-la-ficha-roja/"],["El Universal","https://www.eluniversal.com.mx/nacion/retiran-ficha-roja-de-interpol-a-ines-gomez-mont-y-su-esposo-victor-alvarez-puga-son-factureros-reconocidos-acusa-sheinbaum/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-plan-mexico-suma-20-nuevos-parques-industriales-con-inversion-de-763-m","t":"Plan México suma 20 nuevos parques industriales con inversión de 763 millones de dólares","c":"economia","f":"2026-10-23T06:56","r":"La presidenta Claudia Sheinbaum y la Asociación Mexicana de Parques Industriales Privados anunciaron 20 nuevos parques industriales con 763 millones de dólares de inversión, 4.6 millones de metros cuadrados, 175 empresas y 32 mil 127 empleos. Se ubican en Coahuila, Nuevo León, Ciudad de México, Estado de México, Aguascalientes, Guanajuato, Querétaro y Baja California. Con ellos suman 40 parques en operación de la meta de 100 del Plan México.","b":"","img":"palacio","foto":"","cred":"","src":[["El Mañana","https://elmanana.com.mx/nacional/2026/10/22/plan-mexico-claudia-sheinbaum-anuncia-20-nuevos-parques-industriales-de-la-ampip-con-inversion-de-76-183040.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-23-frente-frio-3-trae-lluvias-a-30-estados-y-posible-aguanieve-en-baja-ca","t":"Frente frío 3 trae lluvias a 30 estados y posible aguanieve en Baja California","c":"nacional","f":"2026-10-23T06:55","r":"El Servicio Meteorológico Nacional prevé lluvias en 30 estados este viernes por el frente frío 3, una circulación ciclónica y una masa de aire frío, con temperaturas que podrían llegar a 0 °C. Las lluvias más fuertes, de 50 a 75 milímetros, se esperan en Chihuahua, y podría caer aguanieve en la sierra de San Pedro Mártir, Baja California. En el Valle de México habrá mañanas frías y con niebla.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/pronostico-meteorologico-mexico-23-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-sheinbaum-llama-oportunista-a-jorge-romero-el-pan-niega-haber-marchado","t":"Sheinbaum llama oportunista a Jorge Romero; el PAN niega haber marchado ante el IMSS","c":"politica","f":"2026-10-23T06:54","r":"La presidenta Claudia Sheinbaum calificó de oportunismo político la presencia del dirigente del PAN, Jorge Romero, en el plantón de trabajadores frente a la sede del IMSS en Reforma, donde pidió la salida de Zoé Robledo. Romero respondió que se trató de una conferencia de prensa y no de una marcha. Los trabajadores, que llevan al menos dos semanas en el lugar, abuchearon al panista y dijeron que su movimiento no es partidista.","b":"","img":"imss","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/jorge-romero-responde-a-claudia-sheinbaum-y-niega-participacion-del-pan-en-marcha-ante-el-imss/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-lenia-batres-defiende-bloquear-comentarios-en-x-la-libertad-de-expresi","t":"Lenia Batres defiende bloquear comentarios en X: la libertad de expresión no ampara insultos","c":"politica","f":"2026-10-23T06:53","r":"La ministra de la Suprema Corte Lenia Batres defendió en un comunicado las restricciones a comentarios en su cuenta de X. Desde enero de 2024, 17 usuarios han promovido amparos en su contra en la Ciudad de México, Guerrero, Puebla y Jalisco; de los 16 resueltos, 14 fueron desechados. Un juez federal concedió recientemente un amparo a un usuario para que pueda comentar en su cuenta.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/10/22/lenia-batres-niega-censura-por-bloquear-comentarios-en-x-la-libertad-de-expresion-no-ampara-insultos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-el-peso-abre-el-viernes-en-18-79-por-dolar-tras-una-semana-a-la-baja","t":"El peso abre el viernes en 18.79 por dólar tras una semana a la baja","c":"economia","f":"2026-10-23T06:52","r":"El tipo de cambio abrió este viernes en alrededor de 18.79 pesos por dólar, un alza de 0.43% frente al cierre previo de 18.71. En la última semana el dólar acumula una ganancia de 1.62% frente a la moneda mexicana. Hacienda estima un tipo de cambio de 19.70 al cierre de 2026.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-23-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-comision-antimonopolio-investiga-el-mercado-de-vales-de-despensa-y-pag","t":"Comisión Antimonopolio investiga el mercado de vales de despensa y pagos electrónicos","c":"economia","f":"2026-10-23T06:51","r":"La Comisión Nacional Antimonopolio inició una investigación por posibles prácticas monopólicas relativas en la aceptación de vales de despensa y medios de pago electrónico en comercios minoristas de todo el país, según un aviso publicado el 22 de octubre en el Diario Oficial de la Federación. El expediente DE-014-2026 surgió de una denuncia y tendrá un plazo de hasta 120 días hábiles, prorrogables. La comisión no identificó a las empresas señaladas.","b":"","img":"bolsa","foto":"","cred":"","src":[["El CEO","https://elceo.com/negocios/cna-inicia-investigacion-contra-mercado-vales-despensa-pagos-electronicos-practicas-monopolicas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-gran-jurado-de-ee-uu-acusa-formalmente-a-el-tanque-senalado-como-cofun","t":"Gran jurado de EE. UU. acusa formalmente a El Tanque, señalado como cofundador del CJNG","c":"seguridad","f":"2026-10-23T06:50","r":"Un gran jurado federal del Distrito de Columbia acusó a Iván Cazarín Molina, El Tanque, de conspirar para distribuir cocaína y metanfetamina hacia Estados Unidos entre 2005 y 2025 y de posesión de un arma de fuego. Fue detenido el 5 de octubre en Zapopan, Jalisco, y está preso en el Altiplano. Una jueza federal desechó un amparo de su defensa contra una posible extradición, porque el trámite aún no inicia formalmente.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/eeuu-presenta-acusacion-formal-contra-el-tanque-del-cjng-por-narcotrafico-y-posesion-de-armas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-mas-de-la-mitad-de-los-policias-asesinados-en-el-pais-son-municipales","t":"Más de la mitad de los policías asesinados en el país son municipales: Causa en Común","c":"seguridad","f":"2026-10-23T06:49","r":"Un informe de Causa en Común registra al menos 665 agentes de seguridad pública asesinados de octubre de 2024 a 2026: 360 municipales, 220 estatales y 85 federales. En lo que va de 2026 han sido asesinados 87 policías municipales. El número de policías municipales al cierre de 2024 fue de 166 mil 224, el más bajo desde 2010.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/10/23/municipales-5-de-cada-10-policias-asesinados/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-detienen-en-culiacan-a-el-coco-ranas-senalado-como-lider-de-una-celula","t":"Detienen en Culiacán a El Coco Ranas, señalado como líder de una célula afín a Los Chapitos","c":"estados","f":"2026-10-23T06:48","r":"La Secretaría de la Defensa Nacional informó la detención de Orlando N, El Coco Ranas, y otras tres personas el 21 de octubre en la colonia Lomas del Sol, en Culiacán, Sinaloa. Se les aseguraron armas, cartuchos, cargadores y equipo táctico. Según Defensa, encabeza la célula Los Ranas, afín a la facción de Los Chapitos; los detenidos quedaron a disposición de la FGR.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/sinaloa/detencion-orlando-n-coco-ranas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-desbordes-de-rios-dejan-comunidades-incomunicadas-en-el-sur-de-veracru","t":"Desbordes de ríos dejan comunidades incomunicadas en el sur de Veracruz","c":"estados","f":"2026-10-23T06:47","r":"Las lluvias del frente frío 2 dejaron al menos 21 localidades afectadas en Minatitlán, 16 de ellas sin acceso por tierra, y viviendas anegadas por la crecida del río Uxpanapa. La presa Canseco, en Catemaco, está al 103% de su capacidad y Conagua realiza desfogues controlados con alerta en diez comunidades de Los Tuxtlas. El gobierno estatal activó los planes DN-III-E, Marina y Tajín.","b":"","img":"lluvia","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/10/23/estados/026n1est?partner=rss"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-linea-a-del-metro-opera-en-dos-tramos-tras-la-caida-de-un-soporte-de-c","t":"Línea A del Metro opera en dos tramos tras la caída de un soporte de catenaria","c":"cdmx","f":"2026-10-23T06:46","r":"La Línea A del Metro dio servicio en dos tramos, de Pantitlán a Canal de San Juan y de Santa Marta a La Paz, luego de que la noche del jueves cayó un soporte de catenaria a la altura de la estación Guelatao. Las estaciones Tepalcates, Guelatao, Peñón Viejo y Acatitla quedaron sin servicio. Camiones de RTP conectan ambos tramos y el titular del Metro, Adrián Rubalcava, dijo que se trabaja las 24 horas para normalizar la operación.","b":"","img":"metro","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/10/23/linea-a-del-metro-suspende-servicio-tras-caida-de-elemento-de-catenaria-y-explosion-que-estaciones-no-dan-servicio-alternativas/"],["Infobae","https://www.infobae.com/mexico/2026/10/23/linea-a-del-metro-opera-en-dos-tramos-por-falla-en-la-catenaria-rtp-brinda-apoyo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-rusia-lanza-21-misiles-balisticos-contra-kiev-pese-a-la-reanudacion-de","t":"Rusia lanza 21 misiles balísticos contra Kiev pese a la reanudación de negociaciones","c":"internacional","f":"2026-10-23T06:45","r":"Rusia lanzó bombardeos que alcanzaron 12 regiones de Ucrania, incluida la capital; en la capital, 21 misiles balísticos alcanzaron viviendas, instalaciones eléctricas, una estación de tren y el metro. Hubo al menos cuatro muertos y decenas de heridos, entre ellos cinco niños. Rusia, Ucrania y Estados Unidos acordaron reanudar las negociaciones, que podrían comenzar después del 10 de noviembre.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mundo/2026/10/23/rusia-continua-bombardeos-en-ucrania-pese-a-buscar-negociar/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-francia-cierra-el-louvre-el-orsay-y-el-museo-picasso-el-sabado-ante-nu","t":"Francia cierra el Louvre, el Orsay y el Museo Picasso el sábado ante nuevas protestas","c":"internacional","f":"2026-10-23T06:44","r":"El Ministerio de Cultura de Francia anunció el cierre del Louvre, el Museo de Orsay y el Museo Picasso este sábado para proteger el patrimonio ante posibles disturbios. Las protestas, iniciadas en septiembre por la situación educativa y el costo de vida, reunieron a más de 500 mil personas el último fin de semana, con saqueos e incendios como el del ayuntamiento histórico de Limoges.","b":"","img":"paris","foto":"","cred":"","src":[["MDZ","https://www.mdzol.com/mundo/2026/10/22/alerta-en-francia-cierran-el-louvre-y-otros-museos-ante-el-temor-de-nuevos-disturbios-1990071.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-trump-ha-deportado-a-unas-980-mil-personas-en-su-segundo-mandato-segun","t":"Trump ha deportado a unas 980 mil personas en su segundo mandato, según el MPI","c":"internacional","f":"2026-10-23T06:43","r":"El Migration Policy Institute calcula que el gobierno de Donald Trump deportó a unas 980 mil personas entre el 20 de enero de 2025 y el 31 de julio de 2026. Más de dos tercios fueron interceptadas en la frontera y solo 20% tenía antecedentes penales. El informe advierte que la medición es difícil por la reducción de reportes del Departamento de Seguridad Nacional.","b":"","img":"texas","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/internacional/trump-deporta-980-mil-migrantes-informe-mpi/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-sismo-de-magnitud-7-en-el-tibet-deja-al-menos-16-muertos","t":"Sismo de magnitud 7 en el Tíbet deja al menos 16 muertos","c":"internacional","f":"2026-10-23T06:42","r":"Un terremoto de magnitud 7.0 sacudió la noche del jueves el distrito de Baqen, en la región china del Tíbet, a unos 190 kilómetros de Nagqu, según el USGS. La agencia Xinhua reportó al menos 16 muertos, y las autoridades locales elevaron a 46 el número de heridos. Al menos 339 viviendas se derrumbaron o resultaron dañadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/22/un-terremoto-de-magnitud-70-sacudio-el-tibet/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-grecia-prohibe-por-ley-las-redes-sociales-a-menores-de-15-anos-desde-2","t":"Grecia prohíbe por ley las redes sociales a menores de 15 años desde 2027","c":"tecnologia","f":"2026-10-23T06:41","r":"El Parlamento griego aprobó una ley que prohíbe el acceso a redes sociales a menores de 15 años a partir del 1 de enero de 2027, incluidas las cuentas ya existentes. Las plataformas deberán aplicar sistemas de verificación de edad que protejan la privacidad; el gobierno propuso usar sus aplicaciones Gov.gr Wallet o Kids Wallet. La ley no prevé sanciones para los padres.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/agencias/2026/10/22/grecia-prohibe-por-ley-el-acceso-a-las-redes-sociales-a-los-menores-de-15-anos/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-23-rays-y-cerveceros-abren-hoy-una-serie-mundial-que-tendra-campeon-inedi","t":"Rays y Cerveceros abren hoy una Serie Mundial que tendrá campeón inédito","c":"deportes","f":"2026-10-23T06:40","r":"Tampa Bay y Milwaukee juegan este viernes el primer partido de la Serie Mundial a las 18:00 horas del centro de México; ninguno de los dos ha ganado el título. El segundo juego será el sábado 24 y la serie, de llegar a siete partidos, terminaría el 31 de octubre. Los Cerveceros barrieron a los Dodgers y los Rays eliminaron 4-2 en la serie a los Guardianes.","b":"","img":"beisbol","foto":"","cred":"","src":[["Fox Sports","https://www.foxsports.com.mx/2026/10/19/lista-la-serie-mundial-2026-milwaukee-brewers-vs-tampa-bay-rays-habra-un-campeon-inedito-en-mlb/"],["TUDN","https://www.tudn.com/futbol/liga-mx/partidos-de-hoy-23-de-octubre-liga-mx-serie-mundial-y-mexicanos-en-el-extranjero"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-la-inflacion-sube-a-3-62-en-la-primera-quincena-de-octubre-por-encima","t":"La inflación sube a 3.62% en la primera quincena de octubre, por encima de lo previsto","c":"economia","f":"2026-10-22T18:50","r":"El Inegi informó que los precios al consumidor subieron 0.41% en la primera mitad de octubre y la inflación anual llegó a 3.62%; el mercado esperaba 3.60%. La subyacente se ubicó en 3.78% anual. Los mayores aumentos fueron en electricidad (18.51%, por el fin del subsidio de verano en 18 ciudades), transporte aéreo (14.77%) y tomate verde (22.07%); bajaron el limón, el aguacate, el plátano y el jitomate.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/10/22/inegi-inflacion-sorprende-al-alza-octubre-3-62-anual"],["El Imparcial","https://www.elimparcial.com/dinero/2026/10/22/inegi-reporta-que-la-inflacion-en-mexico-subio-a-362-anual-en-la-primera-quincena-de-octubre-debido-al-encarecimiento-de-la-electricidad-y-el-transporte-aereo/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-vance-se-fortalece-en-el-pacifico-y-podria-ser-huracan-categoria-3-el","t":"Vance se fortalece en el Pacífico y podría ser huracán categoría 3 el sábado","c":"nacional","f":"2026-10-22T18:49","r":"La tormenta tropical Vance tenía vientos sostenidos de 95 km/h y rachas de 110 km/h a 810 km al sur de Acapulco, según el aviso de las 9:00 horas del SMN. El pronóstico prevé que se convierta en huracán este jueves y alcance categoría 3 el sábado 24, con vientos de hasta 195 km/h, frente a las costas de Guerrero y Michoacán. Por ahora no genera lluvias ni oleaje en territorio nacional, pero Guerrero, Michoacán y Colima deben seguir su evolución.","b":"","img":"huracan","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/preven-que-vance-evolucione-a-huracan-categoria-3-el-proximo-sabado-24-de-octubre-cerca-de-guerrero-y-michoacan/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-el-peso-cierra-en-18-71-por-dolar-su-peor-nivel-desde-septiembre-de-20","t":"El peso cierra en 18.71 por dólar, su peor nivel desde septiembre de 2025","c":"economia","f":"2026-10-22T18:48","r":"El tipo de cambio cerró en 18.7134 pesos por dólar según Banxico, una depreciación de 0.22% y la segunda sesión seguida de pérdidas para la moneda mexicana. Es el nivel más débil desde el 4 de septiembre de 2025. Monex atribuyó el movimiento a la aversión al riesgo por el conflicto en Medio Oriente; Banco Base señaló que la inflación más alta reduce la probabilidad de recortes de tasa de Banxico, lo que moderó la caída.","b":"","img":"bolsa","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/tipo-de-cambio-peso-dolar-hoy-22-de-octubre-de-2026-2/"],["Mexican Times","https://www.mexicantimes.com.mx/peso-mexicano-cierre-22-octubre-18-71/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-rsf-sin-avances-en-la-mayoria-de-los-22-compromisos-del-gobierno-con-l","t":"RSF: sin avances en la mayoría de los 22 compromisos del gobierno con la prensa","c":"nacional","f":"2026-10-22T18:47","r":"Reporteros Sin Fronteras presentó su balance de los dos primeros años del gobierno de Claudia Sheinbaum: 18 periodistas asesinados en ese periodo, 169 desde 2006 y solo 1% de los crímenes esclarecidos. De los 22 compromisos firmados en 2024, diez no muestran avances verificables y dos tuvieron retrocesos. Su director, Thibaut Bruttin, se reunió con la secretaria de Gobernación, Rosa Icela Rodríguez.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/10/22/reporteros-sin-fronteras-no-hay-avances-significativos-en-los-22-compromisos-de-sheinbaum-con-la-prensa/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-somos-y-pri-piden-que-guadalupe-taddei-se-separe-de-la-presidencia-del","t":"Somos y PRI piden que Guadalupe Taddei se separe de la presidencia del INE","c":"politica","f":"2026-10-22T18:46","r":"En la sesión del Consejo General del INE, el representante del partido Somos, Marco Antonio Baños, pidió que la consejera presidenta se separe temporalmente del cargo mientras se investigan reportes sobre sus presuntos vínculos con Alfredo Hernández Casillas, señalado como proveedor del instituto. El PRI exigió su salida si no acredita la legalidad de su gestión. Taddei rechazó las presiones y dijo que no dejará sus funciones.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/23/somos-exige-que-guadalupe-taddei-se-separe-temporalmente-de-la-presidencia-del-ine/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-sheinbaum-la-modalidad-40-se-regulo-porque-se-detectaron-fraudes-en-pe","t":"Sheinbaum: la Modalidad 40 se reguló porque se detectaron fraudes en pensiones","c":"nacional","f":"2026-10-22T18:45","r":"En la conferencia matutina, la presidenta Claudia Sheinbaum explicó que el IMSS decidió regular la Modalidad 40 porque por esa vía se armaban esquemas fraudulentos para obtener pensiones que no correspondían. Dijo que el objetivo es asegurar recursos suficientes para pagar las pensiones reales.","b":"","img":"imss","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/en-vivo-la-mananera-de-la-presidenta-claudia-sheinbaum/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-sheinbaum-niega-que-el-exfiscal-jauregui-haya-desmantelado-un-narcolab","t":"Sheinbaum niega que el exfiscal Jáuregui haya desmantelado un narcolaboratorio","c":"politica","f":"2026-10-22T18:44","r":"La presidenta rechazó las versiones de que su gobierno juzga al exfiscal de Chihuahua César Jáuregui por haber desmantelado un narcolaboratorio y afirmó que él no lo hizo. Sostuvo que si hubiera colusión con el crimen organizado no habría reducción de homicidios y que su objetivo es la paz y la justicia.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/en-vivo-la-mananera-de-la-presidenta-claudia-sheinbaum/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-el-brent-sube-4-y-cierra-en-113-dolares-por-tensiones-en-ormuz","t":"El Brent sube 4% y cierra en 113 dólares por tensiones en Ormuz","c":"economia","f":"2026-10-22T18:43","r":"El crudo Brent para diciembre cerró en 113.17 dólares por barril, 4% más que la sesión previa y su nivel más alto desde mayo; el WTI subió 2.39% a 99.47 dólares. El alza siguió a la amenaza de la Guardia Revolucionaria de Irán de atacar bases de Estados Unidos si Washington sigue escoltando buques en el estrecho de Ormuz, y a ataques de los hutíes contra infraestructura saudí.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/10/22/el-precio-del-brent-subio-un-4-y-alcanzo-su-mayor-precio-desde-mayo-por-la-escalada-en-medio-oriente/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-atacan-a-balazos-un-camion-con-estudiantes-de-secundaria-en-escuinapa","t":"Atacan a balazos un camión con estudiantes de secundaria en Escuinapa, Sinaloa","c":"seguridad","f":"2026-10-22T18:42","r":"Un hombre armado disparó este jueves contra el camión de la ruta El Robalito-Escuinapa, en el que viajaban alumnos de secundaria. El chofer resultó con una lesión leve y siguió manejando hasta un retén militar; los estudiantes salieron ilesos. El Gabinete de Seguridad federal informó que trabaja con la SSP de Sinaloa para localizar a los responsables; no se han reportado detenciones.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/ataque-armado-contra-camion-de-estudiantes-en-escuinapa-despliegan-operativo-federal-para-detener-a-los-agresores/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-detienen-a-los-jefes-de-seguridad-de-momax-y-rio-grande-en-zacatecas","t":"Detienen a los jefes de seguridad de Momax y Río Grande, en Zacatecas","c":"seguridad","f":"2026-10-22T18:41","r":"La Fiscalía de Zacatecas informó la detención de José Miguel N, titular de seguridad de Momax, acusado de facilitación de actividades delictivas; con él se aseguró una granada, cartuchos y posibles drogas sintéticas. También fue detenido José Alonso N, director de Seguridad Pública de Río Grande, investigado por secuestro y extorsión agravada contra ganaderos. En los operativos participaron Defensa, SSPC y Guardia Nacional.","b":"","img":"palacio","foto":"","cred":"","src":[["Noticias PV Nayarit","https://noticiaspvnayarit.com.mx/detienen-a-secretarios-de-seguridad-en-zacatecas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-fiscalia-de-tabasco-acusa-formalmente-a-hernan-bermudez-por-desaparici","t":"Fiscalía de Tabasco acusa formalmente a Hernán Bermúdez por desaparición forzada","c":"estados","f":"2026-10-22T18:40","r":"La Fiscalía General de Tabasco presentó la acusación formal contra Hernán Bermúdez Requena, exsecretario de Seguridad estatal y señalado como líder de La Barredora, con lo que el caso pasa a la etapa intermedia. El fiscal Óscar Tonatiuh Vázquez Landeros informó que la investigación complementaria concluyó. Bermúdez está preso en el Altiplano y enfrenta otro proceso por secuestro y extorsión.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/fiscalia-de-tabasco-formaliza-acusacion-contra-hernan-bermudez-requena-por-el-delito-de-desaparicion-forzada/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-detienen-en-cancun-a-presunto-lider-de-una-red-de-narcomenudeo-y-extor","t":"Detienen en Cancún a presunto líder criminal acusado de narcotráfico y extorsión","c":"estados","f":"2026-10-22T18:39","r":"Marina, SSPC, FGR y la policía de Quintana Roo detuvieron en Cancún a Robert N, señalado como líder de una organización dedicada al tráfico de drogas y la extorsión. En tres cateos se aseguraron 1.3 kilos de marihuana, tres armas, dos vehículos y un teléfono. Quedó a disposición del Ministerio Público.","b":"","img":"palacio","foto":"","cred":"","src":[["Tus Buenas Noticias","https://tusbuenasnoticias.com/noticias/actualidad/2026/10/22/66001-marina-y-autoridades-federales-detienen-a-presunto-lider-criminal-en-cancun"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-sigue-sin-aparecer-domingo-atanacio-quirino-campesino-secuestrado-en-g","t":"Sigue sin aparecer Domingo Atanacio Quirino, campesino secuestrado en Guerrero","c":"estados","f":"2026-10-22T18:38","r":"De los ocho pobladores del ejido El Balcón, en Ajuchitlán del Progreso, privados de la libertad el 24 de septiembre, solo Domingo Atanacio Quirino, de 50 años, sigue sin ser localizado. Según el Centro de Derechos de las Víctimas Minerva Bello, enfermó en cautiverio y fue separado del grupo; seis campesinos fueron hallados con vida el 16 de octubre.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-22-de-octubre-un-hospital-la-ultima-pista-del-paradero-de-domingo-atanacio-quirino-campesino-desaparecido-en-guerrero/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-brugada-la-ley-de-rentas-no-congela-alquileres-ni-ataca-la-propiedad-p","t":"Brugada: la ley de rentas no congela alquileres ni ataca la propiedad privada","c":"cdmx","f":"2026-10-22T18:37","r":"La jefa de Gobierno, Clara Brugada, defendió la reforma enviada al Congreso capitalino el 14 de octubre, que propone que las rentas no suban más que la inflación, contratos mínimos de un año, un solo depósito de garantía y un registro digital de arrendamientos. Según cifras del Inegi citadas, casi 30% de las familias de la ciudad renta su vivienda.","b":"","img":"zocalo","foto":"","cred":"","src":[["Quadratín","https://mexico.quadratin.com.mx/propone-brugada-que-rentas-en-cdmx-no-aumenten-por-encima-de-inflacion/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-iran-reporta-siete-petroleros-danados-en-ormuz-y-amenaza-bases-de-ee-u","t":"Irán reporta siete petroleros dañados en Ormuz y amenaza bases de EE.UU.","c":"internacional","f":"2026-10-22T18:36","r":"La televisión estatal iraní informó que siete buques petroleros se incendiaron o resultaron dañados durante la noche en el estrecho de Ormuz, alcanzados por Irán o por minas; AP no pudo confirmarlo. La fuerza naval de la Guardia Revolucionaria reiteró que atacará bases estadounidenses si Washington sigue guiando barcos por el estrecho. Trump rechazó la última propuesta iraní para poner fin a la guerra.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Gestión / AP","https://gestion.pe/mundo/eeuu/iran-dice-que-hay-7-petroleros-danados-en-ormuz-entre-temores-a-un-repunte-de-la-guerra-noticia"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-la-corte-penal-internacional-gana-el-premio-sajarov-2026","t":"La Corte Penal Internacional gana el Premio Sájarov 2026","c":"internacional","f":"2026-10-22T18:35","r":"El Parlamento Europeo otorgó el Premio Sájarov a la Libertad de Conciencia a la Corte Penal Internacional y a sus funcionarios, sancionados por Estados Unidos por sus investigaciones sobre Gaza. La decisión la tomó la Conferencia de Presidentes que encabeza Roberta Metsola; el premio se entregará el 16 de diciembre en Estrasburgo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Tercera","https://www.latercera.com/mundo/noticia/tribunal-penal-internacional-tpi-es-galardonado-con-el-premio-sajarov-2026-del-parlamento-europeo/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-termina-el-juicio-por-la-muerte-de-maradona-el-veredicto-sera-el-22-de","t":"Termina el juicio por la muerte de Maradona; el veredicto será el 22 de diciembre","c":"deportes","f":"2026-10-22T18:34","r":"El Tribunal Oral en lo Criminal 7 de San Isidro cerró el juicio por la muerte de Diego Maradona y fijó el veredicto para el 22 de diciembre. El médico clínico Pedro Di Spagna fue absuelto luego de que la fiscalía y las querellas desistieran de acusarlo; seis profesionales de la salud siguen procesados. Es el segundo juicio, tras la anulación del primero en 2025.","b":"","img":"estadio","foto":"","cred":"","src":[["El Canciller","https://elcanciller.com/policiales/concluyo-el-juicio-por-la-muerte-de-maradona--absolvieron-al-medico-clinico-y-el-veredicto-se-conocera-en-diciembre_a6ada9acea5932312878e8779"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-llegan-al-autodromo-los-primeros-embarques-de-la-formula-1-para-el-gp","t":"Llegan al Autódromo los primeros embarques de la Fórmula 1 para el GP de México","c":"deportes","f":"2026-10-22T18:33","r":"Los primeros contenedores de las escuderías llegaron el 21 de octubre al Autódromo Hermanos Rodríguez, sede del Gran Premio de la Ciudad de México del 30 de octubre al 1 de noviembre. Sergio Pérez llegará a 300 grandes premios con Cadillac, que debutará en la pista de la Magdalena Mixhuca. Antes, la F1 corre esta semana en Austin.","b":"","img":"autodromo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/la-formula-1-empieza-a-llegar-a-mexico-aterrizan-los-primeros-embarques-en-el-autodromo-hermanos-rodriguez/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-ruben-blades-rosalia-y-cristian-castro-homenajeados-en-los-premios-bil","t":"Rubén Blades, Rosalía y Cristian Castro, homenajeados en los Premios Billboard Latinos","c":"entretenimiento","f":"2026-10-22T18:32","r":"La ceremonia de los Premios Billboard de la Música Latina 2026 en Miami entregó el premio Ícono a Rubén Blades, el del Salón de la Fama a Rosalía, el de Trayectoria a Cristian Castro y el Vanguardia a Fuerza Regida. Peso Pluma, Tito Double P y Fuerza Regida compiten por Artista del Año.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Latin Times","https://www.latintimes.com/billboard-latin-2026-all-winners-600469"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-empleados-de-micron-en-taiwan-hacen-la-primera-huelga-de-la-industria","t":"Trabajadores de Micron en Taiwán inician huelga de 24 horas por reparto de utilidades","c":"tecnologia","f":"2026-10-22T18:31","r":"El sindicato de Micron en Taoyuan inició a las 9:00 del 22 de octubre una huelga de advertencia de 24 horas para exigir una fórmula clara de reparto de utilidades. La votación previa tuvo 1,994 votos a favor de 2,012. Un día antes, la empresa firmó un acuerdo por separado con el sindicato de Taichung; las pláticas siguen el 23 de octubre.","b":"","img":"tech2","foto":"","cred":"","src":[["Hardware Busters","https://hwbusters.com/news/micron-strike-begins-in-taoyuan-after-the-taichung-union-signs-its-own-deal/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-gobierno-reporta-48-mil-millones-de-pesos-recuperados-por-combate-al-h","t":"Gobierno reporta 48 mil millones de pesos recuperados por combate al huachicol fiscal","c":"nacional","f":"2026-10-22T06:59","r":"La presidenta Claudia Sheinbaum informó que en 2026 se han recuperado más de 48 mil millones de pesos por el combate al contrabando de combustibles. El subsecretario de Hidrocarburos, Juan José Vidal Amaro, reportó 2,539 detenidos, 5,572 vehículos decomisados y 173.7 millones de litros asegurados. El SAT ha cancelado 2,224 empresas y la CNE 264 permisos.","b":"","img":"pemex","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/recupera-gobierno-484-mmdp-con-combate-a-huachicol-fiscal/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-dictan-prision-preventiva-a-cesar-jauregui-exfiscal-de-chihuahua-por-t","t":"Dictan prisión preventiva a César Jáuregui, exfiscal de Chihuahua, por traición a la patria","c":"politica","f":"2026-10-22T06:58","r":"César Gustavo Jáuregui Moreno, exfiscal general de Chihuahua, permanece en prisión preventiva acusado de traición a la patria; la FGR presentó cerca de 150 datos de prueba. Su defensa pidió duplicar el plazo constitucional, por lo que un juez federal decidirá el sábado 24 de octubre si lo vincula a proceso. También enfrenta cargos estatales por ejercicio ilegal del servicio público y coalición.","b":"","img":"chihuahua","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/dan-prision-a-jauregui-corral-andrea-y-loera-empujaron-denuncias/"],["N+","https://www.nmas.com.mx/sociedad/resumen-noticias-nocturno-nmas-21-octubre-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-diputados-aprueban-en-lo-general-la-llamada-ley-antimemes","t":"Diputados aprueban en lo general la llamada «Ley Antimemes»","c":"politica","f":"2026-10-22T06:57","r":"La Cámara de Diputados aprobó en lo general, con 312 votos a favor y 119 en contra, reformas al Código Penal Federal y a la Ley Federal de Protección a la Propiedad Industrial. Prevén de uno a cinco años de prisión por el uso indebido de símbolos e identidad gráfica de instituciones públicas para engañar o cometer delitos. La oposición pidió dejar claro que no se castigará la sátira política.","b":"","img":"senado","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/mexico/2026/10/21/diputados-aprueban-ley-antimemes.html"],["Tribuna","https://tribuna.com.mx/mexico/2026/10/21/con-312-votos-a-favor-y-119-en-contra-diputados-aprueban-en-lo-general-la-ley-antimemes_704842/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-comisiones-del-senado-aprueban-la-ley-de-ingresos-2027-y-cambios-al-is","t":"Comisiones del Senado aprueban la Ley de Ingresos 2027 y cambios al ISR","c":"politica","f":"2026-10-22T06:56","r":"Las comisiones de Hacienda y Estudios Legislativos Primera del Senado aprobaron, por 18 votos contra 11, la Ley de Ingresos de la Federación, la Ley Federal de Derechos y reformas al ISR para 2027. El paquete prevé ingresos por 10.6 billones de pesos y un techo de endeudamiento interno neto de hasta 1.7 billones. El pleno lo discutiría la próxima semana.","b":"","img":"senado","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/avanzan-en-senado-leyes-de-ingresos-derechos-y-del-isr/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-trabajo-infantil-baja-a-3-5-millones-de-menores-en-mexico-inegi","t":"Trabajo infantil baja a 3.5 millones de menores en México: INEGI","c":"nacional","f":"2026-10-22T06:55","r":"Según la Encuesta Nacional de Trabajo Infantil 2025 del INEGI, 3.5 millones de niñas, niños y adolescentes de 5 a 17 años estaban en trabajo infantil, frente a 3.7 millones en 2022. La tasa pasó de 13.1% a 12.6%. Entre los menores indígenas, 24.9% trabaja.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/trabajo-infantil-disminuye-pero-todavia-aqueja-a-35-millones/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-la-corte-valida-que-10-del-fais-vaya-directo-a-pueblos-indigenas-y-afr","t":"La Corte valida que 10% del FAIS vaya directo a pueblos indígenas y afromexicanos","c":"politica","f":"2026-10-22T06:54","r":"La Suprema Corte confirmó, por unanimidad, que al menos 10% del Fondo de Aportaciones para la Infraestructura Social se entregue directamente a pueblos y comunidades indígenas y afromexicanas, como fija el Presupuesto 2026. Doce municipios habían impugnado la medida por considerar que afecta su autonomía; la Corte resolvió que no la vulnera.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/21/scjn-valida-entrega-directa-del-fais-a-comunidades-indigenas-y-afromexicanas/"],["N+","https://www.nmas.com.mx/sociedad/resumen-noticias-nocturno-nmas-21-octubre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-san-lazaro-endurece-controles-de-acceso-tras-la-rina-entre-pri-y-mc","t":"San Lázaro endurece controles de acceso tras la riña entre PRI y MC","c":"politica","f":"2026-10-22T06:53","r":"La Junta de Coordinación Política y la mesa directiva de la Cámara de Diputados acordaron impedir la entrada al salón de sesiones sin acreditación y revisar más a fondo a acompañantes y vehículos, luego de que el diputado priista Carlos Eduardo Gutiérrez Mancilla arrojara agua sucia al dirigente de MC, Jorge Álvarez Máynez. El Comité de Ética atenderá la queja de MC.","b":"","img":"senado","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/blindan-controles-en-san-lazaro-tras-rina-mc-pri/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-tormenta-tropical-vance-se-forma-en-el-pacifico-podria-ser-huracan-cat","t":"Tormenta tropical Vance se forma en el Pacífico; podría ser huracán categoría 3","c":"nacional","f":"2026-10-22T06:52","r":"El Servicio Meteorológico Nacional ubicó a Vance a 835 kilómetros al sur de Acapulco, con vientos sostenidos de 65 km/h y rachas de 85 km/h. El pronóstico prevé que se convierta en huracán el viernes y alcance categoría 3 el sábado, lejos de la costa. Por ahora no representa peligro para el territorio nacional.","b":"","img":"huracan","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/agencias/2026/10/22/la-tormenta-tropical-vance-se-forma-en-el-pacifico-pero-sin-afectaciones-aun-sobre-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-imss-limita-desde-hoy-los-beneficios-de-la-modalidad-40-por-12-meses","t":"IMSS limita desde hoy los beneficios de la Modalidad 40 por 12 meses","c":"economia","f":"2026-10-22T06:51","r":"A partir de este 22 de octubre, quienes se inscriban por primera vez a la Modalidad 40 solo podrán cotizar con su último salario registrado o con éste más una UMA, en lugar de elegir hasta 25 UMA. La medida es temporal y no afecta a pensionados ni, por ahora, a quienes ya están inscritos. Los trámites serán solo digitales.","b":"","img":"imss","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/imss-pone-tope-a-los-beneficios-de-la-modalidad-40-por-12-meses/"],["N+","https://www.nmas.com.mx/sociedad/resumen-noticias-nocturno-nmas-21-octubre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-la-bolsa-mexicana-sube-1-43-y-supera-los-70-mil-puntos","t":"La Bolsa mexicana sube 1.43% y supera los 70 mil puntos","c":"economia","f":"2026-10-22T06:50","r":"El S&P/BMV IPC cerró el miércoles en 70,249.54 puntos, con un alza de 1.43%; fue su quinta sesión de ganancias y su nivel más alto desde el 9 de abril. América Móvil subió 7.78%. En contraste, el peso se depreció 1.3% y cerró en 18.67 por dólar, según Banxico.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/10/21/la-bolsa-de-mexico-repunta-un-143-y-escala-por-encima-de-las-70200-unidades/"],["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/10/21/peso-dolar-tipo-de-cambio-precio-hoy-21-de-octubre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-petroleo-cierra-casi-sin-cambios-brent-en-108-79-y-wti-en-97-15-dolare","t":"Petróleo cierra casi sin cambios: Brent en 108.79 y WTI en 97.15 dólares","c":"economia","f":"2026-10-22T06:49","r":"El Brent para diciembre cerró el miércoles en 108.79 dólares por barril, prácticamente sin variación, y el WTI bajó 0.69% a 97.15 dólares. Las exportaciones de Medio Oriente superaron los 24 millones de barriles diarios en la semana al 18 de octubre, lo que contuvo el efecto de nuevos ataques en la región.","b":"","img":"pemex","foto":"","cred":"","src":[["Banca y Negocios","https://www.bancaynegocios.com/petroleo-cierra-sin-grandes-movimientos-pese-a-exportaciones-del-medio-oriente/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-detienen-en-colima-a-el-puma-senalado-como-coordinador-de-una-celula-d","t":"Detienen en Colima a «El Puma», señalado como coordinador de una célula de Los Mezcales","c":"seguridad","f":"2026-10-22T06:48","r":"Policías estatales y elementos de Marina detuvieron en Colima a Édgar Oswaldo «N», alias «El Puma». En operativos relacionados también fue detenida una presunta integrante del CJNG en Cuauhtémoc y se catearon instalaciones en Villa de Álvarez. En total se aseguraron 2,919 bolsas con presunta droga, un arma y un artefacto explosivo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/21/golpean-al-cjng-y-los-mezcales-en-colima-caen-una-vendedora-de-droga-y-el-puma-coordinador-de-una-celula-dedicada-a-cometer-homicidios/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-sedena-confirma-el-envio-de-900-militares-a-guanajuato","t":"Sedena confirma el envío de 900 militares a Guanajuato","c":"seguridad","f":"2026-10-22T06:47","r":"La Secretaría de la Defensa Nacional informó que 900 elementos del Ejército llegaron a Guanajuato el martes 20 de octubre, y no 600 como se informó al inicio. Se suman a la 16 Zona Militar para patrullajes y acciones contra líderes de grupos delictivos, en coordinación con autoridades locales.","b":"","img":"palacio","foto":"","cred":"","src":[["Guanajuato Informa","https://guanajuatoinforma.com/confirma-sedena-que-no-fueron-600-sino-900-los-elementos-que-mando-a-guanajuato/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-madres-buscadoras-levantan-el-bloqueo-en-la-mexico-toluca-tras-35-hora","t":"Madres buscadoras levantan el bloqueo en la México-Toluca tras 35 horas","c":"estados","f":"2026-10-22T06:46","r":"El colectivo Mariposas buscando corazones y justicia nacional retiró su plantón en Lerma tras acordar con la Fiscalía del Estado de México revisar todas las carpetas de personas no localizadas, hacer reuniones periódicas por expediente y crear un mecanismo para sancionar a servidores públicos negligentes. El tránsito se normalizó poco a poco.","b":"","img":"carretera","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/tras-35-horas-buscadoras-levantan-bloqueo-mexico-toluca-llegar-acuerdos-con-fiscal"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-yucatan-sera-sede-del-congreso-mundial-de-ganado-brahman-en-noviembre","t":"Yucatán será sede del Congreso Mundial de Ganado Brahman en noviembre","c":"estados","f":"2026-10-22T06:45","r":"Del 10 al 15 de noviembre, Yucatán recibirá el XXII Congreso Mundial de Ganado Brahman, dentro de la Feria Xmatkuil 2026, con representantes de más de 30 países y unos 800 ejemplares de 85 ranchos. Se estima una derrama de 80 a 100 millones de pesos, según el gobierno del estado.","b":"","img":"ganado","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/10/22/preven-derrama-de-100-mdp-con-congreso-ganadero-en-yucatan/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-comienza-el-montaje-de-una-catrina-de-32-metros-en-el-zocalo","t":"Comienza el montaje de una catrina de 32 metros en el Zócalo","c":"cdmx","f":"2026-10-22T06:44","r":"Trabajadores y artistas iniciaron la instalación de una figura de 32 metros de altura de La Catrina de José Guadalupe Posada frente a la Catedral Metropolitana. Se busca un récord Guinness y se inaugurará con la megaofrenda de Día de Muertos el 29 de octubre.","b":"","img":"ofrenda","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/10/22/inicia-instalacion-de-megacatrina-en-el-zocalo-van-por-record-guinness/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-zelensky-acepta-congelar-las-lineas-del-frente-como-primer-paso-hacia","t":"Zelensky acepta congelar las líneas del frente como primer paso hacia la paz","c":"internacional","f":"2026-10-22T06:43","r":"El presidente de Ucrania, Volodímir Zelensky, aceptó mantener a ambos ejércitos en sus posiciones actuales para detener los combates, a cambio de garantías de seguridad de Estados Unidos y sus aliados. Del lado ruso, el Kremlin indicó que Vladímir Putin está dispuesto a retomar las conversaciones alrededor del 10 de noviembre.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mundo/2026/10/22/ucrania-acepta-congelar-lineas-del-frente-con-rusia/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-juez-de-nuevo-mexico-ordena-a-meta-pagar-25-mil-millones-de-dolares","t":"Juez de Nuevo México ordena a Meta pagar 25 mil millones de dólares","c":"tecnologia","f":"2026-10-22T06:42","r":"Tras un veredicto de jurado que encontró más de 43 millones de violaciones a leyes de protección al consumidor por engañar sobre la privacidad de datos en Facebook, un juez de Nuevo México ordenó a Meta pagar 25 mil millones de dólares al estado. La empresa anunció que apelará.","b":"","img":"tech","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mundo/2026/10/22/meta-enfrenta-sancion-por-25-mmdd/"]],"dest":false,"a":"Redacción"}];
